prompt --application/shared_components/logic/application_processes
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(91000000000088)
,p_process_sequence=>10
,p_process_point=>'ON_NEW_INSTANCE'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'COMPANY_INFO'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  SELECT name_ar,',
unistr('         LTRIM(address || NVL2(phone, '' | \0647\0627\062A\0641: '' || phone, NULL)'),
unistr('               || NVL2(tax_no, '' | \0627\0644\0631\0642\0645 \0627\0644\0636\0631\064A\0628\064A: '' || tax_no, NULL), '' |'')'),
'  INTO   :G_COMPANY_NAME, :G_COMPANY_INFO',
'  FROM   companies WHERE is_parent = ''Y'';',
'EXCEPTION WHEN OTHERS THEN',
unistr('  :G_COMPANY_NAME := ''\0627\0644\0645\0624\0633\0633\0629 \0627\0644\062A\0639\0627\0648\0646\064A\0629 \0627\0644\0648\0637\0646\064A\0629'';'),
'END;'))
,p_process_clob_language=>'PLSQL'
);
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(91000000000089)
,p_process_sequence=>20
,p_process_point=>'AFTER_LOGIN'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'INIT_USER'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  SELECT u.company_id, u.user_role',
'  INTO   :G_COMPANY_ID, :G_USER_ROLE',
'  FROM   app_users u',
'  WHERE  u.user_name = UPPER(:APP_USER)',
'  AND    u.is_active = ''Y'';',
'',
'  SELECT company_id INTO :G_PARENT_ID FROM companies WHERE is_parent = ''Y'';',
'EXCEPTION',
'  WHEN NO_DATA_FOUND THEN',
'    DECLARE l_cnt NUMBER;',
'    BEGIN',
'      SELECT COUNT(*) INTO l_cnt FROM app_users;',
'      IF l_cnt = 0 THEN',
'        :G_USER_ROLE := ''ADMIN'';',
'        SELECT company_id INTO :G_PARENT_ID FROM companies WHERE is_parent = ''Y'';',
'        :G_COMPANY_ID := :G_PARENT_ID;',
'      ELSE',
unistr('        raise_application_error(-20000, ''\0627\0644\0645\0633\062A\062E\062F\0645 \063A\064A\0631 \0645\0639\0631\0651\0641 \0641\064A \062C\062F\0648\0644 \0627\0644\0645\0633\062A\062E\062F\0645\064A\0646 \0623\0648 \063A\064A\0631 \0641\0639\0651\0627\0644'');'),
'      END IF;',
'    END;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
);
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(91000000000090)
,p_process_sequence=>30
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_RATE'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_rate NUMBER;',
'  l_date DATE := NVL(TO_DATE(apex_application.g_x02, ''DD/MM/YYYY''), TRUNC(SYSDATE));',
'BEGIN',
'  SELECT CASE WHEN c.is_base = ''Y'' THEN 1',
'              ELSE (SELECT r.rate FROM exchange_rates r',
'                    WHERE  r.currency_code = c.currency_code',
'                    AND    r.rate_date <= l_date',
'                    ORDER  BY r.rate_date DESC FETCH FIRST 1 ROW ONLY) END',
'  INTO   l_rate',
'  FROM   currencies c',
'  WHERE  c.currency_code = apex_application.g_x01;',
'',
'  apex_json.open_object;',
'  apex_json.write(''rate'', l_rate);',
'  apex_json.close_object;',
'EXCEPTION WHEN NO_DATA_FOUND THEN',
'  apex_json.open_object; apex_json.write(''rate'', ''''); apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
);
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(91000000000091)
,p_process_sequence=>40
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_ACCOUNTS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_json CLOB;',
'BEGIN',
'  SELECT JSON_ARRAYAGG(',
'           JSON_OBJECT(''id'' VALUE account_id, ''code'' VALUE account_code,',
'                       ''name'' VALUE name_ar, ''cash'' VALUE cash_bank)',
'           ORDER BY account_code RETURNING CLOB)',
'  INTO   l_json',
'  FROM   accounts',
'  WHERE  is_postable = ''Y''',
'  AND    is_active   = ''Y''',
'  AND    (company_id IS NULL OR company_id = TO_NUMBER(apex_application.g_x01));',
'',
'  apex_util.prn(COALESCE(l_json, TO_CLOB(''[]'')), FALSE);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
);

end;
