prompt --application/shared_components/security/authentications/oracle_apex_accounts
begin
wwv_flow_imp_shared.create_authentication(
 p_id=>wwv_flow_imp.id(6593650783757329)
,p_name=>'APP_USERS'
,p_scheme_type=>'NATIVE_CUSTOM'
,p_attribute_03=>'auth_user'
,p_attribute_05=>'N'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'FUNCTION auth_user (p_username IN VARCHAR2, p_password IN VARCHAR2) RETURN BOOLEAN IS',
'  l_ok NUMBER;',
'BEGIN',
'  SELECT COUNT(*) INTO l_ok',
'  FROM   app_users u',
'  WHERE  u.user_name = UPPER(TRIM(p_username))',
'  AND    u.is_active = ''Y''',
'  AND    u.password_hash = RAWTOHEX(STANDARD_HASH(UPPER(TRIM(p_username)) || '':'' || p_password, ''SHA256''));',
'  RETURN l_ok = 1;',
'END;'))
,p_invalid_session_type=>'LOGIN'
,p_use_secure_cookie_yn=>'N'
,p_ras_mode=>0
,p_version_scn=>10329216
);
end;
/
