wwv_flow_imp_page.create_page(
 p_id=>30
,p_name=>unistr('\0642\064A\062F \064A\0648\0645\064A\0629')
,p_alias=>'JOURNAL'
,p_step_title=>unistr('\0642\064A\062F \064A\0648\0645\064A\0629')
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var jv = {',
'  grid: null,',
'  companies: [],',
'',
'  init: function () {',
'    var status = apex.item(''P30_STATUS'').getValue() || ''DRAFT'';',
'',
'    jv.grid = new JsonLines({',
'      container: ''#jv_lines'',',
'      readOnly : !DocUtil.canEdit(status),',
'      columns  : [',
unistr('        {name: ''ACCOUNT_ID'',  label: ''\0627\0644\062D\0633\0627\0628'', type: ''lov'', lov: ''accounts'', required: true, width: ''24em''},'),
unistr('        {name: ''DEBIT'',       label: ''\0645\062F\064A\0646'',   type: ''number'', decimals: 2, total: true, width: ''9em''},'),
unistr('        {name: ''CREDIT'',      label: ''\062F\0627\0626\0646'',   type: ''number'', decimals: 2, total: true, width: ''9em''},'),
unistr('        {name: ''DESCRIPTION'', label: ''\0627\0644\0628\064A\0627\0646'', type: ''text'', maxLength: 500, ignoreEmpty: true}'),
'      ],',
unistr('      // \0645\062F\064A\0646 \0623\0648 \062F\0627\0626\0646 \0641\0642\0637 \0641\064A \0627\0644\0633\0637\0631'),
'      onChange: function (row, col) {',
'        if (col === ''DEBIT''  && row.DEBIT)  row.CREDIT = null;',
'        if (col === ''CREDIT'' && row.CREDIT) row.DEBIT  = null;',
'      },',
unistr('      // \0627\0644\0633\0637\0631 \0627\0644\062C\062F\064A\062F \064A\0623\062E\0630 \0628\064A\0627\0646 \0627\0644\0633\0637\0631 \0627\0644\0633\0627\0628\0642 \0623\0648 \0628\064A\0627\0646 \0627\0644\0642\064A\062F'),
'      newRow: function (r, g) {',
'        var prev = g.rows.length ? g.rows[g.rows.length - 1] : null;',
'        r.DESCRIPTION = (prev && prev.DESCRIPTION) || apex.item(''P30_DESCRIPTION'').getValue() || null;',
'      },',
'      onTotals: function (t) {',
'        var d = (t.DEBIT || 0) - (t.CREDIT || 0), el = document.getElementById(''jv_diff'');',
unistr('        el.textContent = JsonLines.fmt(Math.abs(d), 2) + (Math.abs(d) < 0.005 ? '' \2714'' : (d > 0 ? '' (\0645\062F\064A\0646)'' : '' (\062F\0627\0626\0646)''));'),
'        el.className = ''jv-diff '' + (Math.abs(d) < 0.005 ? ''ok'' : ''bad'');',
'      }',
'    });',
'',
'    jv.load();',
'',
unistr('    // \062A\063A\064A\064A\0631 \0627\0644\0634\0631\0643\0629 \064A\0639\064A\062F \062A\062D\0645\064A\0644 \0627\0644\062D\0633\0627\0628\0627\062A (\0644\0643\0644 \0634\0631\0643\0629 \062D\0633\0627\0628\0627\062A\0647\0627 \0627\0644\062E\0627\0635\0629 + \0627\0644\0645\0634\062A\0631\0643\0629)'),
'    apex.jQuery(''#P30_COMPANY_ID'').on(''change'', jv.load);',
unistr('    // \062A\063A\064A\064A\0631 \0627\0644\0639\0645\0644\0629 \0623\0648 \0627\0644\062A\0627\0631\064A\062E \064A\062C\0644\0628 \0633\0639\0631 \0627\0644\0635\0631\0641'),
'    apex.jQuery(''#P30_CURRENCY_CODE, #P30_JOURNAL_DATE'').on(''change'', function () {',
'      DocUtil.loadRate(''P30_CURRENCY_CODE'', ''P30_JOURNAL_DATE'', ''P30_EXCHANGE_RATE'');',
'    });',
unistr('    // Ctrl+S = \062D\0641\0638 \0645\0633\0648\062F\0629'),
'    document.addEventListener(''keydown'', function (e) {',
'      if (e.ctrlKey && (e.key === ''s'' || e.key === ''S'')) { e.preventDefault(); jv.save(''DRAFT''); }',
'    });',
'',
'    EnterNav.first(''#main'');',
'  },',
'',
'  load: function () {',
'    var keep = jv.grid.getData();',
'    apex.server.process(''INIT_DATA'', {',
'      x01: apex.item(''P30_COMPANY_ID'').getValue(),',
'      x02: apex.item(''P30_JOURNAL_ID'').getValue()',
'    }, {dataType: ''json''}).done(function (d) {',
'      jv.companies = d.companies;',
'      jv.grid.setLov(''accounts'', d.accounts);',
'      jv.grid.setData(keep.length ? keep : d.lines);',
'    });',
'  },',
'',
'  save: function (action) {',
'    var errs = [], t = jv.grid.totals();',
unistr('    if (!apex.item(''P30_JT_CODE'').getValue())       errs.push(''\0627\062E\062A\0631 \0646\0648\0639 \0627\0644\0642\064A\062F'');'),
unistr('    if (!apex.item(''P30_JOURNAL_DATE'').getValue())  errs.push(''\0623\062F\062E\0644 \0627\0644\062A\0627\0631\064A\062E'');'),
unistr('    if (!apex.item(''P30_CURRENCY_CODE'').getValue()) errs.push(''\0627\062E\062A\0631 \0627\0644\0639\0645\0644\0629'');'),
'    errs = errs.concat(jv.grid.validate());',
unistr('    if (Math.abs((t.DEBIT || 0) - (t.CREDIT || 0)) >= 0.005) errs.push(''\0627\0644\0642\064A\062F \063A\064A\0631 \0645\062A\0648\0627\0632\0646'');'),
'    if (errs.length) { DocUtil.showErrors(errs); return; }',
'',
'    var doc = {',
'      header: {',
'        JOURNAL_ID   : apex.item(''P30_JOURNAL_ID'').getValue(),',
'        COMPANY_ID   : apex.item(''P30_COMPANY_ID'').getValue(),',
'        JT_CODE      : apex.item(''P30_JT_CODE'').getValue(),',
'        JOURNAL_DATE : apex.item(''P30_JOURNAL_DATE'').getValue(),',
'        CURRENCY_CODE: apex.item(''P30_CURRENCY_CODE'').getValue(),',
'        EXCHANGE_RATE: apex.item(''P30_EXCHANGE_RATE'').getValue(),',
'        REF_NO       : apex.item(''P30_REF_NO'').getValue(),',
'        DESCRIPTION  : apex.item(''P30_DESCRIPTION'').getValue()',
'      },',
'      lines: jv.grid.getData()',
'    };',
'',
'    var go = function () {',
'      DocUtil.save(doc, action, function (d) {',
unistr('        // \0625\0639\0627\062F\0629 \0641\062A\062D \0627\0644\0642\064A\062F \0627\0644\0645\062D\0641\0648\0638'),
'        apex.page.submit({request: ''RELOAD'', set: {P30_JOURNAL_ID: d.id}, showWait: true});',
'      });',
'    };',
'    go();',
'  },',
'',
'  remove: function () {',
unistr('    apex.message.confirm(''\062D\0630\0641 \0647\0630\0647 \0627\0644\0645\0633\0648\062F\0629 \0646\0647\0627\0626\064A\0627\064B\061F'', function (ok) {'),
'      if (!ok) return;',
'      apex.server.process(''DELETE_DOC'', {x01: apex.item(''P30_JOURNAL_ID'').getValue()}, {dataType: ''json''})',
'        .done(function (d) {',
'          if (d.ok) apex.navigation.redirect(''f?p=&APP_ID.:31:&SESSION.::NO:30'');',
unistr('          else DocUtil.showErrors([''\0644\0627 \064A\0645\0643\0646 \062D\0630\0641 \0647\0630\0627 \0627\0644\0642\064A\062F'']);'),
'        });',
'    });',
'  }',
'};'))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
