wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000172)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_acc   CLOB;',
'  l_comp  CLOB;',
'  l_lines CLOB;',
'BEGIN',
'  SELECT JSON_ARRAYAGG(JSON_OBJECT(''id'' VALUE account_id, ''code'' VALUE account_code, ''name'' VALUE name_ar)',
'                       ORDER BY account_code RETURNING CLOB)',
'  INTO   l_acc',
'  FROM   accounts',
'  WHERE  is_postable = ''Y'' AND is_active = ''Y''',
'  AND    (company_id IS NULL OR company_id = TO_NUMBER(apex_application.g_x01));',
'',
'  SELECT JSON_ARRAYAGG(JSON_OBJECT(''v'' VALUE company_id, ''t'' VALUE name_ar)',
'                       ORDER BY company_code RETURNING CLOB)',
'  INTO   l_comp',
'  FROM   companies WHERE is_active = ''Y'';',
'',
'  SELECT JSON_ARRAYAGG(JSON_OBJECT(',
'             ''ACCOUNT_ID''         VALUE account_id,',
'             ''DEBIT''              VALUE NULLIF(debit, 0),',
'             ''CREDIT''             VALUE NULLIF(credit, 0),',
'             ''DESCRIPTION''        VALUE description,',
'             ''PARTNER_COMPANY_ID'' VALUE partner_company_id',
'           ) ORDER BY line_no RETURNING CLOB)',
'  INTO   l_lines',
'  FROM   journal_lines',
'  WHERE  journal_id = TO_NUMBER(apex_application.g_x02);',
'',
'  apex_util.prn(''{"accounts":''  || COALESCE(l_acc,   TO_CLOB(''[]'')) ||',
'                '',"companies":'' || COALESCE(l_comp,  TO_CLOB(''[]'')) ||',
'                '',"lines":''     || COALESCE(l_lines, TO_CLOB(''[]'')) || ''}'', FALSE);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_name=>'INIT_DATA'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000172
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000173)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_clob     CLOB := apex_application.g_clob_01;',
'  l_action   VARCHAR2(10) := apex_application.g_x01;',
'  l_errs     apex_t_varchar2 := apex_t_varchar2();',
'',
'  l_id       NUMBER;',
'  l_company  NUMBER;',
'  l_jt       VARCHAR2(10);',
'  l_date_s   VARCHAR2(20);',
'  l_date     DATE;',
'  l_cur      VARCHAR2(3);',
'  l_rate     NUMBER;',
'  l_ref      VARCHAR2(50);',
'  l_desc     VARCHAR2(500);',
'',
'  l_status   VARCHAR2(10);',
'  l_no       VARCHAR2(30);',
'  l_src      VARCHAR2(10);',
'  l_prefix   VARCHAR2(10);',
'  l_seq      NUMBER;',
'  l_cnt      NUMBER;',
'  l_dr       NUMBER := 0;',
'  l_cr       NUMBER := 0;',
'  l_drb      NUMBER := 0;',
'  l_crb      NUMBER := 0;',
'  l_lines    NUMBER := 0;',
'  l_last     NUMBER;',
'',
'  PROCEDURE err (p VARCHAR2) IS',
'  BEGIN l_errs.EXTEND; l_errs(l_errs.COUNT) := p; END;',
'BEGIN',
unistr('  ---------------------------------------------------------------- \0642\0631\0627\0621\0629 \0627\0644\0631\0623\0633'),
'  SELECT h.journal_id, h.company_id, h.jt_code, h.journal_date,',
'         h.currency_code, h.exchange_rate, h.ref_no, h.description',
'  INTO   l_id, l_company, l_jt, l_date_s, l_cur, l_rate, l_ref, l_desc',
'  FROM   JSON_TABLE(l_clob, ''$.header'' COLUMNS (',
'           journal_id    NUMBER        PATH ''$.JOURNAL_ID'',',
'           company_id    NUMBER        PATH ''$.COMPANY_ID'',',
'           jt_code       VARCHAR2(10)  PATH ''$.JT_CODE'',',
'           journal_date  VARCHAR2(20)  PATH ''$.JOURNAL_DATE'',',
'           currency_code VARCHAR2(3)   PATH ''$.CURRENCY_CODE'',',
'           exchange_rate NUMBER        PATH ''$.EXCHANGE_RATE'',',
'           ref_no        VARCHAR2(50)  PATH ''$.REF_NO'',',
'           description   VARCHAR2(500) PATH ''$.DESCRIPTION'')) h;',
'',
'  BEGIN',
'    l_date := TO_DATE(l_date_s, ''DD/MM/YYYY'');',
unistr('  EXCEPTION WHEN OTHERS THEN err(''\062A\0627\0631\064A\062E \0627\0644\0642\064A\062F \063A\064A\0631 \0635\062D\064A\062D'');'),
'  END;',
'',
unistr('  ---------------------------------------------------------------- \0627\0644\062A\062D\0642\0642 \0645\0646 \0627\0644\0631\0623\0633'),
unistr('  IF :G_USER_ROLE NOT IN (''ADMIN'',''ENTRY'') THEN err(''\0625\062F\062E\0627\0644 \0627\0644\0642\064A\0648\062F \0648\062A\0639\062F\064A\0644\0647\0627 \0645\0646 \0635\0644\0627\062D\064A\0629 \0627\0644\0645\062F\062E\0644 \0641\0642\0637''); END IF;'),
unistr('  IF l_company IS NULL THEN err(''\0627\062E\062A\0631 \0627\0644\0634\0631\0643\0629''); END IF;'),
unistr('  IF l_jt      IS NULL THEN err(''\0627\062E\062A\0631 \0646\0648\0639 \0627\0644\0642\064A\062F''); END IF;'),
unistr('  IF l_cur     IS NULL THEN err(''\0627\062E\062A\0631 \0627\0644\0639\0645\0644\0629''); END IF;'),
unistr('  IF NVL(l_rate, 0) <= 0 THEN err(''\0633\0639\0631 \0627\0644\0635\0631\0641 \063A\064A\0631 \0635\062D\064A\062D''); END IF;'),
'',
'  SELECT COUNT(*) INTO l_cnt FROM dual',
'  WHERE  :G_USER_ROLE = ''ADMIN'' OR l_company = :G_COMPANY_ID',
'     OR  EXISTS (SELECT 1 FROM user_companies',
'                 WHERE user_name = UPPER(:APP_USER) AND company_id = l_company);',
unistr('  IF l_cnt = 0 THEN err(''\0644\064A\0633 \0644\062F\064A\0643 \0635\0644\0627\062D\064A\0629 \0639\0644\0649 \0647\0630\0647 \0627\0644\0634\0631\0643\0629''); END IF;'),
'',
unistr('  -- \0646\0648\0639 \0627\0644\0642\064A\062F: \064A\062F\0648\064A \0644\0644\0642\064A\062F \0627\0644\062C\062F\064A\062F \060C \0648\0627\0644\0642\064A\062F \0627\0644\0645\0648\062C\0648\062F (\0645\062B\0644 \062A\0633\0648\064A\0629 \0627\0644\0634\064A\0643\0627\062A) \064A\062D\062A\0641\0638 \0628\0646\0648\0639\0647'),
'  SELECT COUNT(*) INTO l_cnt FROM journal_types j',
'  WHERE  j.jt_code = l_jt AND j.is_active = ''Y''',
'  AND   (j.manual_allowed = ''Y'' OR EXISTS (SELECT 1 FROM journals x WHERE x.journal_id = l_id AND x.jt_code = l_jt));',
unistr('  IF l_cnt = 0 THEN err(''\0646\0648\0639 \0627\0644\0642\064A\062F \0644\0627 \064A\064F\062F\062E\0644 \064A\062F\0648\064A\0627\064B''); END IF;'),
'',
'  IF l_date IS NOT NULL THEN',
'    SELECT COUNT(*) INTO l_cnt FROM fiscal_years',
'    WHERE  l_date BETWEEN start_date AND end_date AND is_closed = ''N'';',
unistr('    IF l_cnt = 0 THEN err(''\0627\0644\062A\0627\0631\064A\062E \062E\0627\0631\062C \0633\0646\0629 \0645\0627\0644\064A\0629 \0645\0641\062A\0648\062D\0629''); END IF;'),
'  END IF;',
'',
unistr('  -- \0627\0644\0639\0645\0644\0629 \0627\0644\0623\0633\0627\0633\064A\0629 \0633\0639\0631\0647\0627 1 \062F\0627\0626\0645\0627\064B'),
'  SELECT COUNT(*) INTO l_cnt FROM currencies WHERE currency_code = l_cur AND is_base = ''Y'';',
'  IF l_cnt = 1 THEN l_rate := 1; END IF;',
'',
'  IF l_id IS NOT NULL THEN',
'    BEGIN',
'      SELECT status, journal_no, source_type INTO l_status, l_no, l_src',
'      FROM   journals WHERE journal_id = l_id FOR UPDATE;',
unistr('      IF l_src NOT IN (''MANUAL'',''CHEQUE'') THEN err(''\0647\0630\0627 \0627\0644\0642\064A\062F \0646\0627\062A\062C \0639\0646 \0645\0633\062A\0646\062F \0622\062E\0631 \0648\064A\064F\0639\062F\064E\0651\0644 \0645\0646 \0645\0633\062A\0646\062F\0647''); END IF;'),
unistr('      IF l_status NOT IN (''DRAFT'',''RETURNED'') THEN err(''\0627\0644\0642\064A\062F '' || l_no || '' \062A\0645\062A \0645\0631\0627\062C\0639\062A\0647 \0623\0648 \0627\0639\062A\0645\0627\062F\0647 \0623\0648 \062A\0631\062D\064A\0644\0647 \0648\0644\0627 \064A\0645\0643\0646 \062A\0639\062F\064A\0644\0647''); END IF;'),
unistr('    EXCEPTION WHEN NO_DATA_FOUND THEN err(''\0627\0644\0642\064A\062F \063A\064A\0631 \0645\0648\062C\0648\062F'');'),
'    END;',
'  END IF;',
'',
unistr('  ---------------------------------------------------------------- \0627\0644\062A\062D\0642\0642 \0645\0646 \0627\0644\0633\0637\0648\0631'),
'  FOR r IN (SELECT * FROM JSON_TABLE(l_clob, ''$.lines[*]'' COLUMNS (',
'                 line_no    NUMBER       PATH ''$.LINE_NO'',',
'                 account_id NUMBER       PATH ''$.ACCOUNT_ID'',',
'                 debit      NUMBER       PATH ''$.DEBIT'',',
'                 credit     NUMBER       PATH ''$.CREDIT''))) LOOP',
'    l_lines := l_lines + 1;',
'    IF r.account_id IS NULL THEN',
unistr('      err(''\0627\0644\0633\0637\0631 '' || r.line_no || '': \0627\0644\062D\0633\0627\0628 \0645\0637\0644\0648\0628'');'),
'    ELSE',
'      SELECT COUNT(*) INTO l_cnt FROM accounts',
'      WHERE  account_id = r.account_id AND is_postable = ''Y'' AND is_active = ''Y''',
'      AND    (company_id IS NULL OR company_id = l_company);',
unistr('      IF l_cnt = 0 THEN err(''\0627\0644\0633\0637\0631 '' || r.line_no || '': \0627\0644\062D\0633\0627\0628 \063A\064A\0631 \062A\062D\0644\064A\0644\064A \0623\0648 \0645\0648\0642\0648\0641 \0623\0648 \0644\0627 \064A\062A\0628\0639 \0627\0644\0634\0631\0643\0629''); END IF;'),
'    END IF;',
'    IF NVL(r.debit, 0) < 0 OR NVL(r.credit, 0) < 0 THEN',
unistr('      err(''\0627\0644\0633\0637\0631 '' || r.line_no || '': \0644\0627 \062A\064F\0642\0628\0644 \0645\0628\0627\0644\063A \0633\0627\0644\0628\0629'');'),
'    ELSIF (NVL(r.debit, 0) > 0 AND NVL(r.credit, 0) > 0) OR (NVL(r.debit, 0) = 0 AND NVL(r.credit, 0) = 0) THEN',
unistr('      err(''\0627\0644\0633\0637\0631 '' || r.line_no || '': \0623\062F\062E\0644 \0645\0628\0644\063A\0627\064B \0641\064A \0627\0644\0645\062F\064A\0646 \0623\0648 \0627\0644\062F\0627\0626\0646 \0641\0642\0637'');'),
'    END IF;',
'    l_dr := l_dr + NVL(r.debit, 0);',
'    l_cr := l_cr + NVL(r.credit, 0);',
'  END LOOP;',
'',
unistr('  IF l_lines < 2 THEN err(''\0627\0644\0642\064A\062F \064A\062D\062A\0627\062C \0633\0637\0631\064A\0646 \0639\0644\0649 \0627\0644\0623\0642\0644''); END IF;'),
'  IF ROUND(l_dr, 4) <> ROUND(l_cr, 4) THEN',
unistr('    err(''\0627\0644\0642\064A\062F \063A\064A\0631 \0645\062A\0648\0627\0632\0646: \0627\0644\0645\062F\064A\0646 '' || TO_CHAR(l_dr, ''FM999G999G999G990D00'') ||'),
unistr('        '' \0648\0627\0644\062F\0627\0626\0646 '' || TO_CHAR(l_cr, ''FM999G999G999G990D00''));'),
'  END IF;',
'',
unistr('  ---------------------------------------------------------------- \0639\0646\062F \0648\062C\0648\062F \0623\062E\0637\0627\0621'),
'  IF l_errs.COUNT > 0 THEN',
'    ROLLBACK;',
'    apex_json.open_object;',
'    apex_json.write(''ok'', FALSE);',
'    apex_json.write(''errors'', l_errs);',
'    apex_json.close_object;',
'    RETURN;',
'  END IF;',
'',
unistr('  ---------------------------------------------------------------- \0627\0644\062D\0641\0638'),
'  IF l_id IS NULL THEN',
unistr('    -- \0631\0642\0645 \062C\062F\064A\062F: \0627\0644\0628\0627\062F\0626\0629-\0627\0644\0633\0646\0629-\0645\0633\0644\0633\0644'),
'    SELECT prefix INTO l_prefix FROM journal_types WHERE jt_code = l_jt;',
'    UPDATE doc_sequences SET last_no = last_no + 1',
'    WHERE  company_id = l_company AND doc_type = l_jt AND fy_year = EXTRACT(YEAR FROM l_date)',
'    RETURNING last_no INTO l_seq;',
'    IF SQL%ROWCOUNT = 0 THEN',
'      INSERT INTO doc_sequences (company_id, doc_type, fy_year, last_no)',
'      VALUES (l_company, l_jt, EXTRACT(YEAR FROM l_date), 1);',
'      l_seq := 1;',
'    END IF;',
'    l_no := l_prefix || ''-'' || EXTRACT(YEAR FROM l_date) || ''-'' || LPAD(l_seq, 5, ''0'');',
'',
'    INSERT INTO journals (company_id, jt_code, journal_no, journal_date, currency_code, exchange_rate,',
'                          description, ref_no, status, source_type, created_by)',
'    VALUES (l_company, l_jt, l_no, l_date, l_cur, l_rate, l_desc, l_ref, ''DRAFT'', ''MANUAL'', :APP_USER)',
'    RETURNING journal_id INTO l_id;',
'  ELSE',
'    UPDATE journals',
'    SET    company_id = l_company, jt_code = l_jt, journal_date = l_date,',
'           currency_code = l_cur, exchange_rate = l_rate,',
'           description = l_desc, ref_no = l_ref',
'    WHERE  journal_id = l_id;',
'    DELETE FROM journal_lines WHERE journal_id = l_id;',
'  END IF;',
'',
'  INSERT INTO journal_lines (journal_id, line_no, account_id, debit, credit,',
'                             debit_base, credit_base, partner_company_id, description)',
'  SELECT l_id, ROWNUM, account_id, NVL(debit, 0), NVL(credit, 0),',
'         ROUND(NVL(debit, 0) * l_rate, 2), ROUND(NVL(credit, 0) * l_rate, 2),',
'         NULL, description',
'  FROM   JSON_TABLE(l_clob, ''$.lines[*]'' COLUMNS (',
'           account_id         NUMBER        PATH ''$.ACCOUNT_ID'',',
'           debit              NUMBER        PATH ''$.DEBIT'',',
'           credit             NUMBER        PATH ''$.CREDIT'',',
'           description        VARCHAR2(500) PATH ''$.DESCRIPTION''));',
'',
unistr('  -- \0641\0631\0642 \0627\0644\062A\0642\0631\064A\0628 \0628\0627\0644\0639\0645\0644\0629 \0627\0644\0623\0633\0627\0633\064A\0629 \064A\064F\0636\0627\0641 \0639\0644\0649 \0622\062E\0631 \0633\0637\0631 \062F\0627\0626\0646'),
'  SELECT SUM(debit_base), SUM(credit_base) INTO l_drb, l_crb',
'  FROM   journal_lines WHERE journal_id = l_id;',
'  IF l_drb <> l_crb THEN',
'    SELECT MAX(line_id) INTO l_last FROM journal_lines WHERE journal_id = l_id AND credit > 0;',
'    UPDATE journal_lines SET credit_base = credit_base + (l_drb - l_crb) WHERE line_id = l_last;',
'  END IF;',
'',
'  UPDATE journals',
'  SET    total_debit = l_dr, total_credit = l_cr,',
'         status = ''DRAFT'', return_note = NULL',
'  WHERE  journal_id = l_id;',
'  INSERT INTO doc_actions (doc_type, doc_id, action, from_status, to_status, action_by)',
'  VALUES (''JOURNAL'', l_id, ''SAVE'', l_status, ''DRAFT'', :APP_USER);',
'',
'  apex_json.open_object;',
'  apex_json.write(''ok'', TRUE);',
'  apex_json.write(''id'', l_id);',
'  apex_json.write(''no'', l_no);',
unistr('  apex_json.write(''message'', ''\062A\0645 \062D\0641\0638 \0627\0644\0642\064A\062F '' || l_no || '' - \0628\0627\0646\062A\0638\0627\0631 \0627\0644\0645\0631\0627\062C\0639\0629'');'),
'  apex_json.close_object;',
'EXCEPTION',
'  WHEN OTHERS THEN',
'    ROLLBACK;',
'    apex_json.open_object;',
'    apex_json.write(''ok'', FALSE);',
'    apex_json.open_array(''errors'');',
'    apex_json.write(SQLERRM);',
'    apex_json.close_array;',
'    apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_name=>'SAVE_DOC'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000173
);
