wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000224)
,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_process_clob_language=>'PLSQL'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('  -- \062F\0648\0631\0629 \0627\0644\0645\0633\062A\0646\062F: \0645\0633\0648\062F\0629 -> \0645\064F\0631\0627\062C\064E\0639 -> \0645\0639\062A\0645\062F -> \0645\0631\062D\0651\0644 \060C \0648\0627\0644\0625\0639\0627\062F\0629 \0644\0644\0645\062F\062E\0644 \0645\0639 \0627\0644\0633\0628\0628'),
unistr('  -- \0627\0644\0645\0631\0627\062C\0639: \0645\0631\0627\062C\0639\0629 / \0625\0644\063A\0627\0621 \0627\0644\0645\0631\0627\062C\0639\0629 / \0625\0639\0627\062F\0629 \060C \0627\0644\0645\0639\062A\0645\062F: \0627\0639\062A\0645\0627\062F / \0625\0644\063A\0627\0621 \0627\0644\0627\0639\062A\0645\0627\062F / \0625\0639\0627\062F\0629 / \062A\0631\062D\064A\0644 \060C \0645\062F\064A\0631 \0627\0644\0646\0638\0627\0645: \0627\0644\0643\0644'),
'  l_id    NUMBER        := :P40_VOUCHER_ID;',
'  l_req   VARCHAR2(20)  := :REQUEST;',
'  l_role  VARCHAR2(20)  := :G_USER_ROLE;',
'  l_note  VARCHAR2(500) := SUBSTR(TRIM(:P40_WF_NOTE), 1, 500);',
'  l_st    VARCHAR2(10);',
'  l_new   VARCHAR2(10);',
'  l_err   VARCHAR2(400);',
'  l_msg   VARCHAR2(200);',
'  FUNCTION has (p_roles VARCHAR2) RETURN BOOLEAN IS',
'  BEGIN RETURN l_role = ''ADMIN'' OR INSTR('','' || p_roles || '','', '','' || l_role || '','') > 0; END;',
'BEGIN',
'  IF apex_error.have_errors_occurred THEN RETURN; END IF;',
'  IF l_id IS NULL THEN',
unistr('    l_err := ''\0627\062D\0641\0638 \0627\0644\0645\0633\062A\0646\062F \0623\0648\0644\0627\064B'';'),
'  ELSE',
'    SELECT status INTO l_st FROM vouchers WHERE voucher_id = l_id FOR UPDATE;',
'    CASE l_req',
'      WHEN ''REVIEW'' THEN',
unistr('        IF NOT has(''REVIEWER'') THEN l_err := ''\0627\0644\0645\0631\0627\062C\0639\0629 \0645\0646 \0635\0644\0627\062D\064A\0629 \0627\0644\0645\0631\0627\062C\0639'';'),
unistr('        ELSIF l_st <> ''DRAFT'' THEN l_err := ''\0644\0627 \064A\064F\0631\0627\062C\0639 \0625\0644\0627 \0627\0644\0645\0633\062A\0646\062F \0641\064A \062D\0627\0644\0629 \0645\0633\0648\062F\0629'';'),
unistr('        ELSE l_new := ''REVIEWED''; l_msg := ''\062A\0645\062A \0627\0644\0645\0631\0627\062C\0639\0629''; END IF;'),
'      WHEN ''UNREVIEW'' THEN',
unistr('        IF NOT has(''REVIEWER'') THEN l_err := ''\0625\0644\063A\0627\0621 \0627\0644\0645\0631\0627\062C\0639\0629 \0645\0646 \0635\0644\0627\062D\064A\0629 \0627\0644\0645\0631\0627\062C\0639'';'),
unistr('        ELSIF l_st <> ''REVIEWED'' THEN l_err := ''\0627\0644\0645\0633\062A\0646\062F \0644\064A\0633 \0641\064A \062D\0627\0644\0629 \0645\064F\0631\0627\062C\064E\0639 (\0631\0628\0645\0627 \062A\0645 \0627\0639\062A\0645\0627\062F\0647)'';'),
unistr('        ELSE l_new := ''DRAFT''; l_msg := ''\062A\0645 \0625\0644\063A\0627\0621 \0627\0644\0645\0631\0627\062C\0639\0629''; END IF;'),
'      WHEN ''APPROVE'' THEN',
unistr('        IF NOT has(''APPROVER'') THEN l_err := ''\0627\0644\0627\0639\062A\0645\0627\062F \0645\0646 \0635\0644\0627\062D\064A\0629 \0627\0644\0645\0639\062A\0645\062F'';'),
unistr('        ELSIF l_st <> ''REVIEWED'' THEN l_err := ''\0644\0627 \064A\064F\0639\062A\0645\062F \0625\0644\0627 \0627\0644\0645\0633\062A\0646\062F \0627\0644\0645\064F\0631\0627\062C\064E\0639'';'),
unistr('        ELSIF ''Y'' = ''Y'' THEN l_new := ''POSTED''; l_msg := ''\062A\0645 \0627\0644\0627\0639\062A\0645\0627\062F \0648\0627\0644\062A\0631\062D\064A\0644'';'),
unistr('        ELSE l_new := ''APPROVED''; l_msg := ''\062A\0645 \0627\0644\0627\0639\062A\0645\0627\062F''; END IF;'),
'      WHEN ''UNAPPROVE'' THEN',
unistr('        IF NOT has(''APPROVER'') THEN l_err := ''\0625\0644\063A\0627\0621 \0627\0644\0627\0639\062A\0645\0627\062F \0645\0646 \0635\0644\0627\062D\064A\0629 \0627\0644\0645\0639\062A\0645\062F'';'),
unistr('        ELSIF l_st <> ''APPROVED'' THEN l_err := ''\0627\0644\0645\0633\062A\0646\062F \0644\064A\0633 \0641\064A \062D\0627\0644\0629 \0645\0639\062A\0645\062F (\0631\0628\0645\0627 \062A\0645 \062A\0631\062D\064A\0644\0647)'';'),
unistr('        ELSE l_new := ''REVIEWED''; l_msg := ''\062A\0645 \0625\0644\063A\0627\0621 \0627\0644\0627\0639\062A\0645\0627\062F''; END IF;'),
'      WHEN ''RETURN'' THEN',
'        IF NOT ((has(''REVIEWER'') AND l_st IN (''DRAFT'',''REVIEWED'')) OR (has(''APPROVER'') AND l_st IN (''REVIEWED'',''APPROVED''))) THEN',
unistr('          l_err := ''\0644\0627 \064A\0645\0643\0646\0643 \0625\0639\0627\062F\0629 \0647\0630\0627 \0627\0644\0645\0633\062A\0646\062F \0641\064A \062D\0627\0644\062A\0647 \0627\0644\062D\0627\0644\064A\0629'';'),
unistr('        ELSIF l_note IS NULL THEN l_err := ''\0627\0643\062A\0628 \0633\0628\0628 \0627\0644\0625\0639\0627\062F\0629'';'),
unistr('        ELSE l_new := ''RETURNED''; l_msg := ''\062A\0645\062A \0625\0639\0627\062F\0629 \0627\0644\0645\0633\062A\0646\062F \0644\0644\0645\062F\062E\0644''; END IF;'),
'      WHEN ''POST'' THEN',
unistr('        IF ''Y'' <> ''Y'' THEN l_err := ''\0647\0630\0627 \0627\0644\0645\0633\062A\0646\062F \0644\0627 \064A\064F\0631\062D\0651\0644'';'),
unistr('        ELSIF NOT has(''APPROVER'') THEN l_err := ''\0627\0644\062A\0631\062D\064A\0644 \0645\0646 \0635\0644\0627\062D\064A\0629 \0627\0644\0645\0639\062A\0645\062F'';'),
unistr('        ELSIF l_st <> ''APPROVED'' THEN l_err := ''\0644\0627 \064A\064F\0631\062D\0651\0644 \0625\0644\0627 \0627\0644\0645\0633\062A\0646\062F \0627\0644\0645\0639\062A\0645\062F'';'),
unistr('        ELSE l_new := ''POSTED''; l_msg := ''\062A\0645 \0627\0644\062A\0631\062D\064A\0644''; END IF;'),
unistr('      ELSE l_err := ''\0625\062C\0631\0627\0621 \063A\064A\0631 \0645\0639\0631\0648\0641'';'),
'    END CASE;',
'  END IF;',
'',
unistr('  -- \0634\0631\0637 \0625\0636\0627\0641\064A \062E\0627\0635 \0628\0627\0644\0645\0633\062A\0646\062F (\0645\062B\0644: \0625\0630\0646 \0627\0644\0634\064A\0643\0627\062A \0644\0627 \064A\064F\0631\0627\062C\0639 \0642\0628\0644 \062C\062F\0648\0644\0629 \0634\064A\0643\0627\062A\0647)'),
'  IF l_err IS NULL AND l_req IN (''REVIEW'',''APPROVE'') THEN',
'    NULL;',
'  END IF;',
'',
'  IF l_err IS NOT NULL THEN',
'    apex_error.add_error(p_message => l_err, p_display_location => apex_error.c_inline_in_notification);',
'    RETURN;',
'  END IF;',
'',
unistr('  -- \0627\0644\062A\0631\062D\064A\0644 \064A\062A\0645 \0645\0628\0627\0634\0631\0629 \0639\0646\062F \0627\0644\0627\0639\062A\0645\0627\062F'),
'  IF l_new = ''POSTED'' THEN',
'    DECLARE',
unistr('      -- \062A\0631\062D\064A\0644 \0627\0644\0625\0630\0646 (\0646\0642\062F\064A \0623\0648 \0634\064A\0643\0627\062A) = \0625\0646\0634\0627\0621 \0642\064A\062F \0645\0631\062D\0651\0644 \0628\0646\0641\0633 \0631\0642\0645 \0627\0644\0625\0630\0646'),
unistr('      --   \062A\0648\0631\064A\062F \0646\0642\062F\064A : \0645\0646 \062D/ \0627\0644\062E\0632\064A\0646\0629            \0625\0644\0649 \062D/ \0627\0644\062D\0633\0627\0628 \0627\0644\0645\0642\0627\0628\0644'),
unistr('      --   \0635\0631\0641 \0646\0642\062F\064A   : \0645\0646 \062D/ \0627\0644\062D\0633\0627\0628 \0627\0644\0645\0642\0627\0628\0644     \0625\0644\0649 \062D/ \0627\0644\062E\0632\064A\0646\0629'),
unistr('      --   \062A\0648\0631\064A\062F \0634\064A\0643\0627\062A: \0645\0646 \062D/ \0634\064A\0643\0627\062A \062A\062D\062A \0627\0644\062A\062D\0635\064A\0644  \0625\0644\0649 \062D/ \0627\0644\062D\0633\0627\0628 \0627\0644\0645\0642\0627\0628\0644'),
unistr('      --   \0635\0631\0641 \0634\064A\0643\0627\062A  : \0645\0646 \062D/ \0627\0644\062D\0633\0627\0628 \0627\0644\0645\0642\0627\0628\0644     \0625\0644\0649 \062D/ \0634\064A\0643\0627\062A \062A\062D\062A \0627\0644\0635\0631\0641'),
'      v     vouchers%ROWTYPE;',
'      l_jt  VARCHAR2(10);',
'      l_mid NUMBER;',
'      l_jid NUMBER;',
'      l_amt NUMBER;',
'      l_r   NUMBER;',
'      l_p   NUMBER;',
'    BEGIN',
'      SELECT * INTO v FROM vouchers WHERE voucher_id = l_id;',
'      IF v.voucher_kind = ''CHEQUE'' THEN',
'        l_jt := CASE v.voucher_type WHEN ''R'' THEN ''CR'' ELSE ''CP'' END;',
'        BEGIN',
'          SELECT account_id INTO l_mid FROM account_settings',
'          WHERE  company_id = v.company_id',
'          AND    setting_code = CASE v.voucher_type WHEN ''R'' THEN ''CHEQUES_IN'' ELSE ''CHEQUES_OUT'' END;',
'        EXCEPTION WHEN NO_DATA_FOUND THEN',
unistr('          raise_application_error(-20001, ''\062D\062F\062F \062D\0633\0627\0628 \0627\0644\0634\064A\0643\0627\062A \062A\062D\062A \0627\0644\062A\062D\0635\064A\0644 / \062A\062D\062A \0627\0644\0635\0631\0641 \0641\064A \0627\0644\062D\0633\0627\0628\0627\062A \0627\0644\0627\0641\062A\0631\0627\0636\064A\0629'');'),
'        END;',
'      ELSE',
'        l_jt  := CASE v.voucher_type WHEN ''R'' THEN ''RV'' ELSE ''PV'' END;',
'        l_mid := v.cash_account_id;',
'      END IF;',
'      IF v.counter_account_id IS NULL OR l_mid IS NULL THEN',
unistr('        raise_application_error(-20001, ''\0627\0644\0625\0630\0646 \064A\0646\0642\0635\0647 \0627\0644\062D\0633\0627\0628 \0627\0644\0645\0642\0627\0628\0644 \0623\0648 \062D\0633\0627\0628 \0627\0644\062E\0632\064A\0646\0629'');'),
'      END IF;',
'',
'      l_amt := v.total_amount;',
unistr('      l_r   := CASE v.voucher_type WHEN ''R'' THEN l_amt ELSE 0 END;   -- \0645\062F\064A\0646 \0627\0644\062D\0633\0627\0628 \0627\0644\0648\0633\064A\0637 \0641\064A \0627\0644\062A\0648\0631\064A\062F'),
unistr('      l_p   := CASE v.voucher_type WHEN ''P'' THEN l_amt ELSE 0 END;   -- \062F\0627\0626\0646 \0627\0644\062D\0633\0627\0628 \0627\0644\0648\0633\064A\0637 \0641\064A \0627\0644\0635\0631\0641'),
'',
'      IF v.journal_id IS NOT NULL THEN',
unistr('        -- \0625\0630\0646 \0623\064F\0639\064A\062F \0644\0644\0645\0633\0648\062F\0629 \0628\0627\0644\0639\0643\0633 \062B\0645 \0627\0639\062A\064F\0645\062F \0645\0646 \062C\062F\064A\062F: \064A\064F\062D\062F\064E\0651\062B \0642\064A\062F\0647 \0646\0641\0633\0647'),
'        l_jid := v.journal_id;',
'        UPDATE journals',
'        SET    journal_date = v.voucher_date, description = NVL(v.description, journal_no), status = ''POSTED'',',
'               total_debit = l_amt, total_credit = l_amt, reviewed_by = v.reviewed_by, reviewed_on = v.reviewed_on,',
'               approved_by = v.approved_by, approved_on = v.approved_on, posted_by = :APP_USER, posted_on = SYSDATE,',
'               return_note = NULL',
'        WHERE  journal_id = l_jid;',
'        DELETE FROM journal_lines WHERE journal_id = l_jid;',
'      ELSE',
'      INSERT INTO journals (company_id, jt_code, journal_no, journal_date, currency_code, exchange_rate,',
'                            description, status, source_type, source_id, total_debit, total_credit,',
'                            created_by, reviewed_by, reviewed_on, approved_by, approved_on, posted_by, posted_on)',
'      VALUES (v.company_id, l_jt, v.voucher_no, v.voucher_date, v.currency_code, v.exchange_rate,',
unistr('              NVL(v.description, CASE v.voucher_type WHEN ''R'' THEN ''\0625\0630\0646 \062A\0648\0631\064A\062F '' ELSE ''\0625\0630\0646 \0635\0631\0641 '' END || v.voucher_no),'),
'              ''POSTED'', ''VOUCHER'', v.voucher_id, l_amt, l_amt,',
'              v.created_by, v.reviewed_by, v.reviewed_on, v.approved_by, v.approved_on, :APP_USER, SYSDATE)',
'      RETURNING journal_id INTO l_jid;',
'      END IF;',
'',
'      INSERT INTO journal_lines (journal_id, line_no, account_id, debit, credit, debit_base, credit_base, description)',
'      VALUES (l_jid, 1, l_mid, l_r, l_p, ROUND(l_r * v.exchange_rate, 2), ROUND(l_p * v.exchange_rate, 2),',
'              NVL(v.party_name, v.description));',
'      INSERT INTO journal_lines (journal_id, line_no, account_id, debit, credit, debit_base, credit_base, description)',
'      VALUES (l_jid, 2, v.counter_account_id, l_p, l_r, ROUND(l_p * v.exchange_rate, 2), ROUND(l_r * v.exchange_rate, 2),',
'              NVL(v.description, v.party_name));',
'',
'      UPDATE vouchers SET journal_id = l_jid WHERE voucher_id = l_id;',
'    END;',
'  END IF;',
'',
'  UPDATE vouchers',
'  SET    status      = l_new,',
'         reviewed_by = CASE WHEN l_req = ''REVIEW'' THEN :APP_USER WHEN l_req IN (''UNREVIEW'',''RETURN'') THEN NULL ELSE reviewed_by END,',
'         reviewed_on = CASE WHEN l_req = ''REVIEW'' THEN SYSDATE   WHEN l_req IN (''UNREVIEW'',''RETURN'') THEN NULL ELSE reviewed_on END,',
'         approved_by = CASE WHEN l_req = ''APPROVE'' THEN :APP_USER WHEN l_req IN (''UNAPPROVE'',''RETURN'') THEN NULL ELSE approved_by END,',
'         approved_on = CASE WHEN l_req = ''APPROVE'' THEN SYSDATE   WHEN l_req IN (''UNAPPROVE'',''RETURN'') THEN NULL ELSE approved_on END,',
'         return_note = CASE WHEN l_req = ''RETURN'' THEN l_note ELSE return_note END',
'  WHERE  voucher_id = l_id;',
'',
'  INSERT INTO doc_actions (doc_type, doc_id, action, from_status, to_status, note, action_by)',
'  VALUES (''VOUCHER'', l_id, l_req, l_st, l_new, l_note, :APP_USER);',
'',
'  :P40_WF_NOTE := NULL;',
'  apex_application.g_print_success_message := l_msg;',
'END;'))
,p_process_name=>'WORKFLOW'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'REVIEW,UNREVIEW,APPROVE,UNAPPROVE,RETURN,POST'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_internal_uid=>91000000000224
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000225)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  r vouchers%ROWTYPE;',
'BEGIN',
'  SELECT * INTO r FROM vouchers WHERE voucher_id = :P40_VOUCHER_ID;',
'  :P40_VOUCHER_TYPE       := r.voucher_type;',
'  :P40_VOUCHER_NO         := r.voucher_no;',
'  :P40_VOUCHER_DATE       := TO_CHAR(r.voucher_date, ''DD/MM/YYYY'');',
'  :P40_CASH_ACCOUNT_ID    := r.cash_account_id;',
'  :P40_COUNTER_ACCOUNT_ID := r.counter_account_id;',
'  :P40_AMOUNT             := TO_CHAR(r.total_amount, ''FM999G999G999G990D00'');',
'  :P40_PARTY_NAME         := r.party_name;',
'  :P40_DESCRIPTION        := r.description;',
'  :P40_STATUS             := r.status;',
'  :P40_JOURNAL_ID         := r.journal_id;',
'  :P40_RETURN_NOTE := CASE WHEN r.status IN (''RETURNED'',''DRAFT'') THEN r.return_note END;',
unistr(':P40_WF_INFO := TRIM(CASE WHEN r.reviewed_by IS NOT NULL THEN ''\0631\0627\062C\0639\0647 '' || r.reviewed_by || '' '' || TO_CHAR(r.reviewed_on, ''DD/MM/YYYY HH24:MI'') END || CASE WHEN r.approved_by IS NOT NULL THEN '' - \0627\0639\062A\0645\062F\0647 '' || r.approved_by || '' '' || TO_CHAR(r.approved_on, ''DD/MM/YYYY HH24:MI'') END);'),
'END;'))
,p_process_type=>'NATIVE_PLSQL'
,p_process_clob_language=>'PLSQL'
,p_process_name=>'LOAD_HEADER'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':P40_VOUCHER_ID IS NOT NULL'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>91000000000225
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000226)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_clob_language=>'PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P40_VOUCHER_TYPE IS NULL OR :P40_VOUCHER_TYPE NOT IN (''R'',''P'') THEN :P40_VOUCHER_TYPE := ''R''; END IF;',
'IF :P40_VOUCHER_ID IS NULL THEN',
'  :P40_STATUS := NULL;',
'  IF :P40_VOUCHER_DATE IS NULL THEN :P40_VOUCHER_DATE := TO_CHAR(SYSDATE, ''DD/MM/YYYY''); END IF;',
'END IF;',
'IF :P40_VOUCHER_ID IS NULL THEN',
'  SELECT CASE :P40_VOUCHER_TYPE WHEN ''R'' THEN ''11'' ELSE ''12'' END || EXTRACT(YEAR FROM NVL(TO_DATE(:P40_VOUCHER_DATE, ''DD/MM/YYYY''), SYSDATE)) || LPAD(NVL(MAX(last_no), 0) + 1, 5, ''0'') INTO :P40_VOUCHER_NO FROM doc_sequences',
'  WHERE company_id = NVL(:G_COMPANY_ID, :G_PARENT_ID) AND doc_type = CASE :P40_VOUCHER_TYPE WHEN ''R'' THEN ''11'' ELSE ''12'' END AND fy_year = EXTRACT(YEAR FROM NVL(TO_DATE(:P40_VOUCHER_DATE, ''DD/MM/YYYY''), SYSDATE));',
'END IF;',
unistr(':P40_TITLE := CASE :P40_VOUCHER_TYPE WHEN ''R'' THEN ''\0625\0630\0646 \062A\0648\0631\064A\062F \0646\0642\062F\064A'' ELSE ''\0625\0630\0646 \0635\0631\0641 \0646\0642\062F\064A'' END;'),
unistr(':P40_PARTY_LABEL := CASE :P40_VOUCHER_TYPE WHEN ''R'' THEN ''\0627\0633\062A\0644\0645\0646\0627 \0645\0646'' ELSE ''\0635\0631\0641\0646\0627 \0625\0644\0649'' END;')))
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'DEFAULTS'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000226
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000227)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_clob_language=>'PLSQL'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('  -- \062D\0641\0638 \0625\0630\0646 \0627\0644\062A\0648\0631\064A\062F / \0627\0644\0635\0631\0641 \0627\0644\0646\0642\062F\064A (\0627\0644\062D\0633\0627\0628 \0627\0644\0645\0642\0627\0628\0644 \0648\0627\0644\0645\0628\0644\063A \0648\0627\0644\0628\064A\0627\0646 \0641\064A \0627\0644\0631\0623\0633 \0645\0628\0627\0634\0631\0629)'),
unistr('  -- \0627\0644\062A\0631\0642\064A\0645: 11 \062A\0648\0631\064A\062F \0646\0642\062F\064A / 12 \0635\0631\0641 \0646\0642\062F\064A + \0627\0644\0633\0646\0629 + 5 \062E\0627\0646\0627\062A \062A\0633\0644\0633\0644'),
'  l_id    NUMBER       := :P40_VOUCHER_ID;',
'  l_type  VARCHAR2(1)  := :P40_VOUCHER_TYPE;',
'  l_co    NUMBER       := NVL(:G_COMPANY_ID, :G_PARENT_ID);',
'  l_cash  NUMBER       := :P40_CASH_ACCOUNT_ID;',
'  l_acc   NUMBER       := :P40_COUNTER_ACCOUNT_ID;',
'  l_date  DATE;',
'  l_amt   NUMBER;',
'  l_st    VARCHAR2(10);',
'  l_no    VARCHAR2(30);',
'  l_code  VARCHAR2(2);',
'  l_seq   NUMBER;',
'  l_cnt   NUMBER;',
'  l_cur   VARCHAR2(3);',
'  PROCEDURE err (p VARCHAR2) IS',
'  BEGIN apex_error.add_error(p_message => p, p_display_location => apex_error.c_inline_in_notification); END;',
'BEGIN',
unistr('  IF :G_USER_ROLE NOT IN (''ADMIN'',''ENTRY'') THEN err(''\0625\062F\062E\0627\0644 \0627\0644\0623\0630\0648\0646\0627\062A \0648\062A\0639\062F\064A\0644\0647\0627 \0645\0646 \0635\0644\0627\062D\064A\0629 \0627\0644\0645\062F\062E\0644 \0641\0642\0637''); RETURN; END IF;'),
unistr('  IF l_type NOT IN (''R'',''P'') OR l_type IS NULL THEN err(''\0646\0648\0639 \0627\0644\0625\0630\0646 \063A\064A\0631 \0645\0639\0631\0648\0641''); RETURN; END IF;'),
'',
'  BEGIN l_date := TO_DATE(:P40_VOUCHER_DATE, ''DD/MM/YYYY'');',
unistr('  EXCEPTION WHEN OTHERS THEN err(''\062A\0627\0631\064A\062E \0627\0644\0625\0630\0646 \063A\064A\0631 \0635\062D\064A\062D''); END;'),
unistr('  IF l_date IS NULL THEN err(''\0623\062F\062E\0644 \062A\0627\0631\064A\062E \0627\0644\0625\0630\0646''); END IF;'),
'',
'  BEGIN l_amt := TO_NUMBER(REPLACE(:P40_AMOUNT, '','', ''''));',
unistr('  EXCEPTION WHEN OTHERS THEN err(''\0627\0644\0645\0628\0644\063A \063A\064A\0631 \0635\062D\064A\062D''); END;'),
unistr('  IF NVL(l_amt, 0) <= 0 THEN err(''\0623\062F\062E\0644 \0645\0628\0644\063A\0627\064B \0623\0643\0628\0631 \0645\0646 \0635\0641\0631''); END IF;'),
'',
unistr('  IF l_cash IS NULL THEN err(''\0627\062E\062A\0631 \0627\0644\062E\0632\064A\0646\0629'');'),
'  ELSE',
'    SELECT COUNT(*) INTO l_cnt FROM accounts WHERE account_id = l_cash AND cash_bank IN (''C'',''B'') AND is_active = ''Y'';',
unistr('    IF l_cnt = 0 THEN err(''\062D\0633\0627\0628 \0627\0644\062E\0632\064A\0646\0629 \063A\064A\0631 \0635\062D\064A\062D''); END IF;'),
'  END IF;',
'',
unistr('  IF l_acc IS NULL THEN err(''\0627\062E\062A\0631 \0627\0644\062D\0633\0627\0628 \0627\0644\0645\0642\0627\0628\0644'');'),
'  ELSE',
'    SELECT COUNT(*) INTO l_cnt FROM accounts WHERE account_id = l_acc AND is_postable = ''Y'' AND is_active = ''Y'';',
unistr('    IF l_cnt = 0 THEN err(''\0627\0644\062D\0633\0627\0628 \0627\0644\0645\0642\0627\0628\0644 \064A\062C\0628 \0623\0646 \064A\0643\0648\0646 \062D\0633\0627\0628\0627\064B \062A\062D\0644\064A\0644\064A\0627\064B \0641\0639\0651\0627\0644\0627\064B'');'),
unistr('    ELSIF l_acc = l_cash THEN err(''\0627\0644\062D\0633\0627\0628 \0627\0644\0645\0642\0627\0628\0644 \0644\0627 \064A\0643\0648\0646 \0647\0648 \062D\0633\0627\0628 \0627\0644\062E\0632\064A\0646\0629 \0646\0641\0633\0647''); END IF;'),
'  END IF;',
'',
unistr('  IF TRIM(:P40_DESCRIPTION) IS NULL THEN err(''\0623\062F\062E\0644 \0627\0644\0628\064A\0627\0646''); END IF;'),
'',
'  IF l_date IS NOT NULL THEN',
'    SELECT COUNT(*) INTO l_cnt FROM fiscal_years WHERE l_date BETWEEN start_date AND end_date AND is_closed = ''N'';',
unistr('    IF l_cnt = 0 THEN err(''\0627\0644\062A\0627\0631\064A\062E \062E\0627\0631\062C \0633\0646\0629 \0645\0627\0644\064A\0629 \0645\0641\062A\0648\062D\0629''); END IF;'),
'  END IF;',
'',
'  IF l_id IS NOT NULL THEN',
'    BEGIN',
'      SELECT status, voucher_no INTO l_st, l_no FROM vouchers WHERE voucher_id = l_id FOR UPDATE;',
unistr('      IF l_st NOT IN (''DRAFT'',''RETURNED'') THEN err(''\0627\0644\0625\0630\0646 '' || l_no || '' \062A\0645\062A \0645\0631\0627\062C\0639\062A\0647 \0623\0648 \0627\0639\062A\0645\0627\062F\0647 \0648\0644\0627 \064A\0645\0643\0646 \062A\0639\062F\064A\0644\0647''); END IF;'),
unistr('    EXCEPTION WHEN NO_DATA_FOUND THEN err(''\0627\0644\0625\0630\0646 \063A\064A\0631 \0645\0648\062C\0648\062F'');'),
'    END;',
'  END IF;',
'',
'  IF apex_error.have_errors_occurred THEN RETURN; END IF;',
'',
'  SELECT currency_code INTO l_cur FROM currencies WHERE is_base = ''Y'';',
'',
'  IF l_id IS NULL THEN',
'    l_code := CASE l_type WHEN ''R'' THEN ''11'' ELSE ''12'' END;',
'    UPDATE doc_sequences SET last_no = last_no + 1',
'    WHERE  company_id = l_co AND doc_type = l_code AND fy_year = EXTRACT(YEAR FROM l_date)',
'    RETURNING last_no INTO l_seq;',
'    IF SQL%ROWCOUNT = 0 THEN',
'      INSERT INTO doc_sequences (company_id, doc_type, fy_year, last_no) VALUES (l_co, l_code, EXTRACT(YEAR FROM l_date), 1);',
'      l_seq := 1;',
'    END IF;',
'    l_no := l_code || EXTRACT(YEAR FROM l_date) || LPAD(l_seq, 5, ''0'');',
'',
'    INSERT INTO vouchers (company_id, voucher_type, voucher_kind, voucher_no, voucher_date, cash_account_id,',
'                          counter_account_id, currency_code, exchange_rate, pay_method, party_name,',
'                          description, total_amount, status, created_by)',
'    VALUES (l_co, l_type, ''CASH'', l_no, l_date, l_cash, l_acc, l_cur, 1, ''CASH'', :P40_PARTY_NAME,',
'            :P40_DESCRIPTION, l_amt, ''DRAFT'', :APP_USER)',
'    RETURNING voucher_id INTO l_id;',
'    :P40_VOUCHER_ID := l_id;',
'    l_st := NULL;',
'  ELSE',
'    UPDATE vouchers',
'    SET    voucher_date = l_date, cash_account_id = l_cash, counter_account_id = l_acc,',
'           party_name = :P40_PARTY_NAME, description = :P40_DESCRIPTION, total_amount = l_amt,',
'           status = ''DRAFT'', return_note = NULL',
'    WHERE  voucher_id = l_id;',
'  END IF;',
'',
'  INSERT INTO doc_actions (doc_type, doc_id, action, from_status, to_status, action_by)',
'  VALUES (''VOUCHER'', l_id, ''SAVE'', l_st, ''DRAFT'', :APP_USER);',
'',
unistr('  apex_application.g_print_success_message := ''\062A\0645 \062D\0641\0638 \0627\0644\0625\0630\0646 '' || l_no || '' - \0628\0627\0646\062A\0638\0627\0631 \0627\0644\0645\0631\0627\062C\0639\0629'';'),
'END;'))
,p_process_name=>'SAVE_DOC'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(91000000000212)
,p_internal_uid=>91000000000227
);
