,p_step_title=>'&P45_TITLE.'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('// \0625\0630\0646 \062A\0648\0631\064A\062F / \0635\0631\0641 \0634\064A\0643\0627\062A: \0627\0644\0628\0646\0643 \0648\0627\0644\0645\0633\062A\0641\064A\062F \0641\064A \0631\0623\0633 \0627\0644\0625\0630\0646 + \062C\062F\0648\0644 \0627\0644\0634\064A\0643\0627\062A (JSON)'),
unistr('// \0644\0643\0644 \0634\064A\0643 \0645\0633\0644\0633\0644 \0639\0627\0645 \064A\064F\0639\0637\0649 \0639\0646\062F \0627\0644\062D\0641\0638: 16 + \0627\0644\0633\0646\0629 + 5 \062E\0627\0646\0627\062A'),
'var chq = {',
'  grid: null,',
'',
'  init: function () {',
'    var status = apex.item(''P45_STATUS'').getValue() || ''DRAFT'',',
'        pay    = apex.item(''P45_VOUCHER_TYPE'').getValue() === ''P'',',
'        vdate  = apex.item(''P45_VOUCHER_DATE'').getValue() || null;',
'',
'    var cols = [',
unistr('      {name: ''CHEQUE_SERIAL'', label: ''\0627\0644\0645\0633\0644\0633\0644'', type: ''display''},'),
unistr('      {name: ''CHEQUE_NO'', label: ''\0631\0642\0645 \0627\0644\0634\064A\0643'', type: ''text'', required: true, maxLength: 30, width: ''9em''},'),
unistr('      {name: ''DUE_DATE'', label: ''\062A\0627\0631\064A\062E \0627\0644\0635\0631\0641 (\064A\0648\0645/\0634\0647\0631/\0633\0646\0629)'', type: ''text'', required: true, maxLength: 10, width: ''9em'','),
'       defaultValue: vdate},',
unistr('      {name: ''AMOUNT'', label: ''\0627\0644\0645\0628\0644\063A'', type: ''number'', decimals: 2, total: true, required: true, width: ''10em''}'),
'    ];',
unistr('    if (!pay) cols.push({name: ''BANK_NAME'', label: ''\0628\0646\0643 \0627\0644\0633\0627\062D\0628 (\0627\062E\062A\064A\0627\0631\064A)'', type: ''text'', maxLength: 100, width: ''14em'', ignoreEmpty: true});'),
unistr('    cols.push({name: ''STATUS_T'', label: ''\062D\0627\0644\0629 \0627\0644\0634\064A\0643'', type: ''display''});'),
'',
'    chq.grid = new JsonLines({',
'      container: ''#chq_lines'',',
'      readOnly : !DocUtil.canEdit(status),',
'      columns  : cols,',
'      onTotals: function (t) {',
'        var el = document.getElementById(''chq_total'');',
'        if (el) el.textContent = JsonLines.fmt(t.AMOUNT || 0, 2);',
'      }',
'    });',
'',
'    apex.server.process(''INIT_DATA'', {x01: apex.item(''P45_VOUCHER_ID'').getValue()}, {dataType: ''json''})',
'      .done(function (d) { chq.grid.setData(d.lines || []); });',
'',
'    document.addEventListener(''keydown'', function (e) {',
'      if (e.ctrlKey && (e.key === ''s'' || e.key === ''S'')) { e.preventDefault(); chq.save(); }',
'    });',
'    EnterNav.first(''#main'');',
'  },',
'',
'  save: function () {',
'    var errs = [], g = function (n) { return apex.item(''P45_'' + n).getValue(); },',
'        pay = g(''VOUCHER_TYPE'') === ''P'';',
unistr('    if (!g(''VOUCHER_DATE''))       errs.push(''\0623\062F\062E\0644 \062A\0627\0631\064A\062E \0627\0644\0625\0630\0646'');'),
unistr('    if (!g(''BANK_ACCOUNT_ID''))    errs.push(''\0627\062E\062A\0631 \0627\0644\0628\0646\0643'');'),
unistr('    if (!g(''COUNTER_ACCOUNT_ID'')) errs.push(''\0627\062E\062A\0631 \0627\0644\062D\0633\0627\0628 \0627\0644\0645\0642\0627\0628\0644'');'),
unistr('    if (pay && !g(''PARTY_NAME''))  errs.push(''\0623\062F\062E\0644 \0627\0633\0645 \0627\0644\0645\0633\062A\0641\064A\062F (\064A\064F\0637\0628\0639 \0639\0644\0649 \0627\0644\0634\064A\0643\0627\062A)'');'),
unistr('    if (!g(''DESCRIPTION''))        errs.push(''\0623\062F\062E\0644 \0627\0644\0628\064A\0627\0646'');'),
'    errs = errs.concat(chq.grid.validate());',
'    var lines = chq.grid.getData();',
unistr('    if (!lines.length) errs.push(''\0623\062F\062E\0644 \0634\064A\0643\0627\064B \0648\0627\062D\062F\0627\064B \0639\0644\0649 \0627\0644\0623\0642\0644'');'),
'    lines.forEach(function (l, i) {',
unistr('      if (l.DUE_DATE && !/^\005Cd{1,2}\005C/\005Cd{1,2}\005C/\005Cd{4}$/.test(l.DUE_DATE)) errs.push(''\0627\0644\0634\064A\0643 '' + (i + 1) + '': \062A\0627\0631\064A\062E \0627\0644\0635\0631\0641 \0628\0635\064A\063A\0629 \064A\0648\0645/\0634\0647\0631/\0633\0646\0629'');'),
'    });',
'    if (errs.length) { DocUtil.showErrors(errs); return; }',
'',
'    var doc = {',
'      header: {',
'        VOUCHER_ID: g(''VOUCHER_ID''), VOUCHER_TYPE: g(''VOUCHER_TYPE''), VOUCHER_DATE: g(''VOUCHER_DATE''),',
'        BANK_ACCOUNT_ID: g(''BANK_ACCOUNT_ID''), COUNTER_ACCOUNT_ID: g(''COUNTER_ACCOUNT_ID''),',
'        PARTY_NAME: g(''PARTY_NAME''), DESCRIPTION: g(''DESCRIPTION'')',
'      },',
'      lines: lines',
'    };',
'    DocUtil.save(doc, ''DRAFT'', function (d) {',
'      apex.page.submit({request: ''RELOAD'', set: {P45_VOUCHER_ID: d.id}, showWait: true});',
'    });',
'  }',
'};'))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'window.APP_ROLE = ''&G_USER_ROLE.'';',
'chq.init();',
'if (apex.item(''P45_STATUS'').getValue() && !DocUtil.canEdit(apex.item(''P45_STATUS'').getValue())) { [''P45_VOUCHER_DATE'',''P45_BANK_ACCOUNT_ID'',''P45_COUNTER_ACCOUNT_ID'',''P45_PARTY_NAME'',''P45_DESCRIPTION''].forEach(function (n) { apex.item(n).disable(); }); }'))
,p_page_template_options=>'#DEFAULT#'
,p_required_role=>wwv_flow_imp.id(91000000000080)
,p_protection_level=>'N'
);
