wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000282)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_clob_language=>'PLSQL'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  r vouchers%ROWTYPE;',
'BEGIN',
'  SELECT * INTO r FROM vouchers WHERE voucher_id = :P45_VOUCHER_ID;',
'  :P45_VOUCHER_TYPE       := r.voucher_type;',
'  :P45_VOUCHER_NO         := r.voucher_no;',
'  :P45_VOUCHER_DATE       := TO_CHAR(r.voucher_date, ''DD/MM/YYYY'');',
'  :P45_COUNTER_ACCOUNT_ID := r.counter_account_id;',
'  :P45_BANK_ACCOUNT_ID    := r.bank_account_id;',
'  :P45_PARTY_NAME         := r.party_name;',
'  :P45_DESCRIPTION        := r.description;',
'  :P45_STATUS             := r.status;',
'  :P45_JOURNAL_ID         := r.journal_id;',
'  :P45_TOTAL              := TO_CHAR(r.total_amount, ''FM999G999G999G990D00'');',
'  SELECT COUNT(*) INTO :P45_CHQ_COUNT FROM cheques WHERE voucher_id = r.voucher_id;',
'  :P45_RETURN_NOTE := CASE WHEN r.status IN (''RETURNED'',''DRAFT'') THEN r.return_note END;',
unistr(':P45_WF_INFO := TRIM(CASE WHEN r.reviewed_by IS NOT NULL THEN ''\0631\0627\062C\0639\0647 '' || r.reviewed_by || '' '' || TO_CHAR(r.reviewed_on, ''DD/MM/YYYY HH24:MI'') END || CASE WHEN r.approved_by IS NOT NULL THEN '' - \0627\0639\062A\0645\062F\0647 '' || r.approved_by || '' '' || TO_CHAR(r.approved_on, ''DD/MM/YYYY HH24:MI'') END);'),
'END;'))
,p_process_name=>'LOAD_HEADER'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':P45_VOUCHER_ID IS NOT NULL'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>91000000000282
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000283)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_clob_language=>'PLSQL'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P45_VOUCHER_TYPE IS NULL OR :P45_VOUCHER_TYPE NOT IN (''R'',''P'') THEN :P45_VOUCHER_TYPE := ''R''; END IF;',
'IF :P45_VOUCHER_ID IS NULL THEN',
'  :P45_STATUS := NULL;',
'  IF :P45_VOUCHER_DATE IS NULL THEN :P45_VOUCHER_DATE := TO_CHAR(SYSDATE, ''DD/MM/YYYY''); END IF;',
'END IF;',
'IF :P45_VOUCHER_ID IS NULL THEN',
'  SELECT CASE :P45_VOUCHER_TYPE WHEN ''R'' THEN ''13'' ELSE ''14'' END || EXTRACT(YEAR FROM NVL(TO_DATE(:P45_VOUCHER_DATE, ''DD/MM/YYYY''), SYSDATE)) || LPAD(NVL(MAX(last_no), 0) + 1, 5, ''0'') INTO :P45_VOUCHER_NO FROM doc_sequences',
'  WHERE company_id = NVL(:G_COMPANY_ID, :G_PARENT_ID) AND doc_type = CASE :P45_VOUCHER_TYPE WHEN ''R'' THEN ''13'' ELSE ''14'' END AND fy_year = EXTRACT(YEAR FROM NVL(TO_DATE(:P45_VOUCHER_DATE, ''DD/MM/YYYY''), SYSDATE));',
'END IF;',
unistr(':P45_TITLE := CASE :P45_VOUCHER_TYPE WHEN ''R'' THEN ''\0625\0630\0646 \062A\0648\0631\064A\062F \0634\064A\0643\0627\062A'' ELSE ''\0625\0630\0646 \0635\0631\0641 \0634\064A\0643\0627\062A'' END;'),
unistr(':P45_ACC_LABEL := CASE :P45_VOUCHER_TYPE WHEN ''R'' THEN ''\0627\0644\062D\0633\0627\0628 \0627\0644\0645\0642\0627\0628\0644 (\0627\0644\0639\0645\064A\0644 / \0627\0644\062C\0647\0629)'' ELSE ''\0627\0644\062D\0633\0627\0628 \0627\0644\0645\0642\0627\0628\0644 (\0627\0644\0645\0648\0631\062F / \0627\0644\062C\0647\0629)'' END;'),
unistr(':P45_PARTY_LABEL := CASE :P45_VOUCHER_TYPE WHEN ''R'' THEN ''\0627\0633\062A\0644\0645\0646\0627 \0645\0646'' ELSE ''\0627\0633\0645 \0627\0644\0645\0633\062A\0641\064A\062F (\064A\064F\0637\0628\0639 \0639\0644\0649 \0627\0644\0634\064A\0643\0627\062A)'' END;'),
unistr(':P45_BANK_LABEL := CASE :P45_VOUCHER_TYPE WHEN ''R'' THEN ''\0627\0644\0628\0646\0643 \0627\0644\0645\0648\062F\064E\0639 \0641\064A\0647'' ELSE ''\0627\0644\0628\0646\0643 \0627\0644\0645\0633\062D\0648\0628 \0639\0644\064A\0647'' END;')))
,p_process_name=>'DEFAULTS'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000283
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000284)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_clob_language=>'PLSQL'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('  -- x01 = \0631\0642\0645 \0627\0644\0625\0630\0646: \0634\064A\0643\0627\062A \0627\0644\0625\0630\0646'),
'  l_lines CLOB;',
'BEGIN',
'  SELECT JSON_ARRAYAGG(JSON_OBJECT(',
'           ''CHEQUE_SERIAL'' VALUE cheque_serial,',
'           ''CHEQUE_NO''     VALUE cheque_no,',
'           ''BANK_NAME''     VALUE bank_name,',
'           ''DUE_DATE''      VALUE TO_CHAR(due_date, ''DD/MM/YYYY''),',
'           ''AMOUNT''        VALUE amount,',
unistr('           ''STATUS_T''      VALUE DECODE(status, ''PENDING'', ''\0642\0627\0626\0645'', ''CLEARED'', ''\062A\0645 \0627\0644\0635\0631\0641 / \0627\0644\062A\062D\0635\064A\0644'', ''BOUNCED'', ''\0645\0631\062A\062F''))'),
'         ORDER BY line_no RETURNING CLOB)',
'  INTO   l_lines',
'  FROM   cheques WHERE voucher_id = TO_NUMBER(apex_application.g_x01);',
'',
'  apex_util.prn(''{"lines":'' || COALESCE(l_lines, TO_CLOB(''[]'')) || ''}'', FALSE);',
'END;'))
,p_process_name=>'INIT_DATA'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000284
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000285)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('  -- \062D\0641\0638 \0625\0630\0646 \062A\0648\0631\064A\062F / \0635\0631\0641 \0634\064A\0643\0627\062A (Ajax: p_clob_01 = {header, lines})'),
unistr('  -- \0627\0644\062A\0631\0642\064A\0645: 13 \062A\0648\0631\064A\062F \0634\064A\0643\0627\062A / 14 \0635\0631\0641 \0634\064A\0643\0627\062A + \0627\0644\0633\0646\0629 + 5 \062E\0627\0646\0627\062A \062A\0633\0644\0633\0644'),
'  l_clob  CLOB := apex_application.g_clob_01;',
'  l_errs  apex_t_varchar2 := apex_t_varchar2();',
'  l_co    NUMBER := NVL(:G_COMPANY_ID, :G_PARENT_ID);',
'',
'  l_id NUMBER; l_type VARCHAR2(1); l_date_s VARCHAR2(20); l_date DATE; l_acc NUMBER; l_bank NUMBER;',
'  l_serial VARCHAR2(20); l_n NUMBER := 0;',
'  TYPE t_old IS TABLE OF NUMBER INDEX BY VARCHAR2(20);',
'  l_old t_old;',
'  l_party VARCHAR2(150); l_desc VARCHAR2(500);',
'  l_st VARCHAR2(10); l_no VARCHAR2(30); l_code VARCHAR2(2); l_seq NUMBER; l_cnt NUMBER;',
'  l_total NUMBER := 0; l_lines NUMBER := 0; l_due DATE; l_cur VARCHAR2(3);',
'',
'  PROCEDURE err (p VARCHAR2) IS BEGIN l_errs.EXTEND; l_errs(l_errs.COUNT) := p; END;',
'BEGIN',
'  SELECT h.voucher_id, h.voucher_type, h.voucher_date, h.bank_account_id, h.counter_account_id, h.party_name, h.description',
'  INTO   l_id, l_type, l_date_s, l_bank, l_acc, l_party, l_desc',
'  FROM   JSON_TABLE(l_clob, ''$.header'' COLUMNS (',
'           voucher_id         NUMBER        PATH ''$.VOUCHER_ID'',',
'           voucher_type       VARCHAR2(1)   PATH ''$.VOUCHER_TYPE'',',
'           voucher_date       VARCHAR2(20)  PATH ''$.VOUCHER_DATE'',',
'           bank_account_id    NUMBER        PATH ''$.BANK_ACCOUNT_ID'',',
'           counter_account_id NUMBER        PATH ''$.COUNTER_ACCOUNT_ID'',',
'           party_name         VARCHAR2(150) PATH ''$.PARTY_NAME'',',
'           description        VARCHAR2(500) PATH ''$.DESCRIPTION'')) h;',
'',
unistr('  IF :G_USER_ROLE NOT IN (''ADMIN'',''ENTRY'') THEN err(''\0625\062F\062E\0627\0644 \0627\0644\0623\0630\0648\0646\0627\062A \0648\062A\0639\062F\064A\0644\0647\0627 \0645\0646 \0635\0644\0627\062D\064A\0629 \0627\0644\0645\062F\062E\0644 \0641\0642\0637''); END IF;'),
unistr('  IF l_type IS NULL OR l_type NOT IN (''R'',''P'') THEN err(''\0646\0648\0639 \0627\0644\0625\0630\0646 \063A\064A\0631 \0645\0639\0631\0648\0641''); END IF;'),
'',
'  BEGIN l_date := TO_DATE(l_date_s, ''DD/MM/YYYY'');',
unistr('  EXCEPTION WHEN OTHERS THEN err(''\062A\0627\0631\064A\062E \0627\0644\0625\0630\0646 \063A\064A\0631 \0635\062D\064A\062D''); END;'),
unistr('  IF l_date IS NULL THEN err(''\0623\062F\062E\0644 \062A\0627\0631\064A\062E \0627\0644\0625\0630\0646''); END IF;'),
unistr('  IF TRIM(l_desc) IS NULL THEN err(''\0623\062F\062E\0644 \0627\0644\0628\064A\0627\0646''); END IF;'),
unistr('  IF l_type = ''P'' AND TRIM(l_party) IS NULL THEN err(''\0623\062F\062E\0644 \0627\0633\0645 \0627\0644\0645\0633\062A\0641\064A\062F (\064A\064F\0637\0628\0639 \0639\0644\0649 \0627\0644\0634\064A\0643\0627\062A)''); END IF;'),
'  SELECT COUNT(*) INTO l_cnt FROM accounts WHERE account_id = l_bank AND cash_bank = ''B'' AND is_active = ''Y'';',
unistr('  IF l_cnt = 0 THEN err(CASE l_type WHEN ''P'' THEN ''\0627\062E\062A\0631 \0627\0644\0628\0646\0643 \0627\0644\0645\0633\062D\0648\0628 \0639\0644\064A\0647'' ELSE ''\0627\062E\062A\0631 \0627\0644\0628\0646\0643 \0627\0644\0645\0648\062F\064E\0639 \0641\064A\0647'' END); END IF;'),
'',
unistr('  IF l_acc IS NULL THEN err(''\0627\062E\062A\0631 \0627\0644\062D\0633\0627\0628 \0627\0644\0645\0642\0627\0628\0644'');'),
'  ELSE',
'    SELECT COUNT(*) INTO l_cnt FROM accounts WHERE account_id = l_acc AND is_postable = ''Y'' AND is_active = ''Y'' AND cash_bank = ''N'';',
unistr('    IF l_cnt = 0 THEN err(''\0627\0644\062D\0633\0627\0628 \0627\0644\0645\0642\0627\0628\0644 \064A\062C\0628 \0623\0646 \064A\0643\0648\0646 \062D\0633\0627\0628\0627\064B \062A\062D\0644\064A\0644\064A\0627\064B \0641\0639\0651\0627\0644\0627\064B (\063A\064A\0631 \0627\0644\062E\0632\064A\0646\0629 \0648\0627\0644\0628\0646\0648\0643)''); END IF;'),
'  END IF;',
'',
'  IF l_date IS NOT NULL THEN',
'    SELECT COUNT(*) INTO l_cnt FROM fiscal_years WHERE l_date BETWEEN start_date AND end_date AND is_closed = ''N'';',
unistr('    IF l_cnt = 0 THEN err(''\0627\0644\062A\0627\0631\064A\062E \062E\0627\0631\062C \0633\0646\0629 \0645\0627\0644\064A\0629 \0645\0641\062A\0648\062D\0629''); END IF;'),
'  END IF;',
'',
'  IF l_id IS NOT NULL THEN',
'    BEGIN',
'      SELECT status, voucher_no INTO l_st, l_no FROM vouchers WHERE voucher_id = l_id AND voucher_kind = ''CHEQUE'' FOR UPDATE;',
unistr('      IF l_st NOT IN (''DRAFT'',''RETURNED'') THEN err(''\0627\0644\0625\0630\0646 '' || l_no || '' \062A\0645\062A \0645\0631\0627\062C\0639\062A\0647 \0623\0648 \0627\0639\062A\0645\0627\062F\0647 \0648\0644\0627 \064A\0645\0643\0646 \062A\0639\062F\064A\0644\0647''); END IF;'),
unistr('    EXCEPTION WHEN NO_DATA_FOUND THEN err(''\0627\0644\0625\0630\0646 \063A\064A\0631 \0645\0648\062C\0648\062F'');'),
'    END;',
'  END IF;',
'',
'  FOR r IN (SELECT * FROM JSON_TABLE(l_clob, ''$.lines[*]'' COLUMNS (',
'               line_no         NUMBER        PATH ''$.LINE_NO'',',
'               cheque_no       VARCHAR2(30)  PATH ''$.CHEQUE_NO'',',
'               bank_account_id NUMBER        PATH ''$.BANK_ACCOUNT_ID'',',
'               bank_name       VARCHAR2(100) PATH ''$.BANK_NAME'',',
'               due_date        VARCHAR2(20)  PATH ''$.DUE_DATE'',',
'               amount          NUMBER        PATH ''$.AMOUNT''))) LOOP',
'    l_lines := l_lines + 1;',
unistr('    IF r.cheque_no IS NULL THEN err(''\0627\0644\0634\064A\0643 '' || r.line_no || '': \0623\062F\062E\0644 \0631\0642\0645 \0627\0644\0634\064A\0643''); END IF;'),
'    BEGIN',
'      l_due := TO_DATE(r.due_date, ''DD/MM/YYYY'');',
unistr('      IF l_due IS NULL THEN err(''\0627\0644\0634\064A\0643 '' || r.line_no || '': \0623\062F\062E\0644 \062A\0627\0631\064A\062E \0627\0644\0627\0633\062A\062D\0642\0627\0642''); END IF;'),
unistr('    EXCEPTION WHEN OTHERS THEN err(''\0627\0644\0634\064A\0643 '' || r.line_no || '': \062A\0627\0631\064A\062E \0627\0644\0627\0633\062A\062D\0642\0627\0642 \063A\064A\0631 \0635\062D\064A\062D'');'),
'    END;',
unistr('    IF NVL(r.amount, 0) <= 0 THEN err(''\0627\0644\0634\064A\0643 '' || r.line_no || '': \0627\0644\0645\0628\0644\063A \064A\062C\0628 \0623\0646 \064A\0643\0648\0646 \0623\0643\0628\0631 \0645\0646 \0635\0641\0631''); END IF;'),
'    l_total := l_total + NVL(r.amount, 0);',
'  END LOOP;',
unistr('  IF l_lines = 0 THEN err(''\0623\062F\062E\0644 \0634\064A\0643\0627\064B \0648\0627\062D\062F\0627\064B \0639\0644\0649 \0627\0644\0623\0642\0644''); END IF;'),
'',
'  IF l_errs.COUNT > 0 THEN',
'    ROLLBACK;',
'    apex_json.open_object; apex_json.write(''ok'', FALSE); apex_json.write(''errors'', l_errs); apex_json.close_object;',
'    RETURN;',
'  END IF;',
'',
'  SELECT currency_code INTO l_cur FROM currencies WHERE is_base = ''Y'';',
'',
'  IF l_id IS NULL THEN',
'    l_code := CASE l_type WHEN ''R'' THEN ''13'' ELSE ''14'' END;',
'    UPDATE doc_sequences SET last_no = last_no + 1',
'    WHERE  company_id = l_co AND doc_type = l_code AND fy_year = EXTRACT(YEAR FROM l_date)',
'    RETURNING last_no INTO l_seq;',
'    IF SQL%ROWCOUNT = 0 THEN',
'      INSERT INTO doc_sequences (company_id, doc_type, fy_year, last_no) VALUES (l_co, l_code, EXTRACT(YEAR FROM l_date), 1);',
'      l_seq := 1;',
'    END IF;',
'    l_no := l_code || EXTRACT(YEAR FROM l_date) || LPAD(l_seq, 5, ''0'');',
'',
'    INSERT INTO vouchers (company_id, voucher_type, voucher_kind, voucher_no, voucher_date, counter_account_id, bank_account_id,',
'                          currency_code, exchange_rate, pay_method, party_name, description, total_amount, status, created_by)',
'    VALUES (l_co, l_type, ''CHEQUE'', l_no, l_date, l_acc, l_bank, l_cur, 1, ''CHEQUE'', l_party, l_desc, l_total, ''DRAFT'', :APP_USER)',
'    RETURNING voucher_id INTO l_id;',
'    l_st := NULL;',
'  ELSE',
'    UPDATE vouchers',
'    SET    voucher_date = l_date, counter_account_id = l_acc, bank_account_id = l_bank, party_name = l_party, description = l_desc,',
'           total_amount = l_total, status = ''DRAFT'', return_note = NULL',
'    WHERE  voucher_id = l_id;',
unistr('    -- \0627\0644\0645\0633\0644\0633\0644\0627\062A \0627\0644\0633\0627\0628\0642\0629 \062A\0628\0642\0649 \0644\0634\064A\0643\0627\062A\0647\0627 \0639\0646\062F \0625\0639\0627\062F\0629 \0627\0644\062D\0641\0638'),
'    FOR o IN (SELECT cheque_serial FROM cheques WHERE voucher_id = l_id) LOOP l_old(o.cheque_serial) := 1; END LOOP;',
'    DELETE FROM cheques WHERE voucher_id = l_id;',
'  END IF;',
'',
unistr('  -- \0627\0644\0634\064A\0643\0627\062A: \0627\0644\0628\0646\0643 \0648\0627\0644\0645\0633\062A\0641\064A\062F \0645\0646 \0631\0623\0633 \0627\0644\0625\0630\0646 \060C \0648\0644\0643\0644 \0634\064A\0643 \0645\0633\0644\0633\0644 \0639\0627\0645 16 + \0627\0644\0633\0646\0629 + 5 \062E\0627\0646\0627\062A'),
'  FOR r IN (SELECT * FROM JSON_TABLE(l_clob, ''$.lines[*]'' COLUMNS (',
'               cheque_serial VARCHAR2(20)  PATH ''$.CHEQUE_SERIAL'',',
'               cheque_no     VARCHAR2(30)  PATH ''$.CHEQUE_NO'',',
'               bank_name     VARCHAR2(100) PATH ''$.BANK_NAME'',',
'               due_date      VARCHAR2(20)  PATH ''$.DUE_DATE'',',
'               amount        NUMBER        PATH ''$.AMOUNT''))) LOOP',
'    l_n := l_n + 1;',
'    IF r.cheque_serial IS NOT NULL AND l_old.EXISTS(r.cheque_serial) THEN',
'      l_serial := r.cheque_serial;',
'      l_old.DELETE(r.cheque_serial);',
'    ELSE',
'      UPDATE doc_sequences SET last_no = last_no + 1',
'      WHERE  company_id = l_co AND doc_type = ''16'' AND fy_year = EXTRACT(YEAR FROM l_date)',
'      RETURNING last_no INTO l_seq;',
'      IF SQL%ROWCOUNT = 0 THEN',
'        INSERT INTO doc_sequences (company_id, doc_type, fy_year, last_no) VALUES (l_co, ''16'', EXTRACT(YEAR FROM l_date), 1);',
'        l_seq := 1;',
'      END IF;',
'      l_serial := ''16'' || EXTRACT(YEAR FROM l_date) || LPAD(l_seq, 5, ''0'');',
'    END IF;',
'    INSERT INTO cheques (voucher_id, line_no, cheque_serial, cheque_no, bank_account_id, bank_name, due_date, amount, payee_name)',
'    VALUES (l_id, l_n, l_serial, r.cheque_no, CASE WHEN l_type = ''P'' THEN l_bank END,',
'            CASE WHEN l_type = ''R'' THEN r.bank_name END, TO_DATE(r.due_date, ''DD/MM/YYYY''), r.amount, l_party);',
'  END LOOP;',
'',
'  INSERT INTO doc_actions (doc_type, doc_id, action, from_status, to_status, action_by)',
'  VALUES (''VOUCHER'', l_id, ''SAVE'', l_st, ''DRAFT'', :APP_USER);',
'',
'  apex_json.open_object;',
'  apex_json.write(''ok'', TRUE);',
'  apex_json.write(''id'', l_id);',
'  apex_json.write(''no'', l_no);',
unistr('  apex_json.write(''message'', ''\062A\0645 \062D\0641\0638 \0627\0644\0625\0630\0646 '' || l_no || '' - \0628\0627\0646\062A\0638\0627\0631 \0627\0644\0645\0631\0627\062C\0639\0629'');'),
'  apex_json.close_object;',
'EXCEPTION WHEN OTHERS THEN',
'  ROLLBACK;',
'  apex_json.open_object; apex_json.write(''ok'', FALSE);',
'  apex_json.open_array(''errors''); apex_json.write(SQLERRM); apex_json.close_array;',
'  apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_name=>'SAVE_DOC'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000285
);
