,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT v.voucher_id, v.voucher_type,',
unistr('       DECODE(v.voucher_type, ''R'', ''\062A\0648\0631\064A\062F \0634\064A\0643\0627\062A'', ''\0635\0631\0641 \0634\064A\0643\0627\062A'') AS "\0627\0644\0646\0648\0639",'),
unistr('       v.voucher_no AS "\0627\0644\0631\0642\0645", v.voucher_date AS "\0627\0644\062A\0627\0631\064A\062E",'),
unistr('       ca.account_code || '' - '' || ca.name_ar AS "\0627\0644\062D\0633\0627\0628 \0627\0644\0645\0642\0627\0628\0644",'),
unistr('       v.party_name AS "\0627\0644\0627\0633\0645",'),
unistr('       (SELECT COUNT(*) FROM cheques c WHERE c.voucher_id = v.voucher_id) AS "\0639\062F\062F \0627\0644\0634\064A\0643\0627\062A",'),
unistr('       (SELECT TO_CHAR(MIN(c.due_date), ''DD/MM/YYYY'') FROM cheques c WHERE c.voucher_id = v.voucher_id) AS "\0623\0642\0631\0628 \0627\0633\062A\062D\0642\0627\0642",'),
unistr('       v.total_amount AS "\0627\0644\0645\0628\0644\063A", v.description AS "\0627\0644\0628\064A\0627\0646",'),
unistr('       DECODE(v.status, ''DRAFT'', ''\0645\0633\0648\062F\0629'', ''RETURNED'', ''\0645\0639\0627\062F \0644\0644\0645\062F\062E\0644'', ''REVIEWED'', ''\0645\064F\0631\0627\062C\064E\0639'','),
unistr('              ''APPROVED'', ''\0645\0639\062A\0645\062F'', ''POSTED'', ''\0645\0631\062D\0651\0644'', ''REVERSED'', ''\0645\0639\0643\0648\0633'') AS "\0627\0644\062D\0627\0644\0629",'),
unistr('       v.created_by AS "\0627\0644\0645\062F\062E\0644", v.reviewed_by AS "\0627\0644\0645\0631\0627\062C\0639", v.approved_by AS "\0627\0644\0645\0639\062A\0645\062F"'),
'FROM   vouchers v',
'LEFT JOIN accounts ca ON ca.account_id = v.counter_account_id',
'WHERE  v.voucher_kind = ''CHEQUE''',
'AND    (:P46_TYPE IS NULL OR v.voucher_type = :P46_TYPE)',
