,p_location=>null
,p_plug_source_type=>'NATIVE_PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_ctx  apex_exec.t_context;',
'  l_col  apex_exec.t_column;',
'  l_val  VARCHAR2(4000);',
'BEGIN',
'  l_ctx := apex_exec.open_query_context(',
'             p_location  => apex_exec.c_location_local_db,',
unistr('             p_sql_query => q''~SELECT DECODE(v.voucher_type, ''R'', ''\0634\064A\0643\0627\062A \0648\0627\0631\062F\0629 \0644\0644\062A\062D\0635\064A\0644'', ''\0634\064A\0643\0627\062A \0635\0627\062F\0631\0629 \0644\0644\0635\0631\0641'') AS "\0627\0644\0646\0648\0639",'),
unistr('       SUM(CASE WHEN c.due_date < TRUNC(SYSDATE) THEN 1 ELSE 0 END) AS "\0639\062F\062F \0627\0644\0645\062A\0623\062E\0631\0629",'),
unistr('       SUM(CASE WHEN c.due_date < TRUNC(SYSDATE) THEN c.amount ELSE 0 END) AS "\0645\0628\0644\063A \0627\0644\0645\062A\0623\062E\0631\0629",'),
unistr('       SUM(CASE WHEN c.due_date = TRUNC(SYSDATE) THEN 1 ELSE 0 END) AS "\0639\062F\062F \0627\0644\0645\0633\062A\062D\0642\0629 \0627\0644\064A\0648\0645",'),
unistr('       SUM(CASE WHEN c.due_date = TRUNC(SYSDATE) THEN c.amount ELSE 0 END) AS "\0645\0628\0644\063A \0627\0644\0645\0633\062A\062D\0642\0629 \0627\0644\064A\0648\0645",'),
unistr('       SUM(CASE WHEN c.due_date > TRUNC(SYSDATE) AND c.due_date <= TRUNC(SYSDATE) + 7 THEN c.amount ELSE 0 END) AS "\0645\0628\0644\063A \0627\0644\0623\0633\0628\0648\0639 \0627\0644\0642\0627\062F\0645",'),
unistr('       SUM(c.amount) AS "\0625\062C\0645\0627\0644\064A \0627\0644\0642\0627\0626\0645\0629"'),
'FROM   cheques c',
'JOIN   vouchers v ON v.voucher_id = c.voucher_id',
'WHERE  c.status = ''PENDING'' AND v.status IN (''APPROVED'',''POSTED'')',
'GROUP BY v.voucher_type',
'~'');',
'  htp.p(''<div style="overflow-x:auto"><table class="jl-table"><thead><tr>'');',
'  FOR i IN 1 .. apex_exec.get_column_count(l_ctx) LOOP',
'    l_col := apex_exec.get_column(l_ctx, i);',
unistr('    IF l_col.name NOT LIKE ''%\005C_ID'' ESCAPE ''\005C'' AND l_col.name <> ''SORT_KEY'' THEN'),
'      htp.p(''<th>'' || apex_escape.html(l_col.name) || ''</th>'');',
'    END IF;',
'  END LOOP;',
'  htp.p(''</tr></thead><tbody>'');',
'  WHILE apex_exec.next_row(l_ctx) LOOP',
'    htp.p(''<tr>'');',
'    FOR i IN 1 .. apex_exec.get_column_count(l_ctx) LOOP',
'      l_col := apex_exec.get_column(l_ctx, i);',
unistr('      IF l_col.name NOT LIKE ''%\005C_ID'' ESCAPE ''\005C'' AND l_col.name <> ''SORT_KEY'' THEN'),
'        IF l_col.data_type = apex_exec.c_data_type_number THEN',
unistr('          l_val := TO_CHAR(apex_exec.get_number(l_ctx, i), CASE WHEN l_col.name LIKE ''\0639\062F\062F%'' THEN ''FM999G999G990'' ELSE ''FM999G999G999G999G990D00'' END);'),
'          htp.p(''<td class="jl-num">'' || l_val || ''</td>'');',
'        ELSE',
'          htp.p(''<td>'' || apex_escape.html(apex_exec.get_varchar2(l_ctx, i)) || ''</td>'');',
'        END IF;',
'      END IF;',
'    END LOOP;',
'    htp.p(''</tr>'');',
'  END LOOP;',
'  htp.p(''</tbody></table></div>'');',
'  apex_exec.close(l_ctx);',
'EXCEPTION WHEN OTHERS THEN',
'  apex_exec.close(l_ctx);',
'  RAISE;',
'END;'))
);
