wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(91000000000315)
,p_plug_name=>unistr('\0627\0644\0634\064A\0643\0627\062A \062D\0633\0628 \062A\0627\0631\064A\062E \0627\0644\0627\0633\062A\062D\0642\0627\0642')
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(6687458349757443)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_prn_page_header=>unistr('\0627\0644\0634\064A\0643\0627\062A \062D\0633\0628 \062A\0627\0631\064A\062E \0627\0644\0627\0633\062A\062D\0642\0627\0642')
,p_plug_source_type=>'NATIVE_IR'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT c.cheque_id,',
unistr('       c.due_date AS "\062A\0627\0631\064A\062E \0627\0644\0635\0631\0641",'),
'       CASE WHEN c.status <> ''PENDING'' THEN NULL',
unistr('            WHEN c.due_date <  TRUNC(SYSDATE) THEN ''\0645\062A\0623\062E\0631'''),
unistr('            WHEN c.due_date =  TRUNC(SYSDATE) THEN ''\0645\0633\062A\062D\0642 \0627\0644\064A\0648\0645'''),
unistr('            WHEN c.due_date <= TRUNC(SYSDATE) + 7 THEN ''\062E\0644\0627\0644 \0623\0633\0628\0648\0639'' END AS "\0627\0644\062A\0646\0628\064A\0647",'),
unistr('       DECODE(v.voucher_type, ''R'', ''\0648\0627\0631\062F (\062A\062D\0635\064A\0644)'', ''\0635\0627\062F\0631 (\0635\0631\0641)'') AS "\0627\0644\0646\0648\0639",'),
unistr('       c.cheque_serial AS "\0627\0644\0645\0633\0644\0633\0644",'),
unistr('       c.cheque_no AS "\0631\0642\0645 \0627\0644\0634\064A\0643",'),
unistr('       NVL(b.name_ar, vb.name_ar) || CASE WHEN c.bank_name IS NOT NULL THEN '' (\0628\0646\0643 \0627\0644\0633\0627\062D\0628: '' || c.bank_name || '')'' END AS "\0627\0644\0628\0646\0643",'),
unistr('       c.payee_name AS "\0627\0644\0645\0633\062A\0641\064A\062F / \0627\0644\0633\0627\062D\0628",'),
unistr('       c.amount AS "\0627\0644\0645\0628\0644\063A",'),
unistr('       DECODE(c.status, ''PENDING'', ''\0642\0627\0626\0645'','),
unistr('              ''CLEARED'', CASE v.voucher_type WHEN ''R'' THEN ''\062A\0645 \0627\0644\062A\062D\0635\064A\0644'' ELSE ''\062A\0645 \0627\0644\0635\0631\0641'' END,'),
unistr('              ''BOUNCED'', ''\0645\0631\062A\062F'') AS "\062D\0627\0644\0629 \0627\0644\0634\064A\0643",'),
unistr('       c.settle_date AS "\062A\0627\0631\064A\062E \0627\0644\062A\0633\0648\064A\0629",'),
unistr('       j.journal_no AS "\0642\064A\062F \0627\0644\062A\0633\0648\064A\0629",'),
unistr('       DECODE(j.status, ''DRAFT'', ''\0645\0633\0648\062F\0629'', ''RETURNED'', ''\0645\0639\0627\062F \0644\0644\0645\062F\062E\0644'', ''REVIEWED'', ''\0645\064F\0631\0627\062C\064E\0639'','),
unistr('              ''APPROVED'', ''\0645\0639\062A\0645\062F'', ''POSTED'', ''\0645\0631\062D\0651\0644'', ''REVERSED'', ''\0645\0639\0643\0648\0633'') AS "\062D\0627\0644\0629 \0627\0644\0642\064A\062F",'),
unistr('       v.voucher_no AS "\0631\0642\0645 \0627\0644\0625\0630\0646",'),
unistr('       ca.name_ar AS "\0627\0644\062D\0633\0627\0628 \0627\0644\0645\0642\0627\0628\0644",'),
unistr('       ''\0627\062E\062A\064A\0627\0631'' AS "\0625\062C\0631\0627\0621"'),
'FROM   cheques c',
'JOIN   vouchers v ON v.voucher_id = c.voucher_id',
'LEFT JOIN accounts b  ON b.account_id  = c.bank_account_id',
'LEFT JOIN accounts vb ON vb.account_id = v.bank_account_id',
'LEFT JOIN accounts ca ON ca.account_id = v.counter_account_id',
'LEFT JOIN journals j  ON j.journal_id  = c.settle_journal_id',
'WHERE  v.status IN (''APPROVED'',''POSTED'')',
'AND    (:P47_TYPE IS NULL OR v.voucher_type = :P47_TYPE)',
'AND    (:P47_STATUS IS NULL OR c.status = :P47_STATUS)',
'AND    c.due_date BETWEEN NVL(TO_DATE(:P47_FROM, ''DD/MM/YYYY''), DATE ''1900-01-01'')',
'                      AND NVL(TO_DATE(:P47_TO,   ''DD/MM/YYYY''), DATE ''2999-12-31'')',
'ORDER BY c.due_date, c.cheque_no'))
);
