wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000349)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  c cheques%ROWTYPE;',
'  v vouchers%ROWTYPE;',
'  l_bank VARCHAR2(200);',
'BEGIN',
'  SELECT * INTO c FROM cheques  WHERE cheque_id  = :P47_CHEQUE_ID;',
'  SELECT * INTO v FROM vouchers WHERE voucher_id = c.voucher_id;',
'  SELECT MAX(name_ar) INTO l_bank FROM accounts WHERE account_id = c.bank_account_id;',
'',
'  :P47_KIND        := v.voucher_type;',
'  :P47_CHQ_STATUS  := c.status;',
'  :P47_JOURNAL_ID  := c.settle_journal_id;',
'  SELECT MAX(status) INTO :P47_JNL_STATUS FROM journals WHERE journal_id = c.settle_journal_id;',
unistr('  :P47_CLEAR_LABEL := CASE v.voucher_type WHEN ''R'' THEN ''\062A\0645 \0627\0644\062A\062D\0635\064A\0644'' ELSE ''\062A\0645 \0627\0644\0635\0631\0641'' END;'),
'  SELECT MAX(name_ar) INTO l_bank FROM accounts WHERE account_id = NVL(c.bank_account_id, v.bank_account_id);',
'  IF :P47_SETTLE_BANK_ID IS NULL THEN :P47_SETTLE_BANK_ID := v.bank_account_id; END IF;',
unistr('  :P47_INFO := CASE v.voucher_type WHEN ''R'' THEN ''\0634\064A\0643 \0648\0627\0631\062F'' ELSE ''\0634\064A\0643 \0635\0627\062F\0631'' END'),
unistr('            || '' \0645\0633\0644\0633\0644 '' || c.cheque_serial || '' - \0631\0642\0645 '' || c.cheque_no || '' - '' || l_bank'),
unistr('            || '' - \0627\0644\0645\0628\0644\063A '' || TO_CHAR(c.amount, ''FM999G999G999G990D00'')'),
unistr('            || '' - \0627\0644\0627\0633\062A\062D\0642\0627\0642 '' || TO_CHAR(c.due_date, ''DD/MM/YYYY'')'),
unistr('            || '' - \0627\0644\0625\0630\0646 '' || v.voucher_no'),
unistr('            || CASE WHEN v.status <> ''POSTED'' THEN '' (\0627\0644\0625\0630\0646 \0644\0645 \064A\064F\0631\062D\0651\0644 \0628\0639\062F: \0644\0627 \064A\0645\0643\0646 \0627\0644\062A\0633\0648\064A\0629 \0642\0628\0644 \0627\0644\062A\0631\062D\064A\0644)'' END'),
unistr('            || CASE c.status WHEN ''CLEARED'' THEN '' - \062A\0645\062A \0627\0644\062A\0633\0648\064A\0629 \0641\064A '' || TO_CHAR(c.settle_date, ''DD/MM/YYYY'')'),
unistr('                             WHEN ''BOUNCED'' THEN '' - \0645\0631\062A\062F \0641\064A '' || TO_CHAR(c.settle_date, ''DD/MM/YYYY'') END;'),
'  IF :P47_SETTLE_DATE IS NULL THEN',
'    :P47_SETTLE_DATE := TO_CHAR(GREATEST(TRUNC(SYSDATE), c.due_date), ''DD/MM/YYYY'');',
'  END IF;',
'EXCEPTION WHEN NO_DATA_FOUND THEN',
'  :P47_CHEQUE_ID := NULL;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_name=>'LOAD_CHEQUE'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':P47_CHEQUE_ID IS NOT NULL'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>91000000000349
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000350)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_clob_language=>'PLSQL'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('  -- \062A\0633\0648\064A\0629 \0634\064A\0643: \064A\0646\0634\0626 \0642\064A\062F \062A\0633\0648\064A\0629 (\0645\0633\0648\062F\0629) \064A\0645\0631 \0628\0627\0644\0645\0631\0627\062C\0639\0629 \0648\0627\0644\0627\0639\062A\0645\0627\062F \062B\0645 \0627\0644\062A\0631\062D\064A\0644 \0645\0646 \0634\0627\0634\0629 \0627\0644\0642\064A\062F'),
unistr('  --   \0635\0627\062F\0631  + \062A\0645 \0627\0644\0635\0631\0641    : \0645\0646 \062D/ \0634\064A\0643\0627\062A \062A\062D\062A \0627\0644\0635\0631\0641     \0625\0644\0649 \062D/ \0627\0644\0628\0646\0643 \0627\0644\0645\0633\062D\0648\0628 \0639\0644\064A\0647'),
unistr('  --   \0648\0627\0631\062F  + \062A\0645 \0627\0644\062A\062D\0635\064A\0644  : \0645\0646 \062D/ \0627\0644\0628\0646\0643 \0627\0644\0645\0648\062F\0639 \0641\064A\0647     \0625\0644\0649 \062D/ \0634\064A\0643\0627\062A \062A\062D\062A \0627\0644\062A\062D\0635\064A\0644'),
unistr('  --   \0648\0627\0631\062F  + \0645\0631\062A\062F        : \0645\0646 \062D/ \0627\0644\062D\0633\0627\0628 \0627\0644\0645\0642\0627\0628\0644 (\0627\0644\0639\0645\064A\0644) \0625\0644\0649 \062D/ \0634\064A\0643\0627\062A \062A\062D\062A \0627\0644\062A\062D\0635\064A\0644'),
unistr('  --   \0635\0627\062F\0631  + \0645\0631\062A\062F/\0645\0644\063A\0649   : \0645\0646 \062D/ \0634\064A\0643\0627\062A \062A\062D\062A \0627\0644\0635\0631\0641     \0625\0644\0649 \062D/ \0627\0644\062D\0633\0627\0628 \0627\0644\0645\0642\0627\0628\0644 (\0627\0644\0645\0648\0631\062F)'),
'  l_req  VARCHAR2(20) := :REQUEST;',
'  c      cheques%ROWTYPE;',
'  v      vouchers%ROWTYPE;',
'  l_date DATE;',
'  l_mid  NUMBER;',
'  l_dr   NUMBER;',
'  l_cr   NUMBER;',
'  l_jid  NUMBER;',
'  l_seq  NUMBER;',
'  l_no   VARCHAR2(30);',
'  l_cnt  NUMBER;',
'  l_jst  VARCHAR2(10);',
'  l_desc VARCHAR2(500);',
'  PROCEDURE err (p VARCHAR2) IS',
'  BEGIN apex_error.add_error(p_message => p, p_display_location => apex_error.c_inline_in_notification); END;',
'BEGIN',
unistr('  IF :G_USER_ROLE NOT IN (''ADMIN'',''ENTRY'') THEN err(''\062A\0633\0648\064A\0629 \0627\0644\0634\064A\0643\0627\062A \0645\0646 \0635\0644\0627\062D\064A\0629 \0627\0644\0645\062F\062E\0644''); RETURN; END IF;'),
'',
'  SELECT * INTO c FROM cheques WHERE cheque_id = :P47_CHEQUE_ID FOR UPDATE;',
'  SELECT * INTO v FROM vouchers WHERE voucher_id = c.voucher_id;',
'',
unistr('  ------------------------------------------------------------ \0625\0644\063A\0627\0621 \0627\0644\062A\0633\0648\064A\0629 (\062A\0635\062D\064A\062D \062E\0637\0623): \0645\0646 \0635\0644\0627\062D\064A\0629 \0627\0644\0645\0639\062A\0645\062F'),
'  IF l_req = ''UNSETTLE'' THEN',
'    SELECT MAX(status) INTO l_jst FROM journals WHERE journal_id = c.settle_journal_id;',
unistr('    IF :G_USER_ROLE NOT IN (''ADMIN'',''APPROVER'') THEN err(''\0625\0644\063A\0627\0621 \062A\0633\0648\064A\0629 \0627\0644\0634\064A\0643 \0645\0646 \0635\0644\0627\062D\064A\0629 \0627\0644\0645\0639\062A\0645\062F''); RETURN; END IF;'),
'    IF c.status = ''PENDING'' OR NVL(l_jst, ''DRAFT'') = ''REVERSED'' THEN',
unistr('      err(''\0627\0644\0634\064A\0643 \063A\064A\0631 \0645\0633\0648\0651\0649 \0623\0648 \0642\064A\062F\0647 \0645\0639\0643\0648\0633''); RETURN;'),
'    END IF;',
'    INSERT INTO doc_actions (doc_type, doc_id, action, from_status, to_status, note, action_by)',
unistr('    VALUES (''CHEQUE'', c.cheque_id, ''UNSETTLE'', c.status, ''PENDING'', ''\062D\0630\0641 \0642\064A\062F \0627\0644\062A\0633\0648\064A\0629 '' || c.settle_journal_id, :APP_USER);'),
'    UPDATE cheques SET status = ''PENDING'', settle_date = NULL, settle_bank_id = NULL, settle_journal_id = NULL, settled_by = NULL',
'    WHERE  cheque_id = c.cheque_id;',
'    IF c.settle_journal_id IS NOT NULL THEN',
'      DELETE FROM journal_lines WHERE journal_id = c.settle_journal_id;',
'      DELETE FROM journals      WHERE journal_id = c.settle_journal_id;',
'    END IF;',
unistr('    apex_application.g_print_success_message := ''\062A\0645 \0625\0644\063A\0627\0621 \062A\0633\0648\064A\0629 \0627\0644\0634\064A\0643 '' || c.cheque_no;'),
'    RETURN;',
'  END IF;',
'',
unistr('  ------------------------------------------------------------ \0627\0644\062A\062D\0642\0642'),
unistr('  IF v.status <> ''POSTED'' THEN err(''\0644\0627 \062A\064F\0633\0648\0651\0649 \0627\0644\0634\064A\0643\0627\062A \0642\0628\0644 \062A\0631\062D\064A\0644 \0627\0644\0625\0630\0646 '' || v.voucher_no); END IF;'),
unistr('  IF c.status <> ''PENDING'' THEN err(''\0627\0644\0634\064A\0643 \062A\0645\062A \062A\0633\0648\064A\062A\0647 \0645\0646 \0642\0628\0644''); END IF;'),
'  BEGIN l_date := TO_DATE(:P47_SETTLE_DATE, ''DD/MM/YYYY'');',
unistr('  EXCEPTION WHEN OTHERS THEN err(''\062A\0627\0631\064A\062E \0627\0644\062A\0633\0648\064A\0629 \063A\064A\0631 \0635\062D\064A\062D''); END;'),
unistr('  IF l_date IS NULL THEN err(''\0623\062F\062E\0644 \062A\0627\0631\064A\062E \0627\0644\062A\0633\0648\064A\0629'');'),
'  ELSE',
'    SELECT COUNT(*) INTO l_cnt FROM fiscal_years WHERE l_date BETWEEN start_date AND end_date AND is_closed = ''N'';',
unistr('    IF l_cnt = 0 THEN err(''\0627\0644\062A\0627\0631\064A\062E \062E\0627\0631\062C \0633\0646\0629 \0645\0627\0644\064A\0629 \0645\0641\062A\0648\062D\0629''); END IF;'),
'  END IF;',
'  IF l_req = ''CLEAR'' AND v.voucher_type = ''R'' THEN',
'    SELECT COUNT(*) INTO l_cnt FROM accounts WHERE account_id = :P47_SETTLE_BANK_ID AND cash_bank = ''B'';',
unistr('    IF l_cnt = 0 THEN err(''\0627\062E\062A\0631 \0627\0644\0628\0646\0643 \0627\0644\0630\064A \0623\0648\062F\0639 \0641\064A\0647 \0627\0644\0634\064A\0643''); END IF;'),
'  END IF;',
'',
'  BEGIN',
'    SELECT account_id INTO l_mid FROM account_settings',
'    WHERE  company_id = v.company_id AND setting_code = CASE v.voucher_type WHEN ''R'' THEN ''CHEQUES_IN'' ELSE ''CHEQUES_OUT'' END;',
unistr('  EXCEPTION WHEN NO_DATA_FOUND THEN err(''\062D\062F\062F \062D\0633\0627\0628 \0627\0644\0634\064A\0643\0627\062A \0641\064A \0627\0644\062D\0633\0627\0628\0627\062A \0627\0644\0627\0641\062A\0631\0627\0636\064A\0629'');'),
'  END;',
'  IF apex_error.have_errors_occurred THEN RETURN; END IF;',
'',
'  IF v.voucher_type = ''P'' THEN',
'    l_dr := l_mid;',
'    l_cr := CASE l_req WHEN ''CLEAR'' THEN c.bank_account_id ELSE v.counter_account_id END;',
'  ELSE',
'    l_cr := l_mid;',
'    l_dr := CASE l_req WHEN ''CLEAR'' THEN TO_NUMBER(:P47_SETTLE_BANK_ID) ELSE v.counter_account_id END;',
'  END IF;',
'',
unistr('  l_desc := CASE WHEN l_req = ''BOUNCE'' THEN ''\0627\0631\062A\062F\0627\062F \0634\064A\0643 '' WHEN v.voucher_type = ''R'' THEN ''\062A\062D\0635\064A\0644 \0634\064A\0643 '' ELSE ''\0635\0631\0641 \0634\064A\0643 '' END'),
unistr('            || c.cheque_no || '' - \0625\0630\0646 '' || v.voucher_no || CASE WHEN c.payee_name IS NOT NULL THEN '' - '' || c.payee_name END;'),
'',
unistr('  ------------------------------------------------------------ \0642\064A\062F \0627\0644\062A\0633\0648\064A\0629 (\0645\0633\0648\062F\0629) - \0627\0644\062A\0631\0642\064A\0645 15 + \0627\0644\0633\0646\0629 + \062A\0633\0644\0633\0644'),
'  UPDATE doc_sequences SET last_no = last_no + 1',
'  WHERE  company_id = v.company_id AND doc_type = ''15'' AND fy_year = EXTRACT(YEAR FROM l_date)',
'  RETURNING last_no INTO l_seq;',
'  IF SQL%ROWCOUNT = 0 THEN',
'    INSERT INTO doc_sequences (company_id, doc_type, fy_year, last_no) VALUES (v.company_id, ''15'', EXTRACT(YEAR FROM l_date), 1);',
'    l_seq := 1;',
'  END IF;',
'  l_no := ''15'' || EXTRACT(YEAR FROM l_date) || LPAD(l_seq, 5, ''0'');',
'',
'  INSERT INTO journals (company_id, jt_code, journal_no, journal_date, currency_code, exchange_rate, description,',
'                        ref_no, status, source_type, source_id, total_debit, total_credit, created_by)',
unistr('  -- \0627\0644\0634\064A\0643 \0631\0648\062C\0639 \0648\0627\0639\062A\064F\0645\062F \0645\0639 \0625\0630\0646\0647: \0642\064A\062F \0627\0644\062A\0633\0648\064A\0629 \064A\064F\0631\062D\0651\0644 \0645\0628\0627\0634\0631\0629'),
'  VALUES (v.company_id, ''CQ'', l_no, l_date, v.currency_code, v.exchange_rate, l_desc,',
'          c.cheque_no, ''POSTED'', ''CHEQUE'', c.cheque_id, c.amount, c.amount, :APP_USER)',
'  RETURNING journal_id INTO l_jid;',
'  UPDATE journals SET reviewed_by = v.reviewed_by, reviewed_on = v.reviewed_on, approved_by = v.approved_by,',
'         approved_on = v.approved_on, posted_by = :APP_USER, posted_on = SYSDATE WHERE journal_id = l_jid;',
'',
'  INSERT INTO journal_lines (journal_id, line_no, account_id, debit, credit, debit_base, credit_base, description)',
'  VALUES (l_jid, 1, l_dr, c.amount, 0, ROUND(c.amount * v.exchange_rate, 2), 0, l_desc);',
'  INSERT INTO journal_lines (journal_id, line_no, account_id, debit, credit, debit_base, credit_base, description)',
'  VALUES (l_jid, 2, l_cr, 0, c.amount, 0, ROUND(c.amount * v.exchange_rate, 2), l_desc);',
'',
'  UPDATE cheques',
'  SET    status = CASE l_req WHEN ''CLEAR'' THEN ''CLEARED'' ELSE ''BOUNCED'' END,',
'         settle_date = l_date,',
'         settle_bank_id = CASE WHEN l_req = ''CLEAR'' AND v.voucher_type = ''R'' THEN TO_NUMBER(:P47_SETTLE_BANK_ID) END,',
'         settle_journal_id = l_jid, settled_by = :APP_USER',
'  WHERE  cheque_id = c.cheque_id;',
'',
'  INSERT INTO doc_actions (doc_type, doc_id, action, to_status, note, action_by)',
'  VALUES (''JOURNAL'', l_jid, ''POST'', ''POSTED'', l_desc, :APP_USER);',
'',
unistr('  apex_application.g_print_success_message := CASE WHEN l_req = ''BOUNCE'' THEN ''\062A\0645 \062A\0633\062C\064A\0644 \0627\0644\0634\064A\0643 \0645\0631\062A\062F\0627\064B'' WHEN v.voucher_type = ''R'' THEN ''\062A\0645 \062A\062D\0635\064A\0644 \0627\0644\0634\064A\0643'' ELSE ''\062A\0645 \0635\0631\0641 \0627\0644\0634\064A\0643'' END || '' \0648\062A\0631\062D\064A\0644 \0642\064A\062F \0627\0644\062A\0633\0648\064A\0629 '' || l_no;'),
'END;'))
,p_process_name=>'SETTLE'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'CLEAR,BOUNCE,UNSETTLE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_internal_uid=>91000000000350
);
