 p_id=>wwv_flow_imp.id(91000000000352)
,p_plug_name=>'chq'
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(6697232433757451)
,p_plug_display_sequence=>10
,p_location=>null
,p_plug_source_type=>'NATIVE_PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('  -- \0637\0628\0627\0639\0629 \0627\0644\0634\064A\0643 \0628\0645\0642\0627\0633 \0627\0644\0634\064A\0643 \0627\0644\0628\0646\0643\064A: \0627\0644\0645\0648\0627\0636\0639 \0628\0627\0644\0645\0644\064A\0645\062A\0631 \0645\0646 \062C\062F\0648\0644 cheque_layouts \0644\0643\0644 \0628\0646\0643 (\0623\0648 \0627\0644\0645\0642\0627\0633 \0627\0644\0627\0641\062A\0631\0627\0636\064A)'),
'  c  cheques%ROWTYPE;',
'  v  vouchers%ROWTYPE;',
'  ly cheque_layouts%ROWTYPE;',
'  l_bank VARCHAR2(200);',
unistr('  -- \062A\0641\0642\064A\0637 \0627\0644\0645\0628\0644\063A \0628\0627\0644\0639\0631\0628\064A\0629: \062C\0646\064A\0647 \0633\0648\062F\0627\0646\064A \0648\0642\0631\0634'),
'  FUNCTION words3 (n PLS_INTEGER) RETURN VARCHAR2 IS',
'    TYPE t_a IS TABLE OF VARCHAR2(30) INDEX BY PLS_INTEGER;',
'    o t_a; t t_a; h t_a;',
'    l_h PLS_INTEGER := TRUNC(n / 100);',
'    l_r PLS_INTEGER := MOD(n, 100);',
'    l_s VARCHAR2(200);',
'    l_x VARCHAR2(100);',
'  BEGIN',
unistr('    o(1) := ''\0648\0627\062D\062F''; o(2) := ''\0627\062B\0646\0627\0646''; o(3) := ''\062B\0644\0627\062B\0629''; o(4) := ''\0623\0631\0628\0639\0629''; o(5) := ''\062E\0645\0633\0629'';'),
unistr('    o(6) := ''\0633\062A\0629''; o(7) := ''\0633\0628\0639\0629''; o(8) := ''\062B\0645\0627\0646\064A\0629''; o(9) := ''\062A\0633\0639\0629''; o(10) := ''\0639\0634\0631\0629'';'),
unistr('    o(11) := ''\0623\062D\062F \0639\0634\0631''; o(12) := ''\0627\062B\0646\0627 \0639\0634\0631''; o(13) := ''\062B\0644\0627\062B\0629 \0639\0634\0631''; o(14) := ''\0623\0631\0628\0639\0629 \0639\0634\0631''; o(15) := ''\062E\0645\0633\0629 \0639\0634\0631'';'),
unistr('    o(16) := ''\0633\062A\0629 \0639\0634\0631''; o(17) := ''\0633\0628\0639\0629 \0639\0634\0631''; o(18) := ''\062B\0645\0627\0646\064A\0629 \0639\0634\0631''; o(19) := ''\062A\0633\0639\0629 \0639\0634\0631'';'),
unistr('    t(2) := ''\0639\0634\0631\0648\0646''; t(3) := ''\062B\0644\0627\062B\0648\0646''; t(4) := ''\0623\0631\0628\0639\0648\0646''; t(5) := ''\062E\0645\0633\0648\0646'';'),
unistr('    t(6) := ''\0633\062A\0648\0646''; t(7) := ''\0633\0628\0639\0648\0646''; t(8) := ''\062B\0645\0627\0646\0648\0646''; t(9) := ''\062A\0633\0639\0648\0646'';'),
unistr('    h(1) := ''\0645\0627\0626\0629''; h(2) := ''\0645\0627\0626\062A\0627\0646''; h(3) := ''\062B\0644\0627\062B\0645\0627\0626\0629''; h(4) := ''\0623\0631\0628\0639\0645\0627\0626\0629''; h(5) := ''\062E\0645\0633\0645\0627\0626\0629'';'),
unistr('    h(6) := ''\0633\062A\0645\0627\0626\0629''; h(7) := ''\0633\0628\0639\0645\0627\0626\0629''; h(8) := ''\062B\0645\0627\0646\0645\0627\0626\0629''; h(9) := ''\062A\0633\0639\0645\0627\0626\0629'';'),
'    IF l_h > 0 THEN l_s := h(l_h); END IF;',
'    IF l_r > 0 THEN',
'      IF l_r < 20 THEN l_x := o(l_r);',
'      ELSIF MOD(l_r, 10) = 0 THEN l_x := t(TRUNC(l_r / 10));',
unistr('      ELSE l_x := o(MOD(l_r, 10)) || '' \0648'' || t(TRUNC(l_r / 10));'),
'      END IF;',
unistr('      l_s := CASE WHEN l_s IS NULL THEN l_x ELSE l_s || '' \0648'' || l_x END;'),
'    END IF;',
'    RETURN l_s;',
'  END;',
'',
'  FUNCTION words (p NUMBER) RETURN VARCHAR2 IS',
'    l_n   NUMBER := TRUNC(ABS(p));',
'    l_g   PLS_INTEGER;',
'    l_s   VARCHAR2(1000);',
'    l_x   VARCHAR2(300);',
'    TYPE t_s IS TABLE OF VARCHAR2(30) INDEX BY PLS_INTEGER;',
'    s1 t_s; s2 t_s; sp t_s;',
'  BEGIN',
unistr('    IF l_n = 0 THEN RETURN ''\0635\0641\0631''; END IF;'),
unistr('    s1(1) := ''\0623\0644\0641'';   s2(1) := ''\0623\0644\0641\0627\0646'';   sp(1) := ''\0622\0644\0627\0641'';'),
unistr('    s1(2) := ''\0645\0644\064A\0648\0646''; s2(2) := ''\0645\0644\064A\0648\0646\0627\0646''; sp(2) := ''\0645\0644\0627\064A\064A\0646'';'),
unistr('    s1(3) := ''\0645\0644\064A\0627\0631''; s2(3) := ''\0645\0644\064A\0627\0631\0627\0646''; sp(3) := ''\0645\0644\064A\0627\0631\0627\062A'';'),
'    FOR i IN REVERSE 0 .. 3 LOOP',
'      l_g := TRUNC(MOD(l_n, POWER(1000, i + 1)) / POWER(1000, i));',
'      IF l_g > 0 THEN',
'        IF i = 0 THEN l_x := words3(l_g);',
'        ELSIF l_g = 1 THEN l_x := s1(i);',
'        ELSIF l_g = 2 THEN l_x := s2(i);',
'        ELSIF l_g BETWEEN 3 AND 10 THEN l_x := words3(l_g) || '' '' || sp(i);',
'        ELSE l_x := words3(l_g) || '' '' || s1(i);',
'        END IF;',
unistr('        l_s := CASE WHEN l_s IS NULL THEN l_x ELSE l_s || '' \0648'' || l_x END;'),
'      END IF;',
'    END LOOP;',
'    RETURN l_s;',
'  END;',
'',
'  FUNCTION tafqeet (p NUMBER) RETURN VARCHAR2 IS',
'    l_p NUMBER := ROUND(MOD(ABS(p), 1) * 100);',
'  BEGIN',
unistr('    RETURN ''\0641\0642\0637 '' || words(p) || '' \062C\0646\064A\0647 \0633\0648\062F\0627\0646\064A'''),
unistr('        || CASE WHEN l_p > 0 THEN '' \0648'' || words(l_p) || '' \0642\0631\0634'' END || '' \0644\0627 \063A\064A\0631'';'),
'  END;',
'',
'  FUNCTION pos (p_top NUMBER, p_right NUMBER) RETURN VARCHAR2 IS',
'  BEGIN RETURN ''top:'' || TO_CHAR(p_top, ''FM9990.0'') || ''mm;right:'' || TO_CHAR(p_right, ''FM9990.0'') || ''mm;''; END;',
'BEGIN',
'  BEGIN',
'    SELECT * INTO c FROM cheques  WHERE cheque_id  = :P48_CHEQUE_ID;',
'    SELECT * INTO v FROM vouchers WHERE voucher_id = c.voucher_id;',
unistr('  EXCEPTION WHEN NO_DATA_FOUND THEN htp.p(''<p>\0627\0644\0634\064A\0643 \063A\064A\0631 \0645\0648\062C\0648\062F</p>''); RETURN;'),
'  END;',
unistr('  IF v.voucher_type <> ''P'' THEN htp.p(''<p>\0627\0644\0637\0628\0627\0639\0629 \0644\0644\0634\064A\0643\0627\062A \0627\0644\0635\0627\062F\0631\0629 \0641\0642\0637</p>''); RETURN; END IF;'),
'',
'  BEGIN',
'    SELECT * INTO ly FROM cheque_layouts WHERE bank_account_id = c.bank_account_id;',
'  EXCEPTION WHEN NO_DATA_FOUND THEN',
'    SELECT * INTO ly FROM cheque_layouts WHERE bank_account_id IS NULL AND ROWNUM = 1;',
'  END;',
'  SELECT MAX(name_ar) INTO l_bank FROM accounts WHERE account_id = c.bank_account_id;',
'',
'  htp.p(''<style>@page { size: '' || ly.width_mm || ''mm '' || ly.height_mm || ''mm; margin: 0; }</style>'');',
unistr('  htp.p(''<div class="no-print"><button type="button" class="t-Button t-Button--hot" onclick="window.print()">\0637\0628\0627\0639\0629 \0627\0644\0634\064A\0643</button>'''),
unistr('        || '' &nbsp; <span style="color:#666">'' || apex_escape.html(l_bank) || '' - \0645\0633\0644\0633\0644 '' || c.cheque_serial || '' - \0634\064A\0643 \0631\0642\0645 '' || apex_escape.html(c.cheque_no)'),
unistr('        || '' - \0645\0642\0627\0633 '' || ly.width_mm || '' \00D7 '' || ly.height_mm || '' \0645\0645 ('' || apex_escape.html(ly.layout_name) || '')</span></div>'');'),
'  htp.p(''<div class="chq" style="width:'' || ly.width_mm || ''mm;height:'' || ly.height_mm || ''mm;font-size:'' || ly.font_size || ''px">'');',
'  htp.p(''<div style="'' || pos(ly.date_top, ly.date_right) || ''">'' || TO_CHAR(c.due_date, ''DD/MM/YYYY'') || ''</div>'');',
'  htp.p(''<div style="'' || pos(ly.payee_top, ly.payee_right) || ''">'' || apex_escape.html(c.payee_name) || ''</div>'');',
