,p_plug_name=>unistr('\0627\0644\0645\0633\062A\0646\062F\0627\062A \062D\0633\0628 \062F\0648\0631\0647\0627 \0641\064A \0627\0644\0645\0631\0627\062C\0639\0629 \0648\0627\0644\0627\0639\062A\0645\0627\062F')
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(6687458349757443)
,p_plug_display_sequence=>10
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>unistr('\0627\0644\0645\0633\062A\0646\062F\0627\062A \062D\0633\0628 \062F\0648\0631\0647\0627 \0641\064A \0627\0644\0645\0631\0627\062C\0639\0629 \0648\0627\0644\0627\0639\062A\0645\0627\062F')
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT d.journal_id, d.cash_voucher_id, d.chq_voucher_id, d.adj_id, d.voucher_type, d.adj_type,',
unistr('       d."\0627\0644\0645\0633\062A\0646\062F", d."\0642\064A\062F", d."\0625\0630\0646 \0646\0642\062F\064A", d."\0625\0630\0646 \0634\064A\0643\0627\062A", d."\062A\0633\0648\064A\0629 \0631\0648\0627\062A\0628", d."\0627\0644\062A\0627\0631\064A\062E", d."\0627\0644\0628\064A\0627\0646", d."\0627\0644\0645\0628\0644\063A",'),
unistr('       DECODE(d.st, ''DRAFT'', ''\0645\0633\0648\062F\0629 - \0628\0627\0646\062A\0638\0627\0631 \0627\0644\0645\0631\0627\062C\0639\0629'', ''RETURNED'', ''\0645\0639\0627\062F \0644\0644\0645\062F\062E\0644'','),
unistr('              ''REVIEWED'', ''\0645\064F\0631\0627\062C\064E\0639 - \0628\0627\0646\062A\0638\0627\0631 \0627\0644\0627\0639\062A\0645\0627\062F'', ''APPROVED'', ''\0645\0639\062A\0645\062F - \0628\0627\0646\062A\0638\0627\0631 \0627\0644\062A\0631\062D\064A\0644'') AS "\0627\0644\062D\0627\0644\0629",'),
unistr('       d."\0627\0644\0645\062F\062E\0644", d."\0633\0628\0628 \0627\0644\0625\0639\0627\062F\0629"'),
'FROM (',
unistr('  SELECT ''\0642\064A\062F \064A\0648\0645\064A\0629'' AS "\0627\0644\0645\0633\062A\0646\062F", j.journal_no AS "\0642\064A\062F", NULL AS "\0625\0630\0646 \0646\0642\062F\064A", NULL AS "\0625\0630\0646 \0634\064A\0643\0627\062A", NULL AS "\062A\0633\0648\064A\0629 \0631\0648\0627\062A\0628",'),
'         j.journal_id, NULL AS cash_voucher_id, NULL AS chq_voucher_id, NULL AS adj_id, NULL AS voucher_type, NULL AS adj_type,',
unistr('         j.journal_date AS "\0627\0644\062A\0627\0631\064A\062E", j.description AS "\0627\0644\0628\064A\0627\0646", j.total_debit AS "\0627\0644\0645\0628\0644\063A", j.status AS st,'),
unistr('         j.created_by AS "\0627\0644\0645\062F\062E\0644", j.return_note AS "\0633\0628\0628 \0627\0644\0625\0639\0627\062F\0629"'),
'  FROM   journals j WHERE j.status IN (''DRAFT'',''RETURNED'',''REVIEWED'',''APPROVED'') AND j.source_type IN (''MANUAL'',''CHEQUE'')',
'  UNION ALL',
unistr('  SELECT CASE v.voucher_type WHEN ''R'' THEN ''\0625\0630\0646 \062A\0648\0631\064A\062F '' ELSE ''\0625\0630\0646 \0635\0631\0641 '' END || CASE v.voucher_kind WHEN ''CHEQUE'' THEN ''\0634\064A\0643\0627\062A'' ELSE ''\0646\0642\062F\064A'' END,'),
'         NULL, CASE WHEN v.voucher_kind = ''CASH'' THEN v.voucher_no END, CASE WHEN v.voucher_kind = ''CHEQUE'' THEN v.voucher_no END, NULL,',
'         NULL, CASE WHEN v.voucher_kind = ''CASH'' THEN v.voucher_id END, CASE WHEN v.voucher_kind = ''CHEQUE'' THEN v.voucher_id END, NULL,',
'         v.voucher_type, NULL,',
'         v.voucher_date, v.description, v.total_amount, v.status, v.created_by, v.return_note',
'  FROM   vouchers v WHERE v.status IN (''DRAFT'',''RETURNED'',''REVIEWED'',''APPROVED'')',
'  UNION ALL',
unistr('  SELECT DECODE(a.adj_type, ''DED'', ''\062E\0635\0645'', ''DIFF'', ''\0641\0631\0642 \0645\0628\0644\063A'', ''\062D\0627\0641\0632''), NULL, NULL, NULL, a.adj_no,'),
'         NULL, NULL, NULL, a.adj_id, NULL, a.adj_type,',
'         a.adj_date, a.reason, NULL, a.status, a.created_by, a.return_note',
'  FROM   payroll_adj a WHERE a.status IN (''DRAFT'',''RETURNED'',''REVIEWED'')',
') d',
'WHERE (:G_USER_ROLE = ''ADMIN''',
'       OR (:G_USER_ROLE = ''ENTRY''    AND d.st IN (''DRAFT'',''RETURNED''))',
'       OR (:G_USER_ROLE = ''REVIEWER'' AND d.st IN (''DRAFT'',''REVIEWED''))',
'       OR (:G_USER_ROLE = ''APPROVER'' AND d.st IN (''REVIEWED'',''APPROVED'')))'))
,p_query_type=>'SQL'
);
