wwv_flow_imp_page.create_page(
 p_id=>50
,p_name=>unistr('\0641\0627\062A\0648\0631\0629 \0645\0628\064A\0639\0627\062A')
,p_alias=>'SALES'
,p_step_title=>'&P50_TITLE.'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var inv = {',
'  grid: null,',
'',
'  units: function (row, g) {',
'    var it = (g || inv.grid).lovRecord(''items'', row.ITEM_ID);',
'    return it ? it.units : [];',
'  },',
'',
'  init: function () {',
'    var status = apex.item(''P50_STATUS'').getValue() || ''DRAFT'';',
'    inv.grid = new JsonLines({',
'      container: ''#inv_lines'',',
'      readOnly : status !== ''DRAFT'' || !DocUtil.canEdit(status),',
'      columns  : [',
unistr('        {name: ''ITEM_ID'',    label: ''\0627\0644\0635\0646\0641 (\0643\0648\062F / \0627\0633\0645 / \0628\0627\0631\0643\0648\062F)'', type: ''lov'', lov: ''items'', required: true, width: ''26em''},'),
unistr('        {name: ''UNIT_ID'',    label: ''\0627\0644\0648\062D\062F\0629'',   type: ''select'', required: true, nullText: false, options: inv.units, width: ''8em'', readonly: true},'),
unistr('        {name: ''BAL'',        label: ''\0627\0644\0631\0635\064A\062F'',   type: ''display'', decimals: 2, noSubmit: true, width: ''7em''},'),
unistr('        {name: ''QTY'',        label: ''\0627\0644\0643\0645\064A\0629'',   type: ''number'', decimals: 2, required: true, width: ''7em''},'),
unistr('        {name: ''PRICE'',      label: ''\0627\0644\0633\0639\0631'',    type: ''number'', decimals: 2, required: true, width: ''9em'', readonly: true},'),
unistr('        {name: ''DISCOUNT'',   label: ''\0627\0644\062E\0635\0645'',    type: ''number'', decimals: 2, total: true, width: ''7em''},'),
unistr('        {name: ''LINE_TOTAL'', label: ''\0627\0644\0625\062C\0645\0627\0644\064A'', type: ''display'', decimals: 2, total: true, noSubmit: true}'),
'      ],',
'      onChange: function (row, col, g) {',
'        if (col === ''ITEM_ID'') {',
'          var u = inv.units(row, g);',
unistr('          row.UNIT_ID = row[''ITEM_ID$unit''] || (u.length ? u[0].v : null);   // \0648\062D\062F\0629 \0627\0644\0628\0627\0631\0643\0648\062F \0623\0648 \0627\0644\0623\0635\063A\0631'),
'          col = ''UNIT_ID'';',
'        }',
'        var unit = inv.units(row, g).filter(function (x) { return String(x.v) === String(row.UNIT_ID); })[0];',
'        if (col === ''UNIT_ID'') {',
