wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000402)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_clob_language=>'PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE i invoices%ROWTYPE;',
'BEGIN',
'  :P50_LOADED_ID := :P50_INVOICE_ID;',
'  SELECT * INTO i FROM invoices WHERE invoice_id = :P50_INVOICE_ID;',
'  :P50_INVOICE_TYPE := i.invoice_type; :P50_INVOICE_NO := i.invoice_no;',
'  :P50_INVOICE_DATE := TO_CHAR(i.invoice_date, ''DD/MM/YYYY'');',
'  :P50_PAY_TYPE := i.pay_type; :P50_ACCOUNT_ID := i.account_id;',
'  :P50_CUSTOMER_NAME := i.customer_name; :P50_WAREHOUSE_ID := i.warehouse_id; :P50_PRICE_LIST_ID := i.price_list_id;',
'  :P50_CURRENCY_CODE := i.currency_code; :P50_EXCHANGE_RATE := i.exchange_rate;',
'  :P50_DISCOUNT_AMOUNT := i.discount_amount; :P50_DESCRIPTION := i.description;',
'  :P50_STATUS := i.status; :P50_JOURNAL_ID := i.journal_id;',
'END;'))
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'LOAD_HEADER'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':P50_INVOICE_ID IS NOT NULL AND :P50_INVOICE_ID <> NVL(:P50_LOADED_ID, ''x'')'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>91000000000402
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000403)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_clob_language=>'PLSQL'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P50_INVOICE_TYPE IS NULL THEN :P50_INVOICE_TYPE := ''SALE''; END IF;',
'SELECT MAX(shift_id) INTO :P50_SHIFT_ID FROM sales_shifts WHERE user_name = :APP_USER AND status = ''OPEN'';',
'IF :P50_PAY_TYPE IS NULL THEN :P50_PAY_TYPE := ''CASH''; END IF;',
'IF :P50_INVOICE_ID IS NULL THEN',
'  IF :P50_STATUS IS NULL THEN :P50_STATUS := ''DRAFT''; END IF;',
'  IF :P50_WAREHOUSE_ID IS NULL THEN SELECT MIN(warehouse_id) INTO :P50_WAREHOUSE_ID FROM warehouses WHERE company_id = :G_PARENT_ID AND is_active = ''Y''; END IF;',
'  IF :P50_INVOICE_DATE IS NULL THEN :P50_INVOICE_DATE := TO_CHAR(SYSDATE, ''DD/MM/YYYY''); END IF;',
'  IF :P50_CURRENCY_CODE IS NULL THEN SELECT currency_code INTO :P50_CURRENCY_CODE FROM currencies WHERE is_base = ''Y''; :P50_EXCHANGE_RATE := 1; END IF;',
'END IF;',
unistr(':P50_TITLE := CASE :P50_INVOICE_TYPE WHEN ''SALE'' THEN ''\0641\0627\062A\0648\0631\0629 \0645\0628\064A\0639\0627\062A'' ELSE ''\0645\0631\062A\062C\0639 \0645\0628\064A\0639\0627\062A'' END;')))
,p_process_name=>'DEFAULTS'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000403
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000404)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('  -- x01 = \0642\0627\0626\0645\0629 \0627\0644\0623\0633\0639\0627\0631 (\0627\062E\062A\064A\0627\0631\064A\0629) \060C x02 = \0631\0642\0645 \0627\0644\0641\0627\062A\0648\0631\0629 \060C x03 = \0627\0644\0645\062E\0632\0646'),
'  l_items CLOB;',
'  l_lines CLOB;',
'  l_pl    NUMBER := TO_NUMBER(apex_application.g_x01);',
'  l_wh    NUMBER := TO_NUMBER(apex_application.g_x03);',
'BEGIN',
'  SELECT JSON_ARRAYAGG(JSON_OBJECT(',
'           ''id''    VALUE i.item_id,',
'           ''code''  VALUE i.item_code,',
'           ''name''  VALUE i.name_ar,',
'           ''bc0''   VALUE i.barcode,',
'           ''bu''    VALUE i.base_unit_id,',
'           ''bc''    VALUE (SELECT JSON_OBJECTAGG(KEY ub.barcode VALUE ub.unit_id)',
'                          FROM item_units ub WHERE ub.item_id = i.item_id AND ub.barcode IS NOT NULL) FORMAT JSON,',
'           ''bal''   VALUE NVL(b.qty_base, 0),',
'           ''units'' VALUE (SELECT JSON_ARRAYAGG(JSON_OBJECT(',
'                                   ''v''      VALUE u.unit_id,',
'                                   ''t''      VALUE un.name_ar,',
'                                   ''factor'' VALUE u.factor,',
'                                   ''price''  VALUE NVL(p.price, CASE WHEN u.unit_id = i.big_unit_id AND i.big_sale_price > 0 THEN i.big_sale_price ELSE NULLIF(i.sale_price, 0) * u.factor END)) ORDER BY u.factor)',
'                          FROM   item_units u',
'                          JOIN   units un ON un.unit_id = u.unit_id',
'                          LEFT JOIN price_list_items p',
'                                 ON p.price_list_id = l_pl AND p.item_id = u.item_id AND p.unit_id = u.unit_id',
'                          WHERE  u.item_id = i.item_id) FORMAT JSON',
'         ) ORDER BY i.item_code RETURNING CLOB)',
'  INTO   l_items',
'  FROM   items i',
'  LEFT JOIN v_stock_balance b ON b.item_id = i.item_id AND b.warehouse_id = l_wh',
'  WHERE  i.is_active = ''Y'';',
'',
'  SELECT JSON_ARRAYAGG(JSON_OBJECT(',
'           ''ITEM_ID'' VALUE item_id, ''UNIT_ID'' VALUE unit_id, ''QTY'' VALUE qty,',
'           ''PRICE'' VALUE price, ''DISCOUNT'' VALUE NULLIF(discount, 0), ''LINE_TOTAL'' VALUE line_total)',
'         ORDER BY line_no RETURNING CLOB)',
'  INTO   l_lines',
'  FROM   invoice_lines WHERE invoice_id = TO_NUMBER(apex_application.g_x02);',
'',
'  apex_util.prn(''{"items":'' || COALESCE(l_items, TO_CLOB(''[]'')) ||',
'                '',"lines":'' || COALESCE(l_lines, TO_CLOB(''[]'')) || ''}'', FALSE);',
'END;'))
,p_process_type=>'NATIVE_PLSQL'
,p_process_clob_language=>'PLSQL'
,p_process_name=>'INIT_DATA'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000404
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000405)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('  -- \0641\0627\062A\0648\0631\0629 \0645\0628\064A\0639\0627\062A / \0645\0631\062A\062C\0639 \0645\0628\064A\0639\0627\062A \0644\0644\0634\0631\0643\0629 \0627\0644\0623\0645'),
unistr('  -- \0627\0644\0639\0645\064A\0644: \0641\0631\0639 \0645\0646 \0627\0644\0634\0631\0643\0629 (\0622\062C\0644 \0639\0644\0649 \062D\0633\0627\0628 \0627\0644\0641\0631\0639) \0623\0648 \0639\0645\064A\0644 \062E\0627\0631\062C\064A (\0646\0642\062F\064A: \062E\0632\064A\0646\0629 / \062A\062D\0648\064A\0644 \0628\0646\0643\064A \060C \0623\0648 \0622\062C\0644 \0639\0644\0649 \062D\0633\0627\0628)'),
unistr('  -- \0631\0642\0645 \0627\0644\0641\0627\062A\0648\0631\0629 \0623\0631\0642\0627\0645 \0641\0642\0637: \0631\0645\0632 \0627\0644\0646\0648\0639 + \0627\0644\0633\0646\0629 + \0645\062A\0633\0644\0633\0644 5 \0623\0631\0642\0627\0645'),
unistr('  --   1 \0645\0628\064A\0639\0627\062A \0646\0642\062F\064A\0629 \060C 2 \0645\0628\064A\0639\0627\062A \0622\062C\0644\0629 \060C 5 \0645\0631\062A\062C\0639 \0645\0628\064A\0639\0627\062A \0646\0642\062F\064A \060C 6 \0645\0631\062A\062C\0639 \0645\0628\064A\0639\0627\062A \0622\062C\0644'),
'  l_clob   CLOB := apex_application.g_clob_01;',
'  l_action VARCHAR2(10) := apex_application.g_x01;',
'  l_errs   apex_t_varchar2 := apex_t_varchar2();',
'  l_company NUMBER := :G_PARENT_ID;',
'',
'  l_id NUMBER; l_type VARCHAR2(10); l_ctype VARCHAR2(10); l_cust NUMBER; l_date_s VARCHAR2(20); l_date DATE;',
'  l_pay VARCHAR2(10); l_method VARCHAR2(10); l_acc NUMBER; l_cname VARCHAR2(150);',
'  l_wh NUMBER; l_pl NUMBER; l_cur VARCHAR2(3); l_rate NUMBER; l_disc NUMBER; l_desc VARCHAR2(500);',
'',
'  l_status VARCHAR2(10); l_no VARCHAR2(30); l_code VARCHAR2(1); l_seq NUMBER; l_cnt NUMBER;',
'  l_cb VARCHAR2(1); l_branch VARCHAR2(150);',
'  l_gross NUMBER := 0; l_net NUMBER; l_lines NUMBER := 0; l_jt VARCHAR2(10); l_sign NUMBER;',
'  l_jid NUMBER; l_so NUMBER; l_cogs NUMBER; l_base NUMBER; l_line NUMBER := 0;',
'  l_sales_acc NUMBER; l_ret_acc NUMBER; l_cogs_acc NUMBER; l_inv_acc NUMBER;',
'  l_shift NUMBER;',
'',
'  PROCEDURE err (p VARCHAR2) IS BEGIN l_errs.EXTEND; l_errs(l_errs.COUNT) := p; END;',
'',
'  FUNCTION setting (p_code VARCHAR2) RETURN NUMBER IS l NUMBER;',
'  BEGIN',
'    SELECT account_id INTO l FROM account_settings WHERE company_id = l_company AND setting_code = p_code;',
'    RETURN l;',
'  EXCEPTION WHEN NO_DATA_FOUND THEN',
unistr('    raise_application_error(-20010, ''\0644\0645 \064A\064F\0639\0631\064E\0651\0641 \0627\0644\062D\0633\0627\0628 \0627\0644\0627\0641\062A\0631\0627\0636\064A '' || p_code || '' \0644\0644\0634\0631\0643\0629 \0627\0644\0623\0645'');'),
'  END;',
'',
unistr('  PROCEDURE jline (p_acc NUMBER, p_amt NUMBER, p_base NUMBER, p_partner NUMBER DEFAULT NULL) IS   -- \0645\0648\062C\0628 \0645\062F\064A\0646 / \0633\0627\0644\0628 \062F\0627\0626\0646'),
'  BEGIN',
'    IF ROUND(NVL(p_base, 0), 2) = 0 THEN RETURN; END IF;',
'    l_line := l_line + 1;',
'    INSERT INTO journal_lines (journal_id, line_no, account_id, debit, credit, debit_base, credit_base,',
'                               partner_company_id, description)',
'    VALUES (l_jid, l_line, p_acc,',
'            GREATEST(ROUND(p_amt, 4), 0), GREATEST(-ROUND(p_amt, 4), 0),',
'            GREATEST(ROUND(p_base, 2), 0), GREATEST(-ROUND(p_base, 2), 0),',
'            p_partner, l_cname);',
'  END;',
'BEGIN',
'  SELECT h.invoice_id, h.invoice_type, h.customer_type, h.customer_company_id, h.invoice_date,',
'         h.pay_type, h.pay_method, h.account_id, h.customer_name, h.warehouse_id, h.price_list_id,',
'         h.currency_code, h.exchange_rate, NVL(h.discount_amount, 0), h.description',
'  INTO   l_id, l_type, l_ctype, l_cust, l_date_s, l_pay, l_method, l_acc, l_cname, l_wh, l_pl,',
'         l_cur, l_rate, l_disc, l_desc',
'  FROM   JSON_TABLE(l_clob, ''$.header'' COLUMNS (',
'           invoice_id          NUMBER        PATH ''$.INVOICE_ID'',',
'           invoice_type        VARCHAR2(10)  PATH ''$.INVOICE_TYPE'',',
'           customer_type       VARCHAR2(10)  PATH ''$.CUSTOMER_TYPE'',',
'           customer_company_id NUMBER        PATH ''$.CUSTOMER_COMPANY_ID'',',
'           invoice_date        VARCHAR2(20)  PATH ''$.INVOICE_DATE'',',
'           pay_type            VARCHAR2(10)  PATH ''$.PAY_TYPE'',',
'           pay_method          VARCHAR2(10)  PATH ''$.PAY_METHOD'',',
'           account_id          NUMBER        PATH ''$.ACCOUNT_ID'',',
'           customer_name       VARCHAR2(150) PATH ''$.CUSTOMER_NAME'',',
'           warehouse_id        NUMBER        PATH ''$.WAREHOUSE_ID'',',
'           price_list_id       NUMBER        PATH ''$.PRICE_LIST_ID'',',
'           currency_code       VARCHAR2(3)   PATH ''$.CURRENCY_CODE'',',
'           exchange_rate       NUMBER        PATH ''$.EXCHANGE_RATE'',',
'           discount_amount     NUMBER        PATH ''$.DISCOUNT_AMOUNT'',',
'           description         VARCHAR2(500) PATH ''$.DESCRIPTION'')) h;',
'',
unistr('  ------------------------------------------------------------------ \0627\0644\062A\062D\0642\0642 \0645\0646 \0627\0644\0631\0623\0633'),
unistr('  IF l_type NOT IN (''SALE'',''RETURN'') OR l_type IS NULL THEN err(''\0646\0648\0639 \0627\0644\0641\0627\062A\0648\0631\0629 \063A\064A\0631 \0645\0639\0631\0648\0641''); END IF;'),
'  l_jt   := CASE l_type WHEN ''SALE'' THEN ''INV'' ELSE ''RET'' END;',
unistr('  l_sign := CASE l_type WHEN ''SALE'' THEN -1 ELSE 1 END;           -- \0623\062B\0631 \0627\0644\0643\0645\064A\0629 \0639\0644\0649 \0627\0644\0645\062E\0632\0646'),
unistr('  BEGIN l_date := TO_DATE(l_date_s, ''DD/MM/YYYY''); EXCEPTION WHEN OTHERS THEN err(''\0627\0644\062A\0627\0631\064A\062E \063A\064A\0631 \0635\062D\064A\062D''); END;'),
'',
unistr('  IF :G_USER_ROLE NOT IN (''ADMIN'',''ENTRY'') THEN err(''\0644\064A\0633 \0644\062F\064A\0643 \0635\0644\0627\062D\064A\0629 \0639\0644\0649 \0641\0648\0627\062A\064A\0631 \0627\0644\0645\0628\064A\0639\0627\062A''); END IF;'),
unistr('  -- \0627\0644\0628\064A\0639 \062F\0627\062E\0644 \0648\0631\062F\064A\0629 \0645\0641\062A\0648\062D\0629 \0644\0644\0645\0633\062A\062E\062F\0645'),
'  SELECT MAX(shift_id) INTO l_shift FROM sales_shifts WHERE user_name = :APP_USER AND status = ''OPEN'';',
unistr('  IF l_shift IS NULL THEN err(''\0627\0641\062A\062D \0648\0631\062F\064A\0629 \0623\0648\0644\0627\064B \0645\0646 \0635\0641\062D\0629 \0627\0644\0648\0631\062F\064A\0629''); END IF;'),
'',
unistr('  -- \0637\0631\064A\0642\0629 \0627\0644\062F\0641\0639 \0648\0627\0644\062D\0633\0627\0628: \0646\0642\062F\064A = \062E\0632\064A\0646\0629 \0623\0648 \0628\0646\0643 \060C \0622\062C\0644 = \062D\0633\0627\0628 \0627\0644\0639\0645\064A\0644 (\062E\0627\0631\062C\064A \0623\0648 \0641\0631\0639)'),
unistr('  -- \0646\0648\0639 \0627\0644\0639\0645\064A\0644 \0648\0637\0631\064A\0642\0629 \0627\0644\0646\0642\062F \062A\064F\0633\062A\0646\062A\062C \0645\0646 \0627\0644\062D\0633\0627\0628 \0627\0644\0645\062E\062A\0627\0631'),
unistr('  IF l_pay NOT IN (''CASH'',''CREDIT'') OR l_pay IS NULL THEN err(''\0627\062E\062A\0631 \0637\0631\064A\0642\0629 \0627\0644\062F\0641\0639: \0646\0642\062F\064A \0623\0648 \0622\062C\0644''); END IF;'),
'  l_cust := NULL;',
'  BEGIN',
'    SELECT a.cash_bank, ca.company_id, c.name_ar',
'    INTO   l_cb, l_cust, l_branch',
'    FROM   accounts a',
'    LEFT JOIN company_accounts ca ON ca.ar_account_id = a.account_id',
'    LEFT JOIN companies c ON c.company_id = ca.company_id',
'    WHERE  a.account_id = l_acc AND a.is_postable = ''Y'' AND a.is_active = ''Y''',
'    AND    (a.company_id IS NULL OR a.company_id = l_company);',
unistr('    IF l_pay = ''CASH''   AND l_cb NOT IN (''C'',''B'') THEN err(''\0627\062E\062A\0631 \062E\0632\064A\0646\0629\0627\064B \0623\0648 \062D\0633\0627\0628\0627\064B \0628\0646\0643\064A\0627\064B''); END IF;'),
unistr('    IF l_pay = ''CREDIT'' AND l_cb <> ''N''           THEN err(''\0627\062E\062A\0631 \062D\0633\0627\0628 \0627\0644\0639\0645\064A\0644''); END IF;'),
'  EXCEPTION WHEN NO_DATA_FOUND THEN',
unistr('    err(CASE l_pay WHEN ''CASH'' THEN ''\0627\062E\062A\0631 \0627\0644\062E\0632\064A\0646\0629 \0623\0648 \0627\0644\062D\0633\0627\0628 \0627\0644\0628\0646\0643\064A'' ELSE ''\0627\062E\062A\0631 \062D\0633\0627\0628 \0627\0644\0639\0645\064A\0644'' END);'),
'  END;',
'  l_method := CASE WHEN l_pay = ''CASH'' THEN CASE l_cb WHEN ''B'' THEN ''BANK'' ELSE ''CASH'' END END;',
'  l_ctype  := CASE WHEN l_pay = ''CREDIT'' AND l_cust IS NOT NULL THEN ''BRANCH'' ELSE ''EXTERNAL'' END;',
'  IF l_ctype = ''EXTERNAL'' THEN l_cust := NULL; END IF;',
'  IF l_ctype = ''BRANCH'' AND l_cname IS NULL THEN l_cname := l_branch; END IF;',
'',
'  SELECT COUNT(*) INTO l_cnt FROM warehouses WHERE warehouse_id = l_wh AND company_id = l_company AND is_active = ''Y'';',
unistr('  IF l_cnt = 0 THEN err(''\0627\062E\062A\0631 \0645\062E\0632\0646\0627\064B \0645\0646 \0645\062E\0627\0632\0646 \0627\0644\0634\0631\0643\0629 \0627\0644\0623\0645''); END IF;'),
unistr('  IF l_cur IS NULL OR NVL(l_rate, 0) <= 0 THEN err(''\0627\0644\0639\0645\0644\0629 \0623\0648 \0633\0639\0631 \0627\0644\0635\0631\0641 \063A\064A\0631 \0635\062D\064A\062D''); END IF;'),
'  SELECT COUNT(*) INTO l_cnt FROM currencies WHERE currency_code = l_cur AND is_base = ''Y'';',
'  IF l_cnt = 1 THEN l_rate := 1; END IF;',
'',
'  IF l_date IS NOT NULL THEN',
'    SELECT COUNT(*) INTO l_cnt FROM fiscal_years WHERE l_date BETWEEN start_date AND end_date AND is_closed = ''N'';',
unistr('    IF l_cnt = 0 THEN err(''\0627\0644\062A\0627\0631\064A\062E \062E\0627\0631\062C \0633\0646\0629 \0645\0627\0644\064A\0629 \0645\0641\062A\0648\062D\0629''); END IF;'),
'  END IF;',
'',
'  IF l_id IS NOT NULL THEN',
'    BEGIN',
'      SELECT status, invoice_no INTO l_status, l_no FROM invoices WHERE invoice_id = l_id FOR UPDATE;',
unistr('      IF l_status <> ''DRAFT'' THEN err(''\0627\0644\0641\0627\062A\0648\0631\0629 \0645\0631\062D\0651\0644\0629 \0648\0644\0627 \064A\0645\0643\0646 \062A\0639\062F\064A\0644\0647\0627''); END IF;'),
unistr('    EXCEPTION WHEN NO_DATA_FOUND THEN err(''\0627\0644\0641\0627\062A\0648\0631\0629 \063A\064A\0631 \0645\0648\062C\0648\062F\0629''); END;'),
'  END IF;',
'',
unistr('  ------------------------------------------------------------------ \0627\0644\0633\0637\0648\0631'),
'  FOR r IN (SELECT j.line_no, j.qty, j.price, NVL(j.discount, 0) discount, u.factor',
'            FROM JSON_TABLE(l_clob, ''$.lines[*]'' COLUMNS (',
'                   line_no NUMBER PATH ''$.LINE_NO'', item_id NUMBER PATH ''$.ITEM_ID'', unit_id NUMBER PATH ''$.UNIT_ID'',',
'                   qty NUMBER PATH ''$.QTY'', price NUMBER PATH ''$.PRICE'', discount NUMBER PATH ''$.DISCOUNT'')) j',
'            LEFT JOIN item_units u ON u.item_id = j.item_id AND u.unit_id = j.unit_id) LOOP',
'    l_lines := l_lines + 1;',
unistr('    IF r.factor IS NULL THEN err(''\0627\0644\0633\0637\0631 '' || r.line_no || '': \0627\0644\0635\0646\0641 \0623\0648 \0627\0644\0648\062D\062F\0629 \063A\064A\0631 \0635\062D\064A\062D\0629''); END IF;'),
unistr('    IF NVL(r.qty, 0) <= 0 THEN err(''\0627\0644\0633\0637\0631 '' || r.line_no || '': \0627\0644\0643\0645\064A\0629 \064A\062C\0628 \0623\0646 \062A\0643\0648\0646 \0623\0643\0628\0631 \0645\0646 \0635\0641\0631''); END IF;'),
unistr('    IF NVL(r.price, 0) <= 0 THEN err(''\0627\0644\0633\0637\0631 '' || r.line_no || '': \0623\062F\062E\0644 \0633\0639\0631 \0627\0644\0628\064A\0639''); END IF;'),
unistr('    IF r.discount > NVL(r.qty, 0) * NVL(r.price, 0) THEN err(''\0627\0644\0633\0637\0631 '' || r.line_no || '': \0627\0644\062E\0635\0645 \0623\0643\0628\0631 \0645\0646 \0642\064A\0645\0629 \0627\0644\0633\0637\0631''); END IF;'),
'    l_gross := l_gross + NVL(r.qty, 0) * NVL(r.price, 0) - r.discount;',
'  END LOOP;',
unistr('  IF l_lines = 0 THEN err(''\0623\062F\062E\0644 \0635\0646\0641\0627\064B \0648\0627\062D\062F\0627\064B \0639\0644\0649 \0627\0644\0623\0642\0644''); END IF;'),
'  l_net := l_gross - l_disc;',
unistr('  IF l_net <= 0 THEN err(''\0635\0627\0641\064A \0627\0644\0641\0627\062A\0648\0631\0629 \064A\062C\0628 \0623\0646 \064A\0643\0648\0646 \0623\0643\0628\0631 \0645\0646 \0635\0641\0631''); END IF;'),
'',
unistr('  -- \0627\0644\0628\064A\0639: \0627\0644\0631\0635\064A\062F \064A\062C\0628 \0623\0646 \064A\0643\0641\064A'),
'  IF l_type = ''SALE'' AND l_action = ''POST'' THEN',
'    FOR r IN (SELECT i.item_code, SUM(j.qty * u.factor) need, NVL(MAX(b.qty_base), 0) bal',
'              FROM JSON_TABLE(l_clob, ''$.lines[*]'' COLUMNS (',
'                     item_id NUMBER PATH ''$.ITEM_ID'', unit_id NUMBER PATH ''$.UNIT_ID'', qty NUMBER PATH ''$.QTY'')) j',
'              JOIN item_units u ON u.item_id = j.item_id AND u.unit_id = j.unit_id',
'              JOIN items i ON i.item_id = j.item_id',
'              LEFT JOIN v_stock_balance b ON b.item_id = j.item_id AND b.warehouse_id = l_wh',
'              GROUP BY i.item_code) LOOP',
unistr('      IF r.need > r.bal THEN err(''\0627\0644\0635\0646\0641 '' || r.item_code || '': \0627\0644\0631\0635\064A\062F '' || r.bal || '' \0644\0627 \064A\0643\0641\064A \0644\0644\0643\0645\064A\0629 '' || r.need); END IF;'),
'    END LOOP;',
'  END IF;',
'',
'  IF l_errs.COUNT > 0 THEN',
'    ROLLBACK;',
'    apex_json.open_object; apex_json.write(''ok'', FALSE); apex_json.write(''errors'', l_errs); apex_json.close_object;',
'    RETURN;',
'  END IF;',
'',
unistr('  ------------------------------------------------------------------ \0627\0644\0631\0642\0645 \0648\0627\0644\062D\0641\0638'),
'  l_code := CASE WHEN l_type = ''SALE'' AND l_pay = ''CASH'' THEN ''1'' WHEN l_type = ''SALE'' THEN ''2''',
'                 WHEN l_pay = ''CASH'' THEN ''5'' ELSE ''6'' END;',
unistr('  -- \0625\0630\0627 \062A\063A\064A\0651\0631 \0646\0648\0639 \0627\0644\062F\0641\0639 \0641\064A \0645\0633\0648\062F\0629 \0645\062D\0641\0648\0638\0629 \064A\064F\0639\0637\0649 \0631\0642\0645 \062C\062F\064A\062F \0645\0646 \0627\0644\062A\0633\0644\0633\0644 \0627\0644\0635\062D\064A\062D'),
'  IF l_id IS NULL OR SUBSTR(l_no, 1, 1) <> l_code THEN',
'    UPDATE doc_sequences SET last_no = last_no + 1',
'    WHERE company_id = l_company AND doc_type = l_code AND fy_year = EXTRACT(YEAR FROM l_date)',
'    RETURNING last_no INTO l_seq;',
'    IF SQL%ROWCOUNT = 0 THEN',
'      INSERT INTO doc_sequences VALUES (l_company, l_code, EXTRACT(YEAR FROM l_date), 1); l_seq := 1;',
'    END IF;',
'    l_no := l_code || EXTRACT(YEAR FROM l_date) || LPAD(l_seq, 5, ''0'');',
'  END IF;',
'',
'  IF l_id IS NULL THEN',
'    INSERT INTO invoices (company_id, customer_type, customer_company_id, invoice_type, invoice_no, invoice_date,',
'                          pay_type, pay_method, account_id, customer_name, warehouse_id, price_list_id,',
'                          currency_code, exchange_rate, description, created_by, shift_id)',
'    VALUES (l_company, l_ctype, l_cust, l_type, l_no, l_date, l_pay, l_method, l_acc, l_cname, l_wh, l_pl,',
'            l_cur, l_rate, l_desc, :APP_USER, l_shift)',
'    RETURNING invoice_id INTO l_id;',
'  ELSE',
'    UPDATE invoices',
'    SET customer_type = l_ctype, customer_company_id = l_cust, invoice_no = l_no, invoice_date = l_date,',
'        pay_type = l_pay, pay_method = l_method, account_id = l_acc, customer_name = l_cname,',
'        warehouse_id = l_wh, price_list_id = l_pl, currency_code = l_cur, exchange_rate = l_rate,',
'        description = l_desc, shift_id = l_shift',
'    WHERE invoice_id = l_id;',
'    DELETE FROM invoice_lines WHERE invoice_id = l_id;',
'  END IF;',
'',
'  INSERT INTO invoice_lines (invoice_id, line_no, item_id, unit_id, factor, qty, price, discount, line_total)',
'  SELECT l_id, ROWNUM, j.item_id, j.unit_id, u.factor, j.qty, j.price, NVL(j.discount, 0),',
'         ROUND(j.qty * j.price - NVL(j.discount, 0), 4)',
'  FROM   JSON_TABLE(l_clob, ''$.lines[*]'' COLUMNS (',
'           item_id NUMBER PATH ''$.ITEM_ID'', unit_id NUMBER PATH ''$.UNIT_ID'',',
'           qty NUMBER PATH ''$.QTY'', price NUMBER PATH ''$.PRICE'', discount NUMBER PATH ''$.DISCOUNT'')) j',
'  JOIN   item_units u ON u.item_id = j.item_id AND u.unit_id = j.unit_id;',
'',
unistr('  -- \0627\0644\0633\0639\0631 \0645\0646 \0628\064A\0627\0646\0627\062A \0627\0644\0635\0646\0641 (\0623\0648 \0642\0627\0626\0645\0629 \0627\0644\0623\0633\0639\0627\0631) \0648\0644\0627 \064A\064F\0639\062F\064E\0651\0644 \064A\062F\0648\064A\0627\064B'),
'  UPDATE invoice_lines il',
'  SET    price = (SELECT NVL(p.price, CASE WHEN u.unit_id = i.big_unit_id AND i.big_sale_price > 0 THEN i.big_sale_price ELSE NULLIF(i.sale_price, 0) * u.factor END)',
'                  FROM items i JOIN item_units u ON u.item_id = i.item_id AND u.unit_id = il.unit_id',
'                  LEFT JOIN price_list_items p ON p.price_list_id = l_pl AND p.item_id = i.item_id AND p.unit_id = il.unit_id',
'                  WHERE i.item_id = il.item_id)',
'  WHERE  il.invoice_id = l_id;',
'  SELECT COUNT(*) INTO l_cnt FROM invoice_lines WHERE invoice_id = l_id AND NVL(price, 0) <= 0;',
unistr('  IF l_cnt > 0 THEN raise_application_error(-20031, ''\064A\0648\062C\062F \0635\0646\0641 \0628\062F\0648\0646 \0633\0639\0631 \0628\064A\0639 \0641\064A \0635\0641\062D\0629 \0627\0644\0623\0635\0646\0627\0641 \0648\0623\0633\0639\0627\0631\0647\0627''); END IF;'),
'  UPDATE invoice_lines SET line_total = ROUND(qty * price - NVL(discount, 0), 4) WHERE invoice_id = l_id;',
'  SELECT SUM(line_total) INTO l_gross FROM invoice_lines WHERE invoice_id = l_id;',
'  l_net := l_gross - l_disc;',
'',
'  UPDATE invoices SET gross_amount = l_gross, discount_amount = l_disc, net_amount = l_net WHERE invoice_id = l_id;',
'',
unistr('  ------------------------------------------------------------------ \0627\0644\062A\0631\062D\064A\0644: \0627\0644\0645\062E\0632\0648\0646 + \0627\0644\0642\064A\062F'),
'  IF l_action = ''POST'' THEN',
unistr('    -- \062D\0631\0643\0629 \0627\0644\0645\062E\0632\0646 \0628\0645\062A\0648\0633\0637 \0627\0644\062A\0643\0644\0641\0629: \0627\0644\0628\064A\0639 \0635\0627\062F\0631 \060C \0627\0644\0645\0631\062A\062C\0639 \0648\0627\0631\062F'),
'    INSERT INTO stock_trans (company_id, trans_type, trans_no, trans_date, warehouse_id, counter_account_id,',
'                             currency_code, exchange_rate, description, source_type, source_id, status, created_by)',
'    VALUES (l_company, ''INV_OUT'', l_no, l_date, l_wh, l_acc, l_cur, 1, l_no, ''INVOICE'', l_id, ''POSTED'', :APP_USER)',
'    RETURNING trans_id INTO l_so;',
'',
'    INSERT INTO stock_trans_lines (trans_id, line_no, warehouse_id, item_id, unit_id, factor, qty,',
'                                   qty_base, unit_cost, cost_base, value_base)',
'    SELECT l_so, il.line_no, l_wh, il.item_id, il.unit_id, il.factor, il.qty,',
'           l_sign * il.qty * il.factor, 0, NVL(b.avg_cost, 0),',
'           ROUND(l_sign * il.qty * il.factor * NVL(b.avg_cost, 0), 4)',
'    FROM invoice_lines il',
'    LEFT JOIN v_stock_balance b ON b.item_id = il.item_id AND b.warehouse_id = l_wh',
'    WHERE il.invoice_id = l_id;',
'',
unistr('    SELECT -SUM(value_base) INTO l_cogs FROM stock_trans_lines WHERE trans_id = l_so;   -- \0645\0648\062C\0628 \0641\064A \0627\0644\0628\064A\0639'),
'    l_sales_acc := setting(CASE l_ctype WHEN ''BRANCH'' THEN ''SALES'' ELSE ''SALES_EXT'' END);',
'    l_ret_acc   := setting(''SALES_RETURN'');',
'    l_cogs_acc  := setting(''COGS'');',
'    l_inv_acc   := setting(''INVENTORY'');',
'    l_base      := ROUND(l_net * l_rate, 2);',
'',
'    INSERT INTO journals (company_id, jt_code, journal_no, journal_date, currency_code, exchange_rate,',
'                          description, status, source_type, source_id, created_by)',
'    VALUES (l_company, l_jt, l_no, l_date, l_cur, l_rate,',
unistr('            NVL(l_desc, CASE l_type WHEN ''SALE'' THEN ''\0641\0627\062A\0648\0631\0629 \0645\0628\064A\0639\0627\062A '' ELSE ''\0645\0631\062A\062C\0639 \0645\0628\064A\0639\0627\062A '' END || l_no || '' - '' || l_cname),'),
unistr('            ''DRAFT'', ''INVOICE'', l_id, :APP_USER)   -- \064A\064F\0631\062D\0651\0644 \0639\0646\062F \0627\0639\062A\0645\0627\062F \0627\0644\0648\0631\062F\064A\0629'),
'    RETURNING journal_id INTO l_jid;',
'',
'    IF l_type = ''SALE'' THEN',
unistr('      jline(l_acc,       l_net,  l_base, l_cust);          -- \0627\0644\0639\0645\064A\0644 / \0627\0644\062E\0632\064A\0646\0629 / \0627\0644\0628\0646\0643 / \0630\0645\0629 \0627\0644\0641\0631\0639'),
unistr('      jline(l_sales_acc, -l_net, -l_base, l_cust);         -- \0627\0644\0645\0628\064A\0639\0627\062A'),
unistr('      jline(l_cogs_acc,  l_cogs / l_rate,  l_cogs);        -- \062A\0643\0644\0641\0629 \0627\0644\0628\0636\0627\0639\0629 \0627\0644\0645\0628\0627\0639\0629'),
unistr('      jline(l_inv_acc,   -l_cogs / l_rate, -l_cogs);       -- \0627\0644\0645\062E\0632\0648\0646'),
'    ELSE',
unistr('      jline(l_ret_acc,   l_net,  l_base, l_cust);          -- \0645\0631\062F\0648\062F\0627\062A \0627\0644\0645\0628\064A\0639\0627\062A'),
'      jline(l_acc,       -l_net, -l_base, l_cust);',
unistr('      jline(l_inv_acc,   -l_cogs / l_rate, -l_cogs);       -- \0639\0648\062F\0629 \0627\0644\0628\0636\0627\0639\0629 \0644\0644\0645\062E\0632\0648\0646 (l_cogs \0633\0627\0644\0628 \0647\0646\0627)'),
'      jline(l_cogs_acc,  l_cogs / l_rate,  l_cogs);',
'    END IF;',
'',
'    UPDATE journals SET total_debit  = (SELECT SUM(debit)  FROM journal_lines WHERE journal_id = l_jid),',
'                        total_credit = (SELECT SUM(credit) FROM journal_lines WHERE journal_id = l_jid)',
'    WHERE journal_id = l_jid;',
'',
'    UPDATE invoices SET status = ''POSTED'', journal_id = l_jid, stock_out_id = l_so WHERE invoice_id = l_id;',
'  END IF;',
'',
'  apex_json.open_object;',
'  apex_json.write(''ok'', TRUE); apex_json.write(''id'', l_id); apex_json.write(''no'', l_no);',
unistr('  apex_json.write(''message'', CASE WHEN l_action = ''POST'' THEN ''\062A\0645 \062A\0631\062D\064A\0644 \0627\0644\0641\0627\062A\0648\0631\0629 '' ELSE ''\062A\0645 \062D\0641\0638 \0627\0644\0641\0627\062A\0648\0631\0629 '' END || l_no);'),
'  apex_json.close_object;',
'EXCEPTION WHEN OTHERS THEN',
'  ROLLBACK;',
'  apex_json.open_object; apex_json.write(''ok'', FALSE);',
'  apex_json.open_array(''errors''); apex_json.write(SQLERRM); apex_json.close_array;',
'  apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_name=>'SAVE_DOC'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000405
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000406)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('  -- \0627\0644\0631\0642\0645 \0627\0644\062A\0627\0644\064A \0627\0644\0645\062A\0648\0642\0639 \0644\0644\0645\0633\062A\0646\062F \0627\0644\062C\062F\064A\062F (\064A\0638\0647\0631 \0639\0646\062F \0627\0644\0636\063A\0637 \0639\0644\0649 "\062C\062F\064A\062F")'),
unistr('  -- x01 = \0646\0648\0639 \0627\0644\0645\0633\062A\0646\062F \060C x02 = \0637\0631\064A\0642\0629 \0627\0644\062F\0641\0639 \060C x03 = \0627\0644\062A\0627\0631\064A\062E \060C x04 = SALE / PURCHASE / VOUCHER'),
unistr('  -- \0627\0644\0631\0642\0645 \0627\0644\0646\0647\0627\0626\064A \064A\064F\0639\0637\0649 \0639\0646\062F \0627\0644\062D\0641\0638 (\0642\062F \064A\062E\062A\0644\0641 \0625\0630\0627 \062D\0641\0638 \0645\0633\062A\062E\062F\0645 \0622\062E\0631 \0645\0633\062A\0646\062F\0627\064B \0645\0646 \0646\0641\0633 \0627\0644\0646\0648\0639 \0642\0628\0644\0643)'),
'  l_kind VARCHAR2(10) := apex_application.g_x04;',
'  l_type VARCHAR2(10) := apex_application.g_x01;',
'  l_pay  VARCHAR2(10) := apex_application.g_x02;',
'  l_code VARCHAR2(10);',
'  l_year NUMBER;',
'  l_seq  NUMBER;',
'  l_no   VARCHAR2(30);',
'BEGIN',
'  BEGIN',
'    l_year := EXTRACT(YEAR FROM TO_DATE(apex_application.g_x03, ''DD/MM/YYYY''));',
'  EXCEPTION WHEN OTHERS THEN l_year := NULL;',
'  END;',
'  l_year := NVL(l_year, EXTRACT(YEAR FROM SYSDATE));',
'',
'  l_code := CASE l_kind',
'              WHEN ''SALE'' THEN',
'                CASE WHEN l_type = ''SALE'' THEN CASE l_pay WHEN ''CASH'' THEN ''1'' ELSE ''2'' END',
'                     ELSE CASE l_pay WHEN ''CASH'' THEN ''5'' ELSE ''6'' END END',
'              WHEN ''PURCHASE'' THEN',
'                CASE WHEN l_type = ''PURCHASE'' THEN CASE l_pay WHEN ''CASH'' THEN ''3'' ELSE ''4'' END',
'                     ELSE CASE l_pay WHEN ''CASH'' THEN ''7'' ELSE ''8'' END END',
'              ELSE CASE l_type WHEN ''R'' THEN ''RV'' ELSE ''PV'' END',
'            END;',
'',
'  SELECT NVL(MAX(last_no), 0) + 1 INTO l_seq',
'  FROM   doc_sequences',
'  WHERE  company_id = :G_PARENT_ID AND doc_type = l_code AND fy_year = l_year;',
'',
'  l_no := CASE WHEN l_kind = ''VOUCHER'' THEN l_code || ''-'' || l_year || ''-'' || LPAD(l_seq, 5, ''0'')',
'               ELSE l_code || l_year || LPAD(l_seq, 5, ''0'') END;',
'',
'  apex_json.open_object;',
'  apex_json.write(''no'', l_no);',
'  apex_json.close_object;',
'END;'))
,p_process_type=>'NATIVE_PLSQL'
,p_process_clob_language=>'PLSQL'
,p_process_name=>'NEXT_NO'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000406
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000407)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_clob_language=>'PLSQL'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('  -- \0642\0627\0626\0645\0629 \0627\0644\062D\0633\0627\0628\0627\062A \062D\0633\0628 \0637\0631\064A\0642\0629 \0627\0644\062F\0641\0639 (x01 = CASH \0623\0648 CREDIT) \060C \0648 x02 = SALE \0623\0648 PURCHASE'),
unistr('  --   \0646\0642\062F\064A : \0643\0644 \0627\0644\062E\0632\0627\0626\0646 \0648\0627\0644\062D\0633\0627\0628\0627\062A \0627\0644\0628\0646\0643\064A\0629'),
unistr('  --   \0622\062C\0644  : \0627\0644\0645\0628\064A\0639\0627\062A = \0627\0644\0639\0645\0644\0627\0621 (\062A\062D\062A 1106) \0648\0627\0644\0641\0631\0648\0639 \060C \0627\0644\0645\0634\062A\0631\064A\0627\062A = \0627\0644\0645\0648\0631\062F\0648\0646 (\062A\062D\062A 2101)'),
unistr('  --   \0623\0636\0641 \0623\064A \0639\0645\064A\0644 \0623\0648 \0645\0648\0631\062F \062C\062F\064A\062F \0643\062D\0633\0627\0628 \062A\062D\0644\064A\0644\064A \062A\062D\062A \0645\062C\0645\0648\0639\062A\0647 \0641\064A \0634\062C\0631\0629 \0627\0644\062D\0633\0627\0628\0627\062A'),
'  l_json CLOB;',
'  l_pay  VARCHAR2(10) := apex_application.g_x01;',
'  l_kind VARCHAR2(10) := apex_application.g_x02;',
'BEGIN',
'  SELECT JSON_ARRAYAGG(JSON_OBJECT(',
'           ''v'' VALUE a.account_id,',
'           ''t'' VALUE a.account_code || '' - '' || a.name_ar',
unistr('                     || CASE a.cash_bank WHEN ''B'' THEN '' (\0628\0646\0643)'' WHEN ''C'' THEN '' (\062E\0632\064A\0646\0629)'' END'),
unistr('                     || CASE WHEN ca.company_id IS NOT NULL THEN '' (\0641\0631\0639)'' END)'),
'         ORDER BY a.cash_bank DESC, a.account_code RETURNING CLOB)',
'  INTO   l_json',
'  FROM   accounts a',
'  LEFT JOIN company_accounts ca ON ca.ar_account_id = a.account_id',
'  WHERE  a.is_active = ''Y'' AND a.is_postable = ''Y''',
'  AND    (a.company_id IS NULL OR a.company_id = :G_PARENT_ID)',
'  AND    (   (l_pay = ''CASH''   AND a.cash_bank IN (''C'',''B''))',
'          OR (l_pay = ''CREDIT'' AND a.cash_bank = ''N'' AND l_kind = ''SALE''',
unistr('              AND (a.account_code LIKE ''1106%'' OR ca.company_id IS NOT NULL))       -- \0627\0644\0639\0645\0644\0627\0621 + \0627\0644\0641\0631\0648\0639'),
'          OR (l_pay = ''CREDIT'' AND a.cash_bank = ''N'' AND l_kind = ''PURCHASE''',
unistr('              AND a.account_code LIKE ''2101%''));                                    -- \0627\0644\0645\0648\0631\062F\0648\0646'),
'',
'  apex_util.prn(COALESCE(l_json, TO_CLOB(''[]'')), FALSE);',
'END;'))
,p_process_name=>'PAY_ACCOUNTS'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000407
);
