,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(6687458349757443)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>unistr('\0641\0648\0627\062A\064A\0631 \0627\0644\0645\0628\064A\0639\0627\062A \0648\0627\0644\0645\0631\062A\062C\0639\0627\062A')
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT i.invoice_id,',
'       i.invoice_type AS invoice_type_code,',
unistr('       DECODE(i.invoice_type,''SALE'',''\0645\0628\064A\0639\0627\062A'',''\0645\0631\062A\062C\0639 \0645\0628\064A\0639\0627\062A'') AS "\0627\0644\0646\0648\0639",'),
unistr('       i.invoice_no AS "\0627\0644\0631\0642\0645", i.invoice_date AS "\0627\0644\062A\0627\0631\064A\062E",'),
unistr('       CASE i.customer_type WHEN ''BRANCH'' THEN ''\0641\0631\0639: '' || c.name_ar'),
unistr('            ELSE NVL(i.customer_name, a.name_ar) END AS "\0627\0644\0639\0645\064A\0644",'),
unistr('       CASE WHEN i.pay_type = ''CREDIT'' THEN ''\0622\062C\0644'''),
unistr('            WHEN i.pay_method = ''BANK'' THEN ''\0646\0642\062F\064A - \062A\062D\0648\064A\0644 \0628\0646\0643\064A'' ELSE ''\0646\0642\062F\064A - \062E\0632\064A\0646\0629'' END AS "\0627\0644\062F\0641\0639",'),
unistr('       a.name_ar AS "\0627\0644\062D\0633\0627\0628",'),
unistr('       w.name_ar AS "\0627\0644\0645\062E\0632\0646",'),
unistr('       i.net_amount AS "\0627\0644\0635\0627\0641\064A", i.currency_code AS "\0627\0644\0639\0645\0644\0629",'),
unistr('       ROUND(i.net_amount * i.exchange_rate, 2) * DECODE(i.invoice_type,''SALE'',1,-1) AS "\0628\0627\0644\0639\0645\0644\0629 \0627\0644\0623\0633\0627\0633\064A\0629",'),
unistr('       DECODE(i.status,''DRAFT'',''\0645\0633\0648\062F\0629'',''POSTED'',''\0645\0631\062D\0651\0644\0629'',''REVERSED'',''\0645\0639\0643\0648\0633\0629'') AS "\0627\0644\062D\0627\0644\0629",'),
unistr('       ''\0637\0628\0627\0639\0629'' AS "\0637\0628\0627\0639\0629 A4",'),
unistr('       ''\0625\064A\0635\0627\0644'' AS "\0625\064A\0635\0627\0644"'),
'FROM invoices i',
'LEFT JOIN companies c ON c.company_id = i.customer_company_id',
'LEFT JOIN accounts  a ON a.account_id = i.account_id',
'JOIN warehouses w ON w.warehouse_id = i.warehouse_id',
'WHERE i.company_id = :G_PARENT_ID'))
);
