prompt --application/pages/page_00055
begin
wwv_flow_imp_page.create_page(
 p_id=>55
,p_name=>unistr('\0641\0627\062A\0648\0631\0629 \0645\0634\062A\0631\064A\0627\062A')
,p_alias=>'PURCHASE'
,p_step_title=>'&P55_TITLE.'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var pur = {',
'  grid: null,',
'',
'  units: function (row, g) {',
'    var it = (g || pur.grid).lovRecord(''items'', row.ITEM_ID);',
'    return it ? it.units : [];',
'  },',
'',
'  init: function () {',
'    var status = apex.item(''P55_STATUS'').getValue() || ''DRAFT'';',
'    pur.grid = new JsonLines({',
'      container: ''#pur_lines'',',
'      readOnly : !DocUtil.canEdit(status),',
'      columns  : [',
unistr('        {name: ''ITEM_ID'',    label: ''\0627\0644\0635\0646\0641 (\0643\0648\062F / \0627\0633\0645 / \0628\0627\0631\0643\0648\062F)'', type: ''lov'', lov: ''items'', required: true, width: ''26em''},'),
unistr('        {name: ''UNIT_ID'',    label: ''\0627\0644\0648\062D\062F\0629'',   type: ''select'', required: true, nullText: false, options: pur.units, width: ''8em'', readonly: true},'),
unistr('        {name: ''BAL'',        label: ''\0627\0644\0631\0635\064A\062F'',   type: ''display'', decimals: 2, noSubmit: true, width: ''7em''},'),
unistr('        {name: ''QTY'',        label: ''\0627\0644\0643\0645\064A\0629'',   type: ''number'', decimals: 2, required: true, width: ''7em''},'),
