wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000460)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE p purchase_invoices%ROWTYPE; r purchase_invoices%ROWTYPE;',
'BEGIN',
'  :P55_LOADED_ID := :P55_PINV_ID;',
'  SELECT * INTO p FROM purchase_invoices WHERE pinv_id = :P55_PINV_ID;',
'  r := p;',
'  :P55_RETURN_NOTE := CASE WHEN r.status IN (''RETURNED'',''DRAFT'') THEN r.return_note END;',
unistr(':P55_WF_INFO := TRIM(CASE WHEN r.reviewed_by IS NOT NULL THEN ''\0631\0627\062C\0639\0647 '' || r.reviewed_by || '' '' || TO_CHAR(r.reviewed_on, ''DD/MM/YYYY HH24:MI'') END || CASE WHEN r.approved_by IS NOT NULL THEN '' - \0627\0639\062A\0645\062F\0647 '' || r.approved_by || '' '' || TO_CHAR(r.approved_on, ''DD/MM/YYYY HH24:MI'') END);'),
'  IF NOT (:G_USER_ROLE = ''ADMIN'' OR p.company_id = :G_COMPANY_ID) THEN',
unistr('    raise_application_error(-20001, ''\0644\064A\0633 \0644\062F\064A\0643 \0635\0644\0627\062D\064A\0629 \0639\0644\0649 \0647\0630\0647 \0627\0644\0641\0627\062A\0648\0631\0629'');'),
'  END IF;',
'  :P55_INVOICE_TYPE := p.invoice_type; :P55_INVOICE_NO := p.invoice_no; :P55_COMPANY_ID := p.company_id;',
'  :P55_INVOICE_DATE := TO_CHAR(p.invoice_date, ''DD/MM/YYYY''); :P55_SUPPLIER_INV_NO := p.supplier_inv_no;',
'  :P55_PAY_TYPE := p.pay_type; :P55_SUPPLIER_ACCOUNT_ID := p.supplier_account_id; :P55_SUPPLIER_NAME := p.supplier_name;',
'  :P55_WAREHOUSE_ID := p.warehouse_id; :P55_CURRENCY_CODE := p.currency_code; :P55_EXCHANGE_RATE := p.exchange_rate;',
'  :P55_DISCOUNT_AMOUNT := p.discount_amount; :P55_DESCRIPTION := p.description; :P55_STATUS := p.status;',
'  :P55_JOURNAL_ID := p.journal_id;',
'END;'))
,p_process_type=>'NATIVE_PLSQL'
,p_process_clob_language=>'PLSQL'
,p_process_name=>'LOAD_HEADER'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':P55_PINV_ID IS NOT NULL AND :P55_PINV_ID <> NVL(:P55_LOADED_ID, ''x'')'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>91000000000460
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000461)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P55_INVOICE_TYPE IS NULL THEN :P55_INVOICE_TYPE := ''PURCHASE''; END IF;',
'IF :P55_PINV_ID IS NULL THEN',
'  :P55_COMPANY_ID := :G_PARENT_ID;',
'  IF :P55_WAREHOUSE_ID IS NULL THEN SELECT MIN(warehouse_id) INTO :P55_WAREHOUSE_ID FROM warehouses WHERE company_id = :G_PARENT_ID AND is_active = ''Y''; END IF;',
'  IF :P55_STATUS IS NULL THEN :P55_STATUS := ''DRAFT''; END IF;',
'  IF :P55_PAY_TYPE IS NULL THEN :P55_PAY_TYPE := ''CREDIT''; END IF;',
'  IF :P55_INVOICE_DATE IS NULL THEN :P55_INVOICE_DATE := TO_CHAR(SYSDATE, ''DD/MM/YYYY''); END IF;',
'  IF :P55_CURRENCY_CODE IS NULL THEN SELECT currency_code INTO :P55_CURRENCY_CODE FROM currencies WHERE is_base = ''Y''; :P55_EXCHANGE_RATE := 1; END IF;',
'END IF;',
unistr(':P55_TITLE := CASE :P55_INVOICE_TYPE WHEN ''PURCHASE'' THEN ''\0641\0627\062A\0648\0631\0629 \0645\0634\062A\0631\064A\0627\062A'' ELSE ''\0645\0631\062A\062C\0639 \0645\0634\062A\0631\064A\0627\062A'' END;')))
,p_process_clob_language=>'PLSQL'
,p_process_name=>'DEFAULTS'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000461
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000462)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_items CLOB;',
'  l_lines CLOB;',
'  l_wh    NUMBER := TO_NUMBER(apex_application.g_x01);',
'BEGIN',
unistr('  -- \0643\0644 \0627\0644\0623\0635\0646\0627\0641 \0627\0644\0641\0639\0651\0627\0644\0629: \0627\0644\0643\0648\062F\060C \0627\0644\0627\0633\0645\060C \0627\0644\0628\0627\0631\0643\0648\062F\0627\062A\060C \0627\0644\0648\062D\062F\0627\062A \0648\0622\062E\0631 \0633\0639\0631 \0634\0631\0627\0621 \0644\0643\0644 \0648\062D\062F\0629'),
'  SELECT JSON_ARRAYAGG(JSON_OBJECT(',
'           ''id''   VALUE i.item_id,',
'           ''code'' VALUE i.item_code,',
'           ''name'' VALUE i.name_ar,',
'           ''bc0''  VALUE i.barcode,',
'           ''bu''   VALUE i.base_unit_id,',
'           ''bc''   VALUE (SELECT JSON_OBJECTAGG(KEY ub.barcode VALUE ub.unit_id)',
'                         FROM item_units ub WHERE ub.item_id = i.item_id AND ub.barcode IS NOT NULL) FORMAT JSON,',
'           ''bal''  VALUE NVL(b.qty_base, 0),',
'           ''units'' VALUE (SELECT JSON_ARRAYAGG(JSON_OBJECT(',
'                                   ''v''      VALUE u.unit_id,',
'                                   ''t''      VALUE un.name_ar,',
'                                   ''factor'' VALUE u.factor,',
'                                   ''price''  VALUE CASE WHEN u.unit_id = i.big_unit_id AND i.big_purchase_price > 0 THEN i.big_purchase_price ELSE NULLIF(i.purchase_price, 0) * u.factor END)',
'                                 ORDER BY u.factor)',
'                          FROM item_units u JOIN units un ON un.unit_id = u.unit_id',
'                          WHERE u.item_id = i.item_id) FORMAT JSON',
'         ) ORDER BY i.item_code RETURNING CLOB)',
'  INTO   l_items',
'  FROM   items i',
'  LEFT JOIN v_stock_balance b ON b.item_id = i.item_id AND b.warehouse_id = l_wh',
'  WHERE  i.is_active = ''Y'';',
'',
'  SELECT JSON_ARRAYAGG(JSON_OBJECT(',
'           ''ITEM_ID'' VALUE item_id, ''UNIT_ID'' VALUE unit_id, ''QTY'' VALUE qty,',
'           ''PRICE'' VALUE price, ''DISCOUNT'' VALUE NULLIF(discount, 0), ''LINE_TOTAL'' VALUE line_total)',
'         ORDER BY line_no RETURNING CLOB)',
'  INTO   l_lines',
'  FROM   purchase_invoice_lines WHERE pinv_id = TO_NUMBER(apex_application.g_x02);',
'',
'  apex_util.prn(''{"items":'' || COALESCE(l_items, TO_CLOB(''[]'')) ||',
'                '',"lines":'' || COALESCE(l_lines, TO_CLOB(''[]'')) || ''}'', FALSE);',
'END;'))
,p_process_type=>'NATIVE_PLSQL'
,p_process_clob_language=>'PLSQL'
,p_process_name=>'INIT_DATA'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000462
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000463)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_clob   CLOB := apex_application.g_clob_01;',
'  l_action VARCHAR2(10) := apex_application.g_x01;',
'  l_errs   apex_t_varchar2 := apex_t_varchar2();',
'',
'  l_id NUMBER; l_type VARCHAR2(10); l_company NUMBER; l_date_s VARCHAR2(20); l_date DATE;',
'  l_sup_no VARCHAR2(50); l_pay VARCHAR2(10); l_method VARCHAR2(10); l_acc NUMBER; l_sup_name VARCHAR2(150);',
'  l_code VARCHAR2(1);',
'  l_wh NUMBER; l_cur VARCHAR2(3); l_rate NUMBER; l_disc NUMBER; l_desc VARCHAR2(500);',
'',
'  l_status VARCHAR2(10); l_no VARCHAR2(30); l_seq NUMBER; l_cnt NUMBER; l_lines NUMBER := 0;',
'  l_gross NUMBER := 0; l_net NUMBER; l_jt VARCHAR2(10); l_sign NUMBER;',
'  l_st NUMBER; l_jid NUMBER; l_inv NUMBER; l_base NUMBER;',
'',
'  PROCEDURE err (p VARCHAR2) IS BEGIN l_errs.EXTEND; l_errs(l_errs.COUNT) := p; END;',
'BEGIN',
unistr('  l_action := ''DRAFT'';   -- \0627\0644\062A\0631\062D\064A\0644 \064A\062A\0645 \0639\0646\062F \0627\0644\0627\0639\062A\0645\0627\062F'),
'  SELECT h.pinv_id, h.invoice_type, h.company_id, h.invoice_date, h.supplier_inv_no, h.pay_type, h.pay_method,',
'         h.supplier_account_id, h.supplier_name, h.warehouse_id, h.currency_code, h.exchange_rate,',
'         NVL(h.discount_amount, 0), h.description',
'  INTO   l_id, l_type, l_company, l_date_s, l_sup_no, l_pay, l_method, l_acc, l_sup_name, l_wh, l_cur, l_rate, l_disc, l_desc',
'  FROM   JSON_TABLE(l_clob, ''$.header'' COLUMNS (',
'           pinv_id             NUMBER        PATH ''$.PINV_ID'',',
'           invoice_type        VARCHAR2(10)  PATH ''$.INVOICE_TYPE'',',
'           company_id          NUMBER        PATH ''$.COMPANY_ID'',',
'           invoice_date        VARCHAR2(20)  PATH ''$.INVOICE_DATE'',',
'           supplier_inv_no     VARCHAR2(50)  PATH ''$.SUPPLIER_INV_NO'',',
'           pay_type            VARCHAR2(10)  PATH ''$.PAY_TYPE'',',
'           pay_method          VARCHAR2(10)  PATH ''$.PAY_METHOD'',',
'           supplier_account_id NUMBER        PATH ''$.SUPPLIER_ACCOUNT_ID'',',
'           supplier_name       VARCHAR2(150) PATH ''$.SUPPLIER_NAME'',',
'           warehouse_id        NUMBER        PATH ''$.WAREHOUSE_ID'',',
'           currency_code       VARCHAR2(3)   PATH ''$.CURRENCY_CODE'',',
'           exchange_rate       NUMBER        PATH ''$.EXCHANGE_RATE'',',
'           discount_amount     NUMBER        PATH ''$.DISCOUNT_AMOUNT'',',
'           description         VARCHAR2(500) PATH ''$.DESCRIPTION'')) h;',
'',
'  l_jt   := CASE l_type WHEN ''PURCHASE'' THEN ''PUR'' WHEN ''RETURN'' THEN ''PRT'' END;',
unistr('  l_sign := CASE l_type WHEN ''PURCHASE'' THEN 1 ELSE -1 END;          -- \0623\062B\0631 \0627\0644\0643\0645\064A\0629 \0639\0644\0649 \0627\0644\0645\062E\0632\0646'),
unistr('  IF l_jt IS NULL THEN err(''\0646\0648\0639 \0627\0644\0641\0627\062A\0648\0631\0629 \063A\064A\0631 \0645\0639\0631\0648\0641''); END IF;'),
unistr('  BEGIN l_date := TO_DATE(l_date_s, ''DD/MM/YYYY''); EXCEPTION WHEN OTHERS THEN err(''\0627\0644\062A\0627\0631\064A\062E \063A\064A\0631 \0635\062D\064A\062D''); END;'),
'',
unistr('  -- \0627\0644\0645\0634\062A\0631\064A\0627\062A \0644\0644\0634\0631\0643\0629 \0627\0644\0623\0645 \0641\0642\0637'),
'  l_company := :G_PARENT_ID;',
unistr('  IF :G_USER_ROLE NOT IN (''ADMIN'',''ENTRY'') THEN err(''\0644\064A\0633 \0644\062F\064A\0643 \0635\0644\0627\062D\064A\0629 \0639\0644\0649 \0641\0648\0627\062A\064A\0631 \0627\0644\0645\0634\062A\0631\064A\0627\062A''); END IF;'),
unistr('  IF l_pay NOT IN (''CASH'',''CREDIT'') OR l_pay IS NULL THEN err(''\0627\062E\062A\0631 \0637\0631\064A\0642\0629 \0627\0644\062F\0641\0639''); END IF;'),
'',
'  SELECT COUNT(*) INTO l_cnt FROM warehouses WHERE warehouse_id = l_wh AND company_id = l_company AND is_active = ''Y'';',
unistr('  IF l_cnt = 0 THEN err(''\0627\062E\062A\0631 \0645\062E\0632\0646\0627\064B \062A\0627\0628\0639\0627\064B \0644\0644\0634\0631\0643\0629''); END IF;'),
'',
'  SELECT COUNT(*) INTO l_cnt FROM accounts',
'  WHERE account_id = l_acc AND is_postable = ''Y'' AND is_active = ''Y''',
'  AND (company_id IS NULL OR company_id = l_company)',
'  AND (l_pay = ''CREDIT'' AND cash_bank = ''N'' OR l_pay = ''CASH'' AND cash_bank IN (''C'',''B''));',
'  IF l_cnt = 0 THEN',
unistr('    err(CASE WHEN l_pay = ''CREDIT'' THEN ''\0627\062E\062A\0631 \062D\0633\0627\0628 \0627\0644\0645\0648\0631\062F'' ELSE ''\0627\062E\062A\0631 \0627\0644\062E\0632\064A\0646\0629 \0623\0648 \0627\0644\062D\0633\0627\0628 \0627\0644\0628\0646\0643\064A'' END);'),
'  END IF;',
unistr('  -- \0637\0631\064A\0642\0629 \0627\0644\0646\0642\062F \062A\064F\0633\062A\0646\062A\062C \0645\0646 \0627\0644\062D\0633\0627\0628: \0628\0646\0643 \0623\0648 \062E\0632\064A\0646\0629'),
'  BEGIN',
'    SELECT CASE cash_bank WHEN ''B'' THEN ''BANK'' WHEN ''C'' THEN ''CASH'' END INTO l_method FROM accounts WHERE account_id = l_acc;',
'  EXCEPTION WHEN NO_DATA_FOUND THEN l_method := NULL;',
'  END;',
'  IF l_pay = ''CREDIT'' THEN l_method := NULL; END IF;',
'',
unistr('  IF l_cur IS NULL OR NVL(l_rate, 0) <= 0 THEN err(''\0627\0644\0639\0645\0644\0629 \0623\0648 \0633\0639\0631 \0627\0644\0635\0631\0641 \063A\064A\0631 \0635\062D\064A\062D''); END IF;'),
'  SELECT COUNT(*) INTO l_cnt FROM currencies WHERE currency_code = l_cur AND is_base = ''Y'';',
'  IF l_cnt = 1 THEN l_rate := 1; END IF;',
'',
'  IF l_date IS NOT NULL THEN',
'    SELECT COUNT(*) INTO l_cnt FROM fiscal_years WHERE l_date BETWEEN start_date AND end_date AND is_closed = ''N'';',
unistr('    IF l_cnt = 0 THEN err(''\0627\0644\062A\0627\0631\064A\062E \062E\0627\0631\062C \0633\0646\0629 \0645\0627\0644\064A\0629 \0645\0641\062A\0648\062D\0629''); END IF;'),
'  END IF;',
'',
unistr('  -- \0631\0642\0645 \0641\0627\062A\0648\0631\0629 \0627\0644\0645\0648\0631\062F \0644\0627 \064A\062A\0643\0631\0631 \0644\0646\0641\0633 \0627\0644\0645\0648\0631\062F'),
'  IF l_sup_no IS NOT NULL THEN',
'    SELECT COUNT(*) INTO l_cnt FROM purchase_invoices',
'    WHERE company_id = l_company AND supplier_account_id = l_acc AND invoice_type = l_type',
'    AND UPPER(supplier_inv_no) = UPPER(l_sup_no) AND status <> ''REVERSED''',
'    AND pinv_id <> NVL(l_id, -1);',
unistr('    IF l_cnt > 0 THEN err(''\0631\0642\0645 \0641\0627\062A\0648\0631\0629 \0627\0644\0645\0648\0631\062F '' || l_sup_no || '' \0645\0633\062C\0644 \0645\0646 \0642\0628\0644 \0644\0646\0641\0633 \0627\0644\0645\0648\0631\062F''); END IF;'),
'  END IF;',
'',
'  IF l_id IS NOT NULL THEN',
'    BEGIN',
'      SELECT status, invoice_no INTO l_status, l_no FROM purchase_invoices WHERE pinv_id = l_id FOR UPDATE;',
unistr('      IF l_status NOT IN (''DRAFT'',''RETURNED'') THEN err(''\0627\0644\0641\0627\062A\0648\0631\0629 '' || l_no || '' \062A\0645\062A \0645\0631\0627\062C\0639\062A\0647\0627 \0623\0648 \0627\0639\062A\0645\0627\062F\0647\0627 \0648\0644\0627 \064A\0645\0643\0646 \062A\0639\062F\064A\0644\0647\0627''); END IF;'),
unistr('    EXCEPTION WHEN NO_DATA_FOUND THEN err(''\0627\0644\0641\0627\062A\0648\0631\0629 \063A\064A\0631 \0645\0648\062C\0648\062F\0629''); END;'),
'  END IF;',
'',
'  FOR r IN (SELECT j.line_no, j.item_id, j.unit_id, j.qty, j.price, NVL(j.discount, 0) discount, u.factor',
'            FROM JSON_TABLE(l_clob, ''$.lines[*]'' COLUMNS (',
'                   line_no NUMBER PATH ''$.LINE_NO'', item_id NUMBER PATH ''$.ITEM_ID'', unit_id NUMBER PATH ''$.UNIT_ID'',',
'                   qty NUMBER PATH ''$.QTY'', price NUMBER PATH ''$.PRICE'', discount NUMBER PATH ''$.DISCOUNT'')) j',
'            LEFT JOIN item_units u ON u.item_id = j.item_id AND u.unit_id = j.unit_id) LOOP',
'    l_lines := l_lines + 1;',
unistr('    IF r.factor IS NULL THEN err(''\0627\0644\0633\0637\0631 '' || r.line_no || '': \0627\0644\0635\0646\0641 \0623\0648 \0627\0644\0648\062D\062F\0629 \063A\064A\0631 \0635\062D\064A\062D\0629''); END IF;'),
unistr('    IF NVL(r.qty, 0) <= 0 THEN err(''\0627\0644\0633\0637\0631 '' || r.line_no || '': \0627\0644\0643\0645\064A\0629 \064A\062C\0628 \0623\0646 \062A\0643\0648\0646 \0623\0643\0628\0631 \0645\0646 \0635\0641\0631''); END IF;'),
unistr('    IF NVL(r.price, 0) <= 0 THEN err(''\0627\0644\0633\0637\0631 '' || r.line_no || '': \0623\062F\062E\0644 \0633\0639\0631 \0627\0644\0634\0631\0627\0621''); END IF;'),
unistr('    IF r.discount > NVL(r.qty, 0) * NVL(r.price, 0) THEN err(''\0627\0644\0633\0637\0631 '' || r.line_no || '': \0627\0644\062E\0635\0645 \0623\0643\0628\0631 \0645\0646 \0642\064A\0645\0629 \0627\0644\0633\0637\0631''); END IF;'),
'    l_gross := l_gross + NVL(r.qty, 0) * NVL(r.price, 0) - r.discount;',
'  END LOOP;',
unistr('  IF l_lines = 0 THEN err(''\0623\062F\062E\0644 \0635\0646\0641\0627\064B \0648\0627\062D\062F\0627\064B \0639\0644\0649 \0627\0644\0623\0642\0644''); END IF;'),
'  l_net := l_gross - l_disc;',
unistr('  IF l_net <= 0 THEN err(''\0635\0627\0641\064A \0627\0644\0641\0627\062A\0648\0631\0629 \064A\062C\0628 \0623\0646 \064A\0643\0648\0646 \0623\0643\0628\0631 \0645\0646 \0635\0641\0631''); END IF;'),
'',
unistr('  -- \0645\0631\062A\062C\0639 \0627\0644\0645\0634\062A\0631\064A\0627\062A: \0627\0644\0631\0635\064A\062F \064A\062C\0628 \0623\0646 \064A\0643\0641\064A'),
'  IF l_type = ''RETURN'' AND l_action = ''POST'' THEN',
'    FOR r IN (SELECT i.item_code, SUM(j.qty * u.factor) need, NVL(MAX(b.qty_base), 0) bal',
'              FROM JSON_TABLE(l_clob, ''$.lines[*]'' COLUMNS (',
'                     item_id NUMBER PATH ''$.ITEM_ID'', unit_id NUMBER PATH ''$.UNIT_ID'', qty NUMBER PATH ''$.QTY'')) j',
'              JOIN item_units u ON u.item_id = j.item_id AND u.unit_id = j.unit_id',
'              JOIN items i ON i.item_id = j.item_id',
'              LEFT JOIN v_stock_balance b ON b.item_id = j.item_id AND b.warehouse_id = l_wh',
'              GROUP BY i.item_code) LOOP',
unistr('      IF r.need > r.bal THEN err(''\0627\0644\0635\0646\0641 '' || r.item_code || '': \0627\0644\0631\0635\064A\062F '' || r.bal || '' \0644\0627 \064A\0643\0641\064A''); END IF;'),
'    END LOOP;',
'  END IF;',
'',
'  IF l_errs.COUNT > 0 THEN',
'    ROLLBACK;',
'    apex_json.open_object; apex_json.write(''ok'', FALSE); apex_json.write(''errors'', l_errs); apex_json.close_object;',
'    RETURN;',
'  END IF;',
'',
unistr('  ------------------------------------------------------------------ \0627\0644\062D\0641\0638'),
unistr('  -- \0627\0644\0631\0642\0645 \0623\0631\0642\0627\0645 \0641\0642\0637: 3 \0645\0634\062A\0631\064A\0627\062A \0646\0642\062F\064A\0629 \060C 4 \0645\0634\062A\0631\064A\0627\062A \0622\062C\0644\0629 \060C 7 \0645\0631\062A\062C\0639 \0646\0642\062F\064A \060C 8 \0645\0631\062A\062C\0639 \0622\062C\0644 + \0627\0644\0633\0646\0629 + \0645\062A\0633\0644\0633\0644 5 \0623\0631\0642\0627\0645'),
'  l_code := CASE WHEN l_type = ''PURCHASE'' AND l_pay = ''CASH'' THEN ''3'' WHEN l_type = ''PURCHASE'' THEN ''4''',
'                 WHEN l_pay = ''CASH'' THEN ''7'' ELSE ''8'' END;',
'  IF l_id IS NULL OR SUBSTR(l_no, 1, 1) <> l_code THEN',
'    UPDATE doc_sequences SET last_no = last_no + 1',
'    WHERE company_id = l_company AND doc_type = l_code AND fy_year = EXTRACT(YEAR FROM l_date)',
'    RETURNING last_no INTO l_seq;',
'    IF SQL%ROWCOUNT = 0 THEN',
'      INSERT INTO doc_sequences VALUES (l_company, l_code, EXTRACT(YEAR FROM l_date), 1); l_seq := 1;',
'    END IF;',
'    l_no := l_code || EXTRACT(YEAR FROM l_date) || LPAD(l_seq, 5, ''0'');',
'  END IF;',
'',
'  IF l_id IS NULL THEN',
'',
'    INSERT INTO purchase_invoices (company_id, invoice_type, invoice_no, supplier_inv_no, invoice_date, pay_type, pay_method,',
'                                   supplier_account_id, supplier_name, warehouse_id, currency_code, exchange_rate,',
'                                   description, created_by)',
'    VALUES (l_company, l_type, l_no, l_sup_no, l_date, l_pay, l_method, l_acc, l_sup_name, l_wh, l_cur, l_rate, l_desc, :APP_USER)',
'    RETURNING pinv_id INTO l_id;',
'  ELSE',
'    UPDATE purchase_invoices',
'    SET company_id = l_company, invoice_no = l_no, supplier_inv_no = l_sup_no, invoice_date = l_date, pay_type = l_pay, pay_method = l_method,',
'        supplier_account_id = l_acc, supplier_name = l_sup_name, warehouse_id = l_wh,',
'        currency_code = l_cur, exchange_rate = l_rate, description = l_desc',
'    WHERE pinv_id = l_id;',
'    DELETE FROM purchase_invoice_lines WHERE pinv_id = l_id;',
'  END IF;',
'',
'  INSERT INTO purchase_invoice_lines (pinv_id, line_no, item_id, unit_id, factor, qty, price, discount, line_total)',
'  SELECT l_id, ROWNUM, j.item_id, j.unit_id, u.factor, j.qty, j.price, NVL(j.discount, 0),',
'         ROUND(j.qty * j.price - NVL(j.discount, 0), 4)',
'  FROM   JSON_TABLE(l_clob, ''$.lines[*]'' COLUMNS (',
'           item_id NUMBER PATH ''$.ITEM_ID'', unit_id NUMBER PATH ''$.UNIT_ID'',',
'           qty NUMBER PATH ''$.QTY'', price NUMBER PATH ''$.PRICE'', discount NUMBER PATH ''$.DISCOUNT'')) j',
'  JOIN   item_units u ON u.item_id = j.item_id AND u.unit_id = j.unit_id;',
'',
unistr('  -- \0633\0639\0631 \0627\0644\0634\0631\0627\0621 \0645\0646 \0628\064A\0627\0646\0627\062A \0627\0644\0635\0646\0641 \0648\0644\0627 \064A\064F\0639\062F\064E\0651\0644 \064A\062F\0648\064A\0627\064B'),
'  UPDATE purchase_invoice_lines il',
'  SET    price = (SELECT CASE WHEN u.unit_id = i.big_unit_id AND i.big_purchase_price > 0 THEN i.big_purchase_price ELSE NULLIF(i.purchase_price, 0) * u.factor END',
'                  FROM items i JOIN item_units u ON u.item_id = i.item_id AND u.unit_id = il.unit_id',
'                  WHERE i.item_id = il.item_id)',
'  WHERE  il.pinv_id = l_id;',
'  SELECT COUNT(*) INTO l_cnt FROM purchase_invoice_lines WHERE pinv_id = l_id AND NVL(price, 0) <= 0;',
unistr('  IF l_cnt > 0 THEN raise_application_error(-20031, ''\064A\0648\062C\062F \0635\0646\0641 \0628\062F\0648\0646 \0633\0639\0631 \0634\0631\0627\0621 \0641\064A \0635\0641\062D\0629 \0627\0644\0623\0635\0646\0627\0641 \0648\0623\0633\0639\0627\0631\0647\0627''); END IF;'),
'  UPDATE purchase_invoice_lines SET line_total = ROUND(qty * price - NVL(discount, 0), 4) WHERE pinv_id = l_id;',
'  SELECT SUM(line_total) INTO l_gross FROM purchase_invoice_lines WHERE pinv_id = l_id;',
'  l_net := l_gross - l_disc;',
'',
'  UPDATE purchase_invoices SET gross_amount = l_gross, discount_amount = l_disc, net_amount = l_net,',
'         status = ''DRAFT'', return_note = NULL',
'  WHERE pinv_id = l_id;',
'',
unistr('  ------------------------------------------------------------------ \0627\0644\062A\0631\062D\064A\0644: \0627\0644\0645\062E\0632\0648\0646 + \0627\0644\0642\064A\062F'),
'  IF l_action = ''POST'' THEN',
unistr('    -- \062D\0631\0643\0629 \0627\0644\0645\062E\0632\0648\0646: \062A\0643\0644\0641\0629 \0627\0644\0648\062D\062F\0629 \0627\0644\0623\0633\0627\0633\064A\0629 = (\0625\062C\0645\0627\0644\064A \0627\0644\0633\0637\0631 \0628\0639\062F \062A\0648\0632\064A\0639 \062E\0635\0645 \0627\0644\0641\0627\062A\0648\0631\0629) \00D7 \0633\0639\0631 \0627\0644\0635\0631\0641 \00F7 \0627\0644\0643\0645\064A\0629 \0627\0644\0623\0633\0627\0633\064A\0629'),
'    INSERT INTO stock_trans (company_id, trans_type, trans_no, trans_date, warehouse_id, counter_account_id,',
'                             currency_code, exchange_rate, description, source_type, source_id, status, created_by)',
'    VALUES (l_company, ''PURCHASE'', l_no, l_date, l_wh, l_acc, l_cur, l_rate,',
'            NVL(l_desc, l_no), ''PURCHASE'', l_id, ''POSTED'', :APP_USER)',
'    RETURNING trans_id INTO l_st;',
'',
'    INSERT INTO stock_trans_lines (trans_id, line_no, warehouse_id, item_id, unit_id, factor, qty,',
'                                   qty_base, unit_cost, cost_base, value_base)',
'    SELECT l_st, l.line_no, l_wh, l.item_id, l.unit_id, l.factor, l.qty,',
'           l_sign * l.qty * l.factor, l.price,',
'           l.line_total * (l_net / l_gross) * l_rate / (l.qty * l.factor),',
'           ROUND(l_sign * l.line_total * (l_net / l_gross) * l_rate, 4)',
'    FROM purchase_invoice_lines l WHERE l.pinv_id = l_id;',
'',
unistr('    -- \0627\0644\0642\064A\062F: \0645\0634\062A\0631\064A\0627\062A = \0645\062F\064A\0646 \0627\0644\0645\062E\0632\0648\0646 / \062F\0627\0626\0646 \0627\0644\0645\0648\0631\062F \060C \0648\0627\0644\0645\0631\062A\062C\0639 \0628\0627\0644\0639\0643\0633'),
'    BEGIN',
'      SELECT account_id INTO l_inv FROM account_settings WHERE company_id = l_company AND setting_code = ''INVENTORY'';',
'    EXCEPTION WHEN NO_DATA_FOUND THEN',
unistr('      raise_application_error(-20060, ''\0644\0645 \064A\064F\0639\0631\064E\0651\0641 \062D\0633\0627\0628 \0627\0644\0645\062E\0632\0648\0646 (INVENTORY) \0644\0647\0630\0647 \0627\0644\0634\0631\0643\0629'');'),
'    END;',
'    l_base := ROUND(l_net * l_rate, 2);',
'',
'    INSERT INTO journals (company_id, jt_code, journal_no, journal_date, currency_code, exchange_rate,',
'                          description, ref_no, status, source_type, source_id, total_debit, total_credit,',
'                          created_by, posted_by, posted_on)',
'    VALUES (l_company, l_jt, l_no, l_date, l_cur, l_rate,',
unistr('            NVL(l_desc, CASE l_type WHEN ''PURCHASE'' THEN ''\0641\0627\062A\0648\0631\0629 \0645\0634\062A\0631\064A\0627\062A '' ELSE ''\0645\0631\062A\062C\0639 \0645\0634\062A\0631\064A\0627\062A '' END || l_no || '' - '' || l_sup_name),'),
'            l_sup_no, ''POSTED'', ''PURCHASE'', l_id, l_net, l_net, :APP_USER, :APP_USER, SYSDATE)',
'    RETURNING journal_id INTO l_jid;',
'',
'    INSERT INTO journal_lines (journal_id, line_no, account_id, debit, credit, debit_base, credit_base, description)',
'    VALUES (l_jid, 1, CASE l_type WHEN ''PURCHASE'' THEN l_inv ELSE l_acc END, l_net, 0, l_base, 0, l_sup_name);',
'    INSERT INTO journal_lines (journal_id, line_no, account_id, debit, credit, debit_base, credit_base, description)',
'    VALUES (l_jid, 2, CASE l_type WHEN ''PURCHASE'' THEN l_acc ELSE l_inv END, 0, l_net, 0, l_base, l_sup_name);',
'',
'    UPDATE purchase_invoices SET status = ''POSTED'', journal_id = l_jid, stock_trans_id = l_st WHERE pinv_id = l_id;',
'  END IF;',
'',
'  apex_json.open_object;',
'  apex_json.write(''ok'', TRUE); apex_json.write(''id'', l_id); apex_json.write(''no'', l_no);',
unistr('  apex_json.write(''message'', CASE WHEN l_action = ''POST'' THEN ''\062A\0645 \062A\0631\062D\064A\0644 \0627\0644\0641\0627\062A\0648\0631\0629 '' ELSE ''\062A\0645 \062D\0641\0638 \0627\0644\0641\0627\062A\0648\0631\0629 '' END || l_no);'),
'  apex_json.close_object;',
'EXCEPTION WHEN OTHERS THEN',
'  ROLLBACK;',
'  apex_json.open_object; apex_json.write(''ok'', FALSE);',
'  apex_json.open_array(''errors''); apex_json.write(SQLERRM); apex_json.close_array;',
'  apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_name=>'SAVE_DOC'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000463
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000464)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('  -- \0627\0644\0631\0642\0645 \0627\0644\062A\0627\0644\064A \0627\0644\0645\062A\0648\0642\0639 \0644\0644\0645\0633\062A\0646\062F \0627\0644\062C\062F\064A\062F (\064A\0638\0647\0631 \0639\0646\062F \0627\0644\0636\063A\0637 \0639\0644\0649 "\062C\062F\064A\062F")'),
unistr('  -- x01 = \0646\0648\0639 \0627\0644\0645\0633\062A\0646\062F \060C x02 = \0637\0631\064A\0642\0629 \0627\0644\062F\0641\0639 \060C x03 = \0627\0644\062A\0627\0631\064A\062E \060C x04 = SALE / PURCHASE / VOUCHER'),
unistr('  -- \0627\0644\0631\0642\0645 \0627\0644\0646\0647\0627\0626\064A \064A\064F\0639\0637\0649 \0639\0646\062F \0627\0644\062D\0641\0638 (\0642\062F \064A\062E\062A\0644\0641 \0625\0630\0627 \062D\0641\0638 \0645\0633\062A\062E\062F\0645 \0622\062E\0631 \0645\0633\062A\0646\062F\0627\064B \0645\0646 \0646\0641\0633 \0627\0644\0646\0648\0639 \0642\0628\0644\0643)'),
'  l_kind VARCHAR2(10) := apex_application.g_x04;',
'  l_type VARCHAR2(10) := apex_application.g_x01;',
'  l_pay  VARCHAR2(10) := apex_application.g_x02;',
'  l_code VARCHAR2(10);',
'  l_year NUMBER;',
'  l_seq  NUMBER;',
'  l_no   VARCHAR2(30);',
'BEGIN',
'  BEGIN',
'    l_year := EXTRACT(YEAR FROM TO_DATE(apex_application.g_x03, ''DD/MM/YYYY''));',
'  EXCEPTION WHEN OTHERS THEN l_year := NULL;',
'  END;',
'  l_year := NVL(l_year, EXTRACT(YEAR FROM SYSDATE));',
'',
'  l_code := CASE l_kind',
'              WHEN ''SALE'' THEN',
'                CASE WHEN l_type = ''SALE'' THEN CASE l_pay WHEN ''CASH'' THEN ''1'' ELSE ''2'' END',
'                     ELSE CASE l_pay WHEN ''CASH'' THEN ''5'' ELSE ''6'' END END',
'              WHEN ''PURCHASE'' THEN',
'                CASE WHEN l_type = ''PURCHASE'' THEN CASE l_pay WHEN ''CASH'' THEN ''3'' ELSE ''4'' END',
'                     ELSE CASE l_pay WHEN ''CASH'' THEN ''7'' ELSE ''8'' END END',
'              ELSE CASE l_type WHEN ''R'' THEN ''RV'' ELSE ''PV'' END',
'            END;',
'',
'  SELECT NVL(MAX(last_no), 0) + 1 INTO l_seq',
'  FROM   doc_sequences',
'  WHERE  company_id = :G_PARENT_ID AND doc_type = l_code AND fy_year = l_year;',
'',
'  l_no := CASE WHEN l_kind = ''VOUCHER'' THEN l_code || ''-'' || l_year || ''-'' || LPAD(l_seq, 5, ''0'')',
'               ELSE l_code || l_year || LPAD(l_seq, 5, ''0'') END;',
'',
'  apex_json.open_object;',
'  apex_json.write(''no'', l_no);',
'  apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_name=>'NEXT_NO'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000464
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000465)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('  -- \0642\0627\0626\0645\0629 \0627\0644\062D\0633\0627\0628\0627\062A \062D\0633\0628 \0637\0631\064A\0642\0629 \0627\0644\062F\0641\0639 (x01 = CASH \0623\0648 CREDIT) \060C \0648 x02 = SALE \0623\0648 PURCHASE'),
unistr('  --   \0646\0642\062F\064A : \0643\0644 \0627\0644\062E\0632\0627\0626\0646 \0648\0627\0644\062D\0633\0627\0628\0627\062A \0627\0644\0628\0646\0643\064A\0629'),
unistr('  --   \0622\062C\0644  : \0627\0644\0645\0628\064A\0639\0627\062A = \0627\0644\0639\0645\0644\0627\0621 (\062A\062D\062A 1106) \0648\0627\0644\0641\0631\0648\0639 \060C \0627\0644\0645\0634\062A\0631\064A\0627\062A = \0627\0644\0645\0648\0631\062F\0648\0646 (\062A\062D\062A 2101)'),
unistr('  --   \0623\0636\0641 \0623\064A \0639\0645\064A\0644 \0623\0648 \0645\0648\0631\062F \062C\062F\064A\062F \0643\062D\0633\0627\0628 \062A\062D\0644\064A\0644\064A \062A\062D\062A \0645\062C\0645\0648\0639\062A\0647 \0641\064A \0634\062C\0631\0629 \0627\0644\062D\0633\0627\0628\0627\062A'),
'  l_json CLOB;',
'  l_pay  VARCHAR2(10) := apex_application.g_x01;',
'  l_kind VARCHAR2(10) := apex_application.g_x02;',
'BEGIN',
'  SELECT JSON_ARRAYAGG(JSON_OBJECT(',
'           ''v'' VALUE a.account_id,',
'           ''t'' VALUE a.account_code || '' - '' || a.name_ar',
unistr('                     || CASE a.cash_bank WHEN ''B'' THEN '' (\0628\0646\0643)'' WHEN ''C'' THEN '' (\062E\0632\064A\0646\0629)'' END'),
unistr('                     || CASE WHEN ca.company_id IS NOT NULL THEN '' (\0641\0631\0639)'' END)'),
'         ORDER BY a.cash_bank DESC, a.account_code RETURNING CLOB)',
'  INTO   l_json',
'  FROM   accounts a',
'  LEFT JOIN company_accounts ca ON ca.ar_account_id = a.account_id',
'  WHERE  a.is_active = ''Y'' AND a.is_postable = ''Y''',
'  AND    (a.company_id IS NULL OR a.company_id = :G_PARENT_ID)',
'  AND    (   (l_pay = ''CASH''   AND a.cash_bank IN (''C'',''B''))',
'          OR (l_pay = ''CREDIT'' AND a.cash_bank = ''N'' AND l_kind = ''SALE''',
unistr('              AND (a.account_code LIKE ''1106%'' OR ca.company_id IS NOT NULL))       -- \0627\0644\0639\0645\0644\0627\0621 + \0627\0644\0641\0631\0648\0639'),
'          OR (l_pay = ''CREDIT'' AND a.cash_bank = ''N'' AND l_kind = ''PURCHASE''',
unistr('              AND a.account_code LIKE ''2101%''));                                    -- \0627\0644\0645\0648\0631\062F\0648\0646'),
'',
'  apex_util.prn(COALESCE(l_json, TO_CLOB(''[]'')), FALSE);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_name=>'PAY_ACCOUNTS'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000465
);
