wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(91000000000467)
,p_plug_name=>unistr('\0641\0648\0627\062A\064A\0631 \0627\0644\0645\0634\062A\0631\064A\0627\062A \0648\0627\0644\0645\0631\062A\062C\0639\0627\062A')
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(6687458349757443)
,p_plug_display_sequence=>10
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT p.pinv_id,',
unistr('       DECODE(p.invoice_type,''PURCHASE'',''\0645\0634\062A\0631\064A\0627\062A'',''\0645\0631\062A\062C\0639'') AS "\0627\0644\0646\0648\0639",'),
unistr('       c.name_ar AS "\0627\0644\0634\0631\0643\0629", p.invoice_no AS "\0627\0644\0631\0642\0645", p.supplier_inv_no AS "\0631\0642\0645 \0641\0627\062A\0648\0631\0629 \0627\0644\0645\0648\0631\062F",'),
unistr('       p.invoice_date AS "\0627\0644\062A\0627\0631\064A\062E", NVL(p.supplier_name, a.name_ar) AS "\0627\0644\0645\0648\0631\062F",'),
unistr('       DECODE(p.pay_type,''CASH'',''\0646\0642\062F\064A'',''\0622\062C\0644'') AS "\0627\0644\062F\0641\0639", w.name_ar AS "\0627\0644\0645\062E\0632\0646",'),
unistr('       p.net_amount AS "\0627\0644\0635\0627\0641\064A", p.currency_code AS "\0627\0644\0639\0645\0644\0629",'),
unistr('       ROUND(p.net_amount * p.exchange_rate, 2) AS "\0628\0627\0644\0639\0645\0644\0629 \0627\0644\0623\0633\0627\0633\064A\0629",'),
unistr('       DECODE(p.status,''DRAFT'',''\0645\0633\0648\062F\0629'',''POSTED'',''\0645\0631\062D\0651\0644\0629'',''REVERSED'',''\0645\0639\0643\0648\0633\0629'') AS "\0627\0644\062D\0627\0644\0629",'),
'       p.invoice_type AS invoice_type_code,',
unistr('       ''\0637\0628\0627\0639\0629'' AS "\0637\0628\0627\0639\0629 A4"'),
'FROM purchase_invoices p',
'JOIN companies  c ON c.company_id = p.company_id',
'JOIN accounts   a ON a.account_id = p.supplier_account_id',
'JOIN warehouses w ON w.warehouse_id = p.warehouse_id',
'WHERE (:G_USER_ROLE = ''ADMIN'' OR p.company_id = :G_COMPANY_ID',
'       OR p.company_id IN (SELECT company_id FROM user_companies WHERE user_name = UPPER(:APP_USER)))'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>unistr('\0641\0648\0627\062A\064A\0631 \0627\0644\0645\0634\062A\0631\064A\0627\062A \0648\0627\0644\0645\0631\062A\062C\0639\0627\062A')
,p_query_type=>'SQL'
);
