wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(91000000000496)
,p_plug_name=>'body'
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(6697232433757451)
,p_plug_display_sequence=>10
,p_location=>null
,p_plug_source_type=>'NATIVE_PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('  -- \0637\0628\0627\0639\0629 \0641\0627\062A\0648\0631\0629 \0623\0648 \062D\0631\0643\0629 \0645\062E\0632\0648\0646: STOCK = SALE \0623\0648 PURCHASE \0623\0648 STOCK \060C A4 = A4 \0623\0648 80'),
'  l_kind  VARCHAR2(10) := ''STOCK'';',
'  l_small BOOLEAN      := ''A4'' = ''80'';',
'  l_id    NUMBER       := :P95_TRANS_ID;',
'  l_title VARCHAR2(100); l_no VARCHAR2(30); l_date DATE; l_party VARCHAR2(300); l_pay VARCHAR2(100);',
'  l_cur VARCHAR2(3); l_gross NUMBER; l_disc NUMBER; l_net NUMBER; l_status VARCHAR2(10);',
'  l_ref VARCHAR2(50); l_desc VARCHAR2(500); l_user VARCHAR2(100); l_wh VARCHAR2(100);',
'  l_party_lbl VARCHAR2(50); l_wh_id NUMBER;',
'',
'  FUNCTION fn (n NUMBER) RETURN VARCHAR2 IS',
'  BEGIN RETURN TO_CHAR(NVL(n, 0), ''FM999G999G999G990D00''); END;',
'  FUNCTION e (s VARCHAR2) RETURN VARCHAR2 IS BEGIN RETURN apex_escape.html(s); END;',
unistr('  -- \0643\0645\064A\0629 \0628\062F\0648\0646 \0623\0635\0641\0627\0631 \0632\0627\0626\062F\0629: 5 \060C 2.5'),
'  FUNCTION fq (n NUMBER) RETURN VARCHAR2 IS',
'  BEGIN',
'    RETURN CASE WHEN n = TRUNC(n) THEN TO_CHAR(n, ''FM999G999G999G990'')',
'                ELSE RTRIM(TO_CHAR(n, ''FM999G999G999G990D9999''), ''0'') END;',
'  END;',
unistr('  -- \0627\0644\0643\0645\064A\0629 \0628\0627\0644\0639\0628\0648\0629 \0627\0644\0643\0628\0631\0649 \0648\0627\0644\0635\063A\0631\0649: 2 \0643\0631\062A\0648\0646\0629 \0648 5 \0642\0637\0639\0629'),
'  FUNCTION pk (p_item NUMBER, p_unit NUMBER, p_qty NUMBER) RETURN VARCHAR2 IS',
'    l_base NUMBER; l_bf NUMBER; l_bu NUMBER; l_su NUMBER; l_bn VARCHAR2(100); l_sn VARCHAR2(100); l_b NUMBER; l_s NUMBER;',
'  BEGIN',
'    SELECT p_qty * NVL((SELECT u.factor FROM item_units u WHERE u.item_id = p_item AND u.unit_id = p_unit), 1),',
'           i.big_factor, i.big_unit_id, i.base_unit_id,',
'           (SELECT name_ar FROM units WHERE unit_id = i.big_unit_id), (SELECT name_ar FROM units WHERE unit_id = i.base_unit_id)',
'    INTO   l_base, l_bf, l_bu, l_su, l_bn, l_sn',
'    FROM   items i WHERE i.item_id = p_item;',
'    IF l_bu IS NULL OR l_bu = l_su OR NVL(l_bf, 1) <= 1 THEN',
'      RETURN fq(l_base) || '' '' || l_sn;',
'    END IF;',
'    l_b := TRUNC(l_base / l_bf);',
'    l_s := l_base - l_b * l_bf;',
'    RETURN CASE WHEN l_b <> 0 THEN fq(l_b) || '' '' || l_bn END',
unistr('        || CASE WHEN l_b <> 0 AND l_s <> 0 THEN '' \0648 '' END'),
'        || CASE WHEN l_s <> 0 OR l_b = 0 THEN fq(l_s) || '' '' || l_sn END;',
'  EXCEPTION WHEN NO_DATA_FOUND THEN RETURN NULL;',
'  END;',
'BEGIN',
'  IF l_kind = ''SALE'' THEN',
unistr('    SELECT DECODE(i.invoice_type, ''SALE'', ''\0641\0627\062A\0648\0631\0629 \0645\0628\064A\0639\0627\062A'', ''\0645\0631\062A\062C\0639 \0645\0628\064A\0639\0627\062A'')'),
unistr('           || CASE WHEN i.pay_type = ''CASH'' THEN '' \0646\0642\062F\064A\0629'' ELSE '' \0622\062C\0644\0629'' END,'),
'           i.invoice_no, i.invoice_date,',
'           CASE i.customer_type WHEN ''BRANCH'' THEN c.name_ar ELSE NVL(i.customer_name, a.name_ar) END,',
unistr('           CASE WHEN i.pay_type = ''CREDIT'' THEN ''\0622\062C\0644 - '' || a.name_ar'),
unistr('                WHEN i.pay_method = ''BANK'' THEN ''\062A\062D\0648\064A\0644 \0628\0646\0643\064A - '' || a.name_ar ELSE ''\0646\0642\062F\0627\064B'' END,'),
'           i.currency_code, i.gross_amount, i.discount_amount, i.net_amount, i.status, NULL, i.description,',
'           i.created_by, w.name_ar',
'    INTO   l_title, l_no, l_date, l_party, l_pay, l_cur, l_gross, l_disc, l_net, l_status, l_ref, l_desc, l_user, l_wh',
'    FROM   invoices i',
'    LEFT JOIN companies c ON c.company_id = i.customer_company_id',
'    LEFT JOIN accounts  a ON a.account_id = i.account_id',
'    JOIN   warehouses w ON w.warehouse_id = i.warehouse_id',
'    WHERE  i.invoice_id = l_id;',
unistr('    l_party_lbl := ''\0627\0644\0639\0645\064A\0644'';'),
'  ELSIF l_kind = ''PURCHASE'' THEN',
unistr('    SELECT DECODE(p.invoice_type, ''PURCHASE'', ''\0641\0627\062A\0648\0631\0629 \0645\0634\062A\0631\064A\0627\062A'', ''\0645\0631\062A\062C\0639 \0645\0634\062A\0631\064A\0627\062A'')'),
unistr('           || CASE WHEN p.pay_type = ''CASH'' THEN '' \0646\0642\062F\064A\0629'' ELSE '' \0622\062C\0644\0629'' END,'),
'           p.invoice_no, p.invoice_date, NVL(p.supplier_name, a.name_ar),',
unistr('           CASE WHEN p.pay_type = ''CREDIT'' THEN ''\0622\062C\0644 - '' || a.name_ar'),
unistr('                WHEN p.pay_method = ''BANK'' THEN ''\062A\062D\0648\064A\0644 \0628\0646\0643\064A - '' || a.name_ar ELSE ''\0646\0642\062F\0627\064B'' END,'),
'           p.currency_code, p.gross_amount, p.discount_amount, p.net_amount, p.status, p.supplier_inv_no,',
'           p.description, p.created_by, w.name_ar',
'    INTO   l_title, l_no, l_date, l_party, l_pay, l_cur, l_gross, l_disc, l_net, l_status, l_ref, l_desc, l_user, l_wh',
'    FROM   purchase_invoices p',
'    JOIN   accounts a ON a.account_id = p.supplier_account_id',
'    JOIN   warehouses w ON w.warehouse_id = p.warehouse_id',
'    WHERE  p.pinv_id = l_id;',
unistr('    l_party_lbl := ''\0627\0644\0645\0648\0631\062F'';'),
'  ELSE',
unistr('    -- \062D\0631\0643\0629 \0645\062E\0632\0648\0646 (\0625\0634\0639\0627\0631 \0625\0636\0627\0641\0629 \060C \0627\0633\062A\0644\0627\0645 \060C \0635\0631\0641 \060C \062A\062D\0648\064A\0644 \060C \062C\0631\062F): \0627\0644\0642\064A\0645\0629 = \0627\0644\0643\0645\064A\0629 \00D7 \0627\0644\062A\0643\0644\0641\0629'),
unistr('    SELECT CASE t.trans_type WHEN ''OPENING'' THEN ''\0625\0634\0639\0627\0631 \0625\0636\0627\0641\0629 - \0628\0636\0627\0639\0629 \0623\0648\0644 \0627\0644\0645\062F\0629'' WHEN ''RECEIPT'' THEN ''\0627\0633\062A\0644\0627\0645 \0628\0636\0627\0639\0629'''),
unistr('                             WHEN ''ISSUE'' THEN ''\0635\0631\0641 \062F\0627\062E\0644\064A'' WHEN ''TRANSFER'' THEN ''\062A\062D\0648\064A\0644 \0628\064A\0646 \0627\0644\0645\062E\0627\0632\0646'''),
unistr('                             WHEN ''COUNT'' THEN ''\062A\0633\0648\064A\0629 \062C\0631\062F'' WHEN ''DAMAGE'' THEN ''\0641\0627\062A\0648\0631\0629 \0635\0631\0641 \062A\0648\0627\0644\0641'''),
unistr('                             WHEN ''DAMAGE_WO'' THEN ''\062A\0635\0641\064A\0631 \0627\0644\062A\0648\0627\0644\0641 - \0642\0631\0627\0631 \0627\0644\0645\062F\064A\0631'' ELSE ''\062D\0631\0643\0629 \0645\062E\0632\0648\0646'' END,'),
'           t.trans_no, t.trans_date,',
'           CASE WHEN t.trans_type = ''TRANSFER'' THEN tw.name_ar ELSE a.name_ar END,',
unistr('           CASE WHEN t.trans_type = ''TRANSFER'' THEN ''\0625\0644\0649 \0645\062E\0632\0646'' ELSE ''\0627\0644\062D\0633\0627\0628 \0627\0644\0645\0642\0627\0628\0644'' END,'),
'           t.currency_code, t.status, t.description, t.created_by, w.name_ar, t.warehouse_id',
'    INTO   l_title, l_no, l_date, l_party, l_party_lbl, l_cur, l_status, l_desc, l_user, l_wh, l_wh_id',
'    FROM   stock_trans t',
'    JOIN   warehouses w  ON w.warehouse_id  = t.warehouse_id',
'    LEFT JOIN warehouses tw ON tw.warehouse_id = t.to_warehouse_id',
'    LEFT JOIN accounts a ON a.account_id = t.counter_account_id',
'    WHERE  t.trans_id = l_id;',
'    SELECT NVL(SUM(qty * unit_cost), 0) INTO l_gross FROM stock_trans_lines WHERE trans_id = l_id AND warehouse_id = l_wh_id;',
'    l_disc := 0; l_net := l_gross;',
'  END IF;',
'',
'  htp.p(''<div class="inv '' || CASE WHEN l_small THEN ''inv-80'' ELSE ''inv-a4'' END || ''">'');',
unistr('  htp.p(''<div class="inv-title">'' || e(l_title) || CASE l_status WHEN ''DRAFT'' THEN '' <span class="inv-draft">(\0645\0633\0648\062F\0629)</span>'''),
unistr('                                                               WHEN ''REVERSED'' THEN '' <span class="inv-draft">(\0645\0644\063A\0627\0629 \0628\0642\064A\062F \0639\0643\0633\064A)</span>'' END || ''</div>'');'),
'',
unistr('  -- \0628\064A\0627\0646\0627\062A \0627\0644\0645\0633\062A\0646\062F'),
'  htp.p(''<table class="inv-head">'');',
unistr('  htp.p(''<tr><th>'' || CASE l_kind WHEN ''STOCK'' THEN ''\0627\0644\0631\0642\0645'' ELSE ''\0631\0642\0645 \0627\0644\0641\0627\062A\0648\0631\0629'' END || ''</th><td class="inv-no">'' || e(l_no) || ''</td>'''),
unistr('        || CASE WHEN NOT l_small THEN ''<th>\0627\0644\062A\0627\0631\064A\062E</th><td>'' || TO_CHAR(l_date, ''DD/MM/YYYY'') || ''</td>'' END || ''</tr>'');'),
unistr('  IF l_small THEN htp.p(''<tr><th>\0627\0644\062A\0627\0631\064A\062E</th><td>'' || TO_CHAR(l_date, ''DD/MM/YYYY'') || ''</td></tr>''); END IF;'),
'  IF l_party IS NOT NULL THEN',
'    htp.p(''<tr><th>'' || e(l_party_lbl) || ''</th><td'' || CASE WHEN NOT l_small THEN '' colspan="3"'' END || ''>'' || e(l_party) || ''</td></tr>'');',
'  END IF;',
'  IF l_kind <> ''STOCK'' THEN',
unistr('    htp.p(''<tr><th>\0627\0644\062F\0641\0639</th><td'' || CASE WHEN NOT l_small THEN ''>'' || e(l_pay) || ''</td><th>\0627\0644\0639\0645\0644\0629</th><td>'' || e(l_cur)'),
'                                           ELSE ''>'' || e(l_pay) END || ''</td></tr>'');',
'  END IF;',
'  IF l_ref IS NOT NULL THEN',
unistr('    htp.p(''<tr><th>\0631\0642\0645 \0641\0627\062A\0648\0631\0629 \0627\0644\0645\0648\0631\062F</th><td'' || CASE WHEN NOT l_small THEN '' colspan="3"'' END || ''>'' || e(l_ref) || ''</td></tr>'');'),
'  END IF;',
unistr('  IF NOT l_small THEN htp.p(''<tr><th>\0627\0644\0645\062E\0632\0646</th><td colspan="3">'' || e(l_wh) || ''</td></tr>''); END IF;'),
'  htp.p(''</table>'');',
'',
unistr('  -- \0627\0644\0623\0635\0646\0627\0641 (A4: \0627\0644\0643\0645\064A\0629 \0628\0627\0644\0648\062D\062F\0629 \0627\0644\0645\062E\062A\0627\0631\0629 \062B\0645 \0628\0627\0644\0639\0628\0648\0629 \0627\0644\0643\0628\0631\0649 \0648\0627\0644\0635\063A\0631\0649)'),
'  htp.p(''<table class="inv-lines"><thead><tr>'');',
'  IF l_small THEN',
unistr('    htp.p(''<th>\0627\0644\0635\0646\0641</th><th>\0627\0644\0643\0645\064A\0629</th><th>\0627\0644\0633\0639\0631</th><th>\0627\0644\0625\062C\0645\0627\0644\064A</th>'');'),
'  ELSE',
unistr('    htp.p(''<th>#</th><th>\0627\0644\0643\0648\062F</th><th>\0627\0644\0635\0646\0641</th><th>\0627\0644\0648\062D\062F\0629</th><th>\0627\0644\0643\0645\064A\0629</th><th>\0627\0644\0643\0645\064A\0629 \0628\0627\0644\0639\0628\0648\0629 \0627\0644\0643\0628\0631\0649 \0648\0627\0644\0635\063A\0631\0649</th><th>'''),
unistr('          || CASE l_kind WHEN ''STOCK'' THEN ''\0627\0644\062A\0643\0644\0641\0629'' ELSE ''\0627\0644\0633\0639\0631'' END || ''</th>'''),
unistr('          || CASE WHEN l_kind <> ''STOCK'' THEN ''<th>\0627\0644\062E\0635\0645</th>'' END || ''<th>\0627\0644\0625\062C\0645\0627\0644\064A</th>'');'),
'  END IF;',
'  htp.p(''</tr></thead><tbody>'');',
'  FOR r IN (SELECT l.line_no, l.item_id, l.unit_id, it.item_code, it.name_ar item_name, u.name_ar unit_name,',
'                   l.qty, l.price, l.discount, l.line_total',
'            FROM   invoice_lines l JOIN items it ON it.item_id = l.item_id JOIN units u ON u.unit_id = l.unit_id',
'            WHERE  l_kind = ''SALE'' AND l.invoice_id = l_id',
'            UNION ALL',
'            SELECT l.line_no, l.item_id, l.unit_id, it.item_code, it.name_ar, u.name_ar, l.qty, l.price, l.discount, l.line_total',
'            FROM   purchase_invoice_lines l JOIN items it ON it.item_id = l.item_id JOIN units u ON u.unit_id = l.unit_id',
'            WHERE  l_kind = ''PURCHASE'' AND l.pinv_id = l_id',
'            UNION ALL',
'            SELECT l.line_no, l.item_id, l.unit_id, it.item_code, it.name_ar, u.name_ar, l.qty, l.unit_cost, 0, l.qty * l.unit_cost',
'            FROM   stock_trans_lines l JOIN items it ON it.item_id = l.item_id JOIN units u ON u.unit_id = l.unit_id',
'            WHERE  l_kind = ''STOCK'' AND l.trans_id = l_id AND l.warehouse_id = l_wh_id',
'            ORDER BY 1) LOOP',
'    IF l_small THEN',
'      htp.p(''<tr><td>'' || e(r.item_name) || ''<br><small>'' || e(r.unit_name) || ''</small></td><td class="n">''',
'            || fn(r.qty) || ''</td><td class="n">'' || fn(r.price) || ''</td><td class="n">'' || fn(r.line_total) || ''</td></tr>'');',
'    ELSE',
'      htp.p(''<tr><td class="c">'' || r.line_no || ''</td><td>'' || e(r.item_code) || ''</td><td>'' || e(r.item_name) || ''</td><td>''',
'            || e(r.unit_name) || ''</td><td class="n">'' || fq(r.qty) || ''</td><td>'' || e(pk(r.item_id, r.unit_id, r.qty))',
'            || ''</td><td class="n">'' || fn(r.price) || ''</td>''',
'            || CASE WHEN l_kind <> ''STOCK'' THEN ''<td class="n">'' || CASE WHEN r.discount <> 0 THEN fn(r.discount) END || ''</td>'' END',
'            || ''<td class="n">'' || fn(r.line_total) || ''</td></tr>'');',
'    END IF;',
'  END LOOP;',
'  htp.p(''</tbody></table>'');',
'',
unistr('  -- \0627\0644\0625\062C\0645\0627\0644\064A\0627\062A'),
'  htp.p(''<table class="inv-totals">'');',
'  IF l_kind = ''STOCK'' THEN',
unistr('    htp.p(''<tr class="inv-net"><th>\0625\062C\0645\0627\0644\064A \0627\0644\0642\064A\0645\0629</th><td class="n">'' || fn(l_net) || '' '' || e(l_cur) || ''</td></tr>'');'),
'  ELSE',
unistr('    htp.p(''<tr><th>\0627\0644\0625\062C\0645\0627\0644\064A</th><td class="n">'' || fn(l_gross) || ''</td></tr>'');'),
unistr('    IF NVL(l_disc, 0) <> 0 THEN htp.p(''<tr><th>\0627\0644\062E\0635\0645</th><td class="n">'' || fn(l_disc) || ''</td></tr>''); END IF;'),
unistr('    htp.p(''<tr class="inv-net"><th>\0627\0644\0635\0627\0641\064A</th><td class="n">'' || fn(l_net) || '' '' || e(l_cur) || ''</td></tr>'');'),
'  END IF;',
'  htp.p(''</table>'');',
'',
unistr('  IF l_desc IS NOT NULL THEN htp.p(''<div class="inv-desc">\0627\0644\0628\064A\0627\0646: '' || e(l_desc) || ''</div>''); END IF;'),
'',
'  IF l_small THEN',
unistr('    htp.p(''<div class="inv-foot">\0627\0644\0645\0633\062A\062E\062F\0645: '' || e(l_user) || ''<br>'' || TO_CHAR(SYSDATE, ''DD/MM/YYYY HH24:MI'') || ''<br>\0634\0643\0631\0627\064B \0644\062A\0639\0627\0645\0644\0643\0645 \0645\0639\0646\0627</div>'');'),
'  ELSE',
unistr('    htp.p(''<table class="inv-sign"><tr><td>\0627\0644\0645\062D\0627\0633\0628<br><br>..................</td><td>\0623\0645\064A\0646 \0627\0644\0645\062E\0632\0646<br><br>..................</td><td>'''),
unistr('          || CASE l_kind WHEN ''SALE'' THEN ''\0627\0644\0645\0633\062A\0644\0645'' WHEN ''PURCHASE'' THEN ''\0627\0644\0645\0648\0631\062F'' ELSE ''\0627\0644\0645\0639\062A\0645\062F'' END || ''<br><br>..................</td></tr></table>'');'),
unistr('    htp.p(''<div class="inv-foot">\0637\064F\0628\0639\062A \0628\0648\0627\0633\0637\0629 '' || e(:APP_USER) || '' \0641\064A '' || TO_CHAR(SYSDATE, ''DD/MM/YYYY HH24:MI'') || ''</div>'');'),
'  END IF;',
'  htp.p(''</div>'');',
'EXCEPTION WHEN NO_DATA_FOUND THEN',
unistr('  htp.p(''<p>\0627\0644\0645\0633\062A\0646\062F \063A\064A\0631 \0645\0648\062C\0648\062F</p>'');'),
'END;'))
);
end;
