,p_plug_template=>wwv_flow_imp.id(6697232433757451)
,p_plug_display_sequence=>10
,p_location=>null
,p_plug_source_type=>'NATIVE_PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('  -- \0637\0628\0627\0639\0629 \0625\0630\0646 \062A\0648\0631\064A\062F / \0635\0631\0641 (\0646\0642\062F\064A \0623\0648 \0634\064A\0643\0627\062A) A4'),
'  v vouchers%ROWTYPE;',
'  l_cash VARCHAR2(300); l_acc VARCHAR2(300); l_title VARCHAR2(100);',
unistr('  -- \062A\0641\0642\064A\0637 \0627\0644\0645\0628\0644\063A \0628\0627\0644\0639\0631\0628\064A\0629: \062C\0646\064A\0647 \0633\0648\062F\0627\0646\064A \0648\0642\0631\0634'),
'  FUNCTION words3 (n PLS_INTEGER) RETURN VARCHAR2 IS',
'    TYPE t_a IS TABLE OF VARCHAR2(30) INDEX BY PLS_INTEGER;',
'    o t_a; t t_a; h t_a;',
'    l_h PLS_INTEGER := TRUNC(n / 100);',
'    l_r PLS_INTEGER := MOD(n, 100);',
'    l_s VARCHAR2(200);',
'    l_x VARCHAR2(100);',
'  BEGIN',
unistr('    o(1) := ''\0648\0627\062D\062F''; o(2) := ''\0627\062B\0646\0627\0646''; o(3) := ''\062B\0644\0627\062B\0629''; o(4) := ''\0623\0631\0628\0639\0629''; o(5) := ''\062E\0645\0633\0629'';'),
unistr('    o(6) := ''\0633\062A\0629''; o(7) := ''\0633\0628\0639\0629''; o(8) := ''\062B\0645\0627\0646\064A\0629''; o(9) := ''\062A\0633\0639\0629''; o(10) := ''\0639\0634\0631\0629'';'),
unistr('    o(11) := ''\0623\062D\062F \0639\0634\0631''; o(12) := ''\0627\062B\0646\0627 \0639\0634\0631''; o(13) := ''\062B\0644\0627\062B\0629 \0639\0634\0631''; o(14) := ''\0623\0631\0628\0639\0629 \0639\0634\0631''; o(15) := ''\062E\0645\0633\0629 \0639\0634\0631'';'),
unistr('    o(16) := ''\0633\062A\0629 \0639\0634\0631''; o(17) := ''\0633\0628\0639\0629 \0639\0634\0631''; o(18) := ''\062B\0645\0627\0646\064A\0629 \0639\0634\0631''; o(19) := ''\062A\0633\0639\0629 \0639\0634\0631'';'),
unistr('    t(2) := ''\0639\0634\0631\0648\0646''; t(3) := ''\062B\0644\0627\062B\0648\0646''; t(4) := ''\0623\0631\0628\0639\0648\0646''; t(5) := ''\062E\0645\0633\0648\0646'';'),
unistr('    t(6) := ''\0633\062A\0648\0646''; t(7) := ''\0633\0628\0639\0648\0646''; t(8) := ''\062B\0645\0627\0646\0648\0646''; t(9) := ''\062A\0633\0639\0648\0646'';'),
unistr('    h(1) := ''\0645\0627\0626\0629''; h(2) := ''\0645\0627\0626\062A\0627\0646''; h(3) := ''\062B\0644\0627\062B\0645\0627\0626\0629''; h(4) := ''\0623\0631\0628\0639\0645\0627\0626\0629''; h(5) := ''\062E\0645\0633\0645\0627\0626\0629'';'),
unistr('    h(6) := ''\0633\062A\0645\0627\0626\0629''; h(7) := ''\0633\0628\0639\0645\0627\0626\0629''; h(8) := ''\062B\0645\0627\0646\0645\0627\0626\0629''; h(9) := ''\062A\0633\0639\0645\0627\0626\0629'';'),
'    IF l_h > 0 THEN l_s := h(l_h); END IF;',
'    IF l_r > 0 THEN',
'      IF l_r < 20 THEN l_x := o(l_r);',
'      ELSIF MOD(l_r, 10) = 0 THEN l_x := t(TRUNC(l_r / 10));',
unistr('      ELSE l_x := o(MOD(l_r, 10)) || '' \0648'' || t(TRUNC(l_r / 10));'),
'      END IF;',
unistr('      l_s := CASE WHEN l_s IS NULL THEN l_x ELSE l_s || '' \0648'' || l_x END;'),
'    END IF;',
'    RETURN l_s;',
'  END;',
'',
'  FUNCTION words (p NUMBER) RETURN VARCHAR2 IS',
'    l_n   NUMBER := TRUNC(ABS(p));',
'    l_g   PLS_INTEGER;',
'    l_s   VARCHAR2(1000);',
'    l_x   VARCHAR2(300);',
'    TYPE t_s IS TABLE OF VARCHAR2(30) INDEX BY PLS_INTEGER;',
'    s1 t_s; s2 t_s; sp t_s;',
'  BEGIN',
unistr('    IF l_n = 0 THEN RETURN ''\0635\0641\0631''; END IF;'),
unistr('    s1(1) := ''\0623\0644\0641'';   s2(1) := ''\0623\0644\0641\0627\0646'';   sp(1) := ''\0622\0644\0627\0641'';'),
unistr('    s1(2) := ''\0645\0644\064A\0648\0646''; s2(2) := ''\0645\0644\064A\0648\0646\0627\0646''; sp(2) := ''\0645\0644\0627\064A\064A\0646'';'),
unistr('    s1(3) := ''\0645\0644\064A\0627\0631''; s2(3) := ''\0645\0644\064A\0627\0631\0627\0646''; sp(3) := ''\0645\0644\064A\0627\0631\0627\062A'';'),
'    FOR i IN REVERSE 0 .. 3 LOOP',
'      l_g := TRUNC(MOD(l_n, POWER(1000, i + 1)) / POWER(1000, i));',
'      IF l_g > 0 THEN',
'        IF i = 0 THEN l_x := words3(l_g);',
'        ELSIF l_g = 1 THEN l_x := s1(i);',
'        ELSIF l_g = 2 THEN l_x := s2(i);',
'        ELSIF l_g BETWEEN 3 AND 10 THEN l_x := words3(l_g) || '' '' || sp(i);',
'        ELSE l_x := words3(l_g) || '' '' || s1(i);',
'        END IF;',
unistr('        l_s := CASE WHEN l_s IS NULL THEN l_x ELSE l_s || '' \0648'' || l_x END;'),
'      END IF;',
'    END LOOP;',
'    RETURN l_s;',
'  END;',
'',
'  FUNCTION tafqeet (p NUMBER) RETURN VARCHAR2 IS',
'    l_p NUMBER := ROUND(MOD(ABS(p), 1) * 100);',
'  BEGIN',
unistr('    RETURN ''\0641\0642\0637 '' || words(p) || '' \062C\0646\064A\0647 \0633\0648\062F\0627\0646\064A'''),
unistr('        || CASE WHEN l_p > 0 THEN '' \0648'' || words(l_p) || '' \0642\0631\0634'' END || '' \0644\0627 \063A\064A\0631'';'),
'  END;',
'',
'  FUNCTION fn (n NUMBER) RETURN VARCHAR2 IS BEGIN RETURN TO_CHAR(NVL(n, 0), ''FM999G999G999G990D00''); END;',
'  FUNCTION e (s VARCHAR2) RETURN VARCHAR2 IS BEGIN RETURN apex_escape.html(s); END;',
'BEGIN',
'  BEGIN SELECT * INTO v FROM vouchers WHERE voucher_id = :P42_VOUCHER_ID;',
unistr('  EXCEPTION WHEN NO_DATA_FOUND THEN htp.p(''<p>\0627\0644\0625\0630\0646 \063A\064A\0631 \0645\0648\062C\0648\062F</p>''); RETURN; END;'),
'  SELECT MAX(account_code || '' - '' || name_ar) INTO l_cash FROM accounts WHERE account_id = v.cash_account_id;',
'  SELECT MAX(account_code || '' - '' || name_ar) INTO l_acc  FROM accounts WHERE account_id = v.counter_account_id;',
unistr('  l_title := CASE v.voucher_type WHEN ''R'' THEN ''\0625\0630\0646 \062A\0648\0631\064A\062F '' ELSE ''\0625\0630\0646 \0635\0631\0641 '' END'),
unistr('          || CASE v.voucher_kind WHEN ''CHEQUE'' THEN ''\0634\064A\0643\0627\062A'' ELSE ''\0646\0642\062F\064A'' END;'),
'',
'  htp.p(''<div class="inv inv-a4">'');',
'  htp.p(''<div class="inv-title">'' || e(l_title)',
unistr('        || CASE WHEN v.status NOT IN (''APPROVED'',''POSTED'') THEN '' <span class="inv-draft">(\063A\064A\0631 \0645\0639\062A\0645\062F)</span>'' END'),
unistr('        || CASE WHEN v.status = ''REVERSED'' THEN '' <span class="inv-draft">(\0645\0644\063A\0649 \0628\0642\064A\062F \0639\0643\0633\064A)</span>'' END || ''</div>'');'),
'  htp.p(''<table class="inv-head">'');',
unistr('  htp.p(''<tr><th>\0631\0642\0645 \0627\0644\0625\0630\0646</th><td class="inv-no">'' || e(v.voucher_no) || ''</td><th>\0627\0644\062A\0627\0631\064A\062E</th><td>'' || TO_CHAR(v.voucher_date, ''DD/MM/YYYY'') || ''</td></tr>'');'),
unistr('  htp.p(''<tr><th>'' || CASE v.voucher_type WHEN ''R'' THEN ''\0627\0633\062A\0644\0645\0646\0627 \0645\0646'' ELSE ''\0635\0631\0641\0646\0627 \0625\0644\0649'' END || ''</th><td colspan="3">'' || e(v.party_name) || ''</td></tr>'');'),
'  IF v.voucher_kind = ''CASH'' THEN',
unistr('    htp.p(''<tr><th>\0627\0644\062E\0632\064A\0646\0629</th><td colspan="3">'' || e(l_cash) || ''</td></tr>'');'),
'  END IF;',
unistr('  htp.p(''<tr><th>\0627\0644\062D\0633\0627\0628 \0627\0644\0645\0642\0627\0628\0644</th><td colspan="3">'' || e(l_acc) || ''</td></tr>'');'),
unistr('  htp.p(''<tr><th>\0627\0644\0645\0628\0644\063A</th><td class="inv-no">'' || fn(v.total_amount) || ''</td><th>\0627\0644\0639\0645\0644\0629</th><td>\062C\0646\064A\0647 \0633\0648\062F\0627\0646\064A</td></tr>'');'),
unistr('  htp.p(''<tr><th>\0627\0644\0645\0628\0644\063A \0643\062A\0627\0628\0629</th><td colspan="3">'' || e(tafqeet(v.total_amount)) || ''</td></tr>'');'),
unistr('  htp.p(''<tr><th>\0627\0644\0628\064A\0627\0646</th><td colspan="3">'' || e(v.description) || ''</td></tr>'');'),
'  htp.p(''</table>'');',
'',
'  IF v.voucher_kind = ''CHEQUE'' THEN',
unistr('    htp.p(''<table class="inv-lines"><thead><tr><th>#</th><th>\0627\0644\0645\0633\0644\0633\0644</th><th>\0631\0642\0645 \0627\0644\0634\064A\0643</th><th>\0627\0644\0628\0646\0643</th><th>\062A\0627\0631\064A\062E \0627\0644\0635\0631\0641</th>'''),
unistr('          || ''<th>'' || CASE v.voucher_type WHEN ''R'' THEN ''\0627\0644\0633\0627\062D\0628'' ELSE ''\0627\0644\0645\0633\062A\0641\064A\062F'' END || ''</th><th>\0627\0644\0645\0628\0644\063A</th></tr></thead><tbody>'');'),
'    FOR c IN (SELECT c.line_no, c.cheque_serial, c.cheque_no, NVL(b.name_ar, NVL(vb.name_ar, '''')) || CASE WHEN c.bank_name IS NOT NULL THEN '' ('' || c.bank_name || '')'' END bank, c.due_date, c.payee_name, c.amount',
'              FROM cheques c LEFT JOIN accounts b ON b.account_id = c.bank_account_id',
'              JOIN vouchers vv ON vv.voucher_id = c.voucher_id LEFT JOIN accounts vb ON vb.account_id = vv.bank_account_id',
'              WHERE c.voucher_id = v.voucher_id ORDER BY c.line_no) LOOP',
'      htp.p(''<tr><td class="c">'' || c.line_no || ''</td><td>'' || e(c.cheque_serial) || ''</td><td>'' || e(c.cheque_no) || ''</td><td>'' || e(c.bank) || ''</td><td class="c">''',
'            || TO_CHAR(c.due_date, ''DD/MM/YYYY'') || ''</td><td>'' || e(c.payee_name) || ''</td><td class="n">'' || fn(c.amount) || ''</td></tr>'');',
'    END LOOP;',
'    htp.p(''</tbody></table>'');',
'  END IF;',
'',
unistr('  htp.p(''<table class="inv-sign"><tr><td>\0627\0644\0645\062F\062E\0644<br>'' || e(v.created_by) || ''<br>..................</td>'''),
unistr('        || ''<td>\0627\0644\0645\0631\0627\062C\0639<br>'' || e(v.reviewed_by) || ''<br>..................</td>'''),
unistr('        || ''<td>\0627\0644\0645\0639\062A\0645\062F<br>'' || e(v.approved_by) || ''<br>..................</td>'''),
unistr('        || ''<td>'' || CASE v.voucher_type WHEN ''R'' THEN ''\0627\0644\0645\0648\0631\0650\0651\062F'' ELSE ''\0627\0644\0645\0633\062A\0644\0645'' END || ''<br><br>..................</td></tr></table>'');'),
unistr('  htp.p(''<div class="inv-foot">\0637\064F\0628\0639 \0628\0648\0627\0633\0637\0629 '' || e(:APP_USER) || '' \0641\064A '' || TO_CHAR(SYSDATE, ''DD/MM/YYYY HH24:MI'') || ''</div>'');'),
'  htp.p(''</div>'');',
'END;'))
);
end;
