 p_id=>wwv_flow_imp.id(91000000000502)
,p_plug_name=>'body'
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(6697232433757451)
,p_plug_display_sequence=>10
,p_location=>null
,p_plug_source_type=>'NATIVE_PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('  -- \0637\0628\0627\0639\0629 \0642\064A\062F \064A\0648\0645\064A\0629 A4'),
'  j journals%ROWTYPE;',
'  l_type VARCHAR2(100);',
'  FUNCTION fn (n NUMBER) RETURN VARCHAR2 IS BEGIN RETURN CASE WHEN NVL(n, 0) <> 0 THEN TO_CHAR(n, ''FM999G999G999G990D00'') END; END;',
'  FUNCTION e (s VARCHAR2) RETURN VARCHAR2 IS BEGIN RETURN apex_escape.html(s); END;',
'BEGIN',
'  BEGIN SELECT * INTO j FROM journals WHERE journal_id = :P32_JOURNAL_ID;',
unistr('  EXCEPTION WHEN NO_DATA_FOUND THEN htp.p(''<p>\0627\0644\0642\064A\062F \063A\064A\0631 \0645\0648\062C\0648\062F</p>''); RETURN; END;'),
'  SELECT MAX(name_ar) INTO l_type FROM journal_types WHERE jt_code = j.jt_code;',
'',
'  htp.p(''<div class="inv inv-a4">'');',
'  htp.p(''<div class="inv-title">'' || e(l_type)',
unistr('        || CASE WHEN j.status NOT IN (''POSTED'',''REVERSED'') THEN '' <span class="inv-draft">(\063A\064A\0631 \0645\0631\062D\0651\0644)</span>'' END'),
unistr('        || CASE WHEN j.status = ''REVERSED'' THEN '' <span class="inv-draft">(\0645\0639\0643\0648\0633)</span>'' END || ''</div>'');'),
'  htp.p(''<table class="inv-head">'');',
unistr('  htp.p(''<tr><th>\0631\0642\0645 \0627\0644\0642\064A\062F</th><td class="inv-no">'' || e(j.journal_no) || ''</td><th>\0627\0644\062A\0627\0631\064A\062E</th><td>'' || TO_CHAR(j.journal_date, ''DD/MM/YYYY'') || ''</td></tr>'');'),
unistr('  htp.p(''<tr><th>\0627\0644\0628\064A\0627\0646</th><td colspan="3">'' || e(j.description) || ''</td></tr>'');'),
unistr('  IF j.ref_no IS NOT NULL THEN htp.p(''<tr><th>\0627\0644\0645\0631\062C\0639</th><td colspan="3">'' || e(j.ref_no) || ''</td></tr>''); END IF;'),
'  htp.p(''</table>'');',
'',
unistr('  htp.p(''<table class="inv-lines"><thead><tr><th>#</th><th>\0631\0642\0645 \0627\0644\062D\0633\0627\0628</th><th>\0627\0633\0645 \0627\0644\062D\0633\0627\0628</th><th>\0645\062F\064A\0646</th><th>\062F\0627\0626\0646</th><th>\0627\0644\0628\064A\0627\0646</th></tr></thead><tbody>'');'),
'  FOR l IN (SELECT l.line_no, a.account_code, a.name_ar, l.debit, l.credit, l.description',
'            FROM journal_lines l JOIN accounts a ON a.account_id = l.account_id',
'            WHERE l.journal_id = j.journal_id ORDER BY l.line_no) LOOP',
'    htp.p(''<tr><td class="c">'' || l.line_no || ''</td><td>'' || e(l.account_code) || ''</td><td>'' || e(l.name_ar) || ''</td><td class="n">''',
'          || fn(l.debit) || ''</td><td class="n">'' || fn(l.credit) || ''</td><td>'' || e(l.description) || ''</td></tr>'');',
'  END LOOP;',
unistr('  htp.p(''<tr class="inv-net"><td colspan="3"><b>\0627\0644\0625\062C\0645\0627\0644\064A</b></td><td class="n"><b>'' || fn(j.total_debit) || ''</b></td><td class="n"><b>'''),
'        || fn(j.total_credit) || ''</b></td><td></td></tr>'');',
'  htp.p(''</tbody></table>'');',
'',
unistr('  htp.p(''<table class="inv-sign"><tr><td>\0627\0644\0645\062F\062E\0644<br>'' || e(j.created_by) || ''<br>..................</td>'''),
unistr('        || ''<td>\0627\0644\0645\0631\0627\062C\0639<br>'' || e(j.reviewed_by) || ''<br>..................</td>'''),
unistr('        || ''<td>\0627\0644\0645\0639\062A\0645\062F<br>'' || e(j.approved_by) || ''<br>..................</td></tr></table>'');'),
unistr('  htp.p(''<div class="inv-foot">\0637\064F\0628\0639 \0628\0648\0627\0633\0637\0629 '' || e(:APP_USER) || '' \0641\064A '' || TO_CHAR(SYSDATE, ''DD/MM/YYYY HH24:MI'') || ''</div>'');'),
'  htp.p(''</div>'');',
'END;'))
);
end;
