wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000525)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_clob_language=>'PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_err VARCHAR2(4000);',
'FUNCTION chk RETURN VARCHAR2 IS',
'BEGIN',
unistr('-- 1. \062D\0627\0644\0629 \0627\0644\0642\064A\062F \0648\0627\0644\0635\0644\0627\062D\064A\0629'),
'DECLARE j journals%ROWTYPE; l_cnt NUMBER;',
'BEGIN',
'  SELECT * INTO j FROM journals WHERE journal_id = :P60_JOURNAL_ID;',
unistr('  IF j.status <> ''POSTED''            THEN RETURN ''\0627\0644\0642\064A\062F \063A\064A\0631 \0645\0631\062D\0651\0644 \0623\0648 \0645\0639\0643\0648\0633 \0645\0633\0628\0642\0627\064B''; END IF;'),
'  IF j.reversal_of_id IS NOT NULL',
unistr('     OR j.jt_code = ''REV''            THEN RETURN ''\0644\0627 \064A\0645\0643\0646 \0639\0643\0633 \0642\064A\062F \0639\0643\0633\064A''; END IF;'),
'  SELECT COUNT(*) INTO l_cnt FROM invoices WHERE sub_journal_id = j.journal_id;',
unistr('  IF l_cnt > 0 THEN RETURN ''\0647\0630\0627 \0642\064A\062F \0634\0631\0643\0629 \0641\0631\0639\064A\0629 \0646\0627\062A\062C \0639\0646 \0641\0627\062A\0648\0631\0629. \0627\0639\0643\0633 \0642\064A\062F \0627\0644\0634\0631\0643\0629 \0627\0644\0623\0645''; END IF;'),
'  SELECT COUNT(*) INTO l_cnt FROM vouchers v JOIN cheques c ON c.voucher_id = v.voucher_id',
'  WHERE  j.source_type = ''VOUCHER'' AND v.voucher_id = j.source_id AND c.status <> ''PENDING'';',
unistr('  IF l_cnt > 0 THEN RETURN ''\0634\064A\0643\0627\062A \0647\0630\0627 \0627\0644\0625\0630\0646 \062A\0645\062A \062A\0633\0648\064A\0629 \0628\0639\0636\0647\0627. \0623\0644\063A\0650 \0627\0644\062A\0633\0648\064A\0627\062A \0623\0648 \0627\0639\0643\0633 \0642\064A\0648\062F\0647\0627 \0623\0648\0644\0627\064B''; END IF;'),
unistr('  IF :G_USER_ROLE NOT IN (''ADMIN'',''APPROVER'') THEN RETURN ''\0639\0643\0633 \0627\0644\0642\064A\0648\062F \0645\0646 \0635\0644\0627\062D\064A\0629 \0627\0644\0645\0639\062A\0645\062F''; END IF;'),
'  SELECT COUNT(*) INTO l_cnt FROM dual',
'  WHERE :G_USER_ROLE = ''ADMIN'' OR j.company_id = :G_COMPANY_ID',
'     OR EXISTS (SELECT 1 FROM user_companies WHERE user_name = UPPER(:APP_USER) AND company_id = j.company_id);',
unistr('  IF l_cnt = 0 THEN RETURN ''\0644\064A\0633 \0644\062F\064A\0643 \0635\0644\0627\062D\064A\0629 \0639\0644\0649 \0647\0630\0647 \0627\0644\0634\0631\0643\0629''; END IF;'),
'  RETURN NULL;',
unistr('EXCEPTION WHEN NO_DATA_FOUND THEN RETURN ''\0627\0644\0642\064A\062F \063A\064A\0631 \0645\0648\062C\0648\062F'';'),
'END;',
'END;',
'BEGIN',
'  l_err := chk;',
'  IF l_err IS NOT NULL THEN',
'    apex_error.add_error(p_message => l_err, p_display_location => apex_error.c_inline_in_notification);',
'  END IF;',
'END;'))
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CHECK_STATUS'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(91000000000522)
,p_internal_uid=>91000000000525
);
