'FUNCTION chk RETURN VARCHAR2 IS',
'BEGIN',
unistr('-- 2. \062A\0627\0631\064A\062E \0627\0644\0639\0643\0633'),
'DECLARE l_d DATE; l_orig DATE; l_cnt NUMBER;',
'BEGIN',
'  l_d := TO_DATE(:P60_REV_DATE, ''DD/MM/YYYY'');',
'  SELECT journal_date INTO l_orig FROM journals WHERE journal_id = :P60_JOURNAL_ID;',
unistr('  IF l_d < l_orig THEN RETURN ''\062A\0627\0631\064A\062E \0627\0644\0639\0643\0633 \0642\0628\0644 \062A\0627\0631\064A\062E \0627\0644\0642\064A\062F \0627\0644\0623\0635\0644\064A''; END IF;'),
'  SELECT COUNT(*) INTO l_cnt FROM fiscal_years',
'  WHERE l_d BETWEEN start_date AND end_date AND is_closed = ''N'';',
unistr('  IF l_cnt = 0 THEN RETURN ''\062A\0627\0631\064A\062E \0627\0644\0639\0643\0633 \062E\0627\0631\062C \0633\0646\0629 \0645\0627\0644\064A\0629 \0645\0641\062A\0648\062D\0629''; END IF;'),
'  RETURN NULL;',
unistr('EXCEPTION WHEN OTHERS THEN RETURN ''\062A\0627\0631\064A\062E \0627\0644\0639\0643\0633 \063A\064A\0631 \0635\062D\064A\062D'';'),
'END;',
'END;',
'BEGIN',
'  l_err := chk;',
'  IF l_err IS NOT NULL THEN',
'    apex_error.add_error(p_message => l_err, p_display_location => apex_error.c_inline_in_notification);',
'  END IF;',
'END;'))
,p_process_name=>'CHECK_DATE'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(91000000000522)
,p_internal_uid=>91000000000526
);
