wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000554)
,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_process_clob_language=>'PLSQL'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('  -- \062F\0648\0631\0629 \0627\0644\0645\0633\062A\0646\062F: \0645\0633\0648\062F\0629 -> \0645\064F\0631\0627\062C\064E\0639 -> \0645\0639\062A\0645\062F -> \0645\0631\062D\0651\0644 \060C \0648\0627\0644\0625\0639\0627\062F\0629 \0644\0644\0645\062F\062E\0644 \0645\0639 \0627\0644\0633\0628\0628'),
unistr('  -- \0627\0644\0645\0631\0627\062C\0639: \0645\0631\0627\062C\0639\0629 / \0625\0644\063A\0627\0621 \0627\0644\0645\0631\0627\062C\0639\0629 / \0625\0639\0627\062F\0629 \060C \0627\0644\0645\0639\062A\0645\062F: \0627\0639\062A\0645\0627\062F / \0625\0644\063A\0627\0621 \0627\0644\0627\0639\062A\0645\0627\062F / \0625\0639\0627\062F\0629 / \062A\0631\062D\064A\0644 \060C \0645\062F\064A\0631 \0627\0644\0646\0638\0627\0645: \0627\0644\0643\0644'),
'  l_id    NUMBER        := :P70_ADJ_ID;',
'  l_req   VARCHAR2(20)  := :REQUEST;',
'  l_role  VARCHAR2(20)  := :G_USER_ROLE;',
'  l_note  VARCHAR2(500) := SUBSTR(TRIM(:P70_WF_NOTE), 1, 500);',
'  l_st    VARCHAR2(10);',
'  l_new   VARCHAR2(10);',
'  l_err   VARCHAR2(400);',
'  l_msg   VARCHAR2(200);',
'  FUNCTION has (p_roles VARCHAR2) RETURN BOOLEAN IS',
'  BEGIN RETURN l_role = ''ADMIN'' OR INSTR('','' || p_roles || '','', '','' || l_role || '','') > 0; END;',
'BEGIN',
'  IF apex_error.have_errors_occurred THEN RETURN; END IF;',
'  IF l_id IS NULL THEN',
unistr('    l_err := ''\0627\062D\0641\0638 \0627\0644\0645\0633\062A\0646\062F \0623\0648\0644\0627\064B'';'),
'  ELSE',
'    SELECT status INTO l_st FROM payroll_adj WHERE adj_id = l_id FOR UPDATE;',
'    CASE l_req',
'      WHEN ''REVIEW'' THEN',
unistr('        IF NOT has(''REVIEWER'') THEN l_err := ''\0627\0644\0645\0631\0627\062C\0639\0629 \0645\0646 \0635\0644\0627\062D\064A\0629 \0627\0644\0645\0631\0627\062C\0639'';'),
unistr('        ELSIF l_st <> ''DRAFT'' THEN l_err := ''\0644\0627 \064A\064F\0631\0627\062C\0639 \0625\0644\0627 \0627\0644\0645\0633\062A\0646\062F \0641\064A \062D\0627\0644\0629 \0645\0633\0648\062F\0629'';'),
unistr('        ELSE l_new := ''REVIEWED''; l_msg := ''\062A\0645\062A \0627\0644\0645\0631\0627\062C\0639\0629''; END IF;'),
'      WHEN ''UNREVIEW'' THEN',
unistr('        IF NOT has(''REVIEWER'') THEN l_err := ''\0625\0644\063A\0627\0621 \0627\0644\0645\0631\0627\062C\0639\0629 \0645\0646 \0635\0644\0627\062D\064A\0629 \0627\0644\0645\0631\0627\062C\0639'';'),
unistr('        ELSIF l_st <> ''REVIEWED'' THEN l_err := ''\0627\0644\0645\0633\062A\0646\062F \0644\064A\0633 \0641\064A \062D\0627\0644\0629 \0645\064F\0631\0627\062C\064E\0639 (\0631\0628\0645\0627 \062A\0645 \0627\0639\062A\0645\0627\062F\0647)'';'),
unistr('        ELSE l_new := ''DRAFT''; l_msg := ''\062A\0645 \0625\0644\063A\0627\0621 \0627\0644\0645\0631\0627\062C\0639\0629''; END IF;'),
'      WHEN ''APPROVE'' THEN',
unistr('        IF NOT has(''APPROVER'') THEN l_err := ''\0627\0644\0627\0639\062A\0645\0627\062F \0645\0646 \0635\0644\0627\062D\064A\0629 \0627\0644\0645\0639\062A\0645\062F'';'),
unistr('        ELSIF l_st <> ''REVIEWED'' THEN l_err := ''\0644\0627 \064A\064F\0639\062A\0645\062F \0625\0644\0627 \0627\0644\0645\0633\062A\0646\062F \0627\0644\0645\064F\0631\0627\062C\064E\0639'';'),
unistr('        ELSIF ''N'' = ''Y'' THEN l_new := ''POSTED''; l_msg := ''\062A\0645 \0627\0644\0627\0639\062A\0645\0627\062F \0648\0627\0644\062A\0631\062D\064A\0644'';'),
unistr('        ELSE l_new := ''APPROVED''; l_msg := ''\062A\0645 \0627\0644\0627\0639\062A\0645\0627\062F''; END IF;'),
'      WHEN ''UNAPPROVE'' THEN',
unistr('        IF NOT has(''APPROVER'') THEN l_err := ''\0625\0644\063A\0627\0621 \0627\0644\0627\0639\062A\0645\0627\062F \0645\0646 \0635\0644\0627\062D\064A\0629 \0627\0644\0645\0639\062A\0645\062F'';'),
unistr('        ELSIF l_st <> ''APPROVED'' THEN l_err := ''\0627\0644\0645\0633\062A\0646\062F \0644\064A\0633 \0641\064A \062D\0627\0644\0629 \0645\0639\062A\0645\062F (\0631\0628\0645\0627 \062A\0645 \062A\0631\062D\064A\0644\0647)'';'),
unistr('        ELSE l_new := ''REVIEWED''; l_msg := ''\062A\0645 \0625\0644\063A\0627\0621 \0627\0644\0627\0639\062A\0645\0627\062F''; END IF;'),
'      WHEN ''RETURN'' THEN',
'        IF NOT ((has(''REVIEWER'') AND l_st IN (''DRAFT'',''REVIEWED'')) OR (has(''APPROVER'') AND l_st IN (''REVIEWED'',''APPROVED''))) THEN',
unistr('          l_err := ''\0644\0627 \064A\0645\0643\0646\0643 \0625\0639\0627\062F\0629 \0647\0630\0627 \0627\0644\0645\0633\062A\0646\062F \0641\064A \062D\0627\0644\062A\0647 \0627\0644\062D\0627\0644\064A\0629'';'),
unistr('        ELSIF l_note IS NULL THEN l_err := ''\0627\0643\062A\0628 \0633\0628\0628 \0627\0644\0625\0639\0627\062F\0629'';'),
unistr('        ELSE l_new := ''RETURNED''; l_msg := ''\062A\0645\062A \0625\0639\0627\062F\0629 \0627\0644\0645\0633\062A\0646\062F \0644\0644\0645\062F\062E\0644''; END IF;'),
'      WHEN ''POST'' THEN',
unistr('        IF ''N'' <> ''Y'' THEN l_err := ''\0647\0630\0627 \0627\0644\0645\0633\062A\0646\062F \0644\0627 \064A\064F\0631\062D\0651\0644'';'),
unistr('        ELSIF NOT has(''APPROVER'') THEN l_err := ''\0627\0644\062A\0631\062D\064A\0644 \0645\0646 \0635\0644\0627\062D\064A\0629 \0627\0644\0645\0639\062A\0645\062F'';'),
unistr('        ELSIF l_st <> ''APPROVED'' THEN l_err := ''\0644\0627 \064A\064F\0631\062D\0651\0644 \0625\0644\0627 \0627\0644\0645\0633\062A\0646\062F \0627\0644\0645\0639\062A\0645\062F'';'),
unistr('        ELSE l_new := ''POSTED''; l_msg := ''\062A\0645 \0627\0644\062A\0631\062D\064A\0644''; END IF;'),
unistr('      ELSE l_err := ''\0625\062C\0631\0627\0621 \063A\064A\0631 \0645\0639\0631\0648\0641'';'),
'    END CASE;',
'  END IF;',
'',
unistr('  -- \0634\0631\0637 \0625\0636\0627\0641\064A \062E\0627\0635 \0628\0627\0644\0645\0633\062A\0646\062F (\0645\062B\0644: \0625\0630\0646 \0627\0644\0634\064A\0643\0627\062A \0644\0627 \064A\064F\0631\0627\062C\0639 \0642\0628\0644 \062C\062F\0648\0644\0629 \0634\064A\0643\0627\062A\0647)'),
'  IF l_err IS NULL AND l_req IN (''REVIEW'',''APPROVE'') THEN',
'    NULL;',
'  END IF;',
'',
'  IF l_err IS NOT NULL THEN',
'    apex_error.add_error(p_message => l_err, p_display_location => apex_error.c_inline_in_notification);',
'    RETURN;',
'  END IF;',
'',
unistr('  -- \0627\0644\062A\0631\062D\064A\0644 \064A\062A\0645 \0645\0628\0627\0634\0631\0629 \0639\0646\062F \0627\0644\0627\0639\062A\0645\0627\062F'),
'  IF l_new = ''POSTED'' THEN',
'    NULL;',
'  END IF;',
'',
'  UPDATE payroll_adj',
'  SET    status      = l_new,',
'         reviewed_by = CASE WHEN l_req = ''REVIEW'' THEN :APP_USER WHEN l_req IN (''UNREVIEW'',''RETURN'') THEN NULL ELSE reviewed_by END,',
'         reviewed_on = CASE WHEN l_req = ''REVIEW'' THEN SYSDATE   WHEN l_req IN (''UNREVIEW'',''RETURN'') THEN NULL ELSE reviewed_on END,',
'         approved_by = CASE WHEN l_req = ''APPROVE'' THEN :APP_USER WHEN l_req IN (''UNAPPROVE'',''RETURN'') THEN NULL ELSE approved_by END,',
'         approved_on = CASE WHEN l_req = ''APPROVE'' THEN SYSDATE   WHEN l_req IN (''UNAPPROVE'',''RETURN'') THEN NULL ELSE approved_on END,',
'         return_note = CASE WHEN l_req = ''RETURN'' THEN l_note ELSE return_note END',
'  WHERE  adj_id = l_id;',
'',
'  INSERT INTO doc_actions (doc_type, doc_id, action, from_status, to_status, note, action_by)',
'  VALUES (''PAYADJ'', l_id, l_req, l_st, l_new, l_note, :APP_USER);',
'',
'  :P70_WF_NOTE := NULL;',
'  apex_application.g_print_success_message := l_msg;',
'END;'))
,p_process_name=>'WORKFLOW'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'REVIEW,UNREVIEW,APPROVE,UNAPPROVE,RETURN,POST'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_internal_uid=>91000000000554
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000555)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_clob_language=>'PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE r payroll_adj%ROWTYPE;',
'BEGIN',
'  SELECT * INTO r FROM payroll_adj WHERE adj_id = :P70_ADJ_ID;',
'  :P70_RETURN_NOTE := CASE WHEN r.status IN (''RETURNED'',''DRAFT'') THEN r.return_note END;',
unistr(':P70_WF_INFO := TRIM(CASE WHEN r.reviewed_by IS NOT NULL THEN ''\0631\0627\062C\0639\0647 '' || r.reviewed_by || '' '' || TO_CHAR(r.reviewed_on, ''DD/MM/YYYY HH24:MI'') END || CASE WHEN r.approved_by IS NOT NULL THEN '' - \0627\0639\062A\0645\062F\0647 '' || r.approved_by || '' '' || TO_CHAR(r.approved_on, ''DD/MM/YYYY HH24:MI'') END);'),
'  :P70_ADJ_TYPE      := r.adj_type;',
'  :P70_ADJ_NO        := r.adj_no;',
'  :P70_ADJ_DATE      := TO_CHAR(r.adj_date, ''DD/MM/YYYY'');',
'  :P70_PAY_PERIOD    := r.pay_period;',
'  :P70_ALLOWANCE_ID  := r.allowance_id;',
'  :P70_CURRENCY_CODE := r.currency_code;',
'  :P70_EXCHANGE_RATE := r.exchange_rate;',
'  :P70_REASON        := r.reason;',
'  :P70_STATUS        := r.status;',
'END;'))
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'LOAD_HEADER'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':P70_ADJ_ID IS NOT NULL'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>91000000000555
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000556)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_clob_language=>'PLSQL'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P70_ADJ_TYPE IS NULL THEN :P70_ADJ_TYPE := ''DED''; END IF;',
'IF :P70_ADJ_ID IS NULL THEN',
'  IF :P70_STATUS IS NULL THEN :P70_STATUS := ''DRAFT''; END IF;',
'  IF :P70_PAY_PERIOD IS NULL THEN :P70_PAY_PERIOD := TO_CHAR(SYSDATE, ''YYYYMM''); END IF;',
'  IF :P70_ADJ_DATE IS NULL THEN :P70_ADJ_DATE := TO_CHAR(SYSDATE, ''DD/MM/YYYY''); END IF;',
'  IF :P70_CURRENCY_CODE IS NULL THEN SELECT currency_code INTO :P70_CURRENCY_CODE FROM currencies WHERE is_base = ''Y''; :P70_EXCHANGE_RATE := 1; END IF;',
'END IF;',
unistr(':P70_TITLE := CASE :P70_ADJ_TYPE WHEN ''DED'' THEN ''\062E\0635\0645'' WHEN ''DIFF'' THEN ''\0641\0631\0642 \0645\0628\0644\063A'' ELSE ''\062D\0627\0641\0632'' END;')))
,p_process_name=>'DEFAULTS'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000556
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000557)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_clob_language=>'PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_emp   CLOB;',
'  l_lines CLOB;',
'BEGIN',
unistr('  -- \0627\0644\0645\0648\0638\0641\0648\0646 \0627\0644\0641\0639\0651\0627\0644\0648\0646 (\0643\0644 \0627\0644\0634\0631\0643\0627\062A \0644\0644\0645\062F\064A\0631 \0627\0644\0639\0627\0645 \0648HR \0627\0644\0623\0645\060C \0648\0625\0644\0627 \0645\0648\0638\0641\0648 \0634\0631\0643\0629 \0627\0644\0645\0633\062A\062E\062F\0645)'),
'  SELECT JSON_ARRAYAGG(JSON_OBJECT(',
'           ''id''      VALUE e.employee_id,',
'           ''code''    VALUE e.emp_no,',
'           ''name''    VALUE e.name_ar,',
'           ''company'' VALUE c.name_ar,',
'           ''grade''   VALUE g.grade_code)',
'         ORDER BY e.emp_no RETURNING CLOB)',
'  INTO   l_emp',
'  FROM   employees e',
'  JOIN   companies  c ON c.company_id = e.company_id',
'  JOIN   job_grades g ON g.grade_id   = e.grade_id',
'  WHERE  e.is_active = ''Y''',
'  AND    (:G_USER_ROLE IN (''ADMIN'',''ENTRY'',''REVIEWER'',''APPROVER'') AND :G_COMPANY_ID = :G_PARENT_ID',
'          OR e.company_id = :G_COMPANY_ID);',
'',
'  SELECT JSON_ARRAYAGG(JSON_OBJECT(',
'           ''EMPLOYEE_ID'' VALUE l.employee_id, ''DIRECTION'' VALUE l.direction,',
'           ''AMOUNT'' VALUE l.amount, ''NOTES'' VALUE l.notes)',
'         ORDER BY l.line_no RETURNING CLOB)',
'  INTO   l_lines',
'  FROM   payroll_adj_lines l',
'  WHERE  l.adj_id = TO_NUMBER(apex_application.g_x01);',
'',
'  apex_util.prn(''{"employees":'' || COALESCE(l_emp,   TO_CLOB(''[]'')) ||',
'                '',"lines":''     || COALESCE(l_lines, TO_CLOB(''[]'')) || ''}'', FALSE);',
'END;'))
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'INIT_DATA'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000557
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000558)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_clob   CLOB := apex_application.g_clob_01;',
'  l_action VARCHAR2(10) := apex_application.g_x01;',
'  l_errs   apex_t_varchar2 := apex_t_varchar2();',
'',
'  l_id NUMBER; l_type VARCHAR2(5); l_date_s VARCHAR2(20); l_date DATE; l_period VARCHAR2(6);',
'  l_allow NUMBER; l_cur VARCHAR2(3); l_rate NUMBER; l_reason VARCHAR2(500);',
'',
'  l_status VARCHAR2(10); l_no VARCHAR2(30); l_seq NUMBER; l_cnt NUMBER;',
'  l_total NUMBER := 0; l_lines NUMBER := 0; l_parent NUMBER := :G_PARENT_ID;',
'',
'  PROCEDURE err (p VARCHAR2) IS BEGIN l_errs.EXTEND; l_errs(l_errs.COUNT) := p; END;',
'BEGIN',
'  SELECT h.adj_id, h.adj_type, h.adj_date, h.pay_period, h.allowance_id,',
'         h.currency_code, h.exchange_rate, h.reason',
'  INTO   l_id, l_type, l_date_s, l_period, l_allow, l_cur, l_rate, l_reason',
'  FROM   JSON_TABLE(l_clob, ''$.header'' COLUMNS (',
'           adj_id        NUMBER        PATH ''$.ADJ_ID'',',
'           adj_type      VARCHAR2(5)   PATH ''$.ADJ_TYPE'',',
'           adj_date      VARCHAR2(20)  PATH ''$.ADJ_DATE'',',
'           pay_period    VARCHAR2(6)   PATH ''$.PAY_PERIOD'',',
'           allowance_id  NUMBER        PATH ''$.ALLOWANCE_ID'',',
'           currency_code VARCHAR2(3)   PATH ''$.CURRENCY_CODE'',',
'           exchange_rate NUMBER        PATH ''$.EXCHANGE_RATE'',',
'           reason        VARCHAR2(500) PATH ''$.REASON'')) h;',
'',
unistr('  IF l_type NOT IN (''DED'',''DIFF'',''INC'') OR l_type IS NULL THEN err(''\0646\0648\0639 \0627\0644\0645\0633\062A\0646\062F \063A\064A\0631 \0645\0639\0631\0648\0641''); END IF;'),
'  BEGIN l_date := TO_DATE(l_date_s, ''DD/MM/YYYY'');',
unistr('  EXCEPTION WHEN OTHERS THEN err(''\0627\0644\062A\0627\0631\064A\062E \063A\064A\0631 \0635\062D\064A\062D''); END;'),
unistr('  IF l_period IS NULL OR NOT REGEXP_LIKE(l_period, ''^[0-9]{4}(0[1-9]|1[0-2])$'') THEN err(''\0627\062E\062A\0631 \0634\0647\0631 \0627\0644\0631\0627\062A\0628''); END IF;'),
unistr('  IF l_reason IS NULL THEN err(''\0627\0644\0633\0628\0628 \0645\0637\0644\0648\0628''); END IF;'),
unistr('  IF l_cur IS NULL THEN err(''\0627\062E\062A\0631 \0627\0644\0639\0645\0644\0629''); END IF;'),
unistr('  IF NVL(l_rate, 0) <= 0 THEN err(''\0633\0639\0631 \0627\0644\0635\0631\0641 \063A\064A\0631 \0635\062D\064A\062D''); END IF;'),
'  SELECT COUNT(*) INTO l_cnt FROM currencies WHERE currency_code = l_cur AND is_base = ''Y'';',
'  IF l_cnt = 1 THEN l_rate := 1; END IF;',
'',
unistr('  IF :G_USER_ROLE NOT IN (''ADMIN'',''ENTRY'') THEN err(''\0644\064A\0633 \0644\062F\064A\0643 \0635\0644\0627\062D\064A\0629 \0639\0644\0649 \0634\0627\0634\0627\062A \0627\0644\0631\0648\0627\062A\0628''); END IF;'),
'',
'  IF l_id IS NOT NULL THEN',
'    BEGIN',
'      SELECT status, adj_no INTO l_status, l_no FROM payroll_adj WHERE adj_id = l_id FOR UPDATE;',
unistr('      IF l_status NOT IN (''DRAFT'',''RETURNED'') THEN err(''\0627\0644\0645\0633\062A\0646\062F '' || l_no || '' \062A\0645\062A \0645\0631\0627\062C\0639\062A\0647 \0623\0648 \0627\0639\062A\0645\0627\062F\0647 \0648\0644\0627 \064A\0645\0643\0646 \062A\0639\062F\064A\0644\0647''); END IF;'),
unistr('    EXCEPTION WHEN NO_DATA_FOUND THEN err(''\0627\0644\0645\0633\062A\0646\062F \063A\064A\0631 \0645\0648\062C\0648\062F''); END;'),
'  ELSIF l_action = ''CANCEL'' THEN',
unistr('    err(''\0644\0627 \064A\0648\062C\062F \0645\0633\062A\0646\062F \0645\062D\0641\0648\0638 \0644\0625\0644\063A\0627\0626\0647'');'),
'  END IF;',
'',
unistr('  -- \0644\0627 \064A\064F\0642\0628\0644 \0645\0633\062A\0646\062F \0644\0634\0647\0631 \0631\0648\0627\062A\0628 \0633\0628\0642 \062A\0634\063A\064A\0644\0647'),
unistr('  -- (\064A\064F\0641\0639\064E\0651\0644 \0628\0639\062F \0625\0646\0634\0627\0621 \062C\062F\0648\0644 payroll_runs \0641\064A \0645\0631\062D\0644\0629 \0627\0644\0631\0648\0627\062A\0628)'),
'',
'  IF l_action <> ''CANCEL'' THEN',
'    FOR r IN (SELECT * FROM JSON_TABLE(l_clob, ''$.lines[*]'' COLUMNS (',
'                 line_no NUMBER PATH ''$.LINE_NO'', employee_id NUMBER PATH ''$.EMPLOYEE_ID'',',
'                 direction VARCHAR2(1) PATH ''$.DIRECTION'', amount NUMBER PATH ''$.AMOUNT''))) LOOP',
'      l_lines := l_lines + 1;',
'      SELECT COUNT(*) INTO l_cnt FROM employees WHERE employee_id = r.employee_id AND is_active = ''Y'';',
unistr('      IF l_cnt = 0 THEN err(''\0627\0644\0633\0637\0631 '' || r.line_no || '': \0627\0644\0645\0648\0638\0641 \063A\064A\0631 \0645\0648\062C\0648\062F \0623\0648 \063A\064A\0631 \0641\0639\0651\0627\0644''); END IF;'),
unistr('      IF NVL(r.amount, 0) <= 0 THEN err(''\0627\0644\0633\0637\0631 '' || r.line_no || '': \0627\0644\0645\0628\0644\063A \064A\062C\0628 \0623\0646 \064A\0643\0648\0646 \0623\0643\0628\0631 \0645\0646 \0635\0641\0631''); END IF;'),
'      IF l_type = ''DIFF'' AND NVL(r.direction, ''x'') NOT IN (''+'',''-'') THEN',
unistr('        err(''\0627\0644\0633\0637\0631 '' || r.line_no || '': \0627\062E\062A\0631 \0627\0644\0625\0634\0627\0631\0629 (+ \0623\0648 -)'');'),
'      END IF;',
'      l_total := l_total + NVL(r.amount, 0);',
'    END LOOP;',
unistr('    IF l_lines = 0 THEN err(''\0623\062F\062E\0644 \0645\0648\0638\0641\0627\064B \0648\0627\062D\062F\0627\064B \0639\0644\0649 \0627\0644\0623\0642\0644''); END IF;'),
'',
unistr('    -- \0644\0627 \064A\062A\0643\0631\0631 \0627\0644\0645\0648\0638\0641 \0641\064A \0646\0641\0633 \0627\0644\0645\0633\062A\0646\062F'),
'    SELECT COUNT(*) INTO l_cnt FROM (',
'      SELECT employee_id FROM JSON_TABLE(l_clob, ''$.lines[*]'' COLUMNS (employee_id NUMBER PATH ''$.EMPLOYEE_ID''))',
'      GROUP BY employee_id HAVING COUNT(*) > 1);',
unistr('    IF l_cnt > 0 THEN err(''\064A\0648\062C\062F \0645\0648\0638\0641 \0645\0643\0631\0631 \0641\064A \0627\0644\0645\0633\062A\0646\062F''); END IF;'),
'  END IF;',
'',
'  IF l_errs.COUNT > 0 THEN',
'    ROLLBACK;',
'    apex_json.open_object; apex_json.write(''ok'', FALSE); apex_json.write(''errors'', l_errs); apex_json.close_object;',
'    RETURN;',
'  END IF;',
'',
'  IF l_action = ''CANCEL'' THEN',
'    UPDATE payroll_adj SET status = ''CANCELLED'' WHERE adj_id = l_id;',
'  ELSE',
'    IF l_id IS NULL THEN',
'      UPDATE doc_sequences SET last_no = last_no + 1',
'      WHERE company_id = l_parent AND doc_type = l_type AND fy_year = EXTRACT(YEAR FROM l_date)',
'      RETURNING last_no INTO l_seq;',
'      IF SQL%ROWCOUNT = 0 THEN',
'        INSERT INTO doc_sequences (company_id, doc_type, fy_year, last_no) VALUES (l_parent, l_type, EXTRACT(YEAR FROM l_date), 1);',
'        l_seq := 1;',
'      END IF;',
'      l_no := l_type || ''-'' || EXTRACT(YEAR FROM l_date) || ''-'' || LPAD(l_seq, 5, ''0'');',
'',
'      INSERT INTO payroll_adj (adj_type, adj_no, adj_date, pay_period, allowance_id,',
'                               currency_code, exchange_rate, reason, created_by)',
'      VALUES (l_type, l_no, l_date, l_period, l_allow, l_cur, l_rate, l_reason, :APP_USER)',
'      RETURNING adj_id INTO l_id;',
'    ELSE',
'      UPDATE payroll_adj',
'      SET adj_date = l_date, pay_period = l_period, allowance_id = l_allow,',
'          currency_code = l_cur, exchange_rate = l_rate, reason = l_reason',
'      WHERE adj_id = l_id;',
'      DELETE FROM payroll_adj_lines WHERE adj_id = l_id;',
'    END IF;',
'',
unistr('    -- \0627\0644\0634\0631\0643\0629 \062A\0624\062E\0630 \0645\0646 \0628\064A\0627\0646\0627\062A \0627\0644\0645\0648\0638\0641 \0627\0644\062D\0627\0644\064A\0629\060C \0648\0627\0644\0625\0634\0627\0631\0629 \062A\064F\0641\0631\0636 \062D\0633\0628 \0627\0644\0646\0648\0639'),
'    INSERT INTO payroll_adj_lines (adj_id, line_no, employee_id, company_id, direction, amount, notes)',
'    SELECT l_id, ROWNUM, j.employee_id, e.company_id,',
'           CASE l_type WHEN ''DED'' THEN ''-'' WHEN ''INC'' THEN ''+'' ELSE j.direction END,',
'           j.amount, j.notes',
'    FROM   JSON_TABLE(l_clob, ''$.lines[*]'' COLUMNS (',
'             employee_id NUMBER PATH ''$.EMPLOYEE_ID'', direction VARCHAR2(1) PATH ''$.DIRECTION'',',
'             amount NUMBER PATH ''$.AMOUNT'', notes VARCHAR2(300) PATH ''$.NOTES'')) j',
'    JOIN   employees e ON e.employee_id = j.employee_id;',
'',
'    UPDATE payroll_adj',
'    SET total_amount = l_total,',
'        status = ''DRAFT'', return_note = NULL',
'    WHERE adj_id = l_id;',
'  END IF;',
'',
'  apex_json.open_object;',
'  apex_json.write(''ok'', TRUE); apex_json.write(''id'', l_id); apex_json.write(''no'', l_no);',
unistr('  apex_json.write(''message'', CASE l_action WHEN ''APPROVE'' THEN ''\062A\0645 \0627\0639\062A\0645\0627\062F \0627\0644\0645\0633\062A\0646\062F '''),
unistr('                                           WHEN ''CANCEL''  THEN ''\062A\0645 \0625\0644\063A\0627\0621 \0627\0644\0645\0633\062A\0646\062F '''),
unistr('                                           ELSE ''\062A\0645 \062D\0641\0638 \0627\0644\0645\0633\062A\0646\062F '' END || l_no);'),
'  apex_json.close_object;',
'EXCEPTION WHEN OTHERS THEN',
'  ROLLBACK;',
'  apex_json.open_object; apex_json.write(''ok'', FALSE);',
'  apex_json.open_array(''errors''); apex_json.write(SQLERRM); apex_json.close_array;',
'  apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_name=>'SAVE_DOC'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000558
);
