,p_plug_display_sequence=>10
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT a.adj_id, a.adj_type AS adj_type_code,',
unistr('       DECODE(a.adj_type,''DED'',''\062E\0635\0645'',''DIFF'',''\0641\0631\0642 \0645\0628\0644\063A'',''INC'',''\062D\0627\0641\0632'') AS "\0627\0644\0646\0648\0639",'),
unistr('       a.adj_no AS "\0627\0644\0631\0642\0645", a.adj_date AS "\0627\0644\062A\0627\0631\064A\062E",'),
unistr('       SUBSTR(a.pay_period,1,4) || ''-'' || SUBSTR(a.pay_period,5,2) AS "\0634\0647\0631 \0627\0644\0631\0627\062A\0628",'),
unistr('       t.name_ar AS "\0627\0644\0628\0646\062F", a.total_amount AS "\0627\0644\0625\062C\0645\0627\0644\064A", a.currency_code AS "\0627\0644\0639\0645\0644\0629",'),
unistr('       a.reason AS "\0627\0644\0633\0628\0628",'),
unistr('       DECODE(a.status,''DRAFT'',''\0645\0633\0648\062F\0629'',''APPROVED'',''\0645\0639\062A\0645\062F'',''APPLIED'',''\0645\0637\0628\064E\0651\0642'',''CANCELLED'',''\0645\0644\063A\0649'') AS "\0627\0644\062D\0627\0644\0629",'),
unistr('       a.created_by AS "\0623\0646\0634\0623\0647", a.approved_by AS "\0627\0639\062A\0645\062F\0647"'),
'FROM   payroll_adj a',
'LEFT JOIN allowance_types t ON t.allowance_id = a.allowance_id'))
,p_prn_page_header=>unistr('\0627\0644\0645\0633\062A\0646\062F\0627\062A')
,p_plug_source_type=>'NATIVE_IR'
,p_query_type=>'SQL'
);
