wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(91000000000579)
,p_plug_name=>unistr('\0627\0644\0635\0627\0641\064A \062D\0633\0628 \0627\0644\0645\0648\0638\0641')
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(6697232433757451)
,p_plug_display_sequence=>30
,p_location=>null
,p_plug_source_type=>'NATIVE_PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_ctx  apex_exec.t_context;',
'  l_col  apex_exec.t_column;',
'  l_val  VARCHAR2(4000);',
'BEGIN',
'  l_ctx := apex_exec.open_query_context(',
'             p_location  => apex_exec.c_location_local_db,',
unistr('             p_sql_query => q''~SELECT c.name_ar  AS "\0627\0644\0634\0631\0643\0629",'),
unistr('       e.emp_no   AS "\0631\0642\0645 \0627\0644\0645\0648\0638\0641",'),
unistr('       e.name_ar  AS "\0627\0644\0645\0648\0638\0641",'),
unistr('       g.name_ar  AS "\0627\0644\062F\0631\062C\0629",'),
unistr('       a.pay_period AS "\0627\0644\0634\0647\0631",'),
unistr('       SUM(CASE WHEN a.adj_type = ''INC''  THEN l.amount * a.exchange_rate ELSE 0 END) AS "\0627\0644\062D\0648\0627\0641\0632",'),
unistr('       SUM(CASE WHEN a.adj_type = ''DED''  THEN l.amount * a.exchange_rate ELSE 0 END) AS "\0627\0644\062E\0635\0648\0645\0627\062A",'),
unistr('       SUM(CASE WHEN a.adj_type = ''DIFF'' THEN DECODE(l.direction,''+'',1,-1) * l.amount * a.exchange_rate ELSE 0 END) AS "\0627\0644\0641\0631\0648\0642\0627\062A",'),
unistr('       SUM(DECODE(l.direction,''+'',1,-1) * l.amount * a.exchange_rate) AS "\0627\0644\0635\0627\0641\064A (\0628\0627\0644\0639\0645\0644\0629 \0627\0644\0623\0633\0627\0633\064A\0629)"'),
'FROM   payroll_adj a',
'JOIN   payroll_adj_lines l ON l.adj_id = a.adj_id',
'JOIN   employees  e ON e.employee_id = l.employee_id',
'JOIN   job_grades g ON g.grade_id    = e.grade_id',
'JOIN   companies  c ON c.company_id  = l.company_id',
'WHERE  a.status IN (''APPROVED'',''APPLIED'')',
'AND    (:P71_PERIOD  IS NULL OR a.pay_period = :P71_PERIOD)',
'AND    (:P71_COMPANY IS NULL OR l.company_id = :P71_COMPANY)',
'GROUP  BY c.name_ar, e.emp_no, e.name_ar, g.name_ar, a.pay_period',
'ORDER  BY c.name_ar, e.emp_no',
'~'');',
'  htp.p(''<div style="overflow-x:auto"><table class="jl-table"><thead><tr>'');',
'  FOR i IN 1 .. apex_exec.get_column_count(l_ctx) LOOP',
'    l_col := apex_exec.get_column(l_ctx, i);',
unistr('    IF l_col.name NOT LIKE ''%\005C_ID'' ESCAPE ''\005C'' AND l_col.name <> ''SORT_KEY'' THEN'),
'      htp.p(''<th>'' || apex_escape.html(l_col.name) || ''</th>'');',
'    END IF;',
'  END LOOP;',
'  htp.p(''</tr></thead><tbody>'');',
'  WHILE apex_exec.next_row(l_ctx) LOOP',
'    htp.p(''<tr>'');',
'    FOR i IN 1 .. apex_exec.get_column_count(l_ctx) LOOP',
'      l_col := apex_exec.get_column(l_ctx, i);',
unistr('      IF l_col.name NOT LIKE ''%\005C_ID'' ESCAPE ''\005C'' AND l_col.name <> ''SORT_KEY'' THEN'),
'        IF l_col.data_type = apex_exec.c_data_type_number THEN',
unistr('          l_val := TO_CHAR(apex_exec.get_number(l_ctx, i), CASE WHEN l_col.name LIKE ''\0639\062F\062F%'' THEN ''FM999G999G990'' ELSE ''FM999G999G999G999G990D00'' END);'),
'          htp.p(''<td class="jl-num">'' || l_val || ''</td>'');',
'        ELSE',
'          htp.p(''<td>'' || apex_escape.html(apex_exec.get_varchar2(l_ctx, i)) || ''</td>'');',
'        END IF;',
'      END IF;',
'    END LOOP;',
'    htp.p(''</tr>'');',
'  END LOOP;',
'  htp.p(''</tbody></table></div>'');',
'  apex_exec.close(l_ctx);',
'EXCEPTION WHEN OTHERS THEN',
'  apex_exec.close(l_ctx);',
'  RAISE;',
'END;'))
);
end;
/
