wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(91000000000614)
,p_plug_name=>unistr('\0643\0634\0641 \0627\0644\062D\0633\0627\0628')
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(6687458349757443)
,p_plug_display_sequence=>10
,p_plug_display_condition_type=>'EXPRESSION'
,p_plug_display_when_condition=>':P81_ACCOUNT_ID IS NOT NULL'
,p_plug_display_when_cond2=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH acc AS (',
unistr('  -- \0627\0644\062D\0633\0627\0628 \0627\0644\0645\062E\062A\0627\0631 \0648\0643\0644 \0645\0627 \062A\062D\062A\0647 \0645\0646 \062D\0633\0627\0628\0627\062A \062A\062D\0644\064A\0644\064A\0629'),
'  SELECT d.account_id FROM accounts d, accounts p',
'  WHERE  p.account_id = :P81_ACCOUNT_ID',
'  AND    d.account_code LIKE p.account_code || ''%'' AND d.acc_level = 4',
'),',
'rows_ AS (',
unistr('  -- \0627\0644\0642\064A\0648\062F \0627\0644\0645\0631\062D\0651\0644\0629 \0641\0642\0637 (\0627\0644\0642\064A\062F \0627\0644\0645\0639\0643\0648\0633 \0648\0642\064A\062F \0639\0643\0633\0647 \064A\0638\0647\0631\0627\0646 \0645\0639\0627\064B \0641\064A\062A\0635\0641\0651\0631\0627\0646)'),
'  SELECT j.journal_date, j.journal_no, t.name_ar jt_name, j.journal_id, l.line_id,',
'         NVL(l.description, j.description) description, j.currency_code,',
'         CASE WHEN :P81_CURRENCY IS NULL THEN l.debit_base  ELSE l.debit  END dr,',
'         CASE WHEN :P81_CURRENCY IS NULL THEN l.credit_base ELSE l.credit END cr',
'  FROM   journals j',
'  JOIN   journal_lines l ON l.journal_id = j.journal_id',
'  JOIN   journal_types t ON t.jt_code    = j.jt_code',
'  WHERE  l.account_id IN (SELECT account_id FROM acc)',
'  AND    j.status IN (''POSTED'',''REVERSED'')',
'  AND    (:P81_CURRENCY IS NULL OR j.currency_code = :P81_CURRENCY)',
'),',
'opening AS (',
'  SELECT NVL(SUM(dr - cr), 0) bal FROM rows_ WHERE journal_date < TO_DATE(:P81_FROM, ''DD/MM/YYYY'')',
'),',
'period AS (',
'  SELECT r.*,',
'         (SELECT bal FROM opening)',
'         + SUM(dr - cr) OVER (ORDER BY journal_date, journal_id, line_id ROWS UNBOUNDED PRECEDING) run_bal,',
'         ROW_NUMBER() OVER (ORDER BY journal_date, journal_id, line_id) rn',
'  FROM   rows_ r',
'  WHERE  journal_date BETWEEN TO_DATE(:P81_FROM, ''DD/MM/YYYY'') AND TO_DATE(:P81_TO, ''DD/MM/YYYY'')',
')',
unistr('SELECT 0 AS sort_key, NULL AS journal_id, TO_DATE(:P81_FROM, ''DD/MM/YYYY'') AS "\0627\0644\062A\0627\0631\064A\062E", NULL AS "\0631\0642\0645 \0627\0644\0642\064A\062F",'),
unistr('       ''\0631\0635\064A\062F \0623\0648\0644 \0627\0644\0645\062F\0629'' AS "\0627\0644\0646\0648\0639", NULL AS "\0627\0644\0628\064A\0627\0646", NULL AS "\0627\0644\0639\0645\0644\0629",'),
unistr('       GREATEST(o.bal, 0) AS "\0645\062F\064A\0646", GREATEST(-o.bal, 0) AS "\062F\0627\0626\0646",'),
unistr('       ABS(o.bal) AS "\0627\0644\0631\0635\064A\062F", CASE WHEN o.bal > 0 THEN ''\0645\062F\064A\0646'' WHEN o.bal < 0 THEN ''\062F\0627\0626\0646'' END AS "\0637\0628\064A\0639\0629 \0627\0644\0631\0635\064A\062F"'),
'FROM   opening o',
'UNION ALL',
'SELECT p.rn, p.journal_id, p.journal_date, p.journal_no, p.jt_name, p.description, p.currency_code,',
'       p.dr, p.cr,',
unistr('       ABS(p.run_bal), CASE WHEN p.run_bal > 0 THEN ''\0645\062F\064A\0646'' WHEN p.run_bal < 0 THEN ''\062F\0627\0626\0646'' END'),
'FROM   period p',
'UNION ALL',
unistr('SELECT 999999999, NULL, TO_DATE(:P81_TO, ''DD/MM/YYYY''), NULL, ''\0625\062C\0645\0627\0644\064A \0627\0644\062D\0631\0643\0629 \0648\0627\0644\0631\0635\064A\062F \0627\0644\062E\062A\0627\0645\064A'', NULL, NULL,'),
'       NVL((SELECT SUM(dr) FROM period), 0), NVL((SELECT SUM(cr) FROM period), 0),',
'       ABS(o.bal + NVL((SELECT SUM(dr - cr) FROM period), 0)),',
unistr('       CASE WHEN o.bal + NVL((SELECT SUM(dr - cr) FROM period), 0) > 0 THEN ''\0645\062F\064A\0646'''),
unistr('            WHEN o.bal + NVL((SELECT SUM(dr - cr) FROM period), 0) < 0 THEN ''\062F\0627\0626\0646'' END'),
'FROM   opening o',
'ORDER  BY 1'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>unistr('\0643\0634\0641 \0627\0644\062D\0633\0627\0628')
,p_query_type=>'SQL'
);
