,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P81_FROM IS NULL THEN :P81_FROM := TO_CHAR(TRUNC(SYSDATE,''YYYY''), ''DD/MM/YYYY''); END IF;',
'IF :P81_TO IS NULL THEN :P81_TO := TO_CHAR(SYSDATE, ''DD/MM/YYYY''); END IF;',
'IF :P81_ACCOUNT_ID IS NOT NULL THEN',
unistr('  SELECT MAX(''\0643\0634\0641 \062D\0633\0627\0628: '' || account_code || '' - '' || name_ar || '' ('' || DECODE(acc_type, ''ASSET'', ''\0623\0635\0648\0644'', ''LIAB'', ''\062E\0635\0648\0645'', ''EQUITY'', ''\062D\0642\0648\0642 \0645\0644\0643\064A\0629'', ''REV'', ''\0625\064A\0631\0627\062F\0627\062A'', ''EXP'', ''\0645\0635\0631\0648\0641\0627\062A'') || '')'''),
unistr('         || '' \0645\0646 '' || :P81_FROM || '' \0625\0644\0649 '' || :P81_TO)'),
'  INTO :P81_ACC_INFO FROM accounts WHERE account_id = :P81_ACCOUNT_ID;',
'END IF;'))
