,p_process_clob_language=>'PLSQL'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_err VARCHAR2(4000);',
'FUNCTION chk RETURN VARCHAR2 IS',
' l_f DATE; l_t DATE;',
'BEGIN',
unistr('  IF :P81_ACCOUNT_ID IS NULL THEN RETURN ''\0627\062E\062A\0631 \0627\0644\062D\0633\0627\0628''; END IF;'),
'  l_f := TO_DATE(:P81_FROM, ''DD/MM/YYYY''); l_t := TO_DATE(:P81_TO, ''DD/MM/YYYY'');',
unistr('  IF l_f > l_t THEN RETURN ''\062A\0627\0631\064A\062E \0627\0644\0628\062F\0627\064A\0629 \0628\0639\062F \062A\0627\0631\064A\062E \0627\0644\0646\0647\0627\064A\0629''; END IF;'),
'  RETURN NULL;',
unistr('EXCEPTION WHEN OTHERS THEN RETURN ''\0627\0644\062A\0627\0631\064A\062E \063A\064A\0631 \0635\062D\064A\062D (\064A\0648\0645/\0634\0647\0631/\0633\0646\0629)'';'),
'END;',
'BEGIN',
'  l_err := chk;',
'  IF l_err IS NOT NULL THEN',
'    apex_error.add_error(p_message => l_err, p_display_location => apex_error.c_inline_in_notification);',
'  END IF;',
'END;'))
,p_process_name=>'CHECK_DATES'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(91000000000612)
,p_internal_uid=>91000000000629
);
