,p_step_title=>'&P90_TITLE.'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var stk = {',
'  grid: null,',
'',
'  unitsOf: function (row, g) { var it = (g || stk.grid).lovRecord(''items'', row.ITEM_ID); return it ? it.units : []; },',
'  factorOf: function (row) {',
'    var u = stk.unitsOf(row).filter(function (x) { return String(x.v) === String(row.UNIT_ID); })[0];',
'    return u ? u.factor : 1;',
'  },',
'',
'  init: function () {',
'    var type = apex.item(''P90_TRANS_TYPE'').getValue(),',
'        status = apex.item(''P90_STATUS'').getValue() || ''DRAFT'';',
unistr('    // \0627\0644\062A\0643\0644\0641\0629 \0645\0646 \0633\0639\0631 \0634\0631\0627\0621 \0627\0644\0635\0646\0641 \0648\0644\0627 \062A\064F\0639\062F\064E\0651\0644: \0625\0634\0639\0627\0631 \0627\0644\0625\0636\0627\0641\0629 \0648\0627\0644\062A\0648\0627\0644\0641 \0648\062A\0635\0641\064A\0631\0647\0627'),
'    var fixedCost = type === ''OPENING'' || type === ''DAMAGE'' || type === ''DAMAGE_WO'',',
'        showCost  = type === ''RECEIPT'' || fixedCost,',
'        wo        = type === ''DAMAGE_WO'';',
'    stk.type = type;',
'',
'    stk.grid = new JsonLines({',
'      container: ''#st_lines'',',
'      readOnly : !DocUtil.canEdit(status),',
'      columns  : [',
unistr('        {name: ''ITEM_ID'',   label: ''\0627\0644\0635\0646\0641'',  type: ''lov'', lov: ''items'', required: true, width: ''24em''},'),
unistr('        {name: ''UNIT_ID'',   label: ''\0627\0644\0648\062D\062F\0629'', type: ''select'', nullText: false, required: true, options: stk.unitsOf, width: ''8em'', readonly: type === ''OPENING''},'),
unistr('        {name: ''BAL'',       label: wo ? ''\0631\0635\064A\062F \0627\0644\062A\0648\0627\0644\0641'' : ''\0627\0644\0631\0635\064A\062F \0627\0644\062D\0627\0644\064A'', type: ''display'', decimals: 2, noSubmit: true, width: ''8em''},'),
unistr('        {name: ''QTY'',       label: type === ''COUNT'' ? ''\0627\0644\0643\0645\064A\0629 \0627\0644\0641\0639\0644\064A\0629'' : ''\0627\0644\0643\0645\064A\0629'','),
'         type: ''number'', decimals: 2, required: true, width: ''8em''},',
unistr('        {name: ''UNIT_COST'', label: ''\062A\0643\0644\0641\0629 \0627\0644\0648\062D\062F\0629'', type: ''number'', decimals: 4, width: ''9em'', readonly: fixedCost,'),
'         hidden: !showCost},',
unistr('        {name: ''VALUE'',     label: ''\0627\0644\0642\064A\0645\0629'', type: ''display'', decimals: 2, total: true, noSubmit: true,'),
'         hidden: !showCost}',
'      ],',
'      onChange: function (row, col) {',
'        if (col === ''ITEM_ID'') {',
'          var u = stk.unitsOf(row);',
unistr('          // \0625\0634\0639\0627\0631 \0627\0644\0625\0636\0627\0641\0629: \0627\0644\0648\062D\062F\0629 \0627\0644\0643\0628\0631\0649 \0648\0633\0639\0631 \0634\0631\0627\0626\0647\0627 \062A\0644\0642\0627\0626\064A\0627\064B'),
'          row.UNIT_ID = row[''ITEM_ID$unit''] || (u.length ? (type === ''OPENING'' ? u[u.length - 1].v : u[0].v) : null);',
'        }',
'        if (fixedCost && (col === ''ITEM_ID'' || col === ''UNIT_ID'' || !row.UNIT_COST)) {',
'          var uu = stk.unitsOf(row).filter(function (x) { return String(x.v) === String(row.UNIT_ID); })[0];',
'          if (uu && uu.price != null) row.UNIT_COST = uu.price;',
'          if (!row.QTY && row.ITEM_ID) row.QTY = 1;',
'        }',
'        var it = stk.grid.lovRecord(''items'', row.ITEM_ID);',
unistr('        row.BAL = it ? (wo ? it.dmg : it.bal) / stk.factorOf(row) : null;           // \0627\0644\0631\0635\064A\062F \0628\0627\0644\0648\062D\062F\0629 \0627\0644\0645\062E\062A\0627\0631\0629'),
'        row.VALUE = (row.QTY || 0) * (row.UNIT_COST || 0);',
'      }',
'    });',
'    stk.load();',
'    apex.jQuery(''#P90_WAREHOUSE_ID'').on(''change'', stk.load);',
'    apex.jQuery(''#P90_CURRENCY_CODE, #P90_TRANS_DATE'').on(''change'', function () {',
'      DocUtil.loadRate(''P90_CURRENCY_CODE'', ''P90_TRANS_DATE'', ''P90_EXCHANGE_RATE'');',
'    });',
'    document.addEventListener(''keydown'', function (e) {',
'      if (e.ctrlKey && (e.key === ''s'' || e.key === ''S'')) { e.preventDefault(); stk.save(''DRAFT''); }',
'    });',
'    EnterNav.first(''#main'');',
'  },',
'',
'  load: function () {',
'    var keep = stk.grid.getData();',
'    apex.server.process(''INIT_DATA'', {',
'      x01: apex.item(''P90_WAREHOUSE_ID'').getValue(), x02: apex.item(''P90_TRANS_ID'').getValue(),',
