'    }, {dataType: ''json''}).done(function (d) {',
'      stk.grid.setLov(''items'', d.items);',
unistr('      // \062A\0635\0641\064A\0631 \062A\0648\0627\0644\0641 \062C\062F\064A\062F: \0627\0644\0633\0637\0648\0631 \062A\064F\0639\0627\062F \0645\0646 \0631\0635\064A\062F \0627\0644\062A\0648\0627\0644\0641 \0639\0646\062F \062A\063A\064A\064A\0631 \0627\0644\0645\062E\0632\0646'),
'      var rows = (stk.type === ''DAMAGE_WO'' && !apex.item(''P90_TRANS_ID'').getValue()) ? d.lines : (keep.length ? keep : d.lines);',
'      rows.forEach(function (r) { stk.grid.opts.onChange(r, ''QTY'', stk.grid); });',
'      stk.grid.setData(rows);',
'    });',
'  },',
'',
'  print: function () {',
'    window.open(apex.util.makeApplicationUrl({pageId: 95, itemNames: [''P95_TRANS_ID''],',
'      itemValues: [apex.item(''P90_TRANS_ID'').getValue()]}), ''print'', ''width=900,height=1000'');',
'  },',
'',
'  save: function (action) {',
'    var errs = stk.grid.validate();',
unistr('    if (!apex.item(''P90_WAREHOUSE_ID'').getValue()) errs.unshift(''\0627\062E\062A\0631 \0627\0644\0645\062E\0632\0646'');'),
'    if (errs.length) { DocUtil.showErrors(errs); return; }',
'    var g = function (n) { return apex.item(''P90_'' + n).getValue(); };',
'    var doc = {',
'      header: {TRANS_ID: g(''TRANS_ID''), TRANS_TYPE: g(''TRANS_TYPE''), COMPANY_ID: g(''COMPANY_ID''),',
'               TRANS_DATE: g(''TRANS_DATE''), WAREHOUSE_ID: g(''WAREHOUSE_ID''), TO_WAREHOUSE_ID: g(''TO_WAREHOUSE_ID''),',
'               COUNTER_ACCOUNT_ID: g(''COUNTER_ACCOUNT_ID''), CURRENCY_CODE: g(''CURRENCY_CODE''),',
'               EXCHANGE_RATE: g(''EXCHANGE_RATE''), DESCRIPTION: g(''DESCRIPTION'')},',
'      lines: stk.grid.getData()',
'    };',
'    var go = function () {',
'      DocUtil.save(doc, action, function (d) {',
'        apex.page.submit({request: ''RELOAD'', set: {P90_TRANS_ID: d.id}, showWait: true});',
'      });',
'    };',
unistr('    if (action === ''POST'') apex.message.confirm(''\062A\0631\062D\064A\0644 \0627\0644\062D\0631\0643\0629\061F'', function (ok) { if (ok) go(); }); else go();'),
'  }',
'};'))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
