wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000657)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE t stock_trans%ROWTYPE; r stock_trans%ROWTYPE;',
'BEGIN',
'  SELECT * INTO t FROM stock_trans WHERE trans_id = :P90_TRANS_ID;',
'  r := t;',
'  :P90_RETURN_NOTE := CASE WHEN r.status IN (''RETURNED'',''DRAFT'') THEN r.return_note END;',
unistr(':P90_WF_INFO := TRIM(CASE WHEN r.reviewed_by IS NOT NULL THEN ''\0631\0627\062C\0639\0647 '' || r.reviewed_by || '' '' || TO_CHAR(r.reviewed_on, ''DD/MM/YYYY HH24:MI'') END || CASE WHEN r.approved_by IS NOT NULL THEN '' - \0627\0639\062A\0645\062F\0647 '' || r.approved_by || '' '' || TO_CHAR(r.approved_on, ''DD/MM/YYYY HH24:MI'') END);'),
'  IF NOT (:G_USER_ROLE = ''ADMIN'' OR t.company_id = :G_COMPANY_ID) THEN',
unistr('    raise_application_error(-20001, ''\0644\064A\0633 \0644\062F\064A\0643 \0635\0644\0627\062D\064A\0629 \0639\0644\0649 \0647\0630\0647 \0627\0644\062D\0631\0643\0629'');'),
'  END IF;',
'  :P90_TRANS_TYPE := t.trans_type; :P90_TRANS_NO := t.trans_no; :P90_COMPANY_ID := t.company_id;',
'  :P90_TRANS_DATE := TO_CHAR(t.trans_date, ''DD/MM/YYYY''); :P90_WAREHOUSE_ID := t.warehouse_id;',
'  :P90_TO_WAREHOUSE_ID := t.to_warehouse_id; :P90_COUNTER_ACCOUNT_ID := t.counter_account_id;',
'  :P90_CURRENCY_CODE := t.currency_code; :P90_EXCHANGE_RATE := t.exchange_rate;',
'  :P90_DESCRIPTION := t.description; :P90_STATUS := t.status;',
'END;'))
,p_process_type=>'NATIVE_PLSQL'
,p_process_clob_language=>'PLSQL'
,p_process_name=>'LOAD_HEADER'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':P90_TRANS_ID IS NOT NULL'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>91000000000657
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000658)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_clob_language=>'PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P90_TRANS_TYPE IS NULL THEN :P90_TRANS_TYPE := ''RECEIPT''; END IF;',
'IF :P90_TRANS_ID IS NULL THEN',
'  IF :P90_COMPANY_ID IS NULL THEN :P90_COMPANY_ID := :G_COMPANY_ID; END IF;',
'  IF :P90_STATUS IS NULL THEN :P90_STATUS := ''DRAFT''; END IF;',
'  IF :P90_TRANS_DATE IS NULL THEN :P90_TRANS_DATE := TO_CHAR(SYSDATE, ''DD/MM/YYYY''); END IF;',
'  IF :P90_CURRENCY_CODE IS NULL THEN SELECT currency_code INTO :P90_CURRENCY_CODE FROM currencies WHERE is_base = ''Y''; :P90_EXCHANGE_RATE := 1; END IF;',
'END IF;',
unistr(':P90_TITLE := CASE :P90_TRANS_TYPE WHEN ''RECEIPT'' THEN ''\0627\0633\062A\0644\0627\0645 \0628\0636\0627\0639\0629'' WHEN ''ISSUE'' THEN ''\0635\0631\0641 \062F\0627\062E\0644\064A'' WHEN ''TRANSFER'' THEN ''\062A\062D\0648\064A\0644 \0628\064A\0646 \0627\0644\0645\062E\0627\0632\0646'' WHEN ''COUNT'' THEN ''\062A\0633\0648\064A\0629 \062C\0631\062F'' WHEN ''OPENING'' THEN ''\0625\0634\0639\0627\0631 \0625\0636\0627\0641\0629 - \0628\0636\0627\0639\0629 \0623\0648\0644 \0627\0644\0645\062F\0629'' WHEN ''DAMAGE'' THEN ''\0641\0627\062A\0648\0631\0629 \0635\0631\0641 \062A\0648\0627\0644\0641'' WHEN ''DAMAGE_WO'' THEN ''\062A\0635\0641\064A\0631 \0627\0644\062A\0648\0627\0644\0641 - \0642\0631\0627\0631 \0627\0644\0645\062F\064A\0631'' ELSE ''\062D\0631\0643\0629 \0645\062E\0632\0648\0646'' END;')))
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'DEFAULTS'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000658
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000659)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_items CLOB; l_lines CLOB;',
'  l_wh NUMBER := TO_NUMBER(apex_application.g_x01);',
'  l_tid NUMBER := TO_NUMBER(apex_application.g_x02);',
'  l_type VARCHAR2(10) := apex_application.g_x03;',
'BEGIN',
'  SELECT JSON_ARRAYAGG(JSON_OBJECT(',
'           ''id'' VALUE i.item_id, ''code'' VALUE i.item_code, ''name'' VALUE i.name_ar,',
'           ''bc0'' VALUE i.barcode, ''bu'' VALUE i.base_unit_id,',
'           ''bc'' VALUE (SELECT JSON_OBJECTAGG(KEY ub.barcode VALUE ub.unit_id) FROM item_units ub WHERE ub.item_id = i.item_id AND ub.barcode IS NOT NULL) FORMAT JSON,',
'           ''bal''  VALUE NVL(b.qty_base, 0),',
'           ''cost'' VALUE NVL(b.avg_cost, 0),',
unistr('           ''dmg''  VALUE NVL(d.qty_base, 0),                       -- \0631\0635\064A\062F \0627\0644\062A\0648\0627\0644\0641 \063A\064A\0631 \0627\0644\0645\0635\0641\0651\0631'),
'           ''units'' VALUE (SELECT JSON_ARRAYAGG(JSON_OBJECT(''v'' VALUE u.unit_id, ''t'' VALUE un.name_ar,',
'                                                           ''factor'' VALUE u.factor, ''price'' VALUE CASE WHEN u.unit_id = i.big_unit_id AND i.big_purchase_price > 0 THEN i.big_purchase_price ELSE NULLIF(i.purchase_price, 0) * u.factor END) ORDER BY u.factor)',
'                          FROM item_units u JOIN units un ON un.unit_id = u.unit_id',
'                          WHERE u.item_id = i.item_id) FORMAT JSON',
'         ) ORDER BY i.item_code RETURNING CLOB)',
'  INTO   l_items',
'  FROM   items i',
'  LEFT JOIN v_stock_balance b ON b.item_id = i.item_id AND b.warehouse_id = l_wh',
'  LEFT JOIN v_damaged_balance d ON d.item_id = i.item_id AND d.warehouse_id = l_wh',
'  WHERE  i.is_active = ''Y'';',
'',
'  SELECT JSON_ARRAYAGG(JSON_OBJECT(''ITEM_ID'' VALUE item_id, ''UNIT_ID'' VALUE unit_id,',
'                                   ''QTY'' VALUE qty, ''UNIT_COST'' VALUE NULLIF(unit_cost, 0))',
'                       ORDER BY line_no RETURNING CLOB)',
'  INTO   l_lines',
'  FROM   stock_trans_lines',
'  WHERE  trans_id = TO_NUMBER(apex_application.g_x02)',
unistr('  AND    (warehouse_id = l_wh OR l_wh IS NULL)          -- \0641\064A \0627\0644\062A\062D\0648\064A\0644: \0633\0637\0648\0631 \0627\0644\0645\0635\062F\0631 \0641\0642\0637'),
'  AND    (qty_base < 0 OR (SELECT trans_type FROM stock_trans WHERE trans_id = TO_NUMBER(apex_application.g_x02)) <> ''TRANSFER'');',
'',
unistr('  -- \062A\0635\0641\064A\0631 \062A\0648\0627\0644\0641 \062C\062F\064A\062F: \0627\0644\0633\0637\0648\0631 = \0631\0635\064A\062F \0627\0644\062A\0648\0627\0644\0641 \063A\064A\0631 \0627\0644\0645\0635\0641\0651\0631 \0641\064A \0627\0644\0645\062E\0632\0646 \0628\0627\0644\0648\062D\062F\0629 \0627\0644\0635\063A\0631\0649'),
'  IF l_type = ''DAMAGE_WO'' AND l_tid IS NULL AND l_wh IS NOT NULL THEN',
'    SELECT JSON_ARRAYAGG(JSON_OBJECT(''ITEM_ID'' VALUE d.item_id, ''UNIT_ID'' VALUE i.base_unit_id, ''QTY'' VALUE d.qty_base)',
'                         ORDER BY i.item_code RETURNING CLOB)',
'    INTO   l_lines',
'    FROM   v_damaged_balance d JOIN items i ON i.item_id = d.item_id',
'    WHERE  d.warehouse_id = l_wh AND d.qty_base > 0;',
'  END IF;',
'',
'  apex_util.prn(''{"items":'' || COALESCE(l_items, TO_CLOB(''[]'')) ||',
'                '',"lines":'' || COALESCE(l_lines, TO_CLOB(''[]'')) || ''}'', FALSE);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_name=>'INIT_DATA'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000659
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000660)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_clob_language=>'PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_clob   CLOB := apex_application.g_clob_01;',
'  l_action VARCHAR2(10) := apex_application.g_x01;',
'  l_errs   apex_t_varchar2 := apex_t_varchar2();',
'',
'  l_id NUMBER; l_type VARCHAR2(10); l_company NUMBER; l_date_s VARCHAR2(20); l_date DATE;',
'  l_wh NUMBER; l_to_wh NUMBER; l_counter NUMBER; l_cur VARCHAR2(3); l_rate NUMBER; l_desc VARCHAR2(500);',
'  l_base_cur VARCHAR2(3);',
'',
'  l_status VARCHAR2(10); l_no VARCHAR2(30); l_seq NUMBER; l_cnt NUMBER; l_lines NUMBER := 0;',
'  l_jid NUMBER; l_val NUMBER; l_inv NUMBER; l_adj NUMBER;',
'',
'  PROCEDURE err (p VARCHAR2) IS BEGIN l_errs.EXTEND; l_errs(l_errs.COUNT) := p; END;',
'',
'  FUNCTION setting (p_code VARCHAR2) RETURN NUMBER IS l NUMBER;',
'  BEGIN',
'    SELECT account_id INTO l FROM account_settings WHERE company_id = l_company AND setting_code = p_code;',
'    RETURN l;',
'  EXCEPTION WHEN NO_DATA_FOUND THEN',
unistr('    raise_application_error(-20010, ''\0644\0645 \064A\064F\0639\0631\064E\0651\0641 \0627\0644\062D\0633\0627\0628 \0627\0644\0627\0641\062A\0631\0627\0636\064A '' || p_code);'),
'  END;',
'',
unistr('  PROCEDURE jline (p_no NUMBER, p_acc NUMBER, p_amount NUMBER) IS   -- \0645\0648\062C\0628 = \0645\062F\064A\0646 \060C \0633\0627\0644\0628 = \062F\0627\0626\0646'),
'  BEGIN',
'    IF ROUND(p_amount, 2) = 0 THEN RETURN; END IF;',
'    INSERT INTO journal_lines (journal_id, line_no, account_id, debit, credit, debit_base, credit_base, description)',
'    VALUES (l_jid, p_no, p_acc,',
'            GREATEST(ROUND(p_amount, 2), 0), GREATEST(-ROUND(p_amount, 2), 0),',
'            GREATEST(ROUND(p_amount, 2), 0), GREATEST(-ROUND(p_amount, 2), 0), l_desc);',
'  END;',
'BEGIN',
unistr('  l_action := ''DRAFT'';   -- \0627\0644\062A\0631\062D\064A\0644 \064A\062A\0645 \0639\0646\062F \0627\0644\0627\0639\062A\0645\0627\062F'),
'  SELECT h.trans_id, h.trans_type, h.company_id, h.trans_date, h.warehouse_id, h.to_warehouse_id,',
'         h.counter_account_id, h.currency_code, h.exchange_rate, h.description',
'  INTO   l_id, l_type, l_company, l_date_s, l_wh, l_to_wh, l_counter, l_cur, l_rate, l_desc',
'  FROM   JSON_TABLE(l_clob, ''$.header'' COLUMNS (',
'           trans_id NUMBER PATH ''$.TRANS_ID'', trans_type VARCHAR2(10) PATH ''$.TRANS_TYPE'',',
'           company_id NUMBER PATH ''$.COMPANY_ID'', trans_date VARCHAR2(20) PATH ''$.TRANS_DATE'',',
'           warehouse_id NUMBER PATH ''$.WAREHOUSE_ID'', to_warehouse_id NUMBER PATH ''$.TO_WAREHOUSE_ID'',',
'           counter_account_id NUMBER PATH ''$.COUNTER_ACCOUNT_ID'',',
'           currency_code VARCHAR2(3) PATH ''$.CURRENCY_CODE'', exchange_rate NUMBER PATH ''$.EXCHANGE_RATE'',',
'           description VARCHAR2(500) PATH ''$.DESCRIPTION'')) h;',
'',
'  SELECT currency_code INTO l_base_cur FROM currencies WHERE is_base = ''Y'';',
'  IF l_type NOT IN (''RECEIPT'',''OPENING'') OR l_cur IS NULL THEN l_cur := l_base_cur; l_rate := 1; END IF;',
'  IF l_cur = l_base_cur THEN l_rate := 1; END IF;',
'',
unistr('  IF l_type NOT IN (''RECEIPT'',''ISSUE'',''TRANSFER'',''COUNT'',''OPENING'',''DAMAGE'',''DAMAGE_WO'') OR l_type IS NULL THEN err(''\0646\0648\0639 \0627\0644\062D\0631\0643\0629 \063A\064A\0631 \0635\062D\064A\062D''); END IF;'),
unistr('  -- \062A\0635\0641\064A\0631 \0627\0644\062A\0648\0627\0644\0641 \0628\0642\0631\0627\0631 \0627\0644\0645\062F\064A\0631 \0641\0642\0637'),
unistr('  IF l_type = ''DAMAGE_WO'' AND :G_USER_ROLE <> ''ADMIN'' THEN err(''\062A\0635\0641\064A\0631 \0627\0644\062A\0648\0627\0644\0641 \0645\0646 \0635\0644\0627\062D\064A\0629 \0645\062F\064A\0631 \0627\0644\0646\0638\0627\0645 \0641\0642\0637''); END IF;'),
unistr('  BEGIN l_date := TO_DATE(l_date_s, ''DD/MM/YYYY''); EXCEPTION WHEN OTHERS THEN err(''\0627\0644\062A\0627\0631\064A\062E \063A\064A\0631 \0635\062D\064A\062D''); END;'),
'',
'  SELECT COUNT(*) INTO l_cnt FROM dual',
'  WHERE :G_USER_ROLE = ''ADMIN'' OR l_company = :G_COMPANY_ID',
'     OR EXISTS (SELECT 1 FROM user_companies WHERE user_name = UPPER(:APP_USER) AND company_id = l_company);',
unistr('  IF l_cnt = 0 THEN err(''\0644\064A\0633 \0644\062F\064A\0643 \0635\0644\0627\062D\064A\0629 \0639\0644\0649 \0647\0630\0647 \0627\0644\0634\0631\0643\0629''); END IF;'),
'',
'  SELECT COUNT(*) INTO l_cnt FROM warehouses WHERE warehouse_id = l_wh AND company_id = l_company;',
unistr('  IF l_cnt = 0 THEN err(''\0627\062E\062A\0631 \0645\062E\0632\0646\0627\064B \062A\0627\0628\0639\0627\064B \0644\0644\0634\0631\0643\0629''); END IF;'),
'  IF l_type = ''TRANSFER'' THEN',
'    SELECT COUNT(*) INTO l_cnt FROM warehouses WHERE warehouse_id = l_to_wh AND company_id = l_company;',
unistr('    IF l_cnt = 0 OR l_to_wh = l_wh THEN err(''\0627\062E\062A\0631 \0645\062E\0632\0646 \0627\0644\0648\062C\0647\0629 (\0645\062E\062A\0644\0641 \0639\0646 \0627\0644\0645\0635\062F\0631)''); END IF;'),
'  END IF;',
unistr('  IF l_type IN (''RECEIPT'',''ISSUE'') AND l_counter IS NULL THEN err(''\0627\062E\062A\0631 \0627\0644\062D\0633\0627\0628 \0627\0644\0645\0642\0627\0628\0644''); END IF;'),
unistr('  IF NVL(l_rate, 0) <= 0 THEN err(''\0633\0639\0631 \0627\0644\0635\0631\0641 \063A\064A\0631 \0635\062D\064A\062D''); END IF;'),
'',
'  IF l_date IS NOT NULL THEN',
'    SELECT COUNT(*) INTO l_cnt FROM fiscal_years WHERE l_date BETWEEN start_date AND end_date AND is_closed = ''N'';',
unistr('    IF l_cnt = 0 THEN err(''\0627\0644\062A\0627\0631\064A\062E \062E\0627\0631\062C \0633\0646\0629 \0645\0627\0644\064A\0629 \0645\0641\062A\0648\062D\0629''); END IF;'),
'  END IF;',
'',
'  IF l_id IS NOT NULL THEN',
'    BEGIN',
'      SELECT status, trans_no INTO l_status, l_no FROM stock_trans WHERE trans_id = l_id FOR UPDATE;',
unistr('      IF l_status NOT IN (''DRAFT'',''RETURNED'') THEN err(''\0627\0644\062D\0631\0643\0629 '' || l_no || '' \062A\0645\062A \0645\0631\0627\062C\0639\062A\0647\0627 \0623\0648 \0627\0639\062A\0645\0627\062F\0647\0627 \0648\0644\0627 \064A\0645\0643\0646 \062A\0639\062F\064A\0644\0647\0627''); END IF;'),
unistr('    EXCEPTION WHEN NO_DATA_FOUND THEN err(''\0627\0644\062D\0631\0643\0629 \063A\064A\0631 \0645\0648\062C\0648\062F\0629''); END;'),
'  END IF;',
'',
unistr('  -- \0627\0644\062A\062D\0642\0642 \0645\0646 \0627\0644\0633\0637\0648\0631 + \0643\0641\0627\064A\0629 \0627\0644\0631\0635\064A\062F \0644\0644\0635\0627\062F\0631 (\0645\062C\0645\0651\0639 \062D\0633\0628 \0627\0644\0635\0646\0641)'),
'  FOR r IN (SELECT j.line_no, j.item_id, j.unit_id, j.qty, j.unit_cost, u.factor',
'            FROM JSON_TABLE(l_clob, ''$.lines[*]'' COLUMNS (',
'                   line_no NUMBER PATH ''$.LINE_NO'', item_id NUMBER PATH ''$.ITEM_ID'',',
'                   unit_id NUMBER PATH ''$.UNIT_ID'', qty NUMBER PATH ''$.QTY'',',
'                   unit_cost NUMBER PATH ''$.UNIT_COST'')) j',
'            LEFT JOIN item_units u ON u.item_id = j.item_id AND u.unit_id = j.unit_id) LOOP',
'    l_lines := l_lines + 1;',
unistr('    IF r.factor IS NULL THEN err(''\0627\0644\0633\0637\0631 '' || r.line_no || '': \0627\0644\0635\0646\0641 \0623\0648 \0627\0644\0648\062D\062F\0629 \063A\064A\0631 \0635\062D\064A\062D\0629''); END IF;'),
'    IF r.qty IS NULL OR r.qty < 0 OR (r.qty = 0 AND l_type <> ''COUNT'') THEN',
unistr('      err(''\0627\0644\0633\0637\0631 '' || r.line_no || '': \0627\0644\0643\0645\064A\0629 \063A\064A\0631 \0635\062D\064A\062D\0629'');'),
'    END IF;',
unistr('    IF l_type IN (''RECEIPT'',''OPENING'') AND NVL(r.unit_cost, 0) <= 0 THEN err(''\0627\0644\0633\0637\0631 '' || r.line_no || '': \0623\062F\062E\0644 \062A\0643\0644\0641\0629 \0627\0644\0648\062D\062F\0629''); END IF;'),
'  END LOOP;',
unistr('  IF l_lines = 0 THEN err(''\0623\062F\062E\0644 \0635\0646\0641\0627\064B \0648\0627\062D\062F\0627\064B \0639\0644\0649 \0627\0644\0623\0642\0644''); END IF;'),
'',
unistr('  -- \0627\0644\062A\0635\0641\064A\0631: \0644\0627 \064A\062A\062C\0627\0648\0632 \0631\0635\064A\062F \0627\0644\062A\0648\0627\0644\0641 \063A\064A\0631 \0627\0644\0645\0635\0641\0651\0631 \0641\064A \0627\0644\0645\062E\0632\0646'),
'  IF l_type = ''DAMAGE_WO'' THEN',
'    FOR r IN (SELECT j.item_id, i.item_code, SUM(j.qty * u.factor) need, NVL(MAX(d.qty_base), 0) bal',
'              FROM JSON_TABLE(l_clob, ''$.lines[*]'' COLUMNS (',
'                     item_id NUMBER PATH ''$.ITEM_ID'', unit_id NUMBER PATH ''$.UNIT_ID'', qty NUMBER PATH ''$.QTY'')) j',
'              JOIN item_units u ON u.item_id = j.item_id AND u.unit_id = j.unit_id',
'              JOIN items i ON i.item_id = j.item_id',
'              LEFT JOIN v_damaged_balance d ON d.item_id = j.item_id AND d.warehouse_id = l_wh',
'              GROUP BY j.item_id, i.item_code) LOOP',
'      IF r.need > r.bal THEN',
unistr('        err(''\0627\0644\0635\0646\0641 '' || r.item_code || '': \0631\0635\064A\062F \0627\0644\062A\0648\0627\0644\0641 '' || r.bal || '' \0623\0642\0644 \0645\0646 \0643\0645\064A\0629 \0627\0644\062A\0635\0641\064A\0631 '' || r.need);'),
'      END IF;',
'    END LOOP;',
'  END IF;',
'',
'  IF l_type IN (''ISSUE'',''TRANSFER'') AND l_action = ''POST'' THEN',
'    FOR r IN (SELECT j.item_id, i.item_code, SUM(j.qty * u.factor) need, NVL(MAX(b.qty_base), 0) bal',
'              FROM JSON_TABLE(l_clob, ''$.lines[*]'' COLUMNS (',
'                     item_id NUMBER PATH ''$.ITEM_ID'', unit_id NUMBER PATH ''$.UNIT_ID'', qty NUMBER PATH ''$.QTY'')) j',
'              JOIN item_units u ON u.item_id = j.item_id AND u.unit_id = j.unit_id',
'              JOIN items i ON i.item_id = j.item_id',
'              LEFT JOIN v_stock_balance b ON b.item_id = j.item_id AND b.warehouse_id = l_wh',
'              GROUP BY j.item_id, i.item_code) LOOP',
'      IF r.need > r.bal THEN',
unistr('        err(''\0627\0644\0635\0646\0641 '' || r.item_code || '': \0627\0644\0631\0635\064A\062F '' || r.bal || '' \0644\0627 \064A\0643\0641\064A \0644\0644\0643\0645\064A\0629 '' || r.need);'),
'      END IF;',
'    END LOOP;',
'  END IF;',
'',
'  IF l_errs.COUNT > 0 THEN',
'    ROLLBACK;',
'    apex_json.open_object; apex_json.write(''ok'', FALSE); apex_json.write(''errors'', l_errs); apex_json.close_object;',
'    RETURN;',
'  END IF;',
'',
unistr('  ---------------------------------------------------------------- \0627\0644\062D\0641\0638'),
'  IF l_id IS NULL THEN',
'    UPDATE doc_sequences SET last_no = last_no + 1',
'    WHERE company_id = l_company AND doc_type = SUBSTR(l_type, 1, 10) AND fy_year = EXTRACT(YEAR FROM l_date)',
'    RETURNING last_no INTO l_seq;',
'    IF SQL%ROWCOUNT = 0 THEN',
'      INSERT INTO doc_sequences VALUES (l_company, l_type, EXTRACT(YEAR FROM l_date), 1); l_seq := 1;',
'    END IF;',
'    l_no := l_type || ''-'' || EXTRACT(YEAR FROM l_date) || ''-'' || LPAD(l_seq, 5, ''0'');',
'    INSERT INTO stock_trans (company_id, trans_type, trans_no, trans_date, warehouse_id, to_warehouse_id,',
'                             counter_account_id, currency_code, exchange_rate, description, created_by)',
'    VALUES (l_company, l_type, l_no, l_date, l_wh, l_to_wh, l_counter, l_cur, l_rate, l_desc, :APP_USER)',
'    RETURNING trans_id INTO l_id;',
'  ELSE',
'    UPDATE stock_trans SET company_id = l_company, trans_date = l_date, warehouse_id = l_wh,',
'           to_warehouse_id = l_to_wh, counter_account_id = l_counter, currency_code = l_cur,',
'           exchange_rate = l_rate, description = l_desc',
'    WHERE trans_id = l_id;',
'    DELETE FROM stock_trans_lines WHERE trans_id = l_id;',
'  END IF;',
'',
unistr('  -- \0633\0637\0648\0631 \0627\0644\0645\0635\062F\0631 (\0623\0648 \0627\0644\0648\062C\0647\0629 \0641\064A \0627\0644\0627\0633\062A\0644\0627\0645)'),
unistr('  --  RECEIPT : + \0628\0627\0644\062A\0643\0644\0641\0629 \0627\0644\0645\062F\062E\0644\0629  |  ISSUE/TRANSFER : \2212 \0628\0645\062A\0648\0633\0637 \0627\0644\062A\0643\0644\0641\0629  |  COUNT : \0627\0644\0641\0639\0644\064A \2212 \0627\0644\0631\0635\064A\062F'),
'  INSERT INTO stock_trans_lines (trans_id, line_no, warehouse_id, item_id, unit_id, factor, qty,',
'                                 qty_base, unit_cost, cost_base, value_base)',
'  SELECT l_id, ROWNUM, l_wh, j.item_id, j.unit_id, u.factor, j.qty,',
'         x.qty_base, NVL(j.unit_cost, 0), x.cost_base, ROUND(x.qty_base * x.cost_base, 4)',
'  FROM   JSON_TABLE(l_clob, ''$.lines[*]'' COLUMNS (',
'           item_id NUMBER PATH ''$.ITEM_ID'', unit_id NUMBER PATH ''$.UNIT_ID'',',
'           qty NUMBER PATH ''$.QTY'', unit_cost NUMBER PATH ''$.UNIT_COST'')) j',
'  JOIN   item_units u ON u.item_id = j.item_id AND u.unit_id = j.unit_id',
'  LEFT JOIN v_stock_balance b ON b.item_id = j.item_id AND b.warehouse_id = l_wh',
'  CROSS APPLY (SELECT',
'         CASE WHEN l_type IN (''RECEIPT'',''OPENING'') THEN j.qty * u.factor',
'                     WHEN l_type = ''COUNT'' THEN j.qty * u.factor - NVL(b.qty_base, 0)',
unistr('                     WHEN l_type = ''DAMAGE_WO'' THEN 0                 -- \0627\0644\062A\0635\0641\064A\0631 \0644\0627 \064A\063A\064A\0651\0631 \0627\0644\0643\0645\064A\0629'),
'                     ELSE -(j.qty * u.factor) END AS qty_base,',
'         CASE WHEN l_type IN (''RECEIPT'',''OPENING'') THEN NVL(j.unit_cost, 0) * l_rate / u.factor',
'                     ELSE NVL(b.avg_cost, 0) END AS cost_base',
'         FROM dual) x;',
'',
unistr('  -- \0625\0634\0639\0627\0631 \0627\0644\0625\0636\0627\0641\0629 \0648\0627\0644\062A\0648\0627\0644\0641: \0627\0644\062A\0643\0644\0641\0629 = \0633\0639\0631 \0634\0631\0627\0621 \0627\0644\0635\0646\0641 \0648\0644\0627 \062A\064F\0639\062F\064E\0651\0644 \064A\062F\0648\064A\0627\064B'),
'  IF l_type IN (''OPENING'',''DAMAGE'',''DAMAGE_WO'') THEN',
'    UPDATE stock_trans_lines sl',
'    SET    unit_cost = (SELECT CASE WHEN u.unit_id = i.big_unit_id AND i.big_purchase_price > 0 THEN i.big_purchase_price ELSE NULLIF(i.purchase_price, 0) * u.factor END FROM items i JOIN item_units u ON u.item_id = i.item_id AND u.unit_id = sl.unit_id WHERE i.item_id = sl.item_id)',
'    WHERE  sl.trans_id = l_id;',
'    UPDATE stock_trans_lines SET cost_base = NVL(unit_cost, 0) * l_rate / factor, value_base = ROUND(qty_base * NVL(unit_cost, 0) * l_rate / factor, 4)',
'    WHERE  trans_id = l_id;',
'  END IF;',
'  UPDATE stock_trans SET status = ''DRAFT'', return_note = NULL WHERE trans_id = l_id;',
'',
unistr('  -- \0627\0644\062A\062D\0648\064A\0644: \0633\0637\0648\0631 \0627\0644\0648\062C\0647\0629 \0628\0646\0641\0633 \0627\0644\062A\0643\0644\0641\0629'),
'  IF l_type = ''TRANSFER'' THEN',
'    INSERT INTO stock_trans_lines (trans_id, line_no, warehouse_id, item_id, unit_id, factor, qty,',
'                                   qty_base, unit_cost, cost_base, value_base)',
'    SELECT trans_id, line_no + 1000, l_to_wh, item_id, unit_id, factor, qty,',
'           -qty_base, unit_cost, cost_base, -value_base',
'    FROM   stock_trans_lines WHERE trans_id = l_id AND warehouse_id = l_wh;',
'  END IF;',
'',
unistr('  ---------------------------------------------------------------- \0627\0644\062A\0631\062D\064A\0644'),
'  IF l_action = ''POST'' THEN',
'    SELECT SUM(value_base) INTO l_val FROM stock_trans_lines WHERE trans_id = l_id AND warehouse_id = l_wh;',
'',
unistr('    -- \0625\0634\0639\0627\0631 \0627\0644\0625\0636\0627\0641\0629 (\0628\0636\0627\0639\0629 \0623\0648\0644 \0627\0644\0645\062F\0629) \0644\0627 \064A\064F\0646\0634\0626 \0642\064A\062F\0627\064B'),
'    IF l_type NOT IN (''TRANSFER'',''OPENING'',''DAMAGE'',''DAMAGE_WO'') AND ROUND(NVL(l_val, 0), 2) <> 0 THEN',
'      INSERT INTO journals (company_id, jt_code, journal_no, journal_date, currency_code, exchange_rate,',
'                            description, status, source_type, source_id, created_by, posted_by, posted_on)',
'      VALUES (l_company, ''ADJ'', l_no, l_date, l_base_cur, 1, NVL(l_desc, l_no), ''POSTED'', ''MANUAL'', l_id,',
'              :APP_USER, :APP_USER, SYSDATE)',
'      RETURNING journal_id INTO l_jid;',
'',
'      l_inv := setting(''INVENTORY'');',
unistr('      jline(1, l_inv, l_val);                                       -- \0627\0644\0645\062E\0632\0648\0646: + \0648\0627\0631\062F / \2212 \0635\0627\062F\0631'),
'      IF l_type = ''COUNT'' THEN',
unistr('        jline(2, setting(''INVENTORY_ADJ''), -l_val);                 -- \0641\0631\0648\0642\0627\062A \0627\0644\062C\0631\062F'),
'      ELSE',
unistr('        jline(2, l_counter, -l_val);                                -- \0627\0644\0645\0648\0631\062F \0623\0648 \0627\0644\0645\0635\0631\0648\0641'),
'      END IF;',
'',
'      UPDATE journals SET total_debit  = (SELECT SUM(debit)  FROM journal_lines WHERE journal_id = l_jid),',
'                          total_credit = (SELECT SUM(credit) FROM journal_lines WHERE journal_id = l_jid)',
'      WHERE journal_id = l_jid;',
'    END IF;',
'',
'    UPDATE stock_trans SET status = ''POSTED'', journal_id = l_jid WHERE trans_id = l_id;',
'  END IF;',
'',
'  apex_json.open_object;',
'  apex_json.write(''ok'', TRUE); apex_json.write(''id'', l_id); apex_json.write(''no'', l_no);',
unistr('  apex_json.write(''message'', CASE WHEN l_action = ''POST'' THEN ''\062A\0645 \062A\0631\062D\064A\0644 \0627\0644\062D\0631\0643\0629 '' ELSE ''\062A\0645 \062D\0641\0638 \0627\0644\062D\0631\0643\0629 '' END || l_no);'),
'  apex_json.close_object;',
'EXCEPTION WHEN OTHERS THEN',
'  ROLLBACK;',
'  apex_json.open_object; apex_json.write(''ok'', FALSE);',
'  apex_json.open_array(''errors''); apex_json.write(SQLERRM); apex_json.close_array;',
'  apex_json.close_object;',
'END;'))
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SAVE_DOC'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000660
);
