wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(91000000000681)
,p_plug_name=>unistr('\0623\0631\0635\062F\0629 \0627\0644\0645\062E\0632\0646 \062E\0644\0627\0644 \0627\0644\0641\062A\0631\0629 (\0627\0644\0643\0645\064A\0627\062A \0628\0627\0644\0648\062D\062F\0629 \0627\0644\0635\063A\0631\0649)')
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(6697232433757451)
,p_plug_display_sequence=>10
,p_location=>null
,p_plug_display_condition_type=>'EXPRESSION'
,p_plug_display_when_condition=>':P92_WAREHOUSE_ID IS NOT NULL'
,p_plug_display_when_cond2=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_ctx  apex_exec.t_context;',
'  l_col  apex_exec.t_column;',
'  l_val  VARCHAR2(4000);',
'BEGIN',
'  l_ctx := apex_exec.open_query_context(',
'             p_location  => apex_exec.c_location_local_db,',
'             p_sql_query => q''~WITH p AS (',
'  SELECT TO_DATE(:P92_FROM, ''DD/MM/YYYY'') d1, TO_DATE(:P92_TO, ''DD/MM/YYYY'') d2, TO_NUMBER(:P92_WAREHOUSE_ID) wh FROM dual',
'),',
'mv AS (',
unistr('  -- \062D\0631\0643\0627\062A \0627\0644\0645\062E\0632\0646 \0627\0644\0645\0639\062A\0645\062F\0629 \0628\0627\0644\0648\062D\062F\0629 \0627\0644\0635\063A\0631\0649:'),
unistr('  --   \0627\0644\0645\0631\062D\0644  = \0627\0644\0645\0648\062C\0648\062F \0641\0639\0644\064A\0627\064B \0642\0628\0644 \0627\0644\0641\062A\0631\0629 (\0627\0644\062A\0627\0644\0641 \063A\064A\0631 \0627\0644\0645\0635\0641\0651\0649 \0645\0627 \0632\0627\0644 \0641\064A \0627\0644\0645\062E\0632\0646 \060C \0648\0627\0644\0645\0635\0641\0651\0649 \062E\0631\062C)'),
unistr('  --   \0627\0644\0648\0627\0631\062F / \0627\0644\0645\0646\0635\0631\0641 \062E\0644\0627\0644 \0627\0644\0641\062A\0631\0629 \060C \0648\0627\0644\062A\0627\0644\0641 \0627\0644\0645\0635\0641\0651\0649 \0641\064A \0627\0644\0641\062A\0631\0629 \064A\064F\062D\0633\0628 \0645\0646\0635\0631\0641\0627\064B (\062A\062E\0644\0651\0635 \0646\0647\0627\0626\064A)'),
unistr('  --   \0627\0644\062A\0627\0644\0641  = \0627\0644\062A\0627\0644\0641 \063A\064A\0631 \0627\0644\0645\0635\0641\0651\0649 \062D\062A\0649 \0646\0647\0627\064A\0629 \0627\0644\0641\062A\0631\0629 (\064A\0635\0628\062D \0635\0641\0631\0627\064B \0628\0639\062F \062A\0635\0641\064A\0631\0647)'),
unistr('  --   \0627\0644\062D\0627\0644\064A  = \0627\0644\0645\0631\062D\0644 + \0627\0644\0648\0627\0631\062F \2212 \0627\0644\0645\0646\0635\0631\0641 \2212 \0627\0644\062A\0627\0644\0641'),
'  SELECT l.item_id,',
'         SUM(CASE WHEN t.trans_date < p.d1 THEN',
'                   CASE t.trans_type WHEN ''DAMAGE'' THEN 0 WHEN ''DAMAGE_WO'' THEN -(l.qty * l.factor) ELSE l.qty_base END',
'                  ELSE 0 END) op,',
'         SUM(CASE WHEN t.trans_date >= p.d1 AND t.trans_type NOT IN (''DAMAGE'',''DAMAGE_WO'') AND l.qty_base > 0 THEN l.qty_base ELSE 0 END) qin,',
'         SUM(CASE WHEN t.trans_date >= p.d1 AND t.trans_type NOT IN (''DAMAGE'',''DAMAGE_WO'') AND l.qty_base < 0 THEN -l.qty_base',
'                  WHEN t.trans_date >= p.d1 AND t.trans_type = ''DAMAGE_WO'' THEN l.qty * l.factor',
'                  ELSE 0 END) qout,',
'         SUM(CASE t.trans_type WHEN ''DAMAGE'' THEN -l.qty_base WHEN ''DAMAGE_WO'' THEN -(l.qty * l.factor) ELSE 0 END) qdmg',
'  FROM   stock_trans_lines l',
'  JOIN   stock_trans t ON t.trans_id = l.trans_id AND t.status = ''POSTED''',
'  CROSS JOIN p',
'  WHERE  l.warehouse_id = p.wh',
'  AND    t.trans_date < p.d2 + 1',
'  GROUP  BY l.item_id',
'),',
'r AS (',
'  SELECT i.item_code, i.name_ar, ub.name_ar small_name, bu.name_ar big_name,',
'         i.base_unit_id, i.big_unit_id, i.big_factor, NVL(i.purchase_price, 0) price,',
'         m.op, m.qin, m.qout, m.qdmg, m.op + m.qin - m.qout - m.qdmg cur',
'  FROM   mv m',
'  JOIN   items i  ON i.item_id  = m.item_id',
'  JOIN   units ub ON ub.unit_id = i.base_unit_id',
'  LEFT JOIN units bu ON bu.unit_id = i.big_unit_id',
'  WHERE  m.op <> 0 OR m.qin <> 0 OR m.qout <> 0 OR m.qdmg <> 0',
')',
'SELECT LPAD(item_code, 20, ''0'') AS sort_key,',
unistr('       item_code   AS "\0627\0644\0643\0648\062F",'),
unistr('       name_ar     AS "\0627\0644\0635\0646\0641",'),
unistr('       small_name  AS "\0627\0644\0648\062D\062F\0629 \0627\0644\0635\063A\0631\0649",'),
unistr('       op          AS "\0627\0644\0631\0635\064A\062F \0627\0644\0645\0631\062D\0644",'),
unistr('       qin         AS "\0627\0644\0648\0627\0631\062F",'),
unistr('       qout        AS "\0627\0644\0645\0646\0635\0631\0641",'),
unistr('       qdmg        AS "\0627\0644\062A\0627\0644\0641",'),
unistr('       cur         AS "\0627\0644\062D\0627\0644\064A",'),
'       CASE WHEN big_unit_id IS NOT NULL AND big_unit_id <> base_unit_id AND big_factor > 1 THEN',
'              CASE WHEN TRUNC(cur / big_factor) <> 0 THEN TRUNC(cur / big_factor) || '' '' || big_name END',
unistr('           || CASE WHEN TRUNC(cur / big_factor) <> 0 AND MOD(cur, big_factor) <> 0 THEN '' \0648 '' END'),
'           || CASE WHEN MOD(cur, big_factor) <> 0 OR TRUNC(cur / big_factor) = 0 THEN MOD(cur, big_factor) || '' '' || small_name END',
unistr('            ELSE cur || '' '' || small_name END AS "\0627\0644\062D\0627\0644\064A \0628\0627\0644\0639\0628\0648\0627\062A \0627\0644\0643\0628\064A\0631\0629",'),
unistr('       price       AS "\0633\0639\0631 \0634\0631\0627\0621 \0627\0644\0635\063A\0631\0649",'),
unistr('       ROUND(cur * price, 2) AS "\0627\0644\0625\062C\0645\0627\0644\064A"'),
'FROM   r',
'UNION ALL',
unistr('SELECT ''zzzzzzzzzzzzzzzzzzzzz'', NULL, ''\0625\062C\0645\0627\0644\064A \0627\0644\0645\0648\062C\0648\062F \0628\0627\0644\0645\062E\0632\0646'', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,'),
'       NVL(SUM(ROUND(cur * price, 2)), 0)',
'FROM   r',
'ORDER  BY 1',
'~'');',
'  htp.p(''<div style="overflow-x:auto"><table class="jl-table"><thead><tr>'');',
'  FOR i IN 1 .. apex_exec.get_column_count(l_ctx) LOOP',
'    l_col := apex_exec.get_column(l_ctx, i);',
unistr('    IF l_col.name NOT LIKE ''%\005C_ID'' ESCAPE ''\005C'' AND l_col.name <> ''SORT_KEY'' THEN'),
'      htp.p(''<th>'' || apex_escape.html(l_col.name) || ''</th>'');',
'    END IF;',
'  END LOOP;',
'  htp.p(''</tr></thead><tbody>'');',
'  WHILE apex_exec.next_row(l_ctx) LOOP',
'    htp.p(''<tr>'');',
'    FOR i IN 1 .. apex_exec.get_column_count(l_ctx) LOOP',
'      l_col := apex_exec.get_column(l_ctx, i);',
unistr('      IF l_col.name NOT LIKE ''%\005C_ID'' ESCAPE ''\005C'' AND l_col.name <> ''SORT_KEY'' THEN'),
'        IF l_col.data_type = apex_exec.c_data_type_number THEN',
unistr('          l_val := TO_CHAR(apex_exec.get_number(l_ctx, i), CASE WHEN l_col.name LIKE ''\0639\062F\062F%'' THEN ''FM999G999G990'' ELSE ''FM999G999G999G999G990D00'' END);'),
'          htp.p(''<td class="jl-num">'' || l_val || ''</td>'');',
'        ELSE',
'          htp.p(''<td>'' || apex_escape.html(apex_exec.get_varchar2(l_ctx, i)) || ''</td>'');',
'        END IF;',
'      END IF;',
'    END LOOP;',
'    htp.p(''</tr>'');',
'  END LOOP;',
'  htp.p(''</tbody></table></div>'');',
'  apex_exec.close(l_ctx);',
'EXCEPTION WHEN OTHERS THEN',
'  apex_exec.close(l_ctx);',
'  RAISE;',
'END;'))
,p_plug_source_type=>'NATIVE_PLSQL'
);
wwv_flow_imp_page.create_page_process(
