wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000719)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_err VARCHAR2(4000);',
'FUNCTION chk RETURN VARCHAR2 IS',
' l_cnt NUMBER;',
'BEGIN',
'  SELECT COUNT(*) INTO l_cnt FROM payroll_runs',
'  WHERE pay_period = :P100_PERIOD AND status <> ''CANCELLED''',
'  AND   NVL(company_id, 0) <> NVL(:P100_COMPANY_ID, 0)',
'  AND   (company_id IS NULL OR :P100_COMPANY_ID IS NULL OR company_id = :P100_COMPANY_ID);',
unistr('  RETURN CASE WHEN l_cnt > 0 THEN ''\064A\0648\062C\062F \0645\0633\064A\0631 \0622\062E\0631 \0644\0647\0630\0627 \0627\0644\0634\0647\0631 \064A\0634\0645\0644 \0646\0641\0633 \0627\0644\0634\0631\0643\0627\062A'' END;'),
'END;',
'BEGIN',
'  l_err := chk;',
'  IF l_err IS NOT NULL THEN',
'    apex_error.add_error(p_message => l_err, p_display_location => apex_error.c_inline_in_notification);',
'  END IF;',
'END;'))
,p_process_type=>'NATIVE_PLSQL'
,p_process_clob_language=>'PLSQL'
,p_process_name=>'CHECK_OVERLAP'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(91000000000700)
,p_internal_uid=>91000000000719
);
