'FROM payroll_lines p',
'JOIN payroll_runs r ON r.run_id = p.run_id AND r.status = ''APPROVED''',
'JOIN companies c ON c.company_id = p.company_id',
'WHERE r.pay_period BETWEEN :P102_FROM AND :P102_TO',
'GROUP BY c.name_ar',
'ORDER BY 8 DESC'))
);
