,p_alias=>'BRANCH-BAL'
,p_step_title=>unistr('\0628\0646\0648\062F \0645\064A\0632\0627\0646\064A\0629 \0627\0644\0641\0631\0648\0639')
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var brb = {',
'  grid: null,',
'',
'  init: function () {',
'    brb.grid = new JsonLines({',
'      container: ''#brb_lines'',',
'      columns  : [',
unistr('        {name: ''ACCOUNT_ID'', label: ''\0627\0644\062D\0633\0627\0628 (\0643\0648\062F / \0627\0633\0645)'', type: ''lov'', lov: ''accounts'', required: true, width: ''26em''},'),
unistr('        {name: ''DEBIT'',      label: ''\0645\062F\064A\0646'',   type: ''number'', decimals: 2, total: true, width: ''10em''},'),
unistr('        {name: ''CREDIT'',     label: ''\062F\0627\0626\0646'',   type: ''number'', decimals: 2, total: true, width: ''10em''},'),
unistr('        {name: ''NOTES'',      label: ''\0645\0644\0627\062D\0638\0627\062A'', type: ''text'', maxLength: 300}'),
'      ],',
'      onChange: function (row, col) {',
'        if (col === ''DEBIT''  && row.DEBIT)  row.CREDIT = null;',
'        if (col === ''CREDIT'' && row.CREDIT) row.DEBIT  = null;',
'      },',
'      onTotals: function (t) {',
'        var d = (t.DEBIT || 0) - (t.CREDIT || 0), el = document.getElementById(''brb_diff'');',
unistr('        el.textContent = JsonLines.fmt(Math.abs(d), 2) + (Math.abs(d) < 0.005 ? '' \2714 \0645\062A\0648\0627\0632\0646\0629'' : (d > 0 ? '' (\0627\0644\0645\062F\064A\0646 \0623\0643\0628\0631)'' : '' (\0627\0644\062F\0627\0626\0646 \0623\0643\0628\0631)''));'),
'        el.className = ''jv-diff '' + (Math.abs(d) < 0.005 ? ''ok'' : ''bad'');',
'      }',
'    });',
'    brb.load();',
'    apex.jQuery(''#P125_COMPANY_ID, #P125_AS_OF_DATE'').on(''change'', brb.load);',
'    document.addEventListener(''keydown'', function (e) {',
'      if (e.ctrlKey && (e.key === ''s'' || e.key === ''S'')) { e.preventDefault(); brb.save(); }',
'    });',
'  },',
'',
'  load: function () {',
'    if (!apex.item(''P125_COMPANY_ID'').getValue() || !apex.item(''P125_AS_OF_DATE'').getValue()) return;',
'    apex.server.process(''INIT_DATA'', {',
'      x01: apex.item(''P125_COMPANY_ID'').getValue(), x02: apex.item(''P125_AS_OF_DATE'').getValue()',
'    }, {dataType: ''json''}).done(function (d) {',
'      brb.grid.setLov(''accounts'', d.accounts);',
'      brb.grid.setData(d.lines);',
'    });',
'  },',
'',
'  save: function () {',
'    var errs = brb.grid.validate(), t = brb.grid.totals();',
unistr('    if (!apex.item(''P125_COMPANY_ID'').getValue()) errs.unshift(''\0627\062E\062A\0631 \0627\0644\0641\0631\0639'');'),
unistr('    if (!apex.item(''P125_AS_OF_DATE'').getValue()) errs.unshift(''\0623\062F\062E\0644 \062A\0627\0631\064A\062E \0627\0644\0645\064A\0632\0627\0646\064A\0629'');'),
unistr('    if (Math.abs((t.DEBIT || 0) - (t.CREDIT || 0)) >= 0.005) errs.push(''\0627\0644\0645\064A\0632\0627\0646\064A\0629 \063A\064A\0631 \0645\062A\0648\0627\0632\0646\0629'');'),
'    if (errs.length) { DocUtil.showErrors(errs); return; }',
'    DocUtil.save({',
'      header: {COMPANY_ID: apex.item(''P125_COMPANY_ID'').getValue(), AS_OF_DATE: apex.item(''P125_AS_OF_DATE'').getValue()},',
'      lines: brb.grid.getData()',
'    }, ''SAVE'', function () { brb.load(); });',
'  }',
'};'))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'window.APP_ROLE = ''&G_USER_ROLE.'';',
'brb.init();'))
,p_page_template_options=>'#DEFAULT#'
,p_required_role=>wwv_flow_imp.id(91000000000080)
,p_protection_level=>'N'
);
