wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000784)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_clob_language=>'PLSQL'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('  -- x01 = \0627\0644\0641\0631\0639 \060C x02 = \062A\0627\0631\064A\062E \0627\0644\0645\064A\0632\0627\0646\064A\0629 (DD/MM/YYYY)'),
'  l_acc   CLOB;',
'  l_lines CLOB;',
'BEGIN',
'  SELECT JSON_ARRAYAGG(JSON_OBJECT(''id'' VALUE account_id, ''code'' VALUE account_code, ''name'' VALUE name_ar)',
'                       ORDER BY account_code RETURNING CLOB)',
'  INTO   l_acc',
'  FROM   accounts WHERE is_postable = ''Y'' AND is_active = ''Y'';',
'',
'  SELECT JSON_ARRAYAGG(JSON_OBJECT(''ACCOUNT_ID'' VALUE b.account_id, ''DEBIT'' VALUE NULLIF(b.debit, 0),',
'                                   ''CREDIT'' VALUE NULLIF(b.credit, 0), ''NOTES'' VALUE b.notes)',
'                       ORDER BY a.account_code RETURNING CLOB)',
'  INTO   l_lines',
'  FROM   branch_balances b JOIN accounts a ON a.account_id = b.account_id',
'  WHERE  b.company_id = TO_NUMBER(apex_application.g_x01)',
'  AND    b.as_of_date = TO_DATE(apex_application.g_x02, ''DD/MM/YYYY'');',
'',
'  apex_util.prn(''{"accounts":'' || COALESCE(l_acc, TO_CLOB(''[]'')) ||',
'                '',"lines":'' || COALESCE(l_lines, TO_CLOB(''[]'')) || ''}'', FALSE);',
'END;'))
,p_process_name=>'INIT_DATA'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000784
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000785)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_clob    CLOB := apex_application.g_clob_01;',
'  l_errs    apex_t_varchar2 := apex_t_varchar2();',
'  l_company NUMBER := JSON_VALUE(l_clob, ''$.header.COMPANY_ID'' RETURNING NUMBER);',
'  l_date_s  VARCHAR2(20) := JSON_VALUE(l_clob, ''$.header.AS_OF_DATE'');',
'  l_date    DATE;',
'  l_cnt     NUMBER;',
'  l_dr      NUMBER := 0;',
'  l_cr      NUMBER := 0;',
'  PROCEDURE err (p VARCHAR2) IS BEGIN l_errs.EXTEND; l_errs(l_errs.COUNT) := p; END;',
'BEGIN',
unistr('  IF :G_USER_ROLE NOT IN (''ADMIN'',''ENTRY'') THEN err(''\0644\064A\0633 \0644\062F\064A\0643 \0635\0644\0627\062D\064A\0629''); END IF;'),
'  SELECT COUNT(*) INTO l_cnt FROM companies WHERE company_id = l_company AND is_parent = ''N'';',
unistr('  IF l_cnt = 0 THEN err(''\0627\062E\062A\0631 \0627\0644\0641\0631\0639''); END IF;'),
unistr('  BEGIN l_date := TO_DATE(l_date_s, ''DD/MM/YYYY''); EXCEPTION WHEN OTHERS THEN err(''\062A\0627\0631\064A\062E \0627\0644\0645\064A\0632\0627\0646\064A\0629 \063A\064A\0631 \0635\062D\064A\062D''); END;'),
unistr('  IF l_date IS NULL THEN err(''\0623\062F\062E\0644 \062A\0627\0631\064A\062E \0627\0644\0645\064A\0632\0627\0646\064A\0629''); END IF;'),
'',
'  FOR r IN (SELECT j.line_no, j.account_id, NVL(j.debit, 0) debit, NVL(j.credit, 0) credit',
'            FROM JSON_TABLE(l_clob, ''$.lines[*]'' COLUMNS (',
'                   line_no NUMBER PATH ''$.LINE_NO'', account_id NUMBER PATH ''$.ACCOUNT_ID'',',
'                   debit NUMBER PATH ''$.DEBIT'', credit NUMBER PATH ''$.CREDIT'')) j) LOOP',
'    SELECT COUNT(*) INTO l_cnt FROM accounts WHERE account_id = r.account_id AND is_postable = ''Y'';',
unistr('    IF l_cnt = 0 THEN err(''\0627\0644\0633\0637\0631 '' || r.line_no || '': \0627\0644\062D\0633\0627\0628 \064A\062C\0628 \0623\0646 \064A\0643\0648\0646 \062A\062D\0644\064A\0644\064A\0627\064B''); END IF;'),
'    IF r.debit < 0 OR r.credit < 0 OR (r.debit > 0 AND r.credit > 0) THEN',
unistr('      err(''\0627\0644\0633\0637\0631 '' || r.line_no || '': \0623\062F\062E\0644 \0645\0628\0644\063A\0627\064B \0641\064A \0627\0644\0645\062F\064A\0646 \0623\0648 \0627\0644\062F\0627\0626\0646 \0641\0642\0637'');'),
'    END IF;',
'    l_dr := l_dr + r.debit; l_cr := l_cr + r.credit;',
'  END LOOP;',
'',
'  SELECT COUNT(*) INTO l_cnt FROM (',
'    SELECT account_id FROM JSON_TABLE(l_clob, ''$.lines[*]'' COLUMNS (account_id NUMBER PATH ''$.ACCOUNT_ID''))',
'    GROUP BY account_id HAVING COUNT(*) > 1);',
unistr('  IF l_cnt > 0 THEN err(''\064A\0648\062C\062F \062D\0633\0627\0628 \0645\0643\0631\0631''); END IF;'),
'',
'  IF ROUND(l_dr, 2) <> ROUND(l_cr, 2) THEN',
unistr('    err(''\0627\0644\0645\064A\0632\0627\0646\064A\0629 \063A\064A\0631 \0645\062A\0648\0627\0632\0646\0629: \0627\0644\0645\062F\064A\0646 '' || TO_CHAR(l_dr, ''FM999G999G999G990D00'')'),
unistr('        || '' \0648\0627\0644\062F\0627\0626\0646 '' || TO_CHAR(l_cr, ''FM999G999G999G990D00''));'),
'  END IF;',
'',
'  IF l_errs.COUNT > 0 THEN',
'    ROLLBACK;',
'    apex_json.open_object; apex_json.write(''ok'', FALSE); apex_json.write(''errors'', l_errs); apex_json.close_object;',
'    RETURN;',
'  END IF;',
'',
'  DELETE FROM branch_balances WHERE company_id = l_company AND as_of_date = l_date;',
'  INSERT INTO branch_balances (company_id, as_of_date, account_id, debit, credit, notes, entered_by)',
'  SELECT l_company, l_date, account_id, NVL(debit, 0), NVL(credit, 0), notes, :APP_USER',
'  FROM JSON_TABLE(l_clob, ''$.lines[*]'' COLUMNS (',
'         account_id NUMBER PATH ''$.ACCOUNT_ID'', debit NUMBER PATH ''$.DEBIT'',',
'         credit NUMBER PATH ''$.CREDIT'', notes VARCHAR2(300) PATH ''$.NOTES''));',
'',
'  apex_json.open_object;',
'  apex_json.write(''ok'', TRUE);',
unistr('  apex_json.write(''message'', ''\062A\0645 \062D\0641\0638 \0645\064A\0632\0627\0646\064A\0629 \0627\0644\0641\0631\0639 \0628\062A\0627\0631\064A\062E '' || l_date_s);'),
'  apex_json.close_object;',
'EXCEPTION WHEN OTHERS THEN',
'  ROLLBACK;',
'  apex_json.open_object; apex_json.write(''ok'', FALSE);',
'  apex_json.open_array(''errors''); apex_json.write(SQLERRM); apex_json.close_array;',
'  apex_json.close_object;',
'END;'))
,p_process_type=>'NATIVE_PLSQL'
,p_process_clob_language=>'PLSQL'
,p_process_name=>'SAVE_DOC'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000785
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000786)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>'IF :P125_AS_OF_DATE IS NULL THEN :P125_AS_OF_DATE := TO_CHAR(LAST_DAY(ADD_MONTHS(SYSDATE, -1)), ''DD/MM/YYYY''); END IF;'
,p_process_clob_language=>'PLSQL'
,p_process_name=>'DEFAULTS'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000786
);
end;
