wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(91000000000792)
,p_plug_name=>unistr('\0627\0644\0634\0631\0643\0629 \0627\0644\0623\0645 + \0627\0644\0641\0631\0648\0639 = \0627\0644\0645\062C\0645\0648\0639\0629')
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(6697232433757451)
,p_plug_display_sequence=>10
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('  -- \0627\0644\0645\064A\0632\0627\0646\064A\0629 \0627\0644\0645\062C\0645\0651\0639\0629: \0627\0644\0634\0631\0643\0629 \0627\0644\0623\0645 \0645\0646 \0627\0644\0642\064A\0648\062F \0627\0644\0645\0631\062D\0651\0644\0629 + \0643\0644 \0641\0631\0639 \0645\0646 \0622\062E\0631 \0645\064A\0632\0627\0646\064A\0629 \0645\064F\062F\062E\0644\0629 \064A\062F\0648\064A\0627\064B \062D\062A\0649 \0627\0644\062A\0627\0631\064A\062E'),
'  l_date   DATE   := NVL(TO_DATE(:P126_AS_OF_DATE, ''DD/MM/YYYY''), TRUNC(SYSDATE));',
'  l_lvl    NUMBER := NVL(TO_NUMBER(:P126_LEVEL), 2);',
'  l_excl   VARCHAR2(1) := NVL(:P126_EXCLUDE, ''Y'');',
'  l_parent NUMBER := :G_PARENT_ID;',
'',
'  TYPE t_num IS TABLE OF NUMBER INDEX BY PLS_INTEGER;',
'  TYPE t_txt IS TABLE OF VARCHAR2(200) INDEX BY PLS_INTEGER;',
'  br_id   t_num; br_name t_txt; br_date t_txt;',
unistr('  col_tot t_num;                 -- \0625\062C\0645\0627\0644\064A \0643\0644 \0639\0645\0648\062F (\0644\0644\062A\062D\0642\0642 \0645\0646 \0627\0644\062A\0648\0627\0632\0646)'),
'  l_v     NUMBER; l_sum NUMBER; l_any BOOLEAN; l_sign NUMBER; l_n PLS_INTEGER := 0;',
'  l_row   VARCHAR2(32767);',
'',
'  FUNCTION fn (n NUMBER) RETURN VARCHAR2 IS',
'  BEGIN RETURN CASE WHEN NVL(n, 0) = 0 THEN ''-'' ELSE TO_CHAR(n, ''FM999G999G999G990D00'') END; END;',
'BEGIN',
'  FOR b IN (SELECT c.company_id, c.name_ar,',
'                   (SELECT MAX(as_of_date) FROM branch_balances x WHERE x.company_id = c.company_id AND x.as_of_date <= l_date) d',
'            FROM companies c WHERE c.is_parent = ''N'' AND c.is_active = ''Y'' ORDER BY c.company_code) LOOP',
'    l_n := l_n + 1; br_id(l_n) := b.company_id; br_name(l_n) := b.name_ar;',
unistr('    br_date(l_n) := NVL(TO_CHAR(b.d, ''DD/MM/YYYY''), ''\0644\0627 \062A\0648\062C\062F \0645\064A\0632\0627\0646\064A\0629'');'),
'  END LOOP;',
'  FOR i IN 0 .. l_n + 1 LOOP col_tot(i) := 0; END LOOP;',
'',
unistr('  htp.p(''<div style="overflow-x:auto"><table class="jl-table cons-table"><thead><tr><th>\0627\0644\062D\0633\0627\0628</th><th>\0627\0644\0634\0631\0643\0629 \0627\0644\0623\0645<br><small>\0645\0646 \0627\0644\0642\064A\0648\062F \062D\062A\0649 '''),
'        || TO_CHAR(l_date, ''DD/MM/YYYY'') || ''</small></th>'');',
'  FOR i IN 1 .. l_n LOOP',
unistr('    htp.p(''<th>'' || apex_escape.html(br_name(i)) || ''<br><small>\0645\064A\0632\0627\0646\064A\0629 '' || br_date(i) || ''</small></th>'');'),
'  END LOOP;',
unistr('  htp.p(''<th>\0627\0644\0625\062C\0645\0627\0644\064A \0627\0644\0645\062C\0645\0651\0639</th></tr></thead><tbody>'');'),
'',
'  FOR a IN (SELECT account_code, name_ar, acc_type, nature FROM accounts WHERE acc_level = l_lvl ORDER BY account_code) LOOP',
unistr('    l_sign := CASE a.nature WHEN ''D'' THEN 1 ELSE -1 END;   -- \064A\064F\0639\0631\0636 \0627\0644\0631\0635\064A\062F \0628\0637\0628\064A\0639\0629 \0627\0644\062D\0633\0627\0628'),
'    l_any := FALSE;',
'',
unistr('    -- \0627\0644\0634\0631\0643\0629 \0627\0644\0623\0645 \0645\0646 \0627\0644\0642\064A\0648\062F'),
'    SELECT NVL(SUM(l.debit_base - l.credit_base), 0) INTO l_v',
'    FROM   journal_lines l',
'    JOIN   journals j ON j.journal_id = l.journal_id',
'    JOIN   accounts d ON d.account_id = l.account_id',
'    WHERE  j.company_id = l_parent AND j.status IN (''POSTED'',''REVERSED'') AND j.journal_date <= l_date',
'    AND    d.account_code LIKE a.account_code || ''%''',
'    AND    (l_excl = ''N'' OR d.account_id NOT IN (SELECT ar_account_id FROM company_accounts));',
'    l_v := l_v * l_sign; l_sum := l_v; col_tot(0) := col_tot(0) + l_v;',
'    IF l_v <> 0 THEN l_any := TRUE; END IF;',
'    l_row := ''<td class="jl-num">'' || fn(l_v) || ''</td>'';',
'',
unistr('    -- \0627\0644\0641\0631\0648\0639 \0645\0646 \0627\0644\0625\062F\062E\0627\0644 \0627\0644\064A\062F\0648\064A'),
'    FOR i IN 1 .. l_n LOOP',
'      SELECT NVL(SUM(b.debit - b.credit), 0) INTO l_v',
'      FROM   branch_balances b JOIN accounts d ON d.account_id = b.account_id',
'      WHERE  b.company_id = br_id(i)',
'      AND    b.as_of_date = (SELECT MAX(x.as_of_date) FROM branch_balances x WHERE x.company_id = br_id(i) AND x.as_of_date <= l_date)',
'      AND    d.account_code LIKE a.account_code || ''%''',
'      AND    (l_excl = ''N'' OR d.account_id NOT IN (SELECT s.account_id FROM account_settings s WHERE s.setting_code = ''INTERCO_AP''));',
'      l_v := l_v * l_sign; l_sum := l_sum + l_v; col_tot(i) := col_tot(i) + l_v;',
'      IF l_v <> 0 THEN l_any := TRUE; END IF;',
'      l_row := l_row || ''<td class="jl-num">'' || fn(l_v) || ''</td>'';',
'    END LOOP;',
'',
'    IF l_any THEN',
'      htp.p(''<tr><td>'' || apex_escape.html(a.account_code || '' - '' || a.name_ar) || ''</td>'' || l_row',
'            || ''<td class="jl-num"><b>'' || fn(l_sum) || ''</b></td></tr>'');',
'    END IF;',
'  END LOOP;',
'  htp.p(''</tbody></table></div>'');',
unistr('  htp.p(''<p class="jl-hint">\0627\0644\0623\0631\0635\062F\0629 \0628\0637\0628\064A\0639\0629 \0627\0644\062D\0633\0627\0628: \0627\0644\0623\0635\0648\0644 \0648\0627\0644\0645\0635\0631\0648\0641\0627\062A \0645\0648\062C\0628\0629 \0628\0627\0644\0645\062F\064A\0646\060C \0648\0627\0644\062E\0635\0648\0645 \0648\062D\0642\0648\0642 \0627\0644\0645\0644\0643\064A\0629 \0648\0627\0644\0625\064A\0631\0627\062F\0627\062A \0645\0648\062C\0628\0629 \0628\0627\0644\062F\0627\0626\0646. '''),
unistr('        || CASE WHEN l_excl = ''Y'' THEN ''\062A\0645 \0627\0633\062A\0628\0639\0627\062F \0627\0644\062D\0633\0627\0628\0627\062A \0627\0644\0628\064A\0646\064A\0629 (\0630\0645\0645 \0627\0644\0641\0631\0648\0639 \0644\062F\0649 \0627\0644\0623\0645 \0648\062D\0633\0627\0628 \0627\0644\0623\0645 \0644\062F\0649 \0627\0644\0641\0631\0648\0639).'' END || ''</p>'');'),
'END;'))
,p_plug_source_type=>'NATIVE_PLSQL'
);
