wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000817)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  r sales_shifts%ROWTYPE;',
'BEGIN',
'  IF :P58_SHIFT_ID IS NULL THEN',
'    SELECT MAX(shift_id) INTO :P58_SHIFT_ID FROM sales_shifts WHERE user_name = :APP_USER AND status IN (''OPEN'',''RETURNED'');',
'  END IF;',
'  SELECT DECODE(COUNT(*), 0, ''N'', ''Y'') INTO :P58_HAS_OPEN FROM sales_shifts WHERE user_name = :APP_USER AND status IN (''OPEN'',''RETURNED'');',
'  IF :P58_SHIFT_ID IS NOT NULL THEN',
'    SELECT * INTO r FROM sales_shifts WHERE shift_id = :P58_SHIFT_ID;',
'    :P58_SHIFT_NO := r.shift_no;',
'    :P58_STATUS   := r.status;',
'    :P58_USER     := r.user_name;',
'    :P58_NOTES    := r.notes;',
unistr('    :P58_INFO     := ''\0627\0644\0628\0627\0626\0639: '' || r.user_name || '' - \0641\064F\062A\062D\062A '' || TO_CHAR(r.opened_on, ''DD/MM/YYYY HH24:MI'')'),
unistr('                  || CASE WHEN r.closed_on IS NOT NULL THEN '' - \0623\064F\063A\0644\0642\062A '' || TO_CHAR(r.closed_on, ''DD/MM/YYYY HH24:MI'') END;'),
'    :P58_RETURN_NOTE := CASE WHEN r.status IN (''RETURNED'',''DRAFT'') THEN r.return_note END;',
unistr(':P58_WF_INFO := TRIM(CASE WHEN r.reviewed_by IS NOT NULL THEN ''\0631\0627\062C\0639\0647 '' || r.reviewed_by || '' '' || TO_CHAR(r.reviewed_on, ''DD/MM/YYYY HH24:MI'') END || CASE WHEN r.approved_by IS NOT NULL THEN '' - \0627\0639\062A\0645\062F\0647 '' || r.approved_by || '' '' || TO_CHAR(r.approved_on, ''DD/MM/YYYY HH24:MI'') END);'),
'  END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_name=>'LOAD'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000817
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000818)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('  -- \0641\062A\062D \0648\0631\062F\064A\0629 \062C\062F\064A\062F\0629 \0644\0644\0645\0633\062A\062E\062F\0645 (\0631\0642\0645\0647\0627 17 + \0627\0644\0633\0646\0629 + 5 \062E\0627\0646\0627\062A)'),
'  l_cnt NUMBER; l_seq NUMBER; l_co NUMBER := NVL(:G_COMPANY_ID, :G_PARENT_ID); l_y NUMBER := EXTRACT(YEAR FROM SYSDATE);',
'BEGIN',
'  IF :G_USER_ROLE NOT IN (''ADMIN'',''ENTRY'') THEN',
unistr('    apex_error.add_error(p_message => ''\0641\062A\062D \0627\0644\0648\0631\062F\064A\0629 \0645\0646 \0635\0644\0627\062D\064A\0629 \0627\0644\0645\062F\062E\0644 (\0627\0644\0628\0627\0626\0639)'', p_display_location => apex_error.c_inline_in_notification);'),
'    RETURN;',
'  END IF;',
'  SELECT COUNT(*) INTO l_cnt FROM sales_shifts WHERE user_name = :APP_USER AND status IN (''OPEN'',''RETURNED'');',
'  IF l_cnt > 0 THEN',
unistr('    apex_error.add_error(p_message => ''\0644\062F\064A\0643 \0648\0631\062F\064A\0629 \0645\0641\062A\0648\062D\0629 \0623\0648 \0645\0639\0627\062F\0629 \0644\0645 \062A\064F\063A\0644\0642 \0628\0639\062F'', p_display_location => apex_error.c_inline_in_notification);'),
'    RETURN;',
'  END IF;',
'  UPDATE doc_sequences SET last_no = last_no + 1 WHERE company_id = l_co AND doc_type = ''17'' AND fy_year = l_y',
'  RETURNING last_no INTO l_seq;',
'  IF SQL%ROWCOUNT = 0 THEN',
'    INSERT INTO doc_sequences (company_id, doc_type, fy_year, last_no) VALUES (l_co, ''17'', l_y, 1); l_seq := 1;',
'  END IF;',
'  INSERT INTO sales_shifts (company_id, shift_no, user_name, status)',
'  VALUES (l_co, ''17'' || l_y || LPAD(l_seq, 5, ''0''), :APP_USER, ''OPEN'')',
'  RETURNING shift_id INTO :P58_SHIFT_ID;',
'  INSERT INTO doc_actions (doc_type, doc_id, action, to_status, action_by) VALUES (''SHIFT'', :P58_SHIFT_ID, ''OPEN'', ''OPEN'', :APP_USER);',
unistr('  apex_application.g_print_success_message := ''\062A\0645 \0641\062A\062D \0627\0644\0648\0631\062F\064A\0629'';'),
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_name=>'OPEN_SHIFT'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(91000000000803)
,p_internal_uid=>91000000000818
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000819)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('  -- \0625\063A\0644\0627\0642 \0627\0644\0648\0631\062F\064A\0629: \062A\0635\0628\062D \0628\0627\0646\062A\0638\0627\0631 \0627\0644\0645\0631\0627\062C\0639\0629 \0648\0627\0644\0627\0639\062A\0645\0627\062F'),
'  s sales_shifts%ROWTYPE; l_cnt NUMBER;',
'BEGIN',
'  SELECT * INTO s FROM sales_shifts WHERE shift_id = :P58_SHIFT_ID FOR UPDATE;',
'  IF s.status NOT IN (''OPEN'',''RETURNED'') THEN',
unistr('    apex_error.add_error(p_message => ''\0627\0644\0648\0631\062F\064A\0629 \0645\063A\0644\0642\0629 \0645\0646 \0642\0628\0644'', p_display_location => apex_error.c_inline_in_notification); RETURN;'),
'  END IF;',
'  IF s.user_name <> :APP_USER AND :G_USER_ROLE <> ''ADMIN'' THEN',
unistr('    apex_error.add_error(p_message => ''\064A\063A\0644\0642 \0627\0644\0648\0631\062F\064A\0629 \0635\0627\062D\0628\0647\0627 \0641\0642\0637'', p_display_location => apex_error.c_inline_in_notification); RETURN;'),
'  END IF;',
'  SELECT COUNT(*) INTO l_cnt FROM invoices WHERE shift_id = s.shift_id AND status = ''DRAFT'';',
'  IF l_cnt > 0 THEN',
unistr('    apex_error.add_error(p_message => ''\0641\064A \0627\0644\0648\0631\062F\064A\0629 '' || l_cnt || '' \0641\0627\062A\0648\0631\0629 \0645\0633\0648\062F\0629: \0627\062D\0641\0638\0647\0627 \0646\0647\0627\0626\064A\0627\064B \0623\0648 \0627\062D\0630\0641\0647\0627 \0642\0628\0644 \0627\0644\0625\063A\0644\0627\0642'','),
'                         p_display_location => apex_error.c_inline_in_notification); RETURN;',
'  END IF;',
'  UPDATE sales_shifts SET status = ''DRAFT'', closed_on = SYSDATE, notes = :P58_NOTES, return_note = NULL WHERE shift_id = s.shift_id;',
'  INSERT INTO doc_actions (doc_type, doc_id, action, from_status, to_status, action_by)',
'  VALUES (''SHIFT'', s.shift_id, ''CLOSE'', s.status, ''DRAFT'', :APP_USER);',
unistr('  apex_application.g_print_success_message := ''\062A\0645 \0625\063A\0644\0627\0642 \0627\0644\0648\0631\062F\064A\0629 - \0628\0627\0646\062A\0638\0627\0631 \0627\0644\0645\0631\0627\062C\0639\0629 \0648\0627\0644\0627\0639\062A\0645\0627\062F'';'),
'END;'))
,p_process_type=>'NATIVE_PLSQL'
,p_process_clob_language=>'PLSQL'
,p_process_name=>'CLOSE_SHIFT'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(91000000000804)
,p_internal_uid=>91000000000819
);
