,p_plug_source_type=>'NATIVE_IR'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('SELECT s.shift_id, s.shift_no AS "\0631\0642\0645 \0627\0644\0648\0631\062F\064A\0629", s.user_name AS "\0627\0644\0628\0627\0626\0639",'),
unistr('       TO_CHAR(s.opened_on, ''DD/MM/YYYY HH24:MI'') AS "\0627\0644\0641\062A\062D", TO_CHAR(s.closed_on, ''DD/MM/YYYY HH24:MI'') AS "\0627\0644\0625\063A\0644\0627\0642",'),
unistr('       (SELECT COUNT(*) FROM invoices i WHERE i.shift_id = s.shift_id AND i.status = ''POSTED'') AS "\0639\062F\062F \0627\0644\0641\0648\0627\062A\064A\0631",'),
'       (SELECT SUM(CASE WHEN i.invoice_type = ''SALE'' THEN i.net_amount ELSE -i.net_amount END)',
unistr('        FROM invoices i WHERE i.shift_id = s.shift_id AND i.status = ''POSTED'') AS "\0635\0627\0641\064A \0627\0644\0645\0628\064A\0639\0627\062A",'),
unistr('       DECODE(s.status, ''OPEN'', ''\0645\0641\062A\0648\062D\0629'', ''DRAFT'', ''\0645\063A\0644\0642\0629 - \0628\0627\0646\062A\0638\0627\0631 \0627\0644\0645\0631\0627\062C\0639\0629'', ''RETURNED'', ''\0645\0639\0627\062F\0629 \0644\0644\0628\0627\0626\0639'','),
unistr('              ''REVIEWED'', ''\0645\064F\0631\0627\062C\064E\0639\0629 - \0628\0627\0646\062A\0638\0627\0631 \0627\0644\0627\0639\062A\0645\0627\062F'', ''POSTED'', ''\0645\0639\062A\0645\062F\0629 \0648\0645\0631\062D\0651\0644\0629'') AS "\0627\0644\062D\0627\0644\0629",'),
unistr('       s.reviewed_by AS "\0627\0644\0645\0631\0627\062C\0639", s.approved_by AS "\0627\0644\0645\0639\062A\0645\062F"'),
'FROM   sales_shifts s',
'WHERE  (:G_USER_ROLE <> ''ENTRY'' OR s.user_name = :APP_USER)',
'AND    (:P59_STATUS IS NULL OR s.status = :P59_STATUS)',
'ORDER BY s.shift_id DESC'))
,p_query_type=>'SQL'
);
