unistr('       DECODE(i.invoice_type, ''SALE'', ''\0645\0628\064A\0639\0627\062A'', ''\0645\0631\062A\062C\0639'') AS "\0627\0644\0646\0648\0639",'),
unistr('       DECODE(i.pay_type, ''CREDIT'', ''\0622\062C\0644'', DECODE(i.pay_method, ''BANK'', ''\0646\0642\062F\064A - \0628\0646\0643'', ''\0646\0642\062F\064A - \062E\0632\064A\0646\0629'')) AS "\0637\0631\064A\0642\0629 \0627\0644\062F\0641\0639",'),
unistr('       a.name_ar AS "\0627\0644\062D\0633\0627\0628", NVL(i.customer_name, a.name_ar) AS "\0627\0644\0639\0645\064A\0644",'),
unistr('       CASE WHEN i.invoice_type = ''SALE'' THEN i.net_amount ELSE -i.net_amount END AS "\0627\0644\0635\0627\0641\064A",'),
unistr('       s.shift_no AS "\0627\0644\0648\0631\062F\064A\0629"'),
'FROM   invoices i JOIN accounts a ON a.account_id = i.account_id',
'LEFT JOIN sales_shifts s ON s.shift_id = i.shift_id',
'WHERE  i.status = ''POSTED'' AND i.invoice_date BETWEEN NVL(TO_DATE(:P52_FROM, ''DD/MM/YYYY''), TRUNC(SYSDATE)) AND NVL(TO_DATE(:P52_TO, ''DD/MM/YYYY''), TRUNC(SYSDATE)) AND (:P52_USER IS NULL OR i.created_by = :P52_USER)',
'ORDER BY i.invoice_id'))
,p_query_type=>'SQL'
);
