,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('SELECT i.item_id, i.item_code AS "\0627\0644\0643\0648\062F", i.name_ar AS "\0627\0644\0635\0646\0641",'),
unistr('       TO_CHAR(i.expiry_date, ''DD/MM/YYYY'') AS "\062A\0627\0631\064A\062E \0627\0644\0635\0644\0627\062D\064A\0629",'),
unistr('       TRUNC(i.expiry_date) - TRUNC(SYSDATE) AS "\0627\0644\0623\064A\0627\0645 \0627\0644\0645\062A\0628\0642\064A\0629",'),
unistr('       CASE WHEN i.expiry_date < TRUNC(SYSDATE) THEN ''\0645\0646\062A\0647\064A \0627\0644\0635\0644\0627\062D\064A\0629'''),
unistr('            WHEN i.expiry_date <= ADD_MONTHS(TRUNC(SYSDATE), 1) THEN ''\0623\0642\0644 \0645\0646 \0634\0647\0631'''),
unistr('            ELSE ''\062E\0644\0627\0644 3 \0623\0634\0647\0631'' END AS "\0627\0644\062A\0646\0628\064A\0647",'),
unistr('       un.name_ar AS "\0627\0644\0648\062D\062F\0629 \0627\0644\0635\063A\0631\0649",'),
unistr('       NVL((SELECT SUM(b.qty_base) FROM v_stock_balance b WHERE b.item_id = i.item_id), 0) AS "\0627\0644\0643\0645\064A\0629 \0628\0627\0644\0645\062E\0632\0646",'),
unistr('       NVL((SELECT SUM(b.value_base) FROM v_stock_balance b WHERE b.item_id = i.item_id), 0) AS "\0627\0644\0642\064A\0645\0629"'),
'FROM   items i JOIN units un ON un.unit_id = i.base_unit_id',
'WHERE  i.is_active = ''Y'' AND i.expiry_date IS NOT NULL',
'AND    i.expiry_date <= ADD_MONTHS(TRUNC(SYSDATE), NVL(TO_NUMBER(:P94_MONTHS), 3))',
'ORDER BY i.expiry_date'))
