wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000897)
,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('  -- \062F\0648\0631\0629 \0627\0644\0645\0633\062A\0646\062F: \0645\0633\0648\062F\0629 -> \0645\064F\0631\0627\062C\064E\0639 -> \0645\0639\062A\0645\062F -> \0645\0631\062D\0651\0644 \060C \0648\0627\0644\0625\0639\0627\062F\0629 \0644\0644\0645\062F\062E\0644 \0645\0639 \0627\0644\0633\0628\0628'),
unistr('  -- \0627\0644\0645\0631\0627\062C\0639: \0645\0631\0627\062C\0639\0629 / \0625\0644\063A\0627\0621 \0627\0644\0645\0631\0627\062C\0639\0629 / \0625\0639\0627\062F\0629 \060C \0627\0644\0645\0639\062A\0645\062F: \0627\0639\062A\0645\0627\062F / \0625\0644\063A\0627\0621 \0627\0644\0627\0639\062A\0645\0627\062F / \0625\0639\0627\062F\0629 / \062A\0631\062D\064A\0644 \060C \0645\062F\064A\0631 \0627\0644\0646\0638\0627\0645: \0627\0644\0643\0644'),
'  l_id    NUMBER        := :P105_INC_ID;',
'  l_req   VARCHAR2(20)  := :REQUEST;',
'  l_role  VARCHAR2(20)  := :G_USER_ROLE;',
'  l_note  VARCHAR2(500) := SUBSTR(TRIM(:P105_WF_NOTE), 1, 500);',
'  l_st    VARCHAR2(10);',
'  l_new   VARCHAR2(10);',
'  l_err   VARCHAR2(400);',
'  l_msg   VARCHAR2(200);',
'  FUNCTION has (p_roles VARCHAR2) RETURN BOOLEAN IS',
'  BEGIN RETURN l_role = ''ADMIN'' OR INSTR('','' || p_roles || '','', '','' || l_role || '','') > 0; END;',
'BEGIN',
'  IF apex_error.have_errors_occurred THEN RETURN; END IF;',
'  IF l_id IS NULL THEN',
unistr('    l_err := ''\0627\062D\0641\0638 \0627\0644\0645\0633\062A\0646\062F \0623\0648\0644\0627\064B'';'),
'  ELSE',
'    SELECT status INTO l_st FROM annual_incentives WHERE inc_id = l_id FOR UPDATE;',
'    CASE l_req',
'      WHEN ''REVIEW'' THEN',
unistr('        IF NOT has(''REVIEWER'') THEN l_err := ''\0627\0644\0645\0631\0627\062C\0639\0629 \0645\0646 \0635\0644\0627\062D\064A\0629 \0627\0644\0645\0631\0627\062C\0639'';'),
unistr('        ELSIF l_st <> ''DRAFT'' THEN l_err := ''\0644\0627 \064A\064F\0631\0627\062C\0639 \0625\0644\0627 \0627\0644\0645\0633\062A\0646\062F \0641\064A \062D\0627\0644\0629 \0645\0633\0648\062F\0629'';'),
unistr('        ELSE l_new := ''REVIEWED''; l_msg := ''\062A\0645\062A \0627\0644\0645\0631\0627\062C\0639\0629''; END IF;'),
'      WHEN ''UNREVIEW'' THEN',
unistr('        IF NOT has(''REVIEWER'') THEN l_err := ''\0625\0644\063A\0627\0621 \0627\0644\0645\0631\0627\062C\0639\0629 \0645\0646 \0635\0644\0627\062D\064A\0629 \0627\0644\0645\0631\0627\062C\0639'';'),
unistr('        ELSIF l_st <> ''REVIEWED'' THEN l_err := ''\0627\0644\0645\0633\062A\0646\062F \0644\064A\0633 \0641\064A \062D\0627\0644\0629 \0645\064F\0631\0627\062C\064E\0639 (\0631\0628\0645\0627 \062A\0645 \0627\0639\062A\0645\0627\062F\0647)'';'),
unistr('        ELSE l_new := ''DRAFT''; l_msg := ''\062A\0645 \0625\0644\063A\0627\0621 \0627\0644\0645\0631\0627\062C\0639\0629''; END IF;'),
'      WHEN ''APPROVE'' THEN',
unistr('        IF NOT has(''APPROVER'') THEN l_err := ''\0627\0644\0627\0639\062A\0645\0627\062F \0645\0646 \0635\0644\0627\062D\064A\0629 \0627\0644\0645\0639\062A\0645\062F'';'),
unistr('        ELSIF l_st <> ''REVIEWED'' THEN l_err := ''\0644\0627 \064A\064F\0639\062A\0645\062F \0625\0644\0627 \0627\0644\0645\0633\062A\0646\062F \0627\0644\0645\064F\0631\0627\062C\064E\0639'';'),
unistr('        ELSIF ''Y'' = ''Y'' THEN l_new := ''POSTED''; l_msg := ''\062A\0645 \0627\0644\0627\0639\062A\0645\0627\062F \0648\0627\0644\062A\0631\062D\064A\0644'';'),
unistr('        ELSE l_new := ''APPROVED''; l_msg := ''\062A\0645 \0627\0644\0627\0639\062A\0645\0627\062F''; END IF;'),
'      WHEN ''UNAPPROVE'' THEN',
unistr('        IF NOT has(''APPROVER'') THEN l_err := ''\0625\0644\063A\0627\0621 \0627\0644\0627\0639\062A\0645\0627\062F \0645\0646 \0635\0644\0627\062D\064A\0629 \0627\0644\0645\0639\062A\0645\062F'';'),
unistr('        ELSIF l_st <> ''APPROVED'' THEN l_err := ''\0627\0644\0645\0633\062A\0646\062F \0644\064A\0633 \0641\064A \062D\0627\0644\0629 \0645\0639\062A\0645\062F (\0631\0628\0645\0627 \062A\0645 \062A\0631\062D\064A\0644\0647)'';'),
unistr('        ELSE l_new := ''REVIEWED''; l_msg := ''\062A\0645 \0625\0644\063A\0627\0621 \0627\0644\0627\0639\062A\0645\0627\062F''; END IF;'),
'      WHEN ''RETURN'' THEN',
'        IF NOT ((has(''REVIEWER'') AND l_st IN (''DRAFT'',''REVIEWED'')) OR (has(''APPROVER'') AND l_st IN (''REVIEWED'',''APPROVED''))) THEN',
unistr('          l_err := ''\0644\0627 \064A\0645\0643\0646\0643 \0625\0639\0627\062F\0629 \0647\0630\0627 \0627\0644\0645\0633\062A\0646\062F \0641\064A \062D\0627\0644\062A\0647 \0627\0644\062D\0627\0644\064A\0629'';'),
unistr('        ELSIF l_note IS NULL THEN l_err := ''\0627\0643\062A\0628 \0633\0628\0628 \0627\0644\0625\0639\0627\062F\0629'';'),
unistr('        ELSE l_new := ''RETURNED''; l_msg := ''\062A\0645\062A \0625\0639\0627\062F\0629 \0627\0644\0645\0633\062A\0646\062F \0644\0644\0645\062F\062E\0644''; END IF;'),
'      WHEN ''POST'' THEN',
unistr('        IF ''Y'' <> ''Y'' THEN l_err := ''\0647\0630\0627 \0627\0644\0645\0633\062A\0646\062F \0644\0627 \064A\064F\0631\062D\0651\0644'';'),
unistr('        ELSIF NOT has(''APPROVER'') THEN l_err := ''\0627\0644\062A\0631\062D\064A\0644 \0645\0646 \0635\0644\0627\062D\064A\0629 \0627\0644\0645\0639\062A\0645\062F'';'),
unistr('        ELSIF l_st <> ''APPROVED'' THEN l_err := ''\0644\0627 \064A\064F\0631\062D\0651\0644 \0625\0644\0627 \0627\0644\0645\0633\062A\0646\062F \0627\0644\0645\0639\062A\0645\062F'';'),
unistr('        ELSE l_new := ''POSTED''; l_msg := ''\062A\0645 \0627\0644\062A\0631\062D\064A\0644''; END IF;'),
unistr('      ELSE l_err := ''\0625\062C\0631\0627\0621 \063A\064A\0631 \0645\0639\0631\0648\0641'';'),
'    END CASE;',
'  END IF;',
'',
unistr('  -- \0634\0631\0637 \0625\0636\0627\0641\064A \062E\0627\0635 \0628\0627\0644\0645\0633\062A\0646\062F (\0645\062B\0644: \0625\0630\0646 \0627\0644\0634\064A\0643\0627\062A \0644\0627 \064A\064F\0631\0627\062C\0639 \0642\0628\0644 \062C\062F\0648\0644\0629 \0634\064A\0643\0627\062A\0647)'),
'  IF l_err IS NULL AND l_req IN (''REVIEW'',''APPROVE'') THEN',
'    NULL;',
'  END IF;',
'',
'  IF l_err IS NOT NULL THEN',
'    apex_error.add_error(p_message => l_err, p_display_location => apex_error.c_inline_in_notification);',
'    RETURN;',
'  END IF;',
'',
unistr('  -- \0627\0644\062A\0631\062D\064A\0644 \064A\062A\0645 \0645\0628\0627\0634\0631\0629 \0639\0646\062F \0627\0644\0627\0639\062A\0645\0627\062F'),
'  IF l_new = ''POSTED'' THEN',
'    DECLARE',
unistr('      -- \0627\0639\062A\0645\0627\062F \0627\0644\062D\0627\0641\0632 \0627\0644\0633\0646\0648\064A: \0645\0646 \062D/ \0645\0635\0631\0648\0641 \0627\0644\062D\0648\0627\0641\0632 \0625\0644\0649 \062D/ \0631\0648\0627\062A\0628 \0645\0633\062A\062D\0642\0629'),
'      a annual_incentives%ROWTYPE; l_exp NUMBER; l_pay NUMBER; l_jid NUMBER; l_cur VARCHAR2(3);',
'    BEGIN',
'      SELECT * INTO a FROM annual_incentives WHERE inc_id = l_id;',
unistr('      IF a.total_amount <= 0 THEN raise_application_error(-20041, ''\0644\0627 \062A\0648\062C\062F \0645\0628\0627\0644\063A \0641\064A \0627\0644\062D\0627\0641\0632''); END IF;'),
'      BEGIN',
'        SELECT account_id INTO l_exp FROM account_settings WHERE company_id = a.company_id AND setting_code = ''INCENTIVE_EXP'';',
'        SELECT account_id INTO l_pay FROM account_settings WHERE company_id = a.company_id AND setting_code = ''SALARY_PAYABLE'';',
'      EXCEPTION WHEN NO_DATA_FOUND THEN',
unistr('        raise_application_error(-20042, ''\062D\062F\062F \062D\0633\0627\0628\064A \0645\0635\0631\0648\0641 \0627\0644\062D\0648\0627\0641\0632 \0648\0627\0644\0631\0648\0627\062A\0628 \0627\0644\0645\0633\062A\062D\0642\0629 \0641\064A \0627\0644\062D\0633\0627\0628\0627\062A \0627\0644\0627\0641\062A\0631\0627\0636\064A\0629'');'),
'      END;',
'      SELECT currency_code INTO l_cur FROM currencies WHERE is_base = ''Y'';',
'      INSERT INTO journals (company_id, jt_code, journal_no, journal_date, currency_code, exchange_rate, description,',
'                            status, source_type, source_id, total_debit, total_credit, created_by,',
'                            reviewed_by, reviewed_on, approved_by, approved_on, posted_by, posted_on)',
'      VALUES (a.company_id, ''AINC'', a.inc_no, TRUNC(SYSDATE), l_cur, 1,',
unistr('              NVL(a.description, ''\0627\0644\062D\0627\0641\0632 \0627\0644\0633\0646\0648\064A \0644\0639\0627\0645 '' || a.fy_year), ''POSTED'', ''PAYROLL'', a.inc_id,'),
'              a.total_amount, a.total_amount, a.created_by, a.reviewed_by, a.reviewed_on, :APP_USER, SYSDATE, :APP_USER, SYSDATE)',
'      RETURNING journal_id INTO l_jid;',
'      INSERT INTO journal_lines (journal_id, line_no, account_id, debit, credit, debit_base, credit_base, description)',
unistr('      VALUES (l_jid, 1, l_exp, a.total_amount, 0, a.total_amount, 0, ''\0627\0644\062D\0627\0641\0632 \0627\0644\0633\0646\0648\064A '' || a.fy_year);'),
'      INSERT INTO journal_lines (journal_id, line_no, account_id, debit, credit, debit_base, credit_base, description)',
unistr('      VALUES (l_jid, 2, l_pay, 0, a.total_amount, 0, a.total_amount, ''\0627\0644\062D\0627\0641\0632 \0627\0644\0633\0646\0648\064A '' || a.fy_year);'),
'      UPDATE annual_incentives SET journal_id = l_jid WHERE inc_id = l_id;',
'    END;',
'',
'  END IF;',
'',
'  UPDATE annual_incentives',
'  SET    status      = l_new,',
'         reviewed_by = CASE WHEN l_req = ''REVIEW'' THEN :APP_USER WHEN l_req IN (''UNREVIEW'',''RETURN'') THEN NULL ELSE reviewed_by END,',
'         reviewed_on = CASE WHEN l_req = ''REVIEW'' THEN SYSDATE   WHEN l_req IN (''UNREVIEW'',''RETURN'') THEN NULL ELSE reviewed_on END,',
'         approved_by = CASE WHEN l_req = ''APPROVE'' THEN :APP_USER WHEN l_req IN (''UNAPPROVE'',''RETURN'') THEN NULL ELSE approved_by END,',
'         approved_on = CASE WHEN l_req = ''APPROVE'' THEN SYSDATE   WHEN l_req IN (''UNAPPROVE'',''RETURN'') THEN NULL ELSE approved_on END,',
'         return_note = CASE WHEN l_req = ''RETURN'' THEN l_note ELSE return_note END',
'  WHERE  inc_id = l_id;',
'',
'  INSERT INTO doc_actions (doc_type, doc_id, action, from_status, to_status, note, action_by)',
'  VALUES (''ANNUAL_INC'', l_id, l_req, l_st, l_new, l_note, :APP_USER);',
'',
'  :P105_WF_NOTE := NULL;',
'  apex_application.g_print_success_message := l_msg;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_name=>'WORKFLOW'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'REVIEW,UNREVIEW,APPROVE,UNAPPROVE,RETURN,POST'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_internal_uid=>91000000000897
);
