,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('// \0627\0644\062E\0637\0629 (\0627\0644\0645\0648\0627\0632\0646\0629 \0627\0644\062A\0642\062F\064A\0631\064A\0629) \0644\0625\062F\0627\0631\0629: \0643\0644 \0628\0646\0648\062F \0627\0644\0645\064A\0632\0627\0646\064A\0629 \0628\0627\0644\0623\0631\0628\0627\0639 \0627\0644\0623\0631\0628\0639\0629'),
'var plan = {',
'  grid: null,',
'  init: function () {',
'    var status = apex.item(''P122_STATUS'').getValue() || ''DRAFT'';',
'    plan.grid = new JsonLines({',
'      container: ''#plan_lines'',',
'      readOnly : !DocUtil.canEdit(status),',
'      columns  : [',
'        {name: ''BITEM_ID'', label: '''', type: ''display'', hidden: true},',
unistr('        {name: ''NOTE_NO'',  label: ''\0627\0644\0625\064A\0636\0627\062D'', type: ''display'', width: ''6em''},'),
unistr('        {name: ''NAME_AR'',  label: ''\0627\0644\0628\0646\062F'', type: ''display'', width: ''18em''},'),
unistr('        {name: ''TYPE_T'',   label: ''\0627\0644\0646\0648\0639'', type: ''display'', width: ''6em''},'),
unistr('        {name: ''Q1'', label: ''\0627\0644\0631\0628\0639 \0627\0644\0623\0648\0644'',  type: ''number'', decimals: 2, total: true, width: ''9em''},'),
unistr('        {name: ''Q2'', label: ''\0627\0644\0631\0628\0639 \0627\0644\062B\0627\0646\064A'', type: ''number'', decimals: 2, total: true, width: ''9em''},'),
unistr('        {name: ''Q3'', label: ''\0627\0644\0631\0628\0639 \0627\0644\062B\0627\0644\062B'', type: ''number'', decimals: 2, total: true, width: ''9em''},'),
unistr('        {name: ''Q4'', label: ''\0627\0644\0631\0628\0639 \0627\0644\0631\0627\0628\0639'', type: ''number'', decimals: 2, total: true, width: ''9em''},'),
unistr('        {name: ''TOTAL'', label: ''\0627\0644\0625\062C\0645\0627\0644\064A'', type: ''display'', decimals: 2, total: true, noSubmit: true},'),
unistr('        {name: ''NOTES'', label: ''\0645\0644\0627\062D\0638\0627\062A'', type: ''text'', maxLength: 300, ignoreEmpty: true}'),
'      ],',
'      onChange: function (row) { row.TOTAL = (row.Q1 || 0) + (row.Q2 || 0) + (row.Q3 || 0) + (row.Q4 || 0); }',
'    });',
'    apex.server.process(''INIT_DATA'', {x01: apex.item(''P122_PLAN_ID'').getValue()}, {dataType: ''json''})',
'      .done(function (d) {',
'        (d.lines || []).forEach(function (r) { r.TOTAL = (r.Q1 || 0) + (r.Q2 || 0) + (r.Q3 || 0) + (r.Q4 || 0); });',
'        plan.grid.setData(d.lines || []);',
unistr('        // \0627\0644\0628\0646\0648\062F \0645\0639\0631\0651\0641\0629 \0645\0633\0628\0642\0627\064B: \0644\0627 \0633\0637\0631 \0641\0627\0631\063A \0625\0636\0627\0641\064A'),
'        var last = plan.grid.rows[plan.grid.rows.length - 1];',
'        if (last && !last.BITEM_ID && plan.grid.rows.length > 1) { plan.grid.rows.pop(); plan.grid.render(); }',
'      });',
'    document.addEventListener(''keydown'', function (e) {',
'      if (e.ctrlKey && (e.key === ''s'' || e.key === ''S'')) { e.preventDefault(); plan.save(); }',
'    });',
'  },',
'',
'  save: function () {',
'    var g = function (n) { return apex.item(''P122_'' + n).getValue(); };',
unistr('    if (!g(''FY_YEAR'') || !g(''DEPT_ID'')) { DocUtil.showErrors([''\0627\062E\062A\0631 \0627\0644\0633\0646\0629 \0648\0627\0644\0625\062F\0627\0631\0629'']); return; }'),
'    var doc = {',
'      header: {PLAN_ID: g(''PLAN_ID''), FY_YEAR: g(''FY_YEAR''), DEPT_ID: g(''DEPT_ID''), DESCRIPTION: g(''DESCRIPTION'')},',
'      lines: plan.grid.rows.filter(function (r) { return r.BITEM_ID; }).map(function (r) {',
'        return {BITEM_ID: r.BITEM_ID, Q1: r.Q1, Q2: r.Q2, Q3: r.Q3, Q4: r.Q4, NOTES: r.NOTES};',
'      })',
'    };',
'    DocUtil.save(doc, ''DRAFT'', function (d) {',
'      apex.page.submit({request: ''RELOAD'', set: {P122_PLAN_ID: d.id}, showWait: true});',
'    });',
'  }',
'};'))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'window.APP_ROLE = ''&G_USER_ROLE.'';',
'plan.init();',
'if (apex.item(''P122_STATUS'').getValue() && !DocUtil.canEdit(apex.item(''P122_STATUS'').getValue())) { [''P122_FY_YEAR'',''P122_DEPT_ID'',''P122_DESCRIPTION''].forEach(function (n) { apex.item(n).disable(); }); }'))
