wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000936)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  r budget_plans%ROWTYPE;',
'BEGIN',
'  IF :P122_PLAN_ID IS NULL AND :P122_FY_YEAR IS NOT NULL AND :P122_DEPT_ID IS NOT NULL THEN',
'    SELECT MAX(plan_id) INTO :P122_PLAN_ID FROM budget_plans WHERE fy_year = :P122_FY_YEAR AND dept_id = :P122_DEPT_ID;',
'  END IF;',
'  :P122_STATUS := NULL;',
'  IF :P122_PLAN_ID IS NOT NULL THEN',
'    SELECT * INTO r FROM budget_plans WHERE plan_id = :P122_PLAN_ID;',
'    :P122_FY_YEAR     := r.fy_year;',
'    :P122_DEPT_ID     := r.dept_id;',
'    :P122_DESCRIPTION := r.description;',
'    :P122_STATUS      := r.status;',
'    :P122_RETURN_NOTE := CASE WHEN r.status IN (''RETURNED'',''DRAFT'') THEN r.return_note END;',
unistr(':P122_WF_INFO := TRIM(CASE WHEN r.reviewed_by IS NOT NULL THEN ''\0631\0627\062C\0639\0647 '' || r.reviewed_by || '' '' || TO_CHAR(r.reviewed_on, ''DD/MM/YYYY HH24:MI'') END || CASE WHEN r.approved_by IS NOT NULL THEN '' - \0627\0639\062A\0645\062F\0647 '' || r.approved_by || '' '' || TO_CHAR(r.approved_on, ''DD/MM/YYYY HH24:MI'') END);'),
'  END IF;',
'END;'))
,p_process_type=>'NATIVE_PLSQL'
,p_process_clob_language=>'PLSQL'
,p_process_name=>'LOAD'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000936
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000937)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('  -- \0643\0644 \0628\0646\0648\062F \0627\0644\0645\064A\0632\0627\0646\064A\0629 \0627\0644\0641\0639\0651\0627\0644\0629 \0645\0639 \0642\064A\0645 \062E\0637\0629 \0627\0644\0625\062F\0627\0631\0629 (x01 = \0631\0642\0645 \0627\0644\062E\0637\0629)'),
'  l_lines CLOB;',
'BEGIN',
'  SELECT JSON_ARRAYAGG(JSON_OBJECT(',
'           ''BITEM_ID'' VALUE b.bitem_id, ''NOTE_NO'' VALUE b.note_no, ''NAME_AR'' VALUE b.name_ar,',
unistr('           ''TYPE_T''   VALUE DECODE(b.item_type, ''REV'', ''\0625\064A\0631\0627\062F\0627\062A'', ''\0645\0635\0631\0648\0641\0627\062A''),'),
'           ''Q1'' VALUE NULLIF(l.q1, 0), ''Q2'' VALUE NULLIF(l.q2, 0), ''Q3'' VALUE NULLIF(l.q3, 0), ''Q4'' VALUE NULLIF(l.q4, 0),',
'           ''NOTES'' VALUE l.notes)',
'         ORDER BY b.sort_order, b.note_no RETURNING CLOB)',
'  INTO   l_lines',
'  FROM   budget_items b',
'  LEFT JOIN budget_plan_lines l ON l.bitem_id = b.bitem_id AND l.plan_id = TO_NUMBER(apex_application.g_x01)',
'  WHERE  b.is_active = ''Y'' OR l.pline_id IS NOT NULL;',
'',
'  apex_util.prn(''{"lines":'' || COALESCE(l_lines, TO_CLOB(''[]'')) || ''}'', FALSE);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_name=>'INIT_DATA'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000937
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000938)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('  -- \062D\0641\0638 \062E\0637\0629 \0625\062F\0627\0631\0629 \0644\0633\0646\0629 (Ajax: p_clob_01 = {header, lines})'),
'  l_clob CLOB := apex_application.g_clob_01;',
'  l_errs apex_t_varchar2 := apex_t_varchar2();',
'  l_id   NUMBER; l_year NUMBER; l_dept NUMBER; l_desc VARCHAR2(500); l_st VARCHAR2(10);',
'  l_co   NUMBER := NVL(:G_COMPANY_ID, :G_PARENT_ID);',
'  PROCEDURE err (p VARCHAR2) IS BEGIN l_errs.EXTEND; l_errs(l_errs.COUNT) := p; END;',
'BEGIN',
'  SELECT h.plan_id, h.fy_year, h.dept_id, h.description',
'  INTO   l_id, l_year, l_dept, l_desc',
'  FROM   JSON_TABLE(l_clob, ''$.header'' COLUMNS (',
'           plan_id NUMBER PATH ''$.PLAN_ID'', fy_year NUMBER PATH ''$.FY_YEAR'',',
'           dept_id NUMBER PATH ''$.DEPT_ID'', description VARCHAR2(500) PATH ''$.DESCRIPTION'')) h;',
'',
unistr('  IF :G_USER_ROLE NOT IN (''ADMIN'',''ENTRY'') THEN err(''\0625\062F\062E\0627\0644 \0627\0644\062E\0637\0629 \0645\0646 \0635\0644\0627\062D\064A\0629 \0627\0644\0645\062F\062E\0644''); END IF;'),
unistr('  IF l_year IS NULL OR l_dept IS NULL THEN err(''\0627\062E\062A\0631 \0627\0644\0633\0646\0629 \0648\0627\0644\0625\062F\0627\0631\0629''); END IF;'),
'  IF l_id IS NULL THEN',
'    SELECT MAX(plan_id) INTO l_id FROM budget_plans WHERE fy_year = l_year AND dept_id = l_dept;',
'  END IF;',
'  IF l_id IS NOT NULL THEN',
'    SELECT status INTO l_st FROM budget_plans WHERE plan_id = l_id FOR UPDATE;',
unistr('    IF l_st NOT IN (''DRAFT'',''RETURNED'') THEN err(''\062E\0637\0629 \0647\0630\0647 \0627\0644\0625\062F\0627\0631\0629 \0644\0647\0630\0647 \0627\0644\0633\0646\0629 \062A\0645\062A \0645\0631\0627\062C\0639\062A\0647\0627 \0623\0648 \0627\0639\062A\0645\0627\062F\0647\0627 \0648\0644\0627 \064A\0645\0643\0646 \062A\0639\062F\064A\0644\0647\0627''); END IF;'),
'  END IF;',
'  FOR r IN (SELECT * FROM JSON_TABLE(l_clob, ''$.lines[*]'' COLUMNS (',
'               q1 NUMBER PATH ''$.Q1'', q2 NUMBER PATH ''$.Q2'', q3 NUMBER PATH ''$.Q3'', q4 NUMBER PATH ''$.Q4''))) LOOP',
'    IF NVL(r.q1, 0) < 0 OR NVL(r.q2, 0) < 0 OR NVL(r.q3, 0) < 0 OR NVL(r.q4, 0) < 0 THEN',
unistr('      err(''\0644\0627 \062A\064F\0642\0628\0644 \0645\0628\0627\0644\063A \0633\0627\0644\0628\0629''); EXIT;'),
'    END IF;',
'  END LOOP;',
'',
'  IF l_errs.COUNT > 0 THEN',
'    ROLLBACK;',
'    apex_json.open_object; apex_json.write(''ok'', FALSE); apex_json.write(''errors'', l_errs); apex_json.close_object;',
'    RETURN;',
'  END IF;',
'',
'  IF l_id IS NULL THEN',
'    INSERT INTO budget_plans (company_id, fy_year, dept_id, description, created_by)',
'    VALUES (l_co, l_year, l_dept, l_desc, :APP_USER)',
'    RETURNING plan_id INTO l_id;',
'  ELSE',
'    UPDATE budget_plans SET description = l_desc, status = ''DRAFT'', return_note = NULL WHERE plan_id = l_id;',
'    DELETE FROM budget_plan_lines WHERE plan_id = l_id;',
'  END IF;',
'',
'  INSERT INTO budget_plan_lines (plan_id, bitem_id, q1, q2, q3, q4, notes)',
'  SELECT l_id, bitem_id, NVL(q1, 0), NVL(q2, 0), NVL(q3, 0), NVL(q4, 0), notes',
'  FROM   JSON_TABLE(l_clob, ''$.lines[*]'' COLUMNS (',
'           bitem_id NUMBER PATH ''$.BITEM_ID'', q1 NUMBER PATH ''$.Q1'', q2 NUMBER PATH ''$.Q2'',',
'           q3 NUMBER PATH ''$.Q3'', q4 NUMBER PATH ''$.Q4'', notes VARCHAR2(300) PATH ''$.NOTES''))',
'  WHERE  bitem_id IS NOT NULL',
'  AND    (NVL(q1, 0) + NVL(q2, 0) + NVL(q3, 0) + NVL(q4, 0) > 0 OR notes IS NOT NULL);',
'',
'  INSERT INTO doc_actions (doc_type, doc_id, action, from_status, to_status, action_by)',
'  VALUES (''BUDGET_PLAN'', l_id, ''SAVE'', l_st, ''DRAFT'', :APP_USER);',
'',
'  apex_json.open_object;',
'  apex_json.write(''ok'', TRUE);',
'  apex_json.write(''id'', l_id);',
unistr('  apex_json.write(''message'', ''\062A\0645 \062D\0641\0638 \0627\0644\062E\0637\0629 - \0628\0627\0646\062A\0638\0627\0631 \0627\0644\0645\0631\0627\062C\0639\0629'');'),
'  apex_json.close_object;',
'EXCEPTION WHEN OTHERS THEN',
'  ROLLBACK;',
'  apex_json.open_object; apex_json.write(''ok'', FALSE);',
'  apex_json.open_array(''errors''); apex_json.write(SQLERRM); apex_json.close_array;',
'  apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_name=>'SAVE_DOC'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000938
);
