,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(6697232433757451)
,p_plug_display_sequence=>10
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_ctx  apex_exec.t_context;',
'  l_col  apex_exec.t_column;',
'  l_val  VARCHAR2(4000);',
'BEGIN',
'  l_ctx := apex_exec.open_query_context(',
'             p_location  => apex_exec.c_location_local_db,',
'             p_sql_query => q''~WITH pl AS (',
unistr('  -- \062E\0637\0629 \0643\0644 \0625\062F\0627\0631\0629 \0644\0643\0644 \0628\0646\062F (\0627\0644\062E\0637\0637 \0627\0644\0645\0639\062A\0645\062F\0629 \0623\0648 \0643\0644\0647\0627 \062D\0633\0628 \0627\0644\0627\062E\062A\064A\0627\0631)'),
'  SELECT l.bitem_id, d.dept_code, d.name_ar dept, l.q1, l.q2, l.q3, l.q4',
'  FROM   budget_plan_lines l',
'  JOIN   budget_plans p ON p.plan_id = l.plan_id AND p.fy_year = TO_NUMBER(:P123_FY_YEAR)',
'                       AND (NVL(:P123_ONLY_APPROVED, ''N'') = ''N'' OR p.status = ''APPROVED'')',
'  JOIN   departments d ON d.dept_id = p.dept_id',
'), act AS (',
unistr('  -- \0627\0644\0641\0639\0644\064A \0645\0646 \0627\0644\0642\064A\0648\062F \0627\0644\0645\0631\062D\0651\0644\0629 \0644\062D\0633\0627\0628 \0627\0644\0628\0646\062F \0648\0645\0627 \062A\062D\062A\0647 \0628\0627\0644\0623\0631\0628\0627\0639'),
'  SELECT b.bitem_id,',
'         SUM(CASE WHEN TO_CHAR(j.journal_date, ''Q'') = ''1'' THEN x.amt END) a1,',
'         SUM(CASE WHEN TO_CHAR(j.journal_date, ''Q'') = ''2'' THEN x.amt END) a2,',
'         SUM(CASE WHEN TO_CHAR(j.journal_date, ''Q'') = ''3'' THEN x.amt END) a3,',
'         SUM(CASE WHEN TO_CHAR(j.journal_date, ''Q'') = ''4'' THEN x.amt END) a4',
'  FROM   budget_items b',
'  JOIN   accounts pa ON pa.account_id = b.account_id',
'  JOIN   accounts a  ON a.account_code LIKE pa.account_code || ''%''',
'  JOIN   journal_lines jl ON jl.account_id = a.account_id',
'  JOIN   journals j ON j.journal_id = jl.journal_id AND j.status = ''POSTED''',
'                   AND EXTRACT(YEAR FROM j.journal_date) = TO_NUMBER(:P123_FY_YEAR)',
'  CROSS APPLY (SELECT CASE b.item_type WHEN ''EXP'' THEN jl.debit_base - jl.credit_base',
'                                       ELSE jl.credit_base - jl.debit_base END amt FROM dual) x',
'  GROUP BY b.bitem_id',
'), tot AS (',
'  SELECT bitem_id, SUM(q1) q1, SUM(q2) q2, SUM(q3) q3, SUM(q4) q4 FROM pl GROUP BY bitem_id',
')',
unistr('SELECT r.sort_key, r.note_no AS "\0631\0642\0645 \0627\0644\0625\064A\0636\0627\062D", r.item_name AS "\0627\0644\0628\0646\062F", r.line_label AS "\0627\0644\0625\062F\0627\0631\0629 / \0627\0644\0628\064A\0627\0646",'),
unistr('       r.q1 AS "\0627\0644\0631\0628\0639 \0627\0644\0623\0648\0644", r.q2 AS "\0627\0644\0631\0628\0639 \0627\0644\062B\0627\0646\064A", r.q3 AS "\0627\0644\0631\0628\0639 \0627\0644\062B\0627\0644\062B", r.q4 AS "\0627\0644\0631\0628\0639 \0627\0644\0631\0627\0628\0639",'),
unistr('       NVL(r.q1, 0) + NVL(r.q2, 0) + NVL(r.q3, 0) + NVL(r.q4, 0) AS "\0627\0644\0625\062C\0645\0627\0644\064A"'),
'FROM (',
'  SELECT LPAD(b.sort_order, 6, ''0'') || b.note_no || ''1'' || pl.dept_code sort_key, b.note_no, b.name_ar item_name,',
'         pl.dept line_label, pl.q1, pl.q2, pl.q3, pl.q4',
'  FROM   budget_items b JOIN pl ON pl.bitem_id = b.bitem_id',
'  UNION ALL',
unistr('  SELECT LPAD(b.sort_order, 6, ''0'') || b.note_no || ''2'', b.note_no, b.name_ar, ''\0625\062C\0645\0627\0644\064A \0627\0644\062E\0637\0629'', t.q1, t.q2, t.q3, t.q4'),
'  FROM   budget_items b JOIN tot t ON t.bitem_id = b.bitem_id',
'  UNION ALL',
unistr('  SELECT LPAD(b.sort_order, 6, ''0'') || b.note_no || ''3'', b.note_no, b.name_ar, ''\0627\0644\0641\0639\0644\064A'', a.a1, a.a2, a.a3, a.a4'),
'  FROM   budget_items b JOIN act a ON a.bitem_id = b.bitem_id',
'  WHERE  b.account_id IS NOT NULL',
'  UNION ALL',
unistr('  SELECT LPAD(b.sort_order, 6, ''0'') || b.note_no || ''4'', b.note_no, b.name_ar, ''\0627\0644\0627\0646\062D\0631\0627\0641 (\0627\0644\0641\0639\0644\064A - \0627\0644\062E\0637\0629)'','),
'         NVL(a.a1, 0) - NVL(t.q1, 0), NVL(a.a2, 0) - NVL(t.q2, 0), NVL(a.a3, 0) - NVL(t.q3, 0), NVL(a.a4, 0) - NVL(t.q4, 0)',
'  FROM   budget_items b LEFT JOIN tot t ON t.bitem_id = b.bitem_id LEFT JOIN act a ON a.bitem_id = b.bitem_id',
'  WHERE  b.account_id IS NOT NULL AND (t.bitem_id IS NOT NULL OR a.bitem_id IS NOT NULL)',
') r',
'JOIN budget_items bi ON bi.note_no = r.note_no',
'WHERE :P123_BITEM_ID IS NULL OR bi.bitem_id = TO_NUMBER(:P123_BITEM_ID)',
'ORDER BY r.sort_key',
'~'');',
'  htp.p(''<div style="overflow-x:auto"><table class="jl-table"><thead><tr>'');',
'  FOR i IN 1 .. apex_exec.get_column_count(l_ctx) LOOP',
'    l_col := apex_exec.get_column(l_ctx, i);',
unistr('    IF l_col.name NOT LIKE ''%\005C_ID'' ESCAPE ''\005C'' AND l_col.name <> ''SORT_KEY'' THEN'),
'      htp.p(''<th>'' || apex_escape.html(l_col.name) || ''</th>'');',
'    END IF;',
'  END LOOP;',
'  htp.p(''</tr></thead><tbody>'');',
'  WHILE apex_exec.next_row(l_ctx) LOOP',
'    htp.p(''<tr>'');',
'    FOR i IN 1 .. apex_exec.get_column_count(l_ctx) LOOP',
'      l_col := apex_exec.get_column(l_ctx, i);',
unistr('      IF l_col.name NOT LIKE ''%\005C_ID'' ESCAPE ''\005C'' AND l_col.name <> ''SORT_KEY'' THEN'),
'        IF l_col.data_type = apex_exec.c_data_type_number THEN',
unistr('          l_val := TO_CHAR(apex_exec.get_number(l_ctx, i), CASE WHEN l_col.name LIKE ''\0639\062F\062F%'' THEN ''FM999G999G990'' ELSE ''FM999G999G999G999G990D00'' END);'),
'          htp.p(''<td class="jl-num">'' || l_val || ''</td>'');',
'        ELSE',
'          htp.p(''<td>'' || apex_escape.html(apex_exec.get_varchar2(l_ctx, i)) || ''</td>'');',
'        END IF;',
'      END IF;',
'    END LOOP;',
'    htp.p(''</tr>'');',
'  END LOOP;',
'  htp.p(''</tbody></table></div>'');',
'  apex_exec.close(l_ctx);',
'EXCEPTION WHEN OTHERS THEN',
'  apex_exec.close(l_ctx);',
'  RAISE;',
'END;'))
,p_plug_source_type=>'NATIVE_PLSQL'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000946)
,p_process_sequence=>5
,p_process_point=>'BEFORE_HEADER'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P123_FY_YEAR IS NULL THEN :P123_FY_YEAR := TO_CHAR(SYSDATE, ''YYYY''); END IF;',
'IF :P123_ONLY_APPROVED IS NULL THEN :P123_ONLY_APPROVED := ''N''; END IF;'))
,p_process_type=>'NATIVE_PLSQL'
,p_process_clob_language=>'PLSQL'
,p_process_name=>'DEFAULTS'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000946
);
