wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(91000000000951)
,p_plug_name=>unistr('\0627\0644\0645\0624\0634\0631\0627\062A')
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(6697232433757451)
,p_plug_display_sequence=>10
,p_plug_grid_column_span=>4
,p_location=>null
,p_plug_source_type=>'NATIVE_PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_ctx  apex_exec.t_context;',
'  l_col  apex_exec.t_column;',
'  l_val  VARCHAR2(4000);',
'BEGIN',
'  l_ctx := apex_exec.open_query_context(',
'             p_location  => apex_exec.c_location_local_db,',
'             p_sql_query => q''~WITH mv AS (',
'  SELECT j.company_id, c.name_ar company, j.journal_date, a.acc_type, a.account_code, a.cash_bank,',
'         l.debit_base - l.credit_base AS bal, l.partner_company_id',
'  FROM journals j',
'  JOIN journal_lines l ON l.journal_id = j.journal_id',
'  JOIN accounts a ON a.account_id = l.account_id',
'  JOIN companies c ON c.company_id = j.company_id',
'  WHERE j.status IN (''POSTED'',''REVERSED'')',
'  AND (:P1_COMPANY_ID IS NULL OR j.company_id = :P1_COMPANY_ID)',
'  AND (:G_USER_ROLE = ''ADMIN'' OR j.company_id = :G_COMPANY_ID)',
'  AND (NVL(:P1_MODE,''SEP'') = ''SEP'' OR l.partner_company_id IS NULL)',
')',
unistr('SELECT ''\0627\0644\0645\0628\064A\0639\0627\062A'' AS "\0627\0644\0628\064A\0627\0646",'),
unistr('       TO_CHAR(-SUM(CASE WHEN account_code LIKE ''41%'' AND EXTRACT(YEAR FROM journal_date) = :P1_YEAR THEN bal END), ''FM999G999G999G990'') AS "\0627\0644\0642\064A\0645\0629"'),
'FROM mv',
'UNION ALL',
unistr('SELECT ''\062A\0643\0644\0641\0629 \0627\0644\0645\0628\064A\0639\0627\062A'','),
'       TO_CHAR(SUM(CASE WHEN account_code LIKE ''51%'' AND EXTRACT(YEAR FROM journal_date) = :P1_YEAR THEN bal END), ''FM999G999G999G990'')',
'FROM mv',
'UNION ALL',
unistr('SELECT ''\0627\0644\0645\0635\0631\0648\0641\0627\062A'','),
'       TO_CHAR(SUM(CASE WHEN account_code LIKE ''52%'' AND EXTRACT(YEAR FROM journal_date) = :P1_YEAR THEN bal END), ''FM999G999G999G990'')',
'FROM mv',
'UNION ALL',
unistr('SELECT ''\0635\0627\0641\064A \0627\0644\0631\0628\062D'','),
'       TO_CHAR(-SUM(CASE WHEN acc_type IN (''REV'',''EXP'') AND EXTRACT(YEAR FROM journal_date) = :P1_YEAR THEN bal END), ''FM999G999G999G990'')',
'FROM mv',
'UNION ALL',
unistr('SELECT ''\0627\0644\0646\0642\062F\064A\0629 \0648\0627\0644\0628\0646\0648\0643'', TO_CHAR(SUM(CASE WHEN cash_bank IN (''C'',''B'') THEN bal END), ''FM999G999G999G990'')'),
'FROM mv',
'UNION ALL',
unistr('SELECT ''\0630\0645\0645 \0627\0644\0639\0645\0644\0627\0621'', TO_CHAR(SUM(CASE WHEN account_code LIKE ''1106%'' THEN bal END), ''FM999G999G999G990'')'),
'FROM mv',
'UNION ALL',
unistr('SELECT ''\0642\064A\0645\0629 \0627\0644\0645\062E\0632\0648\0646'', TO_CHAR((SELECT ROUND(SUM(qty_base * avg_cost)) FROM v_stock_balance'),
'                                WHERE :P1_COMPANY_ID IS NULL OR company_id = :P1_COMPANY_ID), ''FM999G999G999G990'')',
'FROM dual',
'~'');',
'  htp.p(''<div style="overflow-x:auto"><table class="jl-table"><thead><tr>'');',
'  FOR i IN 1 .. apex_exec.get_column_count(l_ctx) LOOP',
'    l_col := apex_exec.get_column(l_ctx, i);',
unistr('    IF l_col.name NOT LIKE ''%\005C_ID'' ESCAPE ''\005C'' AND l_col.name <> ''SORT_KEY'' THEN'),
'      htp.p(''<th>'' || apex_escape.html(l_col.name) || ''</th>'');',
'    END IF;',
'  END LOOP;',
'  htp.p(''</tr></thead><tbody>'');',
'  WHILE apex_exec.next_row(l_ctx) LOOP',
'    htp.p(''<tr>'');',
'    FOR i IN 1 .. apex_exec.get_column_count(l_ctx) LOOP',
'      l_col := apex_exec.get_column(l_ctx, i);',
unistr('      IF l_col.name NOT LIKE ''%\005C_ID'' ESCAPE ''\005C'' AND l_col.name <> ''SORT_KEY'' THEN'),
'        IF l_col.data_type = apex_exec.c_data_type_number THEN',
unistr('          l_val := TO_CHAR(apex_exec.get_number(l_ctx, i), CASE WHEN l_col.name LIKE ''\0639\062F\062F%'' THEN ''FM999G999G990'' ELSE ''FM999G999G999G999G990D00'' END);'),
'          htp.p(''<td class="jl-num">'' || l_val || ''</td>'');',
'        ELSE',
'          htp.p(''<td>'' || apex_escape.html(apex_exec.get_varchar2(l_ctx, i)) || ''</td>'');',
'        END IF;',
'      END IF;',
'    END LOOP;',
'    htp.p(''</tr>'');',
'  END LOOP;',
'  htp.p(''</tbody></table></div>'');',
'  apex_exec.close(l_ctx);',
'EXCEPTION WHEN OTHERS THEN',
'  apex_exec.close(l_ctx);',
'  RAISE;',
'END;'))
);
