'  l_val  VARCHAR2(4000);',
'BEGIN',
'  l_ctx := apex_exec.open_query_context(',
'             p_location  => apex_exec.c_location_local_db,',
unistr('             p_sql_query => q''~-- \0627\0644\062A\0648\0627\0644\0641 \063A\064A\0631 \0627\0644\0645\0635\0641\0651\0627\0629 (\062A\0646\062A\0638\0631 \0642\0631\0627\0631 \0627\0644\0645\062F\064A\0631 \0628\0627\0644\062A\0635\0641\064A\0631): \0644\0643\0644 \0645\062E\0632\0646 \0648\0635\0646\0641 \0628\0627\0644\0648\062D\062F\0629 \0627\0644\0635\063A\0631\0649 \0648\0642\064A\0645\062A\0647\0627 \0628\0633\0639\0631 \0627\0644\0634\0631\0627\0621'),
'WITH d AS (',
'  SELECT w.name_ar wh, i.item_code, i.name_ar item, un.name_ar unit, d.qty_base qty, NVL(i.purchase_price, 0) price',
'  FROM   v_damaged_balance d',
'  JOIN   warehouses w ON w.warehouse_id = d.warehouse_id',
'  JOIN   items i      ON i.item_id      = d.item_id',
'  JOIN   units un     ON un.unit_id     = i.base_unit_id',
'  WHERE  d.qty_base > 0',
'  AND    (:P1_COMPANY_ID IS NULL OR w.company_id = TO_NUMBER(:P1_COMPANY_ID))',
')',
unistr('SELECT wh || LPAD(item_code, 20, ''0'') AS sort_key, wh AS "\0627\0644\0645\062E\0632\0646", item_code AS "\0627\0644\0643\0648\062F", item AS "\0627\0644\0635\0646\0641",'),
unistr('       qty AS "\0627\0644\0643\0645\064A\0629 \0627\0644\062A\0627\0644\0641\0629", unit AS "\0627\0644\0648\062D\062F\0629", ROUND(qty * price, 2) AS "\0627\0644\0642\064A\0645\0629"'),
'FROM   d',
'UNION ALL',
unistr('SELECT ''zzzz'', NULL, NULL, ''\0625\062C\0645\0627\0644\064A \0627\0644\062A\0648\0627\0644\0641 \063A\064A\0631 \0627\0644\0645\0635\0641\0651\0627\0629'', NULL, NULL, NVL(SUM(ROUND(qty * price, 2)), 0)'),
'FROM   d',
'ORDER  BY 1',
'~'');',
'  htp.p(''<div style="overflow-x:auto"><table class="jl-table"><thead><tr>'');',
'  FOR i IN 1 .. apex_exec.get_column_count(l_ctx) LOOP',
'    l_col := apex_exec.get_column(l_ctx, i);',
unistr('    IF l_col.name NOT LIKE ''%\005C_ID'' ESCAPE ''\005C'' AND l_col.name <> ''SORT_KEY'' THEN'),
'      htp.p(''<th>'' || apex_escape.html(l_col.name) || ''</th>'');',
