,p_plug_name=>unistr('\0623\0635\0646\0627\0641 \0642\0627\0631\0628\062A \0627\0646\062A\0647\0627\0621 \0627\0644\0635\0644\0627\062D\064A\0629 (\062E\0644\0627\0644 3 \0623\0634\0647\0631)')
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(6697232433757451)
,p_plug_display_sequence=>50
,p_plug_grid_column_span=>6
,p_plug_new_grid_row=>false
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_ctx  apex_exec.t_context;',
'  l_col  apex_exec.t_column;',
'  l_val  VARCHAR2(4000);',
'BEGIN',
'  l_ctx := apex_exec.open_query_context(',
'             p_location  => apex_exec.c_location_local_db,',
unistr('             p_sql_query => q''~-- \0623\0635\0646\0627\0641 \0642\0627\0631\0628\062A \0627\0646\062A\0647\0627\0621 \0627\0644\0635\0644\0627\062D\064A\0629 \062E\0644\0627\0644 3 \0623\0634\0647\0631 (\0623\0648 \0627\0646\062A\0647\062A) \0645\0639 \0643\0645\064A\0627\062A\0647\0627 \0628\0627\0644\0645\062E\0632\0646'),
unistr('SELECT i.item_id, i.item_code AS "\0627\0644\0643\0648\062F", i.name_ar AS "\0627\0644\0635\0646\0641",'),
unistr('       TO_CHAR(i.expiry_date, ''DD/MM/YYYY'') AS "\062A\0627\0631\064A\062E \0627\0644\0635\0644\0627\062D\064A\0629",'),
unistr('       TRUNC(i.expiry_date) - TRUNC(SYSDATE) AS "\0639\062F\062F \0627\0644\0623\064A\0627\0645 \0627\0644\0645\062A\0628\0642\064A\0629",'),
unistr('       CASE WHEN i.expiry_date < TRUNC(SYSDATE) THEN ''\0645\0646\062A\0647\064A \0627\0644\0635\0644\0627\062D\064A\0629'''),
unistr('            WHEN i.expiry_date <= ADD_MONTHS(TRUNC(SYSDATE), 1) THEN ''\0623\0642\0644 \0645\0646 \0634\0647\0631'''),
unistr('            ELSE ''\062E\0644\0627\0644 3 \0623\0634\0647\0631'' END AS "\0627\0644\062A\0646\0628\064A\0647",'),
unistr('       un.name_ar AS "\0627\0644\0648\062D\062F\0629 \0627\0644\0635\063A\0631\0649",'),
unistr('       NVL((SELECT SUM(b.qty_base) FROM v_stock_balance b WHERE b.item_id = i.item_id), 0) AS "\0627\0644\0643\0645\064A\0629 \0628\0627\0644\0645\062E\0632\0646",'),
unistr('       NVL((SELECT SUM(b.value_base) FROM v_stock_balance b WHERE b.item_id = i.item_id), 0) AS "\0627\0644\0642\064A\0645\0629"'),
'FROM   items i JOIN units un ON un.unit_id = i.base_unit_id',
'WHERE  i.is_active = ''Y'' AND i.expiry_date IS NOT NULL',
'AND    i.expiry_date <= ADD_MONTHS(TRUNC(SYSDATE), 3)',
'ORDER BY i.expiry_date',
'~'');',
'  htp.p(''<div style="overflow-x:auto"><table class="jl-table"><thead><tr>'');',
'  FOR i IN 1 .. apex_exec.get_column_count(l_ctx) LOOP',
'    l_col := apex_exec.get_column(l_ctx, i);',
unistr('    IF l_col.name NOT LIKE ''%\005C_ID'' ESCAPE ''\005C'' AND l_col.name <> ''SORT_KEY'' THEN'),
'      htp.p(''<th>'' || apex_escape.html(l_col.name) || ''</th>'');',
'    END IF;',
'  END LOOP;',
'  htp.p(''</tr></thead><tbody>'');',
'  WHILE apex_exec.next_row(l_ctx) LOOP',
'    htp.p(''<tr>'');',
'    FOR i IN 1 .. apex_exec.get_column_count(l_ctx) LOOP',
'      l_col := apex_exec.get_column(l_ctx, i);',
unistr('      IF l_col.name NOT LIKE ''%\005C_ID'' ESCAPE ''\005C'' AND l_col.name <> ''SORT_KEY'' THEN'),
'        IF l_col.data_type = apex_exec.c_data_type_number THEN',
unistr('          l_val := TO_CHAR(apex_exec.get_number(l_ctx, i), CASE WHEN l_col.name LIKE ''\0639\062F\062F%'' THEN ''FM999G999G990'' ELSE ''FM999G999G999G999G990D00'' END);'),
'          htp.p(''<td class="jl-num">'' || l_val || ''</td>'');',
'        ELSE',
'          htp.p(''<td>'' || apex_escape.html(apex_exec.get_varchar2(l_ctx, i)) || ''</td>'');',
'        END IF;',
'      END IF;',
'    END LOOP;',
'    htp.p(''</tr>'');',
'  END LOOP;',
'  htp.p(''</tbody></table></div>'');',
'  apex_exec.close(l_ctx);',
'EXCEPTION WHEN OTHERS THEN',
'  apex_exec.close(l_ctx);',
'  RAISE;',
'END;'))
,p_plug_source_type=>'NATIVE_PLSQL'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000000956)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_clob_language=>'PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P1_YEAR IS NULL THEN :P1_YEAR := TO_CHAR(SYSDATE, ''YYYY''); END IF;',
'IF :P1_MODE IS NULL THEN :P1_MODE := ''SEP''; END IF;'))
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'DEFAULTS'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>91000000000956
);
end;
