);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000001093)
,p_process_sequence=>5
,p_process_point=>'AFTER_SUBMIT'
,p_process_clob_language=>'PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_err VARCHAR2(4000);',
'FUNCTION chk RETURN VARCHAR2 IS',
'',
'  FUNCTION n (p VARCHAR2) RETURN NUMBER IS BEGIN RETURN TO_NUMBER(REPLACE(p, '','')); EXCEPTION WHEN OTHERS THEN RETURN NULL; END;',
'BEGIN',
'RETURN CASE',
unistr('  WHEN NVL(n(:P211_BIG_FACTOR), 0) <= 0 THEN ''\0623\062F\062E\0644 \0645\0627 \062A\0639\0627\062F\0644\0647 \0627\0644\0648\062D\062F\0629 \0627\0644\0643\0628\0631\0649 \0645\0646 \0627\0644\0648\062D\062F\0627\062A \0627\0644\0635\063A\0631\0649'''),
unistr('  WHEN :P211_BIG_UNIT_ID = :P211_BASE_UNIT_ID AND n(:P211_BIG_FACTOR) <> 1 THEN ''\0627\0644\0648\062D\062F\0629 \0627\0644\0643\0628\0631\0649 \0647\064A \0646\0641\0633\0647\0627 \0627\0644\0635\063A\0631\0649: \0645\0627 \062A\0639\0627\062F\0644\0647 \064A\062C\0628 \0623\0646 \064A\0643\0648\0646 1'''),
unistr('  WHEN :P211_BIG_UNIT_ID <> :P211_BASE_UNIT_ID AND n(:P211_BIG_FACTOR) <= 1 THEN ''\0627\0644\0648\062D\062F\0629 \0627\0644\0643\0628\0631\0649 \062A\0639\0627\062F\0644 \0623\0643\062B\0631 \0645\0646 \0648\062D\062F\0629 \0635\063A\0631\0649 \0648\0627\062D\062F\0629'''),
unistr('  WHEN NVL(n(:P211_BIG_PURCHASE_PRICE), 0) <= 0 THEN ''\0623\062F\062E\0644 \0633\0639\0631 \0627\0644\0634\0631\0627\0621 \0644\0644\0648\062D\062F\0629 \0627\0644\0643\0628\0631\0649'''),
unistr('  WHEN NVL(n(:P211_BIG_SALE_PRICE), 0) <= 0 THEN ''\0623\062F\062E\0644 \0633\0639\0631 \0627\0644\0628\064A\0639 \0644\0644\0648\062D\062F\0629 \0627\0644\0643\0628\0631\0649'''),
'END;',
'END;',
'BEGIN',
'  l_err := chk;',
'  IF l_err IS NOT NULL THEN',
'    apex_error.add_error(p_message => l_err, p_display_location => apex_error.c_inline_in_notification);',
'  END IF;',
'END;'))
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CHECK_UNITS'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'CREATE,SAVE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_internal_uid=>91000000001093
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000001094)
,p_process_sequence=>7
,p_process_point=>'AFTER_SUBMIT'
,p_process_clob_language=>'PLSQL'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  IF :REQUEST = ''CREATE'' THEN',
'    SELECT TO_CHAR(NVL(MAX(TO_NUMBER(item_code DEFAULT NULL ON CONVERSION ERROR)), 0) + 1) INTO :P211_ITEM_CODE FROM items;',
'  END IF;',
'  :P211_PURCHASE_PRICE := TO_CHAR(ROUND(TO_NUMBER(REPLACE(:P211_BIG_PURCHASE_PRICE, '','')) / TO_NUMBER(REPLACE(:P211_BIG_FACTOR, '','')), 2));',
'  :P211_SALE_PRICE     := TO_CHAR(ROUND(TO_NUMBER(REPLACE(:P211_BIG_SALE_PRICE, '',''))     / TO_NUMBER(REPLACE(:P211_BIG_FACTOR, '','')), 2));',
'  :P211_IS_ACTIVE      := NVL(:P211_IS_ACTIVE, ''N'');',
'END;'))
,p_process_name=>'PREPARE'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'CREATE,SAVE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_internal_uid=>91000000001094
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000001095)
,p_process_sequence=>15
,p_process_point=>'AFTER_SUBMIT'
,p_process_clob_language=>'PLSQL'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_id NUMBER;',
'BEGIN',
'  SELECT item_id INTO l_id FROM items WHERE item_code = :P211_ITEM_CODE;',
'  MERGE INTO item_units u',
'  USING (SELECT item_id, base_unit_id unit_id, 1 factor FROM items WHERE item_id = l_id',
'         UNION ALL',
'         SELECT item_id, big_unit_id, big_factor FROM items WHERE item_id = l_id AND big_unit_id <> base_unit_id AND big_factor > 1) s',
'  ON (u.item_id = s.item_id AND u.unit_id = s.unit_id)',
'  WHEN MATCHED THEN UPDATE SET u.factor = s.factor',
'  WHEN NOT MATCHED THEN INSERT (item_id, unit_id, factor) VALUES (s.item_id, s.unit_id, s.factor);',
'END;'))
,p_process_name=>'SYNC_UNITS'
