wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000001374)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_clob_language=>'PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE a accounts%ROWTYPE;',
'BEGIN',
'  SELECT * INTO a FROM accounts WHERE account_id = :P10_ACCOUNT_ID;',
'  :P10_PARENT_ID := a.parent_id; :P10_ACC_LEVEL := a.acc_level; :P10_ACCOUNT_CODE := a.account_code;',
'  :P10_NAME_AR := a.name_ar; :P10_NAME_EN := a.name_en; :P10_ACC_TYPE := a.acc_type; :P10_NATURE := a.nature;',
'  :P10_CASH_BANK := a.cash_bank; :P10_CURRENCY_CODE := a.currency_code; :P10_COMPANY_ID := a.company_id;',
'  :P10_IS_ACTIVE := a.is_active;',
'END;'))
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'LOAD'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':P10_ACCOUNT_ID IS NOT NULL'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>91000000001374
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000001375)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_clob_language=>'PLSQL'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  PROCEDURE s IS',
'  BEGIN',
'    NULL;',
'  END;',
'BEGIN',
'  IF :P10_IS_ACTIVE IS NULL THEN :P10_IS_ACTIVE := ''Y''; END IF;',
'  IF :P10_CASH_BANK IS NULL THEN :P10_CASH_BANK := ''N''; END IF;',
'  IF :P10_ACCOUNT_CODE IS NULL THEN',
'    DECLARE',
'  l_parent accounts%ROWTYPE;',
'  l_len    PLS_INTEGER;',
'  l_max    VARCHAR2(20);',
'BEGIN',
'  IF :P10_PARENT_ID IS NULL THEN',
'    :P10_ACC_LEVEL := 1;',
'    SELECT TO_CHAR(NVL(MAX(TO_NUMBER(account_code)), 0) + 1)',
'    INTO   :P10_ACCOUNT_CODE',
'    FROM   accounts WHERE acc_level = 1;',
'    RETURN;',
'  END IF;',
'',
'  SELECT * INTO l_parent FROM accounts WHERE account_id = :P10_PARENT_ID;',
'  :P10_ACC_LEVEL := l_parent.acc_level + 1;',
'  :P10_ACC_TYPE  := l_parent.acc_type;',
'  :P10_NATURE    := l_parent.nature;',
'',
unistr('  -- \0637\0648\0644 \0627\0644\062C\0632\0621 \0627\0644\062E\0627\0635 \0628\0627\0644\0645\0633\062A\0648\0649: \06452 = 1 \062E\0627\0646\0629 \060C \06453 = 2 \062E\0627\0646\0629 \060C \06454 = 3 \062E\0627\0646\0627\062A'),
'  l_len := CASE :P10_ACC_LEVEL WHEN 2 THEN 1 WHEN 3 THEN 2 ELSE 3 END;',
'',
'  SELECT MAX(account_code) INTO l_max',
'  FROM   accounts WHERE parent_id = l_parent.account_id;',
'',
'  :P10_ACCOUNT_CODE := l_parent.account_code ||',
'       LPAD(NVL(TO_NUMBER(SUBSTR(l_max, -l_len)), 0) + 1, l_len, ''0'');',
'END;',
'',
'  END IF;',
'END;'))
,p_process_name=>'NEW_DEFAULTS'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':P10_ACCOUNT_ID IS NULL'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>91000000001375
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000001376)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_clob_language=>'PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_err VARCHAR2(4000);',
'FUNCTION chk RETURN VARCHAR2 IS',
' l_lvl NUMBER;',
'BEGIN',
'  IF :P10_PARENT_ID IS NULL THEN RETURN NULL; END IF;',
'  SELECT acc_level INTO l_lvl FROM accounts WHERE account_id = :P10_PARENT_ID;',
'  IF l_lvl >= 4 THEN',
unistr('    RETURN ''\0644\0627 \064A\0645\0643\0646 \0625\0636\0627\0641\0629 \062D\0633\0627\0628 \062A\062D\062A \062D\0633\0627\0628 \062A\062D\0644\064A\0644\064A (\0645\0633\062A\0648\0649 4)'';'),
'  END IF;',
'  IF :P10_ACCOUNT_ID = :P10_PARENT_ID THEN',
unistr('    RETURN ''\0627\0644\062D\0633\0627\0628 \0644\0627 \064A\0643\0648\0646 \0623\0628\0627\064B \0644\0646\0641\0633\0647'';'),
'  END IF;',
'  RETURN NULL;',
'END;',
'BEGIN',
'  l_err := chk;',
'  IF l_err IS NOT NULL THEN',
'    apex_error.add_error(p_message => l_err, p_display_location => apex_error.c_inline_in_notification);',
'  END IF;',
'END;'))
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CHECK_PARENT'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(91000000001370)
,p_internal_uid=>91000000001376
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(91000000001377)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_err VARCHAR2(4000);',
'FUNCTION chk RETURN VARCHAR2 IS',
' l_pcode VARCHAR2(20); l_lvl NUMBER;',
'BEGIN',
'  IF :P10_PARENT_ID IS NULL THEN',
'    l_lvl := 1;',
'  ELSE',
'    SELECT account_code, acc_level + 1 INTO l_pcode, l_lvl',
'    FROM accounts WHERE account_id = :P10_PARENT_ID;',
'  END IF;',
'',
'  IF LENGTH(:P10_ACCOUNT_CODE) <> CASE l_lvl WHEN 1 THEN 1 WHEN 2 THEN 2 WHEN 3 THEN 4 ELSE 7 END THEN',
unistr('    RETURN ''\0637\0648\0644 \0631\0642\0645 \0627\0644\062D\0633\0627\0628 \0641\064A \0627\0644\0645\0633\062A\0648\0649 '' || l_lvl || '' \064A\062C\0628 \0623\0646 \064A\0643\0648\0646 '''),
unistr('           || CASE l_lvl WHEN 1 THEN 1 WHEN 2 THEN 2 WHEN 3 THEN 4 ELSE 7 END || '' \062E\0627\0646\0627\062A'';'),
'  END IF;',
'  IF l_pcode IS NOT NULL AND :P10_ACCOUNT_CODE NOT LIKE l_pcode || ''%'' THEN',
unistr('    RETURN ''\0631\0642\0645 \0627\0644\062D\0633\0627\0628 \064A\062C\0628 \0623\0646 \064A\0628\062F\0623 \0628\0631\0642\0645 \0627\0644\062D\0633\0627\0628 \0627\0644\0623\0628 '' || l_pcode;'),
'  END IF;',
'  IF NOT REGEXP_LIKE(:P10_ACCOUNT_CODE, ''^[0-9]+$'') THEN',
unistr('    RETURN ''\0631\0642\0645 \0627\0644\062D\0633\0627\0628 \0623\0631\0642\0627\0645 \0641\0642\0637'';'),
'  END IF;',
'  RETURN NULL;',
'END;',
'BEGIN',
'  l_err := chk;',
'  IF l_err IS NOT NULL THEN',
'    apex_error.add_error(p_message => l_err, p_display_location => apex_error.c_inline_in_notification);',
'  END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_name=>'CHECK_CODE'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(91000000001370)
,p_internal_uid=>91000000001377
);
