,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT a.account_id,',
unistr('       a.account_code AS "\0631\0642\0645 \0627\0644\062D\0633\0627\0628",'),
unistr('       a.name_ar      AS "\0627\0633\0645 \0627\0644\062D\0633\0627\0628",'),
